window.JLPT_N2_GRAMMAR = [{"id":"g_2025_12","displayName":"12/2025","subtitle":"21 câu • Mondai 7–9 (Ngữ pháp)","m9_passage":"目で味わう\n\n「目で味わう」という言葉があります。もちろん、目で食べ物を食べるという意味ではありません。食べる前に目で見て料理の見た目を楽しむという意味です。しかし、「味わう」という言葉は普通、舌で料理の味を楽しむことを指します。目でも味を感じることはできるのでしょうか。\n\n色使いや盛り方など、料理の見た目がきれいだと食事の楽しみが増すという人も[48]。料理人たちも、塩や酢などを使って野菜の色を鮮やかに保ったり、料理に合う色や形の器を選んだりと、見た目を大切にしています。同じ料理でも、見た目がより良いもののほうがおいしそうに感じられます。\n\nでは、単に料理を見ておいしそうだと思うことを「味わう」と表現しているのでしょうか。[49]近年、料理の見た目が影響するのは食べる前だけではないことがわかってきました。ある研究で、食べ物の味は変えずに、色や器の種類などを変えて提供し、それぞれどんな味か評価させる実験が行われました。すると、全く同じ味のものを食べたにもかかわらず、味が異なると評価した人が多かったそうです。目から入る情報は、食べた時の味の感じ方[50]影響していたのです。このように科学的にも、実際に目で味わっているということが証明されつつあります。\n\n味を感じる仕組みは複雑で、見た目も大切な要素の一つです。それが感覚的に理解されていたからこそ、「目で味わう」と表現されるように[51]。","questions":[{"mondai":7,"q":1,"prompt":"今朝は寝坊をしてしまい、(　　)抜きで大学に来た。","options":["朝食が","朝食の","朝食に","朝食"],"answer":4,"word_explain":"「N＋抜きで」: không có N, bỏ qua N (ví dụ: 朝食抜きで = nhịn ăn sáng / không ăn sáng). Danh từ nối trực tiếp với 抜きで, không dùng trợ từ ở giữa.","translation_vi":"Sáng nay tôi đã ngủ quên nên đã đến trường đại học mà không ăn sáng."},{"mondai":7,"q":2,"prompt":"新しいコーヒーカップを使い始めて(　　)たたないうちに、床に落として割ってしまった。","options":["まだ","まもなく","いくらも","いつのまにか"],"answer":3,"word_explain":"「いくらも〜ないうちに」: chưa được bao lâu, chẳng mấy chốc (thời gian trôi qua chưa đáng kể thì chuyện khác đã xảy ra). 「まだ」 cần đi với khoảng thời gian cụ thể như 「まだ1週間も〜ないうちに」.","translation_vi":"Mới bắt đầu dùng chiếc cốc cà phê mới chẳng được bao lâu thì tôi đã làm rơi xuống sàn và vỡ mất."},{"mondai":7,"q":3,"prompt":"（鉄道会社のホームページで） 「一日乗車券」は、ご購入いただいた当日(　　)、何度でも自由に乗り降りができる乗車券です。","options":["につれ","に際し","にわたり","に限り"],"answer":4,"word_explain":"「N＋に限り」: chỉ giới hạn trong N / chỉ riêng vào N (ở đây là 「ご購入いただいた当日に限り」 = chỉ trong ngày quý khách đã mua).","translation_vi":"(Trên trang chủ của công ty đường sắt) \"Vé đi tàu một ngày\" là loại vé chỉ giới hạn trong ngày quý khách mua vé, có thể tự do lên xuống bao nhiêu lần cũng được."},{"mondai":7,"q":4,"prompt":"苦手な同僚と同じチームで仕事をすることになってしまったが、決まった(　　)、うまく付き合っていこうと思う。","options":["からには","わりには","ばかりか","どころか"],"answer":1,"word_explain":"「Vた＋からには」: một khi đã... thì... (thể hiện ý chí, quyết tâm của người nói sau khi một sự việc đã được xác định/quyết định).","translation_vi":"Tôi đành phải làm việc chung nhóm với người đồng nghiệp mà mình không hợp, nhưng một khi đã quyết định rồi thì tôi nghĩ mình sẽ cố gắng hòa hợp với họ."},{"mondai":7,"q":5,"prompt":"A社のおもちゃは、赤ちゃんが口に(　　)、米や小麦を原料にして作られているそうだ。","options":["入れてもよければ","入れてもいいように","入れることがあれば","入れることがあるように"],"answer":2,"word_explain":"「〜てもいいように」: để cho dù... cũng không sao / nhằm mục đích cho phép tình huống đó xảy ra một cách an toàn.","translation_vi":"Nghe nói đồ chơi của công ty A được làm từ nguyên liệu gạo và lúa mì để cho dù em bé có cho vào miệng cũng không sao."},{"mondai":7,"q":6,"prompt":"私は音楽大学でバイオリンを専攻しているが、卒業後は演奏家(　　)、子供たちに教えるという形でバイオリンに関わっていきたいと思っている。","options":["としてだったら","にとってだったら","としてではなく","にとってではなく"],"answer":3,"word_explain":"「N＋としてではなく」: không phải với tư cách là N (mà là một cách khác). 「〜として」 chỉ tư cách/vai trò, còn 「〜にとって」 chỉ lập trường/đối với ai đó.","translation_vi":"Tôi đang học chuyên ngành violin ở trường đại học âm nhạc, nhưng sau khi tốt nghiệp tôi muốn gắn bó với violin không phải với tư cách là một nghệ sĩ biểu diễn, mà dưới hình thức dạy cho trẻ em."},{"mondai":7,"q":7,"prompt":"（卓球教室で） A「私、卓球初めてなんです。」 B「私も、友達と遊びで少し(　　)、習うのははじめてです。」","options":["やったことがあるだけで","やったことがあることで","やっていなかったことで","やっていなかっただけで"],"answer":1,"word_explain":"「〜たことがあるだけで」: chỉ là đã từng làm... thôi (nhấn mạnh mức độ giới hạn: chỉ chơi giải trí một chút với bạn, chứ chưa từng học).","translation_vi":"(Ở lớp học bóng bàn) A: \"Tôi mới chơi bóng bàn lần đầu đấy.\" B: \"Tôi cũng chỉ từng chơi đùa một chút với bạn bè thôi, còn đi học bài bản thì đây là lần đầu tiên.\""},{"mondai":7,"q":8,"prompt":"後輩の田中さんは仕事熱心だが、少しまじめすぎる(　　)。","options":["ことになっている","ところがある","がちだ","ものだ"],"answer":2,"word_explain":"「V/A＋ところがある」: có chỗ / có phần / có điểm (dùng để nhận xét về tính cách, đặc điểm, khuynh hướng của người hoặc sự việc). 「がちだ」 không đi sau động từ thể từ điển.","translation_vi":"Hậu bối Tanaka rất nhiệt huyết trong công việc, nhưng có phần hơi quá nghiêm túc."},{"mondai":7,"q":9,"prompt":"駅前のラーメン屋はいつも込んでいて、けっこう待たされるのに、今日はそんなに(　　)。","options":["待たずに済んだ","待ったおかげだ","待ちきれなかった","待たなければよかった"],"answer":1,"word_explain":"「Vない＋ずに済んだ」: đã thoát khỏi việc phải làm gì / đã không phải làm gì. Phù hợp với ngữ cảnh đối lập với 「いつも込んでいて、けっこう待たされるのに」.","translation_vi":"Quán ramen trước nhà ga lúc nào cũng đông và thường phải chờ khá lâu, thế mà hôm nay tôi đã không phải chờ lâu đến thế."},{"mondai":7,"q":10,"prompt":"私は彼と結婚したいと思っているが、彼はきっとまだ結婚は(　　)。","options":["考えなくなってもしかたない","考えなくなるに違いない","考えていなくてもしかたない","考えていないに違いない"],"answer":4,"word_explain":"「きっと〜に違いない」: chắc chắn là... (suy đoán có độ chắc chắn cao của người nói). 「まだ考えていない」 diễn tả trạng thái hiện tại vẫn chưa nghĩ tới.","translation_vi":"Tôi muốn kết hôn với anh ấy, nhưng chắc chắn anh ấy vẫn chưa nghĩ đến chuyện kết hôn đâu."},{"mondai":7,"q":11,"prompt":"（会議で） 社長「新商品のコマーシャルについては、どうなっていますか。」 課長「はい。それについては、担当の私からご報告(　　)。」","options":["なさいます","おっしゃいます","申し上げます","伺います"],"answer":3,"word_explain":"「ご＋N(Hán-Nhật)＋申し上げます」: khiêm nhường ngữ trang trọng của 「〜します」 (ở đây là 「ご報告申し上げます」 = tôi xin phép báo cáo lên cấp trên). 「なさいます」「おっしゃいます」 là tôn kính ngữ.","translation_vi":"(Trong cuộc họp) Giám đốc: \"Về quảng cáo sản phẩm mới thì tình hình thế nào rồi?\" Trưởng phòng: \"Vâng. Về vấn đề đó, tôi – người phụ trách – xin phép được báo cáo ạ.\""},{"mondai":7,"q":12,"prompt":"ピアノの発表会の前に、間違えそうで怖いと先生に言ったら、「ちょっとぐらい(　　)よ。大事なのは楽しんで弾くことだよ。」と言ってくれた。","options":["間違えちゃいけないんだ","間違えたっていいんだ","間違えなきゃいいんだ","間違えたいんじゃないんだ"],"answer":2,"word_explain":"「〜たっていい」 (= 〜てもいい): dù có... cũng không sao / cứ... cũng được. Dùng để trấn an học trò trước buổi biểu diễn.","translation_vi":"Trước buổi biểu diễn piano, khi tôi nói với thầy/cô rằng tôi sợ mình sẽ đánh nhầm, thầy/cô đã động viên tôi rằng: \"Nhầm một chút cũng không sao đâu. Điều quan trọng là chơi đàn một cách vui vẻ đấy.\""},{"mondai":8,"q":13,"prompt":"ちょっと ＿＿＿　＿＿＿　★　＿＿＿ 好みのTシャツを見つけてしまい、つい買ってしまった。","options":["だけの","つもりで","服屋に入ったら","見る"],"answer":2,"word_explain":"Thứ tự đúng: 4 → 1 → ★2 → 3 (ちょっと見るだけの★つもりで服屋に入ったら). Cấu trúc 「Vる＋だけのつもりで」 (chỉ với ý định làm V thôi). Vị trí ★ là ô thứ 3 nên đáp án là 2.","translation_vi":"Chỉ định ghé vào cửa hàng quần áo xem thử một chút thôi, thế mà tôi lại tìm thấy chiếc áo phông đúng gu nên lỡ mua mất."},{"mondai":8,"q":14,"prompt":"兄は最近ずっと「歯が痛くて眠れない」と言っているけれど、歯医者には行こうとしない。そんなに ＿＿＿　＿＿＿　★　＿＿＿ 。","options":["痛い","早く行けばいい","のに","んだったら"],"answer":2,"word_explain":"Thứ tự đúng: 1 → 4 → ★2 → 3 (そんなに痛いんだったら★早く行けばいいのに). Cấu trúc 「〜んだったら〜ばいいのに」 (nếu đến mức đó thì cứ... đi cho xong, trách nhẹ/tiếc nuối). Vị trí ★ là ô thứ 3 nên đáp án là 2.","translation_vi":"Anh trai tôi dạo này cứ nói suốt là \"đau răng không ngủ được\", nhưng lại chẳng chịu đi nha sĩ. Nếu đau đến thế thì đi sớm đi có phải hơn không."},{"mondai":8,"q":15,"prompt":"「ABCチーズ」はチーズ料理の専門店で、私のような ＿＿＿　＿＿＿　★　＿＿＿ 店だ。","options":["人に","好きでたまらないという","チーズが","ぜひおすすめしたい"],"answer":1,"word_explain":"Thứ tự đúng: 3 → 2 → ★1 → 4 (チーズが好きでたまらないという★人にぜひおすすめしたい). Cụm 「チーズが好きでたまらないという人」 bổ nghĩa danh từ, kết hợp 「人にぜひおすすめしたい店」. Vị trí ★ là ô thứ 3 nên đáp án là 1.","translation_vi":"\"ABC Cheese\" là cửa hàng chuyên các món phô mai, là quán mà tôi rất muốn giới thiệu cho những người mê phô mai không chịu nổi như tôi."},{"mondai":8,"q":16,"prompt":"親友の花子に初めて会ったとき、初対面とは思えない ＿＿＿　＿＿＿　★　＿＿＿ 。","options":["よく覚えている","ぐらい","のを","話が盛り上がった"],"answer":3,"word_explain":"Thứ tự đúng: 2 → 4 → ★3 → 1 (ぐらい話が盛り上がった★のをよく覚えている). Cấu trúc 「〜とは思えないぐらい〜のをよく覚えている」 (nhớ rõ chuyện... đến mức không thể nghĩ là...). Vị trí ★ là ô thứ 3 nên đáp án là 3.","translation_vi":"Tôi vẫn nhớ rất rõ rằng khi mới gặp người bạn thân Hanako lần đầu, chúng tôi đã nói chuyện sôi nổi đến mức không nghĩ đó là lần đầu gặp mặt."},{"mondai":8,"q":17,"prompt":"学生のころ、様々な国を旅行して、自分の ＿＿＿　＿＿＿　★　＿＿＿ 、世界には多様な考え方があることを知った。","options":["出会えない","交流したことで","国にいては","様々な文化や価値観を持つ人と"],"answer":4,"word_explain":"Thứ tự đúng: 3 → 1 → ★4 → 2 (国にいては出会えない★様々な文化や価値観を持つ人と交流したことで). Cụm 「自分の国にいては出会えない」 bổ nghĩa cho 「様々な文化や価値観を持つ人」. Vị trí ★ là ô thứ 3 nên đáp án là 4.","translation_vi":"Thời sinh viên, tôi đã đi du lịch nhiều nước, và nhờ giao lưu với những người có nền văn hóa và hệ giá trị đa dạng mà nếu chỉ ở nước mình sẽ không thể gặp được, tôi đã biết rằng trên thế giới có rất nhiều cách suy nghĩ khác nhau."},{"mondai":9,"q":18,"prompt":"Chỗ trống [48] trong đoạn văn trên","options":["多いとします","多かったとします","多いでしょう","多かったでしょう"],"answer":3,"word_explain":"「〜という人も多いでしょう」: chắc hẳn cũng có nhiều người cho rằng... (phỏng đoán mang tính phổ quát ở hiện tại, làm tiền đề cho câu sau về các đầu bếp). 「〜とします」 là giả định (\"giả sử là...\"), không phù hợp ngữ cảnh.","translation_vi":"Chắc hẳn cũng có nhiều người nói rằng khi cách phối màu hay bày biện món ăn đẹp mắt thì niềm vui khi ăn uống cũng tăng lên."},{"mondai":9,"q":19,"prompt":"Chỗ trống [49] trong đoạn văn trên","options":["実は","確かに","しかも","ところが"],"answer":1,"word_explain":"Câu trước đặt câu hỏi: \"Vậy có phải người ta chỉ gọi việc nhìn món ăn thấy ngon mắt là 'thưởng thức' không?\". Sau câu hỏi tu từ 「〜のでしょうか。」, dùng 「実は」(thực ra là) để mở ra phát hiện mới/sự thật bất ngờ rằng hình thức còn ảnh hưởng cả tới cảm nhận vị khi ăn.","translation_vi":"Thực ra gần đây, người ta đã phát hiện ra rằng việc hình thức món ăn có ảnh hưởng không chỉ dừng lại ở trước khi ăn."},{"mondai":9,"q":20,"prompt":"Chỗ trống [50] trong đoạn văn trên","options":["にのみ","にまで","に限らず","に比べて"],"answer":2,"word_explain":"「〜にまで影響していた」: ảnh hưởng đến cả... (nhấn mạnh mức độ lan rộng: không chỉ trước khi ăn mà ảnh hưởng tới tận cảm nhận vị lúc ăn). Phù hợp với ý 「食べる前だけではない」 ở trên.","translation_vi":"Thông tin đi vào từ mắt đã ảnh hưởng đến cả cách cảm nhận hương vị khi ăn."},{"mondai":9,"q":21,"prompt":"Chỗ trống [51] trong đoạn văn trên","options":["なったにすぎません","なったはずがありません","なったとはいえません","なったのかもしれません"],"answer":4,"word_explain":"「〜からこそ、〜ようになったのかもしれません」: chính vì... nên có lẽ đã trở nên như vậy (phỏng đoán nguyên nhân hình thành cách nói 「目で味わう」). Các phương án còn lại đều mang nghĩa phủ định hoặc hạ thấp, mâu thuẫn với 「からこそ」.","translation_vi":"Chính vì điều đó đã được hiểu một cách cảm tính nên có lẽ người ta mới bắt đầu diễn đạt là \"thưởng thức bằng mắt\"."}]},{"id":"g_2025_07","displayName":"07/2025","subtitle":"21 câu • Mondai 7–9 (Ngữ pháp)","m9_passage":"高齢者の外出支援\n\nオ　ヒョンミ\n\n現在、日本では65歳以上の高齢者が人口の約3割に達するほど高齢化が進んでいる。そんな日本で今、高齢者の体と心の健康のために外出を支援するサービスの重要性が増しているそうだ。このサービスには、どのような効果があるのだろうか。\n\n外出を支援するサービスは、大きく分けて二つある。まず一つ目は、移動をサポートするサービスで、主に車での送迎サービスだ。車の運転が困難な人や、最寄りのバス停や駅まで歩くことが負担になる人に[48]。二つ目は、外出の機会を提供するサービスだ。用事がないから外出しないという高齢者は[49]。そのため、商店街での割引を実施したり、集まっておしゃべりができる会を開いたりするなど、外出の目的や場所を提供している。これらのサービスにより、外出の回数が増えたという人も多いそうだ。\n\n外出回数は、高齢者の体と心の健康に大きく影響する。[50]調査では、歩行に障害が出た人の数は、外出回数が1日1回以上の人より3日に1回未満の人のほうが約4倍も多かった。また、外出は心の健康のために欠かせないという研究報告もある。外出によって脳に刺激を与えることは、脳の機能が低下するのを防ぎ、心の健康につながるのだそうだ。\n\n外出と健康の関係を考えると、高齢者が外出することには大きな意味がある。高齢化が進む日本[51]、外出支援サービスは重要な役割を果たしているのだ。","questions":[{"mondai":7,"q":1,"prompt":"南市は、市民ホールを建設する(　　)、周辺の住民に対して説明会を行う予定だ。","options":["とすると","にあたって","ものなら","わりには"],"answer":2,"word_explain":"Vる + にあたって: nhân dịp, trước khi tiến hành một việc quan trọng (xây dựng hội trường công dân). Các phương án khác: とすると (nếu giả sử), ものなら (nếu có thể), わりには (tuy... nhưng lại).","translation_vi":"Thành phố Minami dự định sẽ tổ chức buổi giải thích cho người dân xung quanh nhân dịp/trước khi xây dựng hội trường công dân."},{"mondai":7,"q":2,"prompt":"彼女は、まだ小学生(　　)、すでに数々の国際的なピアノコンクールで優勝している。","options":["こそ","すら","ながらも","どころか"],"answer":3,"word_explain":"N + ながらも: mặc dù là N nhưng vẫn... (diễn tả sự tương phản: còn là học sinh tiểu học mà đã vô địch nhiều cuộc thi quốc tế).","translation_vi":"Cô bé dù vẫn còn là học sinh tiểu học nhưng đã giành chiến thắng ở nhiều cuộc thi piano quốc tế."},{"mondai":7,"q":3,"prompt":"仕事ができると言われる人は、そうでない人と比べて(　　)何が違うのだろうか。","options":["いったい","おそらく","かえって","どうしても"],"answer":1,"word_explain":"いったい〜のだろうか: rốt cuộc thì... (thường đi với từ để hỏi như 何 để nhấn mạnh sự thắc mắc).","translation_vi":"Những người được khen là làm việc giỏi so với những người không như vậy thì rốt cuộc khác nhau ở điểm nào nhỉ?"},{"mondai":7,"q":4,"prompt":"（旅館で） 旅館の人「いらっしゃいませ。本日は森川旅館に(　　)と思っている。ありがとうこさいます。」","options":["伺いまして","お越しになり","参りまして","おいでくださり"],"answer":4,"word_explain":"おいでくださり (từ おいでくださる = tôn kính ngữ của 来る + くださる): cảm ơn khách đã đến thăm (nối tiếp với ありがとうございます). 伺いまして và 参りまして là khiêm nhường ngữ (dùng cho bản thân), お越しになり thiếu くださる nên không dùng để cảm ơn. (Lưu ý: bản PDF in nhầm cụm \"と思っている。ありがとうこさいます\").","translation_vi":"(Ở lữ quán) Nhân viên lữ quán: \"Xin kính chào quý khách. Xin cảm ơn quý khách hôm nay đã ghé thăm Lữ quán Morikawa.\""},{"mondai":7,"q":5,"prompt":"父は、健康のことを考えてなるべく(　　)、会社から家まで１時間かけて歩いて帰ってくることもある。","options":["歩こうとしそうで","歩こうとすることで","歩くようにしているらしく","歩くようにしていたら"],"answer":3,"word_explain":"Vる + ようにしている + らしく: dường như đang cố gắng duy trì thói quen V (đi bộ hết sức có thể vì sức khỏe).","translation_vi":"Bố tôi vì nghĩ cho sức khỏe nên dường như cố gắng đi bộ hết sức có thể, có khi còn đi bộ mất 1 tiếng từ công ty về nhà."},{"mondai":7,"q":6,"prompt":"図書館で本を借りたのだが、最後まで(　　)、返却期限が来そうだ。","options":["読み終わるより","読み終わらないうちに","読んでしまうまで","読んでしまわなければ"],"answer":2,"word_explain":"Vない + うちに: nhân lúc chưa..., trước khi... (trước khi đọc xong hết cuốn sách thì sắp đến hạn trả).","translation_vi":"Tôi đã mượn sách ở thư viện, nhưng trước khi kịp đọc hết thì có vẻ sắp đến hạn trả rồi."},{"mondai":7,"q":7,"prompt":"最近成績が伸びないので、このままの勉強方法(　　)先生に相談してみた。","options":["でいいことを","ならいいことを","でいいのかどうか","なちいいのかどうか"],"answer":3,"word_explain":"N + でいいのかどうか: liệu dùng N như vậy có ổn không (dùng với 相談してみた: hỏi ý kiến/trao đổi xem có được không).","translation_vi":"Vì dạo này thành tích không tiến bộ nên tôi đã thử hỏi ý kiến thầy/cô xem phương pháp học cứ như hiện tại có ổn không."},{"mondai":7,"q":8,"prompt":"環境問題への意識が世界的に高まってきており、メーカー間の電気自動車の開発競争は激しくなる(　　)。","options":["一方だ","次第だ","ほどだ","べきだ"],"answer":1,"word_explain":"Vる + 一方だ: ngày càng trở nên..., cứ tiếp tục theo chiều hướng... (cuộc cạnh tranh ngày càng gay gắt hơn).","translation_vi":"Nhận thức về vấn đề môi trường đang tăng cao trên toàn thế giới, và cuộc cạnh tranh phát triển xe điện giữa các hãng sản xuất ngày càng trở nên gay gắt."},{"mondai":7,"q":9,"prompt":"週末、山に登った。とても暑い日だったが、頂上の近くは気温が低くて寒い(　　)。","options":["とよかった","に違いなかった","かのようだった","くらいだった"],"answer":4,"word_explain":"Aい + くらいだ: đến mức... (diễn tả mức độ: nhiệt độ thấp đến mức thấy lạnh dù hôm đó trời rất nóng).","translation_vi":"Cuối tuần tôi đã leo núi. Dù là một ngày rất nóng, nhưng gần đỉnh núi nhiệt độ thấp đến mức lạnh luôn."},{"mondai":7,"q":10,"prompt":"満員電車に乗るのは嫌だが、ほかに手段がないので、(　　)。","options":["乗るものではない","乗りようがない","乗らないわけにはいかない","乗らなくてもかまわない"],"answer":3,"word_explain":"Vない + わけにはいかない: không thể không làm V (do hoàn cảnh/nghĩa vụ bắt buộc: không có cách nào khác nên đành phải đi tàu).","translation_vi":"Dù ghét đi tàu điện đông nghịt nhưng vì không có phương tiện nào khác nên không thể không đi (đành phải đi)."},{"mondai":7,"q":11,"prompt":"（テレビ番組で） 司会「薬はどうして水以外の飲み物で飲んではいけないんでしょうか。」 医者「それは、お茶やジュースで飲むと薬の効きめに影響が出る(　　)。」","options":["ことがあるためです","ことにするためです","ことがあるはずです","ことにするはずです"],"answer":1,"word_explain":"Vる + ことがある + ためです: là bởi vì có trường hợp xảy ra việc V (trả lời cho câu hỏi nguyên nhân どうして〜んでしょうか).","translation_vi":"(Trên chương trình truyền hình) MC: \"Tại sao không được uống thuốc với đồ uống khác ngoài nước lọc ạ?\" Bác sĩ: \"Đó là vì nếu uống với trà hay nước ép thì có trường hợp sẽ ảnh hưởng đến hiệu quả của thuốc.\""},{"mondai":7,"q":12,"prompt":"私は猫アレルギーで、猫に触ると体がかゆくなってしまうのだが、猫は好きなので見るとつい(　　)。","options":["触ってみたがっている","触ってみたくなってしまう","触ってみてほしがっている","触ってみてほしくなってしまう"],"answer":2,"word_explain":"つい + Vて + みたく + なってしまう: bất giác/lỡ trở nên muốn thử làm V (chủ ngữ là 私 nên dùng たくなる, không dùng たがる của ngôi thứ 3).","translation_vi":"Tôi bị dị ứng mèo, cứ chạm vào mèo là người lại bị ngứa, nhưng vì thích mèo nên hễ nhìn thấy là bất giác lại muốn chạm thử vào nó."},{"mondai":8,"q":13,"prompt":"このバン用では、原料の＿＿＿　＿＿＿　★　＿＿＿一つ一つ丁寧にパンを作っているそうだ","options":["こだわって","小麦粉は","水にまで","もちろん"],"answer":3,"word_explain":"Thứ tự đúng: 2 → 4 → ★3 → 1. Cấu trúc 「Aはもちろん、Bにまで」 (không chỉ A mà đến cả B cũng...) + こだわって (chú trọng, cầu kỳ). (Lưu ý: bản PDF in nhầm \"パン屋\" thành \"バン用\").","translation_vi":"Nghe nói tiệm bánh mì này không chỉ chú trọng nguyên liệu là bột mì mà còn tỉ mỉ đến cả nước, làm từng chiếc bánh một cách cẩn thận."},{"mondai":8,"q":14,"prompt":"昨日は、梅雨の＿＿＿　＿＿＿　★　＿＿＿、久しぶりに洗濯物を外に干すことができた。","options":["いい天気で","時期にしては","この","珍しく"],"answer":4,"word_explain":"Thứ tự đúng: 3 → 2 → ★4 → 1. Cấu trúc 「Nにしては」 (so với N thì...): 梅雨のこの時期にしては (so với thời điểm mùa mưa như thế này) + 珍しくいい天気で (thời tiết đẹp hiếm thấy). (Lưu ý: trong bản PDF câu này bị đánh số nhầm thành 43).","translation_vi":"Hôm qua, so với thời điểm mùa mưa thế này thì trời lại nắng đẹp hiếm thấy, nên lâu lắm rồi tôi mới phơi được quần áo ra ngoài."},{"mondai":8,"q":15,"prompt":"今回のセミナーの開催日が人の＿＿＿　＿＿＿　★　＿＿＿参加者が集まったのは大成功といえる。","options":["集まりにくい","ことを考えると","平日だった","200名もの"],"answer":2,"word_explain":"Thứ tự đúng: 1 → 3 → ★2 → 4. Mệnh đề bổ nghĩa 「人の集まりにくい平日だった」 + 「ことを考えると」 (xét đến việc...) + 「200名もの」 (tới tận 200 người tham gia).","translation_vi":"Xét việc ngày tổ chức hội thảo lần này là ngày thường vốn khó tập trung mọi người, việc có tới 200 người tham gia có thể coi là một thành công lớn."},{"mondai":8,"q":16,"prompt":"人には＿＿＿　＿＿＿　★　＿＿＿気づくのは難しい。。","options":["良さがあるというが","誰にでも","その人にしかない","自分でそれに"],"answer":1,"word_explain":"Thứ tự đúng: 2 → 3 → ★1 → 4. 「人には誰にでも」 (ở mỗi con người, ai cũng...) + 「その人にしかない良さがあるというが」 (nói là có điểm tốt chỉ người đó mới có, nhưng...) + 「自分でそれに気づくのは難しい」 (tự mình nhận ra điều đó thì khó).","translation_vi":"Người ta nói rằng ai cũng có điểm tốt mà chỉ riêng người đó mới có, nhưng tự mình nhận ra điều đó thì thật khó."},{"mondai":8,"q":17,"prompt":"昨日の晩、目覚まし時計をセットするのを忘れてしまい、今朝は寝坊してしまった。それでも＿＿＿　＿＿＿　★　＿＿＿からだ。。","options":["のは","たまたまかかってきた","電話に起こされた","遅刻をせずに済んだ"],"answer":2,"word_explain":"Thứ tự đúng: 4 → 1 → ★2 → 3. Cấu trúc 「〜のは〜からだ」 (lý do mà... là vì...): 遅刻をせずに済んだのは、たまたまかかってきた電話に起こされたからだ。","translation_vi":"Tối hôm qua tôi quên đặt đồng hồ báo thức nên sáng nay đã ngủ quên. Thế nhưng lý do tôi vẫn không bị muộn là vì đã được đánh thức bởi cuộc điện thoại tình cờ gọi tới."},{"mondai":9,"q":18,"prompt":"Chỗ trống [48] trong đoạn văn trên","options":["利用させてほしい","利用されている","利用してくれている","利用してもいい"],"answer":2,"word_explain":"Thể bị động 「〜に利用されている」 (được sử dụng bởi đối tượng nào đó), phù hợp với chủ ngữ ẩn là \"dịch vụ đưa đón bằng ô tô\" (車での送迎サービス) ở câu trước trong bài viết khách quan.","translation_vi":"Dịch vụ này đang được sử dụng bởi những người gặp khó khăn trong việc lái xe ô tô hay những người cảm thấy việc đi bộ đến trạm xe buýt hoặc nhà ga gần nhất là gánh nặng."},{"mondai":9,"q":19,"prompt":"Chỗ trống [49] trong đoạn văn trên","options":["少なかったはずだ","少なくなったのだ","少なくないという","少なくなりかねない"],"answer":3,"word_explain":"「少なくないという」 (nghe nói là không ít / có rất nhiều). Câu sau có 「そのため...外出の目的や場所を提供している」 (Vì vậy họ cung cấp mục đích và địa điểm để ra ngoài), cho thấy số người cao tuổi không ra ngoài vì không có việc bận là rất nhiều (không ít).","translation_vi":"Nghe nói có không ít người cao tuổi không ra ngoài vì không có việc gì cần làm."},{"mondai":9,"q":20,"prompt":"Chỗ trống [50] trong đoạn văn trên","options":["このような","その","次の","ある"],"answer":4,"word_explain":"「ある調査では」 (theo một cuộc khảo sát nọ). Trước đó chưa hề nhắc đến cuộc khảo sát nào nên không thể dùng 「このような」 hay 「その」, và số liệu được nêu ngay trong cùng câu nên không dùng 「次の」.","translation_vi":"Theo một cuộc khảo sát nọ, số người gặp trở ngại trong việc đi lại ở nhóm ra ngoài dưới 1 lần trong 3 ngày nhiều gấp khoảng 4 lần so với nhóm ra ngoài từ 1 lần trở lên mỗi ngày."},{"mondai":9,"q":21,"prompt":"Chỗ trống [51] trong đoạn văn trên","options":["において","に限らず","を中心に","をはじめ"],"answer":1,"word_explain":"「N + において」 (tại, ở — dùng trong văn viết để chỉ phạm vi, địa điểm: tại nước Nhật đang già hóa). Các lựa chọn khác (に限らず: không chỉ; を中心に: lấy... làm trung tâm; をはじめ: tiêu biểu là...) không phù hợp ngữ cảnh kết bài.","translation_vi":"Tại nước Nhật nơi tình trạng già hóa dân số đang tiến triển, dịch vụ hỗ trợ đi lại bên ngoài đang đóng một vai trò quan trọng."}]},{"id":"g_2024_12","displayName":"12/2024","subtitle":"21 câu • Mondai 7–9 (Ngữ pháp)","m9_passage":"以下は、留学生の作文である。\n\n農業ボランティア\nゴメス　フランシスコ\n\n半年前、私は友達に誘われて、働き手が足りない農家を手伝う「農業ボランティア」を始めた。過去にごみ拾いなどのボランティアはしたことがあったが、農業ボランティアのことは友達に聞くまで知らなかった。私は日本でいろいろな経験をしたいと思っていたので、参加することにした。\n\n私が手伝っているのは南さんという農家だ。40代のご夫婦がトマトやキャベツなど、いろいろな野菜を作っている。農作業は初めての経験だったが、農業は想像していた以上に知識や経験が必要だと感じた。[48]、収穫のタイミングは、成長の具合や天気予報を基に、いつがいいかを判断しなければならない。また、トマトなどは成長の段階に応じて与える水の量を変えないとしっかり育たない。体力 [49] 必要で、農業は本当に大変な仕事だ。\n\n初めのころは、わからないことが多く、よく質問をして南さんたちの作業を止めてしまっていた。手伝いではなく邪魔をしているのではないかと不安になることもあった。それでも、「ありがとう。助かっているよ。」といつも声をかけてくれたので、だんだん自分も役に立てていると感じられるようになった。収穫したばかりのトマトを初めて食べさせてもらったときはあまりにおいしくて [50]。収穫したときの達成感や大切に育てた野菜を味わう喜びは、このボランティアに参加しなければ感じられなかっただろう。\n\n農業ボランティアとして役に立てたことがうれしかったし、多くの貴重な経験をすることができた。[51] 本当によかったと思う。","questions":[{"mondai":7,"q":1,"prompt":"水泳教室に通い始めたころは、怖くて水に顔をつけること（　　）できなかったが、今は泳ぐのが大好きだ。","options":["なら","ほど","さえ","ばかり"],"answer":3,"word_explain":"「～さえ～ない」: thậm chí... cũng không, nhấn mạnh mức độ tối thiểu/cực đoan (ngay cả việc úp mặt xuống nước cũng không làm được).","translation_vi":"Hồi mới bắt đầu đi học bơi, vì sợ nên tôi thậm chí còn không thể úp mặt xuống nước, nhưng bây giờ tôi rất thích bơi."},{"mondai":7,"q":2,"prompt":"この作業はかなり大変なので、一日で終わらせるのは（　　）無理だろう。","options":["つい","まず","たとえ","今にも"],"answer":2,"word_explain":"「まず（～だろう／～ない）」: gần như chắc chắn là..., hầu như khó mà.... Dùng để đưa ra phán đoán gần như chắc chắn của người nói.","translation_vi":"Công việc này khá vất vả nên việc hoàn thành trong một ngày có lẽ là hầu như không thể."},{"mondai":7,"q":3,"prompt":"母はいちごジャムを作るとき、いちご100グラム（　　）80グラムの砂糖を使う。","options":["に対して","に関して","によって","にあたって"],"answer":1,"word_explain":"「～に対して」: biểu thị tỷ lệ tương ứng (cứ 100g dâu tây thì dùng 80g đường).","translation_vi":"Khi làm mứt dâu, mẹ tôi dùng 80 gam đường cho mỗi 100 gam dâu tây."},{"mondai":7,"q":4,"prompt":"この図書館には、借りている本を全部（　　）、ほかの本が借りられないという規則がある。","options":["返したすえに","返したとはいえ","返してはじめて","返してからでないと"],"answer":4,"word_explain":"「～てからでないと（～ない）」: nếu chưa/không làm... trước thì không thể..., diễn tả điều kiện tiên quyết bắt buộc.","translation_vi":"Thư viện này có quy định là nếu chưa trả hết số sách đang mượn thì không thể mượn sách khác."},{"mondai":7,"q":5,"prompt":"タクシー会社を経営する青山氏は、インタビューで「お客様から感謝の言葉を（　　）、人の役に立つ喜びを感じます。」と語った。","options":["いただくよう","さしあげるよう","いただくたび","さしあげるたび"],"answer":3,"word_explain":"「～たび（に）」: mỗi lần.... Kết hợp với khiêm nhường ngữ「いただく」(nhận từ khách hàng), diễn tả mỗi lần nhận được lời cảm ơn lại cảm thấy niềm vui.","translation_vi":"Ông Aoyama, người điều hành công ty taxi, đã chia sẻ trong buổi phỏng vấn: \"Mỗi lần nhận được lời cảm ơn từ khách hàng, tôi lại cảm thấy niềm vui khi được giúp ích cho mọi người.\""},{"mondai":7,"q":6,"prompt":"妻は息子にどうしてもピアノを習わせたいと言っているが、私は本人が（　　）無理にさせなくてもいいと思っている。","options":["やらされないのなら","やりたがらないのなら","やってほしくないのに","やってもはじまらないのに"],"answer":2,"word_explain":"「Vたい」dùng cho ngôi thứ 3 chuyển thành「Vたがる」(やりたがらない: không muốn làm) + 「のなら」(nếu như). Phù hợp khi nói về ý muốn của con trai.","translation_vi":"Vợ tôi nói nhất định muốn cho con trai học piano, nhưng tôi nghĩ nếu bản thân thằng bé không muốn học thì không cần phải ép buộc làm gì."},{"mondai":7,"q":7,"prompt":"この研究を始めたころは、そんなことを研究して意味が（　　）批判的な意見も多かったが、最近少しずつ認めてもらえるようになってきた。","options":["あるというような","あるのかというような","あるということの","あるのかということの"],"answer":2,"word_explain":"「～のかというような + N」: dẫn lại ý kiến mang tính chất nghi vấn, nghi ngờ (\"những ý kiến chỉ trích kiểu như liệu có ý nghĩa gì không\").","translation_vi":"Hồi mới bắt đầu nghiên cứu này, có rất nhiều ý kiến chỉ trích kiểu như \"nghiên cứu chuyện đó liệu có ý nghĩa gì không\", nhưng gần đây dần dần đã bắt đầu được công nhận."},{"mondai":7,"q":8,"prompt":"腕のけがはまだ完全に（　　）が、日常生活には困らなくなった。","options":["治りようがない","治らないでもない","治ったにすぎない","治ったわけではない"],"answer":4,"word_explain":"「～わけではない」: không hẳn là..., không có nghĩa là.... Dùng để phủ định một phần (tuy chưa khỏi hoàn toàn nhưng không còn bất tiện).","translation_vi":"Vết thương ở tay vẫn chưa hẳn là đã khỏi hoàn toàn, nhưng không còn gây khó khăn cho sinh hoạt hằng ngày nữa."},{"mondai":7,"q":9,"prompt":"私は20年前に初めて富士山に登った。山頂に立ったときの感動は今でも（　　）。","options":["忘れがたい","忘れかけている","忘れないといい","忘れるおそれがある"],"answer":1,"word_explain":"「Vます + がたい」: khó mà... (diễn tả việc gì đó rất khó thực hiện về mặt tâm lý/tình cảm; 忘れがたい: khó quên).","translation_vi":"Lần đầu tiên tôi leo núi Phú Sĩ là cách đây 20 năm. Cảm xúc khi đứng trên đỉnh núi đến tận bây giờ tôi vẫn khó lòng quên được."},{"mondai":7,"q":10,"prompt":"洗濯機に入れるときに気づいたからよかったが、もう少しで大事な領収書をズボンのポケットに入れたまま（　　）。","options":["洗濯したようだ","洗濯するつもりだった","洗濯したせいだ","洗濯するところだった"],"answer":4,"word_explain":"「もう少しで～（する）ところだった」: suýt chút nữa thì đã... (diễn tả việc không hay suýt xảy ra nhưng may mắn đã kịp ngăn lại).","translation_vi":"May mà lúc cho vào máy giặt tôi đã phát hiện ra, chứ suýt chút nữa là đã giặt luôn cả hóa đơn quan trọng vẫn để trong túi quần rồi."},{"mondai":7,"q":11,"prompt":"毎晩私は、5歳の娘が寝る前にベッドで本を読んでやるのだが、読んでいるうちに自分のほうが（　　）。","options":["寝てしまうことがある","寝ておくことがある","寝てしまうことにする","寝ておくことにする"],"answer":1,"word_explain":"「～てしまう」diễn tả hành động ngoài ý muốn (lỡ ngủ thiếp đi); 「～ことがある」diễn tả sự việc thỉnh thoảng có xảy ra.","translation_vi":"Mỗi tối trước khi con gái 5 tuổi đi ngủ tôi đều đọc sách cho bé nghe trên giường, nhưng trong lúc đọc thì thỉnh thoảng chính tôi lại ngủ thiếp đi mất."},{"mondai":7,"q":12,"prompt":"社長として、社員全員が仕事に満足できる環境を整えたい。それは単なる理想（　　）。いや、私は理想ではなく必ず実現できると信じている。","options":["でしかないはずだ","でなくてはいけないはずだ","でしかないのだろうか","ではいけないのだろうか"],"answer":3,"word_explain":"「～でしかない」: chỉ là... mà thôi; kết hợp 「～のだろうか」tạo câu hỏi tự vấn (\"Liệu đó có phải chỉ là lý tưởng suông không?\") rồi phủ định ở câu sau.","translation_vi":"Với tư cách là giám đốc, tôi muốn xây dựng một môi trường mà tất cả nhân viên đều hài lòng với công việc. Liệu điều đó có phải chỉ là lý tưởng suông không? Không, tôi tin rằng đó không phải lý tưởng mà nhất định có thể thực hiện được."},{"mondai":8,"q":13,"prompt":"長く使っている電子レンジが壊れてしまった。古いものだし、修理に ＿＿＿　＿＿＿　★　＿＿＿ 買い替えたほうがいいかもしれない。","options":["もう","考えると","かかる","費用を"],"answer":2,"word_explain":"Thứ tự đúng: 3 → 4 → ★2 → 1. Cụm「修理にかかる費用を考えると」(nghĩ đến chi phí tốn cho việc sửa chữa) nối với「もう買い替えたほうがいいかもしれない」(có lẽ nên mua cái mới thay thế rồi).","translation_vi":"Chiếc lò vi sóng dùng lâu năm bị hỏng mất rồi. Vì cũng là đồ cũ rồi, nghĩ đến chi phí tốn cho việc sửa chữa thì có lẽ nên mua cái mới thay thế luôn thì hơn."},{"mondai":8,"q":14,"prompt":"娘「今度のスピーチコンテスト、参加しようかなあ。でも、自信ないなあ。」 母「チャレンジ ＿＿＿　＿＿＿　★　＿＿＿ ？　いい経験になると思うよ。」","options":["だけ","みたら","する","して"],"answer":4,"word_explain":"Thứ tự đúng: 3 → 1 → ★4 → 2. Cấu trúc「VるだけVてみる」(するだけしてみたら？): cứ thử làm xem sao, khuyên nhủ cứ thử sức một lần.","translation_vi":"Con gái: \"Cuộc thi hùng biện lần này không biết con có nên tham gia không nhỉ. Nhưng con không tự tin lắm.\" Mẹ: \"Con cứ thử sức xem sao? Mẹ nghĩ sẽ là một trải nghiệm tốt đấy.\""},{"mondai":8,"q":15,"prompt":"このドレスを着ると、＿＿＿　＿＿＿　★　＿＿＿ 気分になる。","options":["映画か何かに","なったような","出てくる","お姫様にでも"],"answer":4,"word_explain":"Thứ tự đúng: 1 → 3 → ★4 → 2. Mệnh đề định ngữ「映画か何かに出てくるお姫様」(nàng công chúa xuất hiện trong phim hay gì đó) kết hợp với「～にでもなったような気分」(cảm giác như thể đã trở thành...).","translation_vi":"Khi mặc chiếc váy này vào, tôi có cảm giác như thể mình đã trở thành một nàng công chúa xuất hiện trong phim hay gì đó vậy."},{"mondai":8,"q":16,"prompt":"昨日は「母の日」だったので、いつもおいしいお弁当を ＿＿＿　＿＿＿　★　＿＿＿ 母が欲しがっていたアクセサリーをプレゼントした。","options":["感謝の","作ってくれて","ありがとうという","気持ちを込めて"],"answer":1,"word_explain":"Thứ tự đúng: 2 → 3 → ★1 → 4. Cụm「作ってくれてありがとうという感謝の気持ちを込めて」(gửi gắm tấm lòng biết ơn với lời cảm ơn vì đã luôn làm cơm hộp ngon cho con).","translation_vi":"Hôm qua là \"Ngày của Mẹ\", nên với tấm lòng biết ơn và lời cảm ơn mẹ vì lúc nào cũng làm cơm hộp ngon cho con, tôi đã tặng mẹ món phụ kiện mà mẹ vẫn luôn muốn có."},{"mondai":8,"q":17,"prompt":"学生時代は、周りの人から ＿＿＿　＿＿＿　★　＿＿＿ 無理して人に合わせようとすることが多かった。","options":["言えずに","気にするあまり","自分の本当の気持ちを","自分がどう思われているかを"],"answer":3,"word_explain":"Thứ tự đúng: 4 → 2 → ★3 → 1. Mẫu「～あまり」(vì quá... nên dẫn đến...): vì quá để tâm xem người xung quanh nghĩ gì về mình (自分がどう思われているかを気にするあまり), nên không thể nói ra cảm xúc thật (自分の本当の気持ちを言えずに).","translation_vi":"Thời còn đi học, vì quá bận tâm xem mọi người xung quanh nghĩ gì về mình, tôi thường không thể nói ra cảm xúc thật của bản thân mà hay gượng ép mình để chiều theo người khác."},{"mondai":9,"q":18,"prompt":"Chỗ trống [48] trong đoạn văn trên","options":["一方","そして","例えば","ただし"],"answer":3,"word_explain":"Câu trước nêu nhận xét chung (\"nông nghiệp đòi hỏi kiến thức và kinh nghiệm nhiều hơn tưởng tượng\"), câu sau đưa ra ví dụ cụ thể (cách xác định thời điểm thu hoạch, điều chỉnh lượng nước tưới), nên dùng「例えば」(ví dụ như).","translation_vi":"Ví dụ như, đối với thời điểm thu hoạch thì phải dựa vào tình trạng phát triển và dự báo thời tiết để phán đoán lúc nào là thích hợp."},{"mondai":9,"q":19,"prompt":"Chỗ trống [49] trong đoạn văn trên","options":["だけ","も","は","こそ"],"answer":2,"word_explain":"Trước đó đã nhắc đến việc nông nghiệp cần \"kiến thức và kinh nghiệm\", ở đây bổ sung thêm rằng \"thể lực cũng cần thiết\", nên dùng trợ từ「も」.","translation_vi":"Thể lực cũng cần thiết nữa, nên nông nghiệp quả thực là một công việc vất vả."},{"mondai":9,"q":20,"prompt":"Chỗ trống [50] trong đoạn văn trên","options":["感動したことだ","感動していた","感動したはずだ","感動してしまった"],"answer":4,"word_explain":"「～てしまう」diễn tả phản ứng cảm xúc tự nhiên, bộc phát mạnh mẽ ngoài ý muốn khi kết hợp với「あまりにおいしくて」(\"vì ngon quá mức nên tôi đã vô cùng cảm động\").","translation_vi":"Lần đầu tiên được cho ăn thử quả cà chua vừa mới thu hoạch, vì ngon quá mức nên tôi đã vô cùng cảm động."},{"mondai":9,"q":21,"prompt":"Chỗ trống [51] trong đoạn văn trên","options":["やってみて","やってみても","やってみたら","やってみたから"],"answer":1,"word_explain":"Mẫu「Vてよかった」(thật tốt vì đã làm V / may mà đã làm V):「やってみて本当によかったと思う」(Tôi thấy thật tốt vì mình đã thử tham gia).","translation_vi":"Tôi nghĩ thật tốt vì mình đã thử tham gia hoạt động này."}]},{"id":"g_2024_07","displayName":"07/2024","subtitle":"21 câu • Mondai 7–9 (Ngữ pháp)","m9_passage":"紅葉の異変\nサリム ソフィア\n\n私は日本の秋の景色が好きです。秋になって紅葉が始まり、緑だった葉が黄色やオレンジ、赤に変わると、とてもきれいです。秋の紅葉は、日本の四季の変化を感じさせてくれるものです。\n\n[48] ですが、先日テレビで、紅葉がピークを迎える時期が年々遅くなっているというニュースを見ました。中には、1月になってからピークを迎えたところもあるそうで、驚きました。温暖化によって平均気温が上昇していることが大きな原因だそうです。私は、夏が過ぎて気温が下がってくれば、必ず紅葉が始まると思っていました。[49]、そうではありませんでした。紅葉には、条件となる気温の変化がありました。\n\n葉の変色が始まるのは、1日の最低気温が大体8度以下になってからです。秋になっても、最低気温が一定の気温まで下がらなければ、紅葉は [50]。その後、さらに寒くなり、5〜6度まで下がると、紅葉は一気に進みます。また、5度以下の日が続くと、最も美しい紅葉が見られるといわれています。\n\n紅葉に起きている異変を知り、このまま温暖化が進むと、日本の秋の景色が変わってしまう可能性もあるのではないかと思いました。もしかしたら、紅葉自体が見られなくなる日も来るかもしれません。紅葉を通して、温暖化が身近な問題であることをより強く [51]。","questions":[{"mondai":7,"q":1,"prompt":"卓球クラブの山谷さんは大きな大会で何度も優勝しているのに、「私(　　)まだまだですよ」といつも言っている。","options":["まで","さえ","ばかり","なんか"],"answer":4,"word_explain":"「〜なんか」dùng để tự hạ thấp bản thân một cách khiêm tốn (\"người như tôi thì...\"), phù hợp với cụm 「まだまだですよ」.","translation_vi":"Anh Yamaya ở câu lạc bộ bóng bàn dù đã nhiều lần vô địch ở các giải đấu lớn nhưng lúc nào cũng nói: \"Người như tôi vẫn còn kém lắm\"."},{"mondai":7,"q":2,"prompt":"携帯電話を一人一台持つのは当たり前と言われる現代で、私のように携帯電話なしで生活している人は(　　)いるのだろうか。","options":["どうも","どれほど","どうしても","どんなに"],"answer":2,"word_explain":"「どれほど〜いるのだろうか」dùng để hỏi hoặc tự hỏi về số lượng/mức độ (\"có bao nhiêu...\"). 「どんなに」đi với tính từ/trạng thái mức độ chứ không dùng để hỏi số lượng người tồn tại.","translation_vi":"Trong thời đại ngày nay khi việc mỗi người sở hữu một chiếc điện thoại di động được xem là đương nhiên, không biết có bao nhiêu người đang sống không có điện thoại di động như tôi nhỉ."},{"mondai":7,"q":3,"prompt":"花山市では、きゅうりやトマト、なす(　　)夏の野菜が多く生産されている。","options":["とする","に関する","といった","に沿った"],"answer":3,"word_explain":"「AやB、CといったN」dùng để liệt kê ví dụ tiêu biểu (\"những N như A, B, C\").","translation_vi":"Ở thành phố Hanayama, các loại rau mùa hè như dưa chuột, cà chua, cà tím được sản xuất rất nhiều."},{"mondai":7,"q":4,"prompt":"彼とは数年前に先輩の結婚式で(　　)、ずっと会っていない。","options":["会ったきり","会ったばかりか","会っただけに","会ったところ"],"answer":1,"word_explain":"「Vた＋きり」diễn tả một hành động xảy ra trong quá khứ rồi từ đó về sau trạng thái không tiếp tục/không làm lại nữa (\"từ sau khi... thì suốt...\").","translation_vi":"Kể từ lần gặp anh ấy ở đám cưới của đàn anh vài năm trước, tôi vẫn chưa gặp lại lần nào."},{"mondai":7,"q":5,"prompt":"近所に子供向けのダンススクールができるらしい、オープンしたら、娘を体験レッスンに(　　)と思っている。","options":["参加してみようか","参加させてみようか","参加してみてよかった","参加させてみてよかった"],"answer":2,"word_explain":"Chủ thể thực hiện hành động là người nói (phụ huynh), đối tượng tham gia là 「娘を」 nên cần thể sai khiến 「参加させる」 kết hợp 「〜てみようかと思っている」 (\"định thử cho con tham gia xem sao\"). Loại 3, 4 vì là thì quá khứ.","translation_vi":"Nghe nói gần nhà sắp mở trường dạy nhảy cho trẻ em, khi khai trương tôi định sẽ cho con gái tham gia thử buổi học trải nghiệm xem sao."},{"mondai":7,"q":6,"prompt":"（カメラ屋で） 客「カメラを海に落としてしまって、電源が入らないんです。中に水が入ってしまったようなのですが…。」 店員「海水が入った(　　)、修理は難しいかもしれませんが、一応見てみますね。」","options":["のであれば","ことであれば","のであって","ことであって"],"answer":1,"word_explain":"「〜のであれば」dùng để giả định dựa trên thông tin đối phương vừa nói (\"nếu đúng là nước biển đã vào...\"). 「ことであれば」chỉ đi với danh từ 「Nのことであれば」, không nối trực tiếp sau mệnh đề động từ.","translation_vi":"(Tại cửa hàng máy ảnh) Khách: \"Tôi làm rơi máy ảnh xuống biển và không bật nguồn lên được. Hình như nước đã vào bên trong rồi...\" Nhân viên: \"Nếu là nước biển đã vào bên trong thì việc sửa chữa có thể khó, nhưng tôi sẽ thử kiểm tra xem sao nhé.\""},{"mondai":7,"q":7,"prompt":"母「引っ越しまでまだ時間はあるけど、直前になってあわてないように(　　)、荷物の整理進めておきなさいね。」 息子「うん、分かった。」","options":["少しだけでいいのに","少しだけならよくでも","少しずつでいいから","少しずつならよく"],"answer":3,"word_explain":"「少しずつでいいから」(\"từng chút một cũng được nên...\"), hợp nghĩa khuyên nhủ làm dần từng ít một trước khi chuyển nhà.","translation_vi":"Mẹ: \"Đến lúc chuyển nhà vẫn còn thời gian, nhưng để sát ngày không bị cuống lên thì làm từng chút một cũng được, con hãy dọn dẹp đồ đạc dần đi nhé.\" Con trai: \"Vâng, con biết rồi.\""},{"mondai":7,"q":8,"prompt":"1896年の第1回オリンピックに参加した国と地域の数は14だったが、2004年には200を超える(　　)。","options":["べきだった","つもりだった","ほかなかった","までになった"],"answer":4,"word_explain":"「Vる＋までになった」diễn tả sự phát triển, thay đổi đạt tới một mức độ đáng kể (\"đã trở nên đến mức...\").","translation_vi":"Số quốc gia và vùng lãnh thổ tham gia Thế vận hội lần thứ nhất năm 1896 là 14, nhưng đến năm 2004 đã tăng lên đến mức vượt quá 200."},{"mondai":7,"q":9,"prompt":"チームでの仕事をスムースに進めるには、メンバー同士の十分なコミュニケーション(　　)。","options":["にすぎない","が欠かせない","のおかげだ","とのことだ"],"answer":2,"word_explain":"「〜が欠かせない」có nghĩa là \"không thể thiếu\", phù hợp với cấu trúc mục đích 「〜には」 (\"để làm ~ thì không thể thiếu...\").","translation_vi":"Để công việc nhóm tiến triển suôn sẻ, sự giao tiếp đầy đủ giữa các thành viên là điều không thể thiếu."},{"mondai":7,"q":10,"prompt":"昨日、新しくできた遊園地に行った。電車より車のほうが早いだろうと思って車で行ったら、ひどい渋滞でかえって時間がかかってしまった。やはり電車で(　　)。","options":["行けばよかった","行くはずだった","行かなくて済んだ","行きたくてしかたがなかった"],"answer":1,"word_explain":"「Vばよかった」diễn tả sự hối tiếc về một việc đã không làm trong quá khứ (\"giá mà đã đi bằng tàu điện thì tốt rồi\").","translation_vi":"Hôm qua tôi đã đi công viên giải trí mới mở. Nghĩ rằng đi ô tô sẽ nhanh hơn tàu điện nên tôi đi ô tô, ai ngờ kẹt xe kinh khủng khiến lại mất nhiều thời gian hơn. Giá như tôi đi bằng tàu điện thì tốt biết mấy."},{"mondai":7,"q":11,"prompt":"往復2時間の通勤を週に5日、40年間続けたとすると、通勤時間は約2万時間で、2年以上の時間を通勤に使う(　　)。","options":["ということにする","ということにしている","ということになる","ということになっている"],"answer":3,"word_explain":"「〜ということになる」diễn tả kết quả suy luận hoặc tính toán logic từ giả thiết 「〜とすると」 (\"tính ra là / suy ra là...\").","translation_vi":"Nếu giả sử đi làm cả đi lẫn về mất 2 tiếng mỗi ngày, 5 ngày một tuần trong 40 năm, thì thời gian đi làm sẽ vào khoảng 20.000 tiếng, tức là tính ra dùng hơn 2 năm cho việc đi làm."},{"mondai":7,"q":12,"prompt":"(電話で) A「お電話ありがとうございます。クロカワ建設営業課でございます。」 B「高橋さんはいらっしゃいますか。」 A「失礼ですが、お名前を(　　)。」","options":["伺ったらいかがでしょうか","伺ってもよろしいでしょうか","お伝えしたらいかがでしょうか","お伝えしてもよろしいでしょうか"],"answer":2,"word_explain":"「伺う」là khiêm nhường ngữ của 「聞く」(hỏi), kết hợp 「〜てもよろしいでしょうか」(\"tôi xin phép hỏi tên được không ạ?\") là mẫu kính ngữ chuẩn khi nghe điện thoại.","translation_vi":"(Qua điện thoại) A: \"Cảm ơn quý khách đã gọi điện. Đây là phòng Kinh doanh công ty Xây dựng Kurokawa.\" B: \"Cho hỏi anh/chị Takahashi có ở đó không ạ?\" A: \"Xin lỗi, tôi có thể hỏi tên quý khách được không ạ?\""},{"mondai":8,"q":13,"prompt":"「さわら」という魚は、漢字の「鰆」と書く＿＿＿　★　＿＿＿　＿＿＿魚の一つだ。","options":["ように","わかる","ことから","春を代表する"],"answer":2,"word_explain":"Thứ tự đúng: 3 → ★2 → 1 → 4. Cấu trúc 「〜ことからわかるように」 (\"như có thể thấy từ việc...\") và cụm danh từ 「春を代表する魚の一つだ」.","translation_vi":"Loài cá gọi là \"Sawara\" là một trong những loài cá tiêu biểu cho mùa xuân, như có thể hiểu qua việc nó được viết bằng chữ Hán là 「鰆」 (cá + xuân)."},{"mondai":8,"q":14,"prompt":"会議での西山さんのプレゼンは、普段はなかなか＿＿＿　＿＿＿　＿＿＿　★素晴らしかった。","options":["ぐらい","課長が","褒める","褒めることができない"],"answer":1,"word_explain":"Thứ tự đúng: 4 → 2 → 3 → ★1. 「なかなか〜ない」 đi với 「褒めることができない」 bổ nghĩa cho 「課長が」, sau đó là 「褒めるぐらい素晴らしかった」 (\"tuyệt vời đến mức trưởng phòng cũng khen\").","translation_vi":"Bài thuyết trình của anh Nishiyama trong cuộc họp tuyệt vời đến mức ngay cả trưởng phòng — người bình thường hiếm khi có thể khen ai — cũng phải khen ngợi."},{"mondai":8,"q":15,"prompt":"同じ気温＿＿＿　★　＿＿＿　＿＿＿は大きく変える","options":["感じ方","でも","温度や風の強さなど","によって"],"answer":3,"word_explain":"Thứ tự đúng: 2 → ★3 → 4 → 1. 「同じ気温でも」(dù cùng nhiệt độ) + 「温度や風の強さなどによって」(tùy thuộc vào...) + 「感じ方」 làm chủ ngữ cho vế sau.","translation_vi":"Ngay cả ở cùng một nhiệt độ, tùy vào nhiệt độ (độ ẩm) hay sức gió, v.v. mà cách cảm nhận cũng thay đổi rất lớn."},{"mondai":8,"q":16,"prompt":"「山川大学アニメ研究会」は＿＿＿　＿＿＿　★　＿＿＿できた団体だ。","options":["学生が","集まって","アニメが","すきでたまらないという"],"answer":1,"word_explain":"Thứ tự đúng: 3 → 4 → ★1 → 2. Mệnh đề định ngữ 「アニメがすきでたまらないという」 bổ nghĩa cho 「学生が」, tiếp nối 「集まってできた団体だ」.","translation_vi":"\"Hội nghiên cứu Anime Đại học Yamakawa\" là một tổ chức được thành lập bởi những sinh viên yêu thích anime đến mức không chịu nổi tập hợp lại."},{"mondai":8,"q":17,"prompt":"会社の今井先輩は自分はミスが多いといつも言っているが＿＿＿　★　＿＿＿　＿＿＿ように見える。","options":["新人で","何でも完璧にできている","わたしからすると","わからないことばかりの"],"answer":4,"word_explain":"Thứ tự đúng: 1 → ★4 → 3 → 2. 「新人でわからないことばかりのわたし」 (tôi — một người mới đầy điều chưa biết) + 「〜からすると」 (\"đối với / đứng từ góc độ của tôi thì\") + 「何でも完璧にできているように見える」.","translation_vi":"Tiền bối Imai ở công ty lúc nào cũng bảo mình hay mắc lỗi, nhưng dưới góc nhìn của một người mới còn đầy điều chưa biết như tôi thì anh ấy trông có vẻ làm mọi thứ đều hoàn hảo."},{"mondai":9,"q":18,"prompt":"Chỗ trống [48] trong đoạn văn trên.","options":["そこの紅葉","そんな紅葉","そちら","紅葉"],"answer":2,"word_explain":"Đoạn 1 vừa ca ngợi vẻ đẹp của lá đỏ mùa thu (紅葉). Đầu đoạn 2 dùng 「そんな紅葉ですが」 để quy chiếu lại \"lá đỏ mùa thu như thế\" và mở ý chuyển sang thực trạng bất thường.","translation_vi":"Nói về lá đỏ mùa thu như vậy, nhưng hôm trước trên TV tôi đã xem được tin tức rằng thời điểm lá đỏ đạt đỉnh đẹp nhất đang ngày càng muộn dần qua từng năm."},{"mondai":9,"q":19,"prompt":"Chỗ trống [49] trong đoạn văn trên.","options":["結局","確かに","しかし","つまり"],"answer":3,"word_explain":"Câu trước tác giả từng nghĩ chỉ cần qua mùa hè và nhiệt độ hạ xuống là lá đỏ chắc chắn sẽ bắt đầu, câu sau phủ định 「そうではありませんでした」 nên cần liên từ đối lập 「しかし」 (\"tuy nhiên\").","translation_vi":"Tuy nhiên, thực tế lại không phải như vậy."},{"mondai":9,"q":20,"prompt":"Chỗ trống [50] trong đoạn văn trên.","options":["始まらないのです","始まらないためです","始まらないのでしょうか","始まらないためでしょうか"],"answer":1,"word_explain":"Đoạn văn đang giải thích cơ chế thực tế: lá bắt đầu đổi màu khi nhiệt độ thấp nhất xuống khoảng dưới 8 độ, vì vậy nếu không giảm tới mức đó thì 「始まらないのです」 (dùng 「〜のです」 để giải thích nguyên lý/lý do). Không dùng 「〜ためです」 (sai cấu trúc) hay dạng nghi vấn 「〜のでしょうか」.","translation_vi":"Dù mùa thu có đến nhưng nếu nhiệt độ thấp nhất không giảm xuống đến một mức nhất định thì lá đỏ sẽ không bắt đầu chuyển màu."},{"mondai":9,"q":21,"prompt":"Chỗ trống [51] trong đoạn văn trên.","options":["感じているからだと思います","感じられるところだと思います","感じさせることができました","感じるようになりました"],"answer":4,"word_explain":"Câu kết bài diễn thuyết nêu lên sự thay đổi trong nhận thức của người viết sau khi biết về biến đổi của lá đỏ: 「〜ようになりました」 (\"đã trở nên cảm thấy / bắt đầu cảm nhận thấy\").","translation_vi":"Thông qua lá đỏ mùa thu, tôi đã bắt đầu cảm nhận mạnh mẽ hơn rằng sự nóng lên toàn cầu là một vấn đề rất gần gũi với chúng ta."}]},{"id":"g_2023_12","displayName":"12/2023","subtitle":"21 câu • Mondai 7–9 (Ngữ pháp)","m9_passage":"温泉の正しい入り方\n\n疲れを感じたとき、温泉に行きたくなるという人も多いのではないでしょうか。ただ、温泉に入って、元気になるどころか逆に疲れてしまったという声を聞くことも少なくありません。[48]、温泉は入り方を間違えると体に負担をかけてしまうのです。\n\n体に負担をかけないためにまずしてほしいのは、お湯に入る前に丁寧に「かけ湯」をすることです。心臓から遠い足先などから温泉のお湯をゆっくり、たっぷりかけていきましょう。「かけ湯」には、お湯の温度や温泉の成分に体を慣れさせるといった重要な役割があります。お湯に入る前には必ず「かけ湯」を[49]。\n\nそして、お湯に入っている時間にも注意が必要です。お湯に入っている時間は、ぬるく感じるお湯でも20分程度、熱いお湯なら3～5分程度にするのが良いと言われています。また、1日に何度も温泉に入るのもあまり良くありません。1日に1、2回、多くても3回程度にしておきましょう。\n\n温泉の成分が肌に負担を[50]。ですから、刺激の強い酸性の温泉に入ったときや、肌への刺激が強いと感じたときは、最後に温泉ではないお湯や水を体にかけ、肌に残った温泉の成分を流しましょう。なお、肌への刺激が強くなければ、流さないほうが温泉の成分が肌に残るのでおすすめです。\n\nせっかく疲れをとりに温泉に行ったのに、[51]もったいないですよね。正しい入り方で日ごろの疲れがとれますように。","questions":[{"mondai":7,"q":1,"prompt":"私の3人の兄はみんな料理が苦手で、一番上の兄(　　)、卵もうまく割れない。","options":["にとって","にしては","に比べて","に至っては"],"answer":4,"word_explain":"「Nに至っては」: đến lượt / ngay cả N thì thậm chí còn... (nêu ví dụ cực đoan hơn để nhấn mạnh). Các đáp án khác: にとって (đối với), にしては (so với ~ thì), に比べて (so với).","translation_vi":"Ba người anh của tôi ai cũng kém nấu ăn, đến anh cả thì ngay cả trứng cũng không đập khéo được."},{"mondai":7,"q":2,"prompt":"来週の説明会に参加するしない(　　)、この書類は必ず読んでおいてください。","options":["とはいえ","としても","に限らず","にかかわらず"],"answer":4,"word_explain":"「～するしないにかかわらず」: bất kể có làm ~ hay không. Các đáp án khác: とはいえ (tuy nói vậy nhưng), としても (cho dù là), に限らず (không chỉ giới hạn ở).","translation_vi":"Bất kể có tham gia buổi giới thiệu tuần tới hay không, xin hãy nhất định đọc trước tài liệu này."},{"mondai":7,"q":3,"prompt":"駅前に新しいラーメン屋がオープンしていた。(　　)できたのだろう。","options":["いまにも","まさか","いつのまに","そのうち"],"answer":3,"word_explain":"「いつのまに」: từ lúc nào không hay (dùng khi ngạc nhiên nhận ra sự việc đã diễn ra rồi). Các đáp án khác: いまにも (sắp sửa), まさか (chẳng lẽ), そのうち (chẳng bao lâu nữa).","translation_vi":"Trước nhà ga đã mở một quán ramen mới rồi. Không biết quán được mở từ lúc nào nhỉ."},{"mondai":7,"q":4,"prompt":"この植物は、寒さに強い(　　)、暑さや湿気に弱い。","options":["反面","点で","ものを","からといって"],"answer":1,"word_explain":"「A反面、B」: mặt khác / ngược lại (nêu hai mặt đối lập của cùng một đối tượng). Các đáp án khác: 点で (ở điểm là), ものを (thế mà lại - tiếc nuối), からといって (dù nói rằng ~ nhưng).","translation_vi":"Loài cây này chịu lạnh tốt, nhưng mặt khác lại yếu trước nóng và độ ẩm."},{"mondai":7,"q":5,"prompt":"A「今度北町に行くんだけど、おいしいレストラン、知らない？」 B「すし屋(　　)、1軒知ってるよ。」","options":["でいいし","でよければ","がいいと","がよくても"],"answer":2,"word_explain":"「Nでよければ」: nếu N cũng được thì... (đưa ra gợi ý khiêm tốn hoặc thay thế khi chưa chắc có đúng ý đối phương hoàn toàn không).","translation_vi":"A: \"Sắp tới mình định đến Kitamachi, cậu có biết nhà hàng nào ngon không?\" B: \"Nếu quán sushi cũng được thì mình biết một quán đấy.\""},{"mondai":7,"q":6,"prompt":"懐中電灯を(　　)、電池が切れていて、つかなかった。","options":["使おうとしたら","使うようにしたら","使おうとするなら","使うようにするなら"],"answer":1,"word_explain":"「Vようとしたら」: khi định làm V thì phát hiện/xảy ra sự việc ngoài ý muốn. Các dạng ようにする (cố gắng để) hay なら (nếu thì) không phù hợp ngữ cảnh.","translation_vi":"Khi tôi định bật đèn pin thì phát hiện hết pin nên đèn không sáng."},{"mondai":7,"q":7,"prompt":"(マラソン大会のホームページで) 周辺住民の方の迷惑になりますので、指定の駐車場以外には(　　)、お願いいたします。","options":["駐車なさらないよう","駐車していただくよう","駐車なさらないため","駐車していただくため"],"answer":1,"word_explain":"「なさる」(kính ngữ của する) + phủ định「ない」+「よう(に)お願いいたします」: kính trọng đề nghị người đọc đừng làm gì (駐車なさらないようお願いいたします).","translation_vi":"(Trên trang chủ giải marathon) Vì sẽ gây phiền phức cho cư dân xung quanh, xin quý vị vui lòng không đỗ xe ngoài bãi đỗ xe được chỉ định."},{"mondai":7,"q":8,"prompt":"林選手がオリンピックに出場できるかどうかは、今度の大会の結果(　　)。","options":["のみだ","次第だ","にほかならない","でも不思議ではない"],"answer":2,"word_explain":"「N次第だ」: tùy thuộc vào N (thường đi với cấu trúc ～かどうかは N次第だ). Các đáp án khác: のみだ (chỉ là), にほかならない (chính là / không ngoài), でも不思議ではない (dù ~ cũng không có gì lạ).","translation_vi":"Việc tuyển thủ Hayashi có thể tham dự Olympic hay không là tùy thuộc vào kết quả giải đấu lần này."},{"mondai":7,"q":9,"prompt":"最近、パソコンを使っていると、突然画面が真っ暗(　　)。故障しているのかもしれない。","options":["にすることがある","にしたところだ","になることがある","になったところだ"],"answer":3,"word_explain":"「真っ暗になる」(tự động từ: trở nên tối đen) +「Vることがある」(thỉnh thoảng xảy ra). Dạng ところだ (vừa mới) và にする (tha động từ) không hợp chủ ngữ 「画面が」 và trạng ngữ 「最近…使っていると」.","translation_vi":"Gần đây, khi đang dùng máy tính thì thỉnh thoảng màn hình bỗng tối đen. Có lẽ máy bị hỏng rồi cũng nên."},{"mondai":7,"q":10,"prompt":"あのときの友人の言葉は、夢をあきらめそうになっていた私にもう一度頑張ろうと(　　)。","options":["思ってくれた","思ってほしかった","思わせてくれた","思わせてほしかった"],"answer":3,"word_explain":"Thể sai khiến + てくれる「思わせてくれた」: lời nói của bạn đã khiến cho tôi nghĩ như vậy (mang sắc thái biết ơn).","translation_vi":"Lời nói của người bạn lúc đó đã khiến tôi—người đang sắp từ bỏ ước mơ—nghĩ rằng mình hãy cố gắng thêm một lần nữa."},{"mondai":7,"q":11,"prompt":"(会社で) 社長「あ、さっきの会議室にペンを忘れたみたいだ。」 秘書「では、私が取って(　　)。」","options":["おります","まいります","くださいます","いらっしゃいます"],"answer":2,"word_explain":"「Vてまいります」là khiêm nhường ngữ của「Vてきます」(đi làm gì rồi quay lại), thư ký nói với giám đốc về hành động của mình.","translation_vi":"(Ở công ty) Giám đốc: \"À, hình như tôi để quên bút ở phòng họp lúc nãy rồi.\" Thư ký: \"Vậy để tôi đi lấy về ạ.\""},{"mondai":7,"q":12,"prompt":"(電話で) 店員「お電話ありがとうございます。さくら美容院です。」 田中「あ、今日の7時に予約している田中ですが、ちょっと仕事が長引いていて……。できたら8時に変更して(　　)。」 店員「はい、大丈夫ですよ。」","options":["もらったらいかがですか","もらうのではないでしょうか","もらわなければなりませんか","もらえるとありがたいんですが"],"answer":4,"word_explain":"「Vてもらえるとありがたいんですが」: mẫu câu nhờ vả lịch sự, nhẹ nhàng (\"nếu anh/chị có thể làm V giúp tôi thì tôi rất cảm kích...\").","translation_vi":"(Qua điện thoại) Nhân viên: \"Cảm ơn quý khách đã gọi. Đây là salon tóc Sakura ạ.\" Tanaka: \"À, tôi là Tanaka đã đặt lịch lúc 7 giờ hôm nay, nhưng công việc hơi kéo dài một chút... Nếu được thì đổi sang 8 giờ giúp tôi thì tốt quá ạ.\" Nhân viên: \"Vâng, được ạ.\""},{"mondai":8,"q":13,"prompt":"この本の内容をきちんと　＿＿＿　★　＿＿＿　＿＿＿　多いだろう。","options":["それなりの","理解するには","難しいと感じる人も","知識が求められるので"],"answer":1,"word_explain":"Thứ tự đúng: 2 → ★1 → 4 → 3. 「きちんと理解するには」(để hiểu rõ) → 「それなりの知識が求められるので」(vì đòi hỏi kiến thức nhất định) → 「難しいと感じる人も多いだろう」(chắc cũng nhiều người thấy khó).","translation_vi":"Để hiểu rõ ràng nội dung cuốn sách này thì đòi hỏi kiến thức nhất định, nên chắc cũng có nhiều người cảm thấy khó."},{"mondai":8,"q":14,"prompt":"石油は、自動車や航空機などの　＿＿＿　★　＿＿＿　＿＿＿　原料としても利用されている。","options":["使われる","だけでなく","プラスチック製品を作る","燃料として"],"answer":1,"word_explain":"Thứ tự đúng: 4 → ★1 → 2 → 3. 「燃料として使われるだけでなく」(không chỉ được dùng làm nhiên liệu) → 「プラスチック製品を作る原料としても」(mà còn làm nguyên liệu tạo ra sản phẩm nhựa).","translation_vi":"Dầu mỏ không chỉ được sử dụng làm nhiên liệu cho ô tô hay máy bay mà còn được sử dụng làm nguyên liệu để sản xuất các sản phẩm nhựa."},{"mondai":8,"q":15,"prompt":"東鉄道竹山線内にある二つの信号機が故障しており、大事故が　＿＿＿　＿＿＿　★　＿＿＿　明らかになった。","options":["起きかねない","続いていたことが","状態が","危険な"],"answer":3,"word_explain":"Thứ tự đúng: 1 → 4 → ★3 → 2. 「大事故が起きかねない危険な状態が」(tình trạng nguy hiểm có khả năng xảy ra tai nạn lớn) + 「続いていたことが明らかになった」(việc nó đã kéo dài được làm rõ).","translation_vi":"Sự việc tình trạng nguy hiểm có thể xảy ra tai nạn lớn ở hai đèn tín hiệu bị hỏng trên tuyến Takeyama của đường sắt Higashi đã kéo dài nay đã được làm sáng tỏ."},{"mondai":8,"q":16,"prompt":"(インタビューで) 「店長になって最初の1年間は大変でした。店長になった　＿＿＿　＿＿＿　★　＿＿＿　と悩むこともありました。」","options":["といっても","ばかりで","わからないこと","自分でいいのか"],"answer":2,"word_explain":"Thứ tự đúng: 1 → 3 → ★2 → 4. 「店長になったといっても」(tuy nói là đã thành cửa hàng trưởng nhưng) + 「わからないことばかりで」(toàn chuyện chưa biết) + 「自分でいいのかと悩むこともありました」.","translation_vi":"(Trong buổi phỏng vấn) \"Năm đầu tiên sau khi trở thành cửa hàng trưởng thật vất vả. Nói là đã thành cửa hàng trưởng nhưng toàn những điều không biết, cũng có lúc tôi trăn trở liệu mình làm có ổn không.\""},{"mondai":8,"q":17,"prompt":"家を買うことについて　＿＿＿　＿＿＿　★　＿＿＿　簡単に引っ越せないのが嫌だと言っている。","options":["夫は","買ってしまうと","否定的な","一度"],"answer":4,"word_explain":"Thứ tự đúng: 3 → 1 → ★4 → 2. 「家を買うことについて否定的な夫は」(người chồng không tán thành việc mua nhà) + 「一度買ってしまうと」(một khi lỡ mua rồi thì).","translation_vi":"Người chồng có thái độ không tán thành về việc mua nhà nói rằng một khi đã mua rồi thì không thể chuyển nhà dễ dàng được, ông ấy ghét điều đó."},{"mondai":9,"q":18,"prompt":"Chỗ trống [48] trong đoạn văn trên","options":["実は","一方で","しかも","ちなみに"],"answer":1,"word_explain":"「実は」: Thực ra là... (dùng để giải thích sự thật/nguyên nhân đằng sau hiện tượng bất ngờ được nêu ở câu trước: đi tắm suối nước nóng tưởng khỏe lên mà lại mệt thêm).","translation_vi":"Thực ra, suối nước nóng nếu vào sai cách sẽ gây gánh nặng cho cơ thể."},{"mondai":9,"q":19,"prompt":"Chỗ trống [49] trong đoạn văn trên","options":["するからです","するのでしょう","するつもりです","するようにしてください"],"answer":4,"word_explain":"「～ようにしてください」: hãy cố gắng / nhớ làm ~ (lời khuyên/hướng dẫn nhất quán với giọng văn bài viết: ～してほしいのは…、～ていきましょう、～ておきましょう).","translation_vi":"Trước khi xuống bồn nước nóng, nhất định hãy thực hiện việc \"dội nước làm quen\" (kakeyu)."},{"mondai":9,"q":20,"prompt":"Chỗ trống [50] trong đoạn văn trên","options":["かけたとします","かけることもあります","かけたと思います","かけることにあります"],"answer":2,"word_explain":"「～こともあります」: cũng có trường hợp / cũng có lúc ~. Phù hợp với câu tiếp theo nêu trường hợp kích ứng mạnh thì nên xả lại bằng nước thường, còn không kích ứng mạnh thì không cần xả.","translation_vi":"Thành phần của suối nước nóng cũng có lúc gây gánh nặng cho làn da."},{"mondai":9,"q":21,"prompt":"Chỗ trống [51] trong đoạn văn trên","options":["疲れてしまい","疲れてしまったのが","疲れてしまっては","疲れてしまうばかりで"],"answer":3,"word_explain":"「～てはもったいない」: nếu mà lại ~ thì thật lãng phí/đáng tiếc (nêu giả định điều không mong muốn đi kèm đánh giá tiêu cực).","translation_vi":"Cất công đi suối nước nóng để giải tỏa mệt mỏi mà lại mệt mất thì thật lãng phí phải không nào."}]},{"id":"g_2023_07","displayName":"07/2023","subtitle":"21 câu • Mondai 7–9 (Ngữ pháp)","m9_passage":"以下は、留学生がスピーチのために書いた文章である。\n\n香道\nベルナールマリー\n\n「香道」とは、香りを楽しむ日本の伝統文化です。私は、友人が香道の体験ができる教室に誘ってくれたのをきっかけに、初めて香道のことを知りました。私は普段から香水などで香りを楽しんでいるので、香道の体験も楽しむことができました。\n\n香道は、「香木」と呼ばれる木の破片を熱し、その香りを楽しみます。「香木」[48]そのような名前の木がもともと存在するわけではありません。いくつかの種類の木の中で、様々な自然条件のもとで、年月の経過によって香りを発生させるようになった木をそう呼びます。人工的に生産できないため、大変貴重なものと[49]。\n\n香道には600年以上の歴史がありますが、その存在はあまり知られていません。数に限りがある香木は、香道が広まり需要が増えすぎればなくなるおそれもあります。[50]、香道ではあまり多くの弟子を受け入れませんでした。香道がよく知られていないのは、そういった事情もあるそうです。\n\n香道では、香りをかいで、じっくりと味わうことを「香りを聞く」と言います。香りに心を傾けて聞くことを基本に、香りを聞きながら古典文学を鑑賞したり、どれがどの香木の香りかを当てて楽しんだりもします。\n\n繊細な香りを心の中でゆっくり味わうことを通して、私は「香りを聞く」という意味がわかったような気がしました。香水のように手軽ではありませんが、このような香りの楽しみ方も[51]。","questions":[{"mondai":7,"q":1,"prompt":"この小説は、物語が進む(　　)主人公の少年の心理が変化していくのが面白い。","options":["としても","とはいえ","につれて","にあたって"],"answer":3,"word_explain":"Vるにつれて: càng... càng..., cùng với sự tiến triển của V thì trạng thái sau cũng biến đổi theo.","translation_vi":"Cuốn tiểu thuyết này hay ở chỗ tâm lý của cậu bé nhân vật chính dần thay đổi theo diễn biến của câu chuyện."},{"mondai":7,"q":2,"prompt":"昨日行ったレストランは、味もサービスも最低だった。(　　)行きたくない。","options":["二度と","必ずしも","まさか","あまりに"],"answer":1,"word_explain":"二度と〜ない: không bao giờ... nữa, nhất quyết không lặp lại lần thứ hai.","translation_vi":"Nhà hàng hôm qua tôi đi cả hương vị lẫn dịch vụ đều tệ hết sức. Tôi không bao giờ muốn đến đó lần nữa."},{"mondai":7,"q":3,"prompt":"今回のオリンピックで、体操の青木選手は、メダルは獲得できなかった(　　)、素晴らしい演技も見せてくれた。","options":["からといって","どころか","あげくに","ものの"],"answer":4,"word_explain":"〜ものの: tuy là... nhưng... (nối hai vế tương phản, thừa nhận vế trước nhưng nhấn mạnh vế sau).","translation_vi":"Tại kỳ Olympic lần này, tuy vận động viên thể dục dụng cụ Aoki không giành được huy chương nhưng anh ấy cũng đã thể hiện một màn trình diễn tuyệt vời."},{"mondai":7,"q":4,"prompt":"60代の父が、趣味(　　)何歳から始めても遅くないだろうと言って、最近ピアノ教室にか通い始めた","options":["としてだけ","としてなら","にとっては","にとっても"],"answer":2,"word_explain":"Nとしてなら: nếu xét với tư cách là N / nếu chỉ coi là N thì... (phù hợp với nghĩa \"nếu là sở thích thì tuổi nào bắt đầu cũng được\").","translation_vi":"Bố tôi ngoài 60 tuổi bảo rằng nếu là với tư cách sở thích thì bắt đầu ở độ tuổi nào cũng không muộn, rồi gần đây ông đã bắt đầu đi học lớp piano."},{"mondai":7,"q":5,"prompt":"約束の時間に友人の家に着いてインターホンを押すと、慌てた様子で友人が玄関に出てきた。(　　)、パジャマの姿のままだった。","options":["起きるところだったら","起きるところらしく","起きたばかりだったら","起きたばかりらしく"],"answer":4,"word_explain":"Vたばかり (vừa mới làm xong) + らしく (dạng liên dụng của らしい, phỏng đoán dựa trên dấu hiệu bên ngoài: có vẻ như vừa mới dậy nên...).","translation_vi":"Tôi đến nhà bạn đúng giờ hẹn và bấm chuông thì bạn tôi hớt hải bước ra cửa. Có vẻ như cậu ấy vừa mới ngủ dậy nên vẫn còn mặc nguyên đồ ngủ."},{"mondai":7,"q":6,"prompt":"「リマインド」とは「再確認」の意味を持ち、「会議の日程が近づいてきたので、出席者にリマインドした。」(　　)使用されるビジネス用語である。","options":["というように","というような","ということのように","ということのような"],"answer":1,"word_explain":"〜というように + động từ (使用される): theo cách như là... (dùng để nêu câu ví dụ minh họa cho cách sử dụng). というような phải đi với danh từ.","translation_vi":"\"Remind\" mang nghĩa là \"xác nhận lại\", là một thuật ngữ kinh doanh được sử dụng theo cách như: \"Vì lịch họp đã đến gần nên tôi đã nhắc lại cho những người tham dự.\""},{"mondai":7,"q":7,"prompt":"学校や病院では定期的に避難訓練が行われている。避難訓練を(　　)、火災などがあったときに落ち着いて行動できるからだ。","options":["しておくには","しているとしても","しておくことで","しているかという"],"answer":3,"word_explain":"Vておく (làm sẵn, chuẩn bị trước) + ことで (bằng việc, nhờ việc...). Nhờ tập dượt trước nên khi có hỏa hoạn mới bình tĩnh xử lý được.","translation_vi":"Ở trường học và bệnh viện, việc diễn tập sơ tán được tiến hành định kỳ. Đó là vì nhờ việc diễn tập sẵn như vậy mà khi xảy ra hỏa hoạn hay sự cố, mọi người có thể hành động một cách bình tĩnh."},{"mondai":7,"q":8,"prompt":"明日、友達と映画を見に行くことになった。映画館で映画を見るのは、大学の時以来だから、約5年(　　)だ","options":["まで","など","きり","ぶり"],"answer":4,"word_explain":"[Khoảng thời gian] + ぶりだ: sau một khoảng thời gian dài mới lặp lại một việc gì đó (\"sau khoảng 5 năm mới lại...\").","translation_vi":"Ngày mai tôi sẽ đi xem phim cùng bạn. Đã từ thời đại học rồi mới lại đi xem phim ở rạp nên tính ra là khoảng 5 năm rồi mới đi lại."},{"mondai":7,"q":9,"prompt":"睡眠には、体や脳にたまった疲労をとる効果がある。睡眠時間を削ることは、体や脳を回復させる大切な機会を奪うことに(　　)のだ。","options":["ほかならない","欠かせない","すぎない","限らない"],"answer":1,"word_explain":"〜にほかならない: không gì khác chính là... (khẳng định mạnh mẽ bản chất của sự việc).","translation_vi":"Giấc ngủ có tác dụng giải tỏa mệt mỏi tích tụ trong cơ thể và não bộ. Việc cắt giảm thời gian ngủ không gì khác chính là tước đi cơ hội quý giá giúp cơ thể và não bộ hồi phục."},{"mondai":7,"q":10,"prompt":"（会社で） 木村：「山下さん、先ほどさくら銀行の南さんからお電話がありまして。今日中に連絡してほしい(　　)。 山下：「はい、わかりました」","options":["ことになりました","とのことでした","と助かるのですが","ようにしてください"],"answer":2,"word_explain":"〜とのことだ / とのことでした: nghe nói rằng / có lời nhắn rằng (truyền đạt lại lời của người khác một cách lịch sự).","translation_vi":"(Ở công ty) Kimura: \"Anh Yamashita ơi, lúc nãy có điện thoại của anh Minami bên ngân hàng Sakura. Anh ấy nhắn là muốn anh liên lạc trong hôm nay.\" Yamashita: \"Vâng, tôi hiểu rồi.\""},{"mondai":7,"q":11,"prompt":"駅前に新しくできたカフェに友達を誘って行ってみたら、定休日だった。事前に確認しておく(　　)。","options":["しかなかった","ほどではなかった","べきだった","せいだった"],"answer":3,"word_explain":"Vるべきだった: lẽ ra đã nên làm... (bày tỏ sự hối tiếc về việc đã không làm).","translation_vi":"Tôi rủ bạn đến thử quán cà phê mới mở trước nhà ga thì lại trúng ngày nghỉ định kỳ. Lẽ ra tôi nên kiểm tra trước mới phải."},{"mondai":7,"q":12,"prompt":"（インタビューで） 選手「今回優勝できたのは、多くの方に(　　)。本当にありがとうございました。」","options":["応援してくださったおかげです","応援していただいたおかげです","応援してくださったことだと思います","応援していただいたことだと思います"],"answer":2,"word_explain":"Khi dùng ～ていただく (nhận được sự giúp đỡ từ ai), đối tượng thực hiện đi với trợ từ に (多くの方に応援していただいた), kết hợp ～のは～おかげです (có được thành quả là nhờ...).","translation_vi":"(Trong buổi phỏng vấn) Vận động viên: \"Lần này tôi có thể giành chức vô địch là nhờ có sự cổ vũ của rất nhiều người. Xin chân thành cảm ơn.\""},{"mondai":8,"q":13,"prompt":"隣のクラスの友達とけんかしてしまい、学校の廊下で ＿＿＿　＿＿＿　★　＿＿＿ なくなってしまった。","options":["こと","すら","目を合わせる","すれ違っても"],"answer":1,"word_explain":"Thứ tự đúng: 4 → 3 → ★1 → 2. Cấu trúc Vることすら〜ない (thậm chí ngay cả việc V cũng không). Cụm hoàn chỉnh: すれ違っても目を合わせることすらなくなってしまった。","translation_vi":"Vì đã cãi nhau với người bạn ở lớp bên cạnh nên dù có đi lướt qua nhau ở hành lang trường, chúng tôi thậm chí không còn nhìn mặt nhau nữa."},{"mondai":8,"q":14,"prompt":"このソファーは、それなりの大きさはあるが、見た目 ＿＿＿　＿＿＿　★　＿＿＿ 楽に動かせる。","options":["ほどの","でも","重さはないため","一人"],"answer":4,"word_explain":"Thứ tự đúng: 1 → 3 → ★4 → 2. Mẫu Nほどの〜はない (không có mức độ như N) + ため (vì) và 一人でも (ngay cả một mình cũng...). Cụm hoàn chỉnh: 見た目ほどの重さはないため一人でも楽に動かせる。","translation_vi":"Chiếc ghế sofa này tuy có kích thước khá lớn nhưng vì không nặng như vẻ ngoài của nó nên một mình cũng có thể di chuyển dễ dàng."},{"mondai":8,"q":15,"prompt":"友達にスキー旅行に誘われている。返事を ＿＿＿　＿＿＿　★　＿＿＿ まだ返事ができていない。","options":["決まっていなくて","仕事の予定が","しなければ","と思いながらも"],"answer":2,"word_explain":"Thứ tự đúng: 3 → 4 → ★2 → 1. Cấu trúc 返事をしなければと思いながらも (dù nghĩ phải trả lời nhưng) + 仕事の予定が決まっていなくて (vì lịch làm việc chưa cố định nên).","translation_vi":"Tôi đang được bạn rủ đi du lịch trượt tuyết. Dù vẫn nghĩ là phải trả lời nhưng vì lịch trình công việc chưa được chốt nên tôi vẫn chưa thể hồi âm được."},{"mondai":8,"q":16,"prompt":"私は、美術館では音声ガイドの機械を借りて、説明を聞きながら作品を鑑賞する。作品のどこに ＿＿＿　＿＿＿　★　＿＿＿ その作品をより深く味わえるからだ。","options":["わかると","注目して","いいのかが","鑑賞したら"],"answer":3,"word_explain":"Thứ tự đúng: 2 → 4 → ★3 → 1. Mẫu nghi vấn từ + Vたらいいのかがわかる (biết được nên làm thế nào). Cụm hoàn chỉnh: 作品のどこに注目して鑑賞したらいいのかがわかると。","translation_vi":"Ở bảo tàng mỹ thuật, tôi thuê máy thuyết minh âm thanh và vừa nghe giải thích vừa thưởng thức tác phẩm. Bởi vì khi biết được nên chú ý vào điểm nào của tác phẩm để thưởng thức thì ta có thể cảm nhận sâu sắc hơn tác phẩm đó."},{"mondai":8,"q":17,"prompt":"雪が降っている ＿＿＿　＿＿＿　★　＿＿＿ 風がほとんどないからだろう。","options":["わりに","のは","寒く感じない","そんなに"],"answer":3,"word_explain":"Thứ tự đúng: 1 → 4 → ★3 → 2. Cấu trúc Vるわりに (tuy... nhưng / so với việc... thì) kết hợp 〜のは〜からだろう (việc... là vì...). Cụm hoàn chỉnh: 雪が降っているわりにそんなに寒く感じないのは。","translation_vi":"Sở dĩ không cảm thấy lạnh đến thế dù tuyết đang rơi, có lẽ là vì hầu như không có gió."},{"mondai":9,"q":18,"prompt":"Chỗ trống [48] trong đoạn văn trên","options":["のように","のほかに","といっても","であっても"],"answer":3,"word_explain":"Nといっても: tuy nói là N nhưng... (dùng để giải thích rằng thực tế không phải như tên gọi \"hương mộc\" dễ khiến người ta lầm tưởng).","translation_vi":"Tuy gọi là \"hương mộc\", nhưng vốn dĩ không phải tồn tại một loài cây có tên như vậy."},{"mondai":9,"q":19,"prompt":"Chỗ trống [49] trong đoạn văn trên","options":["しておきます","されています","しておく点です","されている点です"],"answer":2,"word_explain":"Nとされている (ở đây lịch sự là とされています): được xem là / được coi là (phù hợp cấu trúc câu trần thuật không có chủ ngữ dạng 〜のは).","translation_vi":"Vì không thể sản xuất nhân tạo nên nó được coi là một thứ vô cùng quý giá."},{"mondai":9,"q":20,"prompt":"Chỗ trống [50] trong đoạn văn trên","options":["一方","ちなみに","ところが","そのため"],"answer":4,"word_explain":"そのため (vì vậy / do đó): chỉ mối quan hệ nhân quả trực tiếp với câu trước (vì sợ hương mộc cạn kiệt nếu nhu cầu tăng cao nên không nhận nhiều đệ tử).","translation_vi":"Vì thế, trong Hương đạo người ta đã không tiếp nhận quá nhiều đệ tử."},{"mondai":9,"q":21,"prompt":"Chỗ trống [51] trong đoạn văn trên","options":["いいものだと思います","いいと思ったのでしょう","よかったはずです","よかったのではありませんか"],"answer":1,"word_explain":"〜ものだと思います: diễn tả cảm nhận, đánh giá chân thành của chính người viết ở phần kết bài phát biểu.","translation_vi":"Tuy không tiện lợi như nước hoa, nhưng tôi nghĩ cách thưởng thức hương thơm như thế này cũng thật tuyệt vời."}]},{"id":"g_2022_12","displayName":"12/2022","subtitle":"21 câu • Mondai 7–9 (Ngữ pháp)","m9_passage":"現代人は座りすぎだとよく言われます。皆がずっと席に座ってパソコンで作業をしているという職場も珍しくないのではないでしょうか。座りすぎが様々な体の不調の原因になるという研究報告も[48]。座りすぎは、日本人の4人に1人が抱えているという腰の痛みの原因にもなると考えられています。\n\n座っている姿勢は体にあまり負担がかかっていないと思うかもしれません。[49]、座り方によっては、実は立っているときの2倍もの負担が腰にかかるのだそうです。座っている時間が長くなるほど、腰への負担も大きくなり、それが腰痛につながります。かといって、ずっと立ったまま仕事をするというのも現実的ではありません。長時間立っていると、足に疲れがたまってしまうという問題もあります。大切なのは、[50]姿勢を長く続けないことです。理想は30分に1回、少なくとも1時間に一回立って、少し動くのがいいとされています。\n\n実際に、仕事中に時々立って動くようにしてみた人の多くが、腰痛の改善や疲れを感じにくいといった効果を感じているようです。座りっぱなしを避け、時々立って体を動かすことは、気軽にできる腰痛対策であり、仕事中の集中力維持にもつながります。職場で座っている時間が長い人は、[51]。","questions":[{"mondai":7,"q":1,"prompt":"先週末は、(　　)かけだった3冊の本をすべて最後まで読んだ。","options":["読む","読み","読んで","読んだ"],"answer":2,"word_explain":"Cấu trúc 「Vます (bỏ ます) + かけだ」 diễn tả hành động đang làm dở dang, chưa hoàn thành (ở đây là \"đọc dở\").","translation_vi":"Cuối tuần trước, tôi đã đọc hết đến trang cuối cả 3 cuốn sách đang đọc dở."},{"mondai":7,"q":2,"prompt":"子供のころはピーマンが嫌いだったが、今は嫌いではない。(　　)好きな野菜の一つだ。","options":["むしろ","いったい","そのうち","ちっとも"],"answer":1,"word_explain":"「むしろ」 mang nghĩa \"đúng hơn là / trái lại\", dùng để đính chính hoặc nhấn mạnh mức độ cao hơn so với nhận định trước đó.","translation_vi":"Hồi nhỏ tôi ghét ớt chuông, nhưng bây giờ thì không ghét nữa. Đúng hơn là nó còn là một trong những loại rau tôi thích."},{"mondai":7,"q":3,"prompt":"来年3月の完成(　　)、新しい体育館の建設工事が着々と進んでいる。","options":["を込めて","に際して","を通じて","に向けて"],"answer":4,"word_explain":"「N + に向けて」 có nghĩa là \"hướng tới (mục tiêu/thời điểm nào đó)\", diễn tả hành động chuẩn bị hoặc tiến hành để đạt tới mốc đó.","translation_vi":"Hướng tới việc hoàn thành vào tháng 3 năm sau, công trình xây dựng nhà thi đấu mới đang được tiến hành một cách thuận lợi."},{"mondai":7,"q":4,"prompt":"(携帯電話の店で) 父「どれにしようかな。通話ができれば十分なんだけど」 息子「通話ができるだけ(　　)、これにしたら?」","options":["がいいと","でいいなら","でいいけど","がいいのに"],"answer":2,"word_explain":"「～でいいなら」 nghĩa là \"nếu chỉ cần ~ là được thì...\", tiếp nhận điều kiện tối thiểu mà đối phương vừa nói để đưa ra gợi ý.","translation_vi":"(Ở cửa hàng điện thoại) Bố: \"Chọn cái nào đây nhỉ. Chỉ cần gọi điện được là đủ rồi.\" Con trai: \"Nếu chỉ cần gọi điện được là ổn thì bố chọn cái này đi?\""},{"mondai":7,"q":5,"prompt":"課長に、次の会議までにこの資料を(　　)言われた。","options":["読んでおくように","読んでおきなさい","読んでくるか","読んでこい"],"answer":1,"word_explain":"Cấu trúc 「Vる / Vない + ように言われる」 dùng để tường thuật lại lời yêu cầu, dặn dò của người khác (\"được bảo/dặn là hãy...\").","translation_vi":"Tôi được trưởng phòng dặn là hãy đọc trước tài liệu này trước cuộc họp tiếp theo."},{"mondai":7,"q":6,"prompt":"休みの日(　　)、昼過ぎまで寝ているのはよくないと思う。","options":["どころか","かというと","にしては","だからといって"],"answer":4,"word_explain":"「N + だからといって」 mang nghĩa \"dù nói là ~ đi chăng nữa (nhưng...)\", dùng để phủ định hoặc phê phán một hành động/suy nghĩ dựa trên lý do đó.","translation_vi":"Dù là ngày nghỉ đi chăng nữa, tôi nghĩ việc ngủ đến quá trưa cũng không tốt."},{"mondai":7,"q":7,"prompt":"先月から食堂でアルバイトを始めた。お客さんがおいしいと(　　)、うれしくなり、もっと頑張ろうと思える。","options":["言ってあげるたびに","言ってあげるように","言ってくれるたびに","言ってくれるように"],"answer":3,"word_explain":"「Vる + たびに」 nghĩa là \"mỗi lần...\", kết hợp với 「～てくれる」 để chỉ việc người khác (khách hàng) nói điều tốt đẹp cho mình.","translation_vi":"Từ tháng trước tôi bắt đầu làm thêm ở nhà ăn. Mỗi lần khách hàng khen ngon, tôi lại thấy vui và có động lực cố gắng hơn nữa."},{"mondai":7,"q":8,"prompt":"(映画館で) 夫「席の番号、忘れちゃった。何番(　　)?」 妻「Jの14と15だよ」","options":["だったよね","だっけ","じゃなかったの","なんじゃないか"],"answer":2,"word_explain":"「～だっけ」 dùng ở cuối câu hỏi khi người nói quên mất thông tin từng biết và muốn hỏi lại để nhớ ra (\"...ấy nhỉ?\").","translation_vi":"(Ở rạp chiếu phim) Chồng: \"Anh quên mất số ghế rồi. Số mấy ấy nhỉ?\" Vợ: \"J14 và J15 đấy.\""},{"mondai":7,"q":9,"prompt":"「倉庫の中を片付けなければ」と前からずっと思っているのだが、忙しくてなかなか(　　)。","options":["できずにいる","できるだろうか","できないこともない","できるのではないか"],"answer":1,"word_explain":"「Vず(に)いる」 (với する → せずに / できる → できずにいる) diễn tả trạng thái không thể thực hiện hành động nào đó suốt một khoảng thời gian cho đến hiện tại.","translation_vi":"Từ trước đến nay tôi vẫn luôn nghĩ \"phải dọn dẹp trong nhà kho mới được\", nhưng vì bận quá nên mãi vẫn chưa làm được."},{"mondai":7,"q":10,"prompt":"(劇場ないのアナウンスで) スタッフ「お客様にご案内(　　)。ただいま、一階ロビーにおいて、公演パンフレントを販売しております、ぜひご利用ください」","options":["なさいます","うけたまわります","申し上げます","おっしゃいます"],"answer":3,"word_explain":"「ご案内申し上げます」 là cách nói khiêm nhường ngữ trang trọng (ご + danh từ + 申し上げます) dùng để thông báo, hướng dẫn cho khách hàng.","translation_vi":"(Thông báo trong nhà hát) Nhân viên: \"Xin trân trọng thông báo tới quý khách. Hiện tại ở sảnh tầng 1 đang bày bán tập giới thiệu buổi diễn, xin mời quý khách ghé mua.\""},{"mondai":7,"q":11,"prompt":"昨日はかなり風が強くて、何度も帽子を(　　)。","options":["飛ばされたところだ","飛んでいったところだ","飛ばされそうになった","飛んでいきそうになった"],"answer":3,"word_explain":"Cấu trúc bị động phiền toái 「(帽子を) 飛ばされる」 kết hợp với 「Vます + そうになった」 nghĩa là \"suýt nữa thì bị (gió) thổi bay\". Vì phía trước có trợ từ 「を」 nên không dùng tự động từ 「飛んでいく」.","translation_vi":"Hôm qua gió khá mạnh, suýt nữa thì tôi bị gió thổi bay mũ mấy lần liền."},{"mondai":7,"q":12,"prompt":"昨日、最近評判のレストランに行った。サービスと雰囲気はとてもよかったが、味は(　　)。","options":["期待していなかったせいでだ","期待していたからではなかった","期待していなかったはずだ","期待していたほどではなかった"],"answer":4,"word_explain":"「Vていた + ほどではなかった」 nghĩa là \"không đến mức như đã...\", diễn tả thực tế không đạt được như mức độ đã kỳ vọng.","translation_vi":"Hôm qua tôi đã đến nhà hàng gần đây rất nổi tiếng. Dịch vụ và không khí rất tốt, nhưng hương vị thì không ngon như tôi đã kỳ vọng."},{"mondai":8,"q":13,"prompt":"私はとにかく勉強が嫌いで、学校があまりすきではない子供だった。そんな ＿＿＿　＿＿＿　★　＿＿＿ きっかけだった。","options":["ある先生との","教師になりたいと思ったのは","私が","出会いが"],"answer":1,"word_explain":"Thứ tự đúng: 3 → 2 → ★1 → 4. Câu hoàn chỉnh: 「そんな私が教師になりたいと思ったのはある先生との出会いがきっかけだった。」 (Cấu trúc nhấn mạnh 「～のは…がきっかけだ」: Việc mà một người như tôi muốn trở thành giáo viên là bắt nguồn từ cuộc gặp gỡ với một người thầy).","translation_vi":"Hồi nhỏ tôi cực kỳ ghét học và không thích trường học lắm. Việc một người như tôi lại muốn trở thành giáo viên bắt nguồn từ cuộc gặp gỡ với một người thầy."},{"mondai":8,"q":14,"prompt":"若いときに努力して ＿＿＿　＿＿＿　★　＿＿＿ なって必ず将来役に立つと思う。","options":["経験は","目標を","自信と","達成した"],"answer":1,"word_explain":"Thứ tự đúng: 2 → 4 → ★1 → 3. Câu hoàn chỉnh: 「若いときに努力して目標を達成した経験は自信となって必ず将来役に立つと思う。」 (Cụm 「目標を達成した経験」 làm chủ ngữ với 「は」, theo sau là 「自信となって」 nghĩa là \"trở thành sự tự tin\").","translation_vi":"Tôi nghĩ rằng kinh nghiệm nỗ lực đạt được mục tiêu khi còn trẻ sẽ trở thành sự tự tin và chắc chắn có ích cho tương lai."},{"mondai":8,"q":15,"prompt":"この町では、都心で家を借りる ＿＿＿　＿＿＿　★　＿＿＿ 家が借りられる。","options":["場合","半分程度の","家賃で","と比べて"],"answer":2,"word_explain":"Thứ tự đúng: 1 → 4 → ★2 → 3. Câu hoàn chỉnh: 「この町では、都心で家を借りる場合と比べて半分程度の家賃で家が借りられる。」 (「～場合と比べて」: so với trường hợp...; 「半分程度の家賃で」: với tiền thuê nhà khoảng một nửa).","translation_vi":"Ở thị trấn này, so với việc thuê nhà ở trung tâm thành phố thì có thể thuê được nhà với tiền thuê chỉ bằng khoảng một nửa."},{"mondai":8,"q":16,"prompt":"＿＿＿　＿＿＿　★　＿＿＿ 酸素や栄養が十分に細胞に届かなくなってしまう。","options":["運ばれる","悪くなると","血液の流れが","血液によって"],"answer":4,"word_explain":"Thứ tự đúng: 3 → 2 → ★4 → 1. Câu hoàn chỉnh: 「血液の流れが悪くなると血液によって運ばれる酸素や栄養が十分に細胞に届かなくなってしまう。」 (「血液の流れが悪くなると」: nếu tuần hoàn máu kém đi; 「血液によって運ばれる」 bổ nghĩa cho 「酸素や栄養」).","translation_vi":"Khi tuần hoàn máu kém đi, oxy và chất dinh dưỡng được máu vận chuyển sẽ không thể đến được tế bào một cách đầy đủ."},{"mondai":8,"q":17,"prompt":"さくら駅周辺の再開発事業を行う ＿＿＿　＿＿＿　★　＿＿＿ 予定だ。","options":["さくら市は","に先立って","関係者に対する","説明会を開催する"],"answer":3,"word_explain":"Thứ tự đúng: 2 → 1 → ★3 → 4. Câu hoàn chỉnh: 「さくら駅周辺の再開発事業を行うに先立って、さくら市は関係者に対する説明会を開催する予定だ。」 (「V辞書形 + に先立って」 nghĩa là \"trước khi thực hiện...\"; 「関係者に対する説明会」 là \"buổi giải trình dành cho các bên liên quan\").","translation_vi":"Trước khi tiến hành dự án tái phát triển khu vực quanh ga Sakura, thành phố Sakura dự định sẽ tổ chức buổi giải trình dành cho các bên liên quan."},{"mondai":9,"q":18,"prompt":"Chỗ trống [48] trong đoạn văn trên","options":["増えそうでした","増えてきました","増えていきました","増えたところでした"],"answer":2,"word_explain":"「Vて + きました (～てくる)」 diễn tả sự biến đổi, gia tăng từ trước đến thời điểm hiện tại (\"ngày càng tăng lên\").","translation_vi":"Các báo cáo nghiên cứu chỉ ra rằng việc ngồi quá nhiều là nguyên nhân gây ra nhiều bất ổn về sức khỏe cũng ngày càng tăng lên."},{"mondai":9,"q":19,"prompt":"Chỗ trống [49] trong đoạn văn trên","options":["つもり","しかも","ところが","というのは"],"answer":3,"word_explain":"「ところが」 là liên từ chỉ sự chuyển ý trái ngược với dự đoán hoặc suy nghĩ ở câu trước (\"thế nhưng / tuy nhiên\").","translation_vi":"Thế nhưng, tùy vào cách ngồi mà thực chất thắt lưng phải chịu áp lực gấp đôi so với khi đứng."},{"mondai":9,"q":20,"prompt":"Chỗ trống [50] trong đoạn văn trên","options":["同じ","違う","この","以下の"],"answer":1,"word_explain":"「同じ」 (cùng một): đoạn trước đề cập cả ngồi lâu và đứng lâu đều có hại, nên điều quan trọng là không giữ \"cùng một\" tư thế trong thời gian dài.","translation_vi":"Điều quan trọng là không duy trì cùng một tư thế trong thời gian dài."},{"mondai":9,"q":21,"prompt":"Chỗ trống [51] trong đoạn văn trên","options":["試してもいいですか","試したらいいのでしょうか","試してみればよかったですか","試してみてはいかがでしょうか"],"answer":4,"word_explain":"「Vて + みてはいかがでしょうか」 là cách nói đề xuất, khuyên nhủ lịch sự dành cho người đọc (\"bạn hãy thử ~ xem sao\").","translation_vi":"Những người có thời gian ngồi nhiều ở nơi làm việc, bạn hãy thử áp dụng cách này xem sao?"}]},{"id":"g_2022_07","displayName":"07/2022","subtitle":"21 câu • Mondai 7–9 (Ngữ pháp)","m9_passage":"地下駐輪場\n\n誰もが安全に、そして快適に暮らせる街をつくるため、各自治体はさまざまな取り組みを行っている。特に都市部において、駅周辺の整備は重要な課題となる。\n\n今回取り上げるのは、自転車の[48]出し。多くの駅には駐輪場が設置されているが、スペースには限りがある。駐輪場を利用できない人が多くなると、道路や歩道など許可されていない場所に置かれる自転車が増え、車両や歩行者の通行の妨げになってしまう。\n\nそこで有効になるのが地下空間の利用だ。地下に駐輪場があること自体はそれほど珍しくない。だが最近では、新しいタイプの地下駐輪場も見られる。それは、地下に[49]。全自動式の地下駐輪場なのだ。自転車だけを運ぶエレベーターが設置されており、地上で自転車をエレベーターに乗せてボタンを押すと、機械によって地下の駐輪スペースへと運ばれる。そして、機械が判断して空いている場所へ収納してくれる。取り出すときも、暗証番号を入力すれば、機械が地上へ運んできてくれる。\n\n[50]にはさまざまなメリットがある。たとえば、出し入れの手軽さだ。荷物が多い人や子供連れにとっては、駐輪場の中を移動せずに自転車を取り出せるというのは非常に便利だ。また、人が出入りしないので、盗難の心配もない。\n\n駐輪場不足を解決し、より快適で安全な街に[51]、全自動式の地下駐輪場の設置は有効な手段の一つだといえる。今後も増えていきそうだ。","questions":[{"mondai":7,"q":1,"prompt":"このカレーは１５分（　　）あればできるので、よく作る","options":["を","も","に","が"],"answer":2,"word_explain":"[Số lượng/Thời lượng] + も + あれば～: chỉ cần có (chỉ khoảng thời gian/số lượng tối thiểu là đủ).","translation_vi":"Món cà ri này chỉ cần khoảng 15 phút là làm xong nên tôi thường xuyên nấu."},{"mondai":7,"q":2,"prompt":"A「新しい携帯電話、ちょっと使いづらいんだよね」 B「使っていれば（　　）慣れるよ」","options":["いまにも","ようやく","そのうち","いつのまに"],"answer":3,"word_explain":"そのうち: chẳng bao lâu nữa, dần dần rồi cũng (chỉ sự thay đổi xảy ra trong tương lai gần). いまにも là sắp sửa xảy ra ngay tức thì; ようやく là cuối cùng cũng (sau nỗ lực).","translation_vi":"A: \"Chiếc điện thoại mới này hơi khó dùng nhỉ.\" B: \"Cứ dùng rồi chẳng mấy chốc sẽ quen thôi.\""},{"mondai":7,"q":3,"prompt":"今朝は寝坊してしまい、食事をする時間（　　）顔を洗う時間もなかった","options":["すら","しか","とはいえ","どころか"],"answer":4,"word_explain":"A どころか B: đừng nói là A, đến cả B cũng (nhấn mạnh mức độ B còn dễ/cơ bản hơn A mà cũng không làm được).","translation_vi":"Sáng nay tôi ngủ quên mất nên đừng nói là thời gian ăn sáng, ngay cả thời gian rửa mặt cũng không có."},{"mondai":7,"q":4,"prompt":"A「ねえ、経済学のレポート書けた？」 B「うん、難しかったけど、（　　）書いたよ」","options":["書けば","書いてでも","書くだけは","書いたわりに"],"answer":3,"word_explain":"Vる + だけは + Vた: ít nhất thì cũng đã làm được việc V (chỉ mức tối thiểu, không đảm bảo chất lượng tốt).","translation_vi":"A: \"Này, cậu viết xong báo cáo môn Kinh tế học chưa?\" B: \"Ừ, tuy khó nhưng ít ra tớ cũng viết xong rồi.\""},{"mondai":7,"q":5,"prompt":"情報技術の発展（　　）、コミュニケーションの手段は多様化している。","options":["において","にこたえて","にあたって","にともなって"],"answer":4,"word_explain":"N + にともなって: cùng với, theo đà (sự biến đổi/phát triển của N kéo theo sự thay đổi ở vế sau).","translation_vi":"Cùng với sự phát triển của công nghệ thông tin, các phương tiện giao tiếp đang ngày càng đa dạng hơn."},{"mondai":7,"q":6,"prompt":"（歯医者のホームページで） 虫歯が小さい（　　）、簡単な治療で済みます。虫歯かもしれないと思ったら、早めに受診するようにしましょう。","options":["うちなら","うちでも","だけなら","だけでも"],"answer":1,"word_explain":"A + うちなら: nhân lúc còn đang ở trạng thái A (chưa chuyển sang trạng thái xấu hơn), thì... (đi với kết quả tích cực/nhẹ nhàng).","translation_vi":"(Trên trang chủ nha khoa) Khi vết sâu răng còn nhỏ thì chỉ cần điều trị đơn giản là xong. Nếu thấy có khả năng bị sâu răng, hãy đi khám sớm."},{"mondai":7,"q":7,"prompt":"A水族館では、２か月前にイルカの赤ちゃんが生まれてから来場者が増え、非常に混雑する（　　）、開館時間を早めることを検討している","options":["ようにしたとしても","ようにしたことから","ようになったとしても","ようになったことから"],"answer":4,"word_explain":"Vる + ようになる (biến đổi trạng thái tự nhiên: trở nên đông đúc) + ことから (vì lý do / xuất phát từ việc...).","translation_vi":"Tại thủy cung A, kể từ khi cá heo con chào đời cách đây 2 tháng, lượng khách tham quan tăng lên và trở nên rất đông đúc, vì vậy họ đang xem xét việc mở cửa sớm hơn."},{"mondai":7,"q":8,"prompt":"（ホテルで） 客「これから西森町に行くんですが、どこかおいしい和食のお店はありませんか」 フロント「西森町に（　　）、『さくら』はいかがでしょうか。大変人気のあるお店です」","options":["伺うんでしたら","伺いますと","いらっしゃるんでしたら","いらっしゃいますと"],"answer":3,"word_explain":"Tôn kính ngữ của 行く là いらっしゃる (lễ tân nói với khách; 伺う là khiêm nhường ngữ). Kết hợp ～んでしたら (nếu như anh/chị đi... thì) dùng để đưa ra lời khuyên, gợi ý lịch sự.","translation_vi":"(Ở khách sạn) Khách: \"Bây giờ tôi định đến phố Nishimori, ở đó có quán đồ Nhật nào ngon không?\" Lễ tân: \"Nếu quý khách đến phố Nishimori thì quán 'Sakura' thế nào ạ? Đó là quán rất được ưa chuộng.\""},{"mondai":7,"q":9,"prompt":"田中さんは仕事が忙しいらしく、最近テニスクラブの練習を（　　）だ。","options":["休みかねない","休みがち","休むとのことだ","休むに違いない"],"answer":2,"word_explain":"Vます + がちだ: hay có khuynh hướng (làm điều không mong muốn như nghỉ, ốm, quên...).","translation_vi":"Anh Tanaka có vẻ bận công việc nên gần đây hay nghỉ tập ở câu lạc bộ tennis."},{"mondai":7,"q":10,"prompt":"飼っている犬が最近よくしゃっくりをする。心配になって病院で聞いてみたら、１時間以上続く場合は検査したほうがいいが、すぐに止まるなら（　　）と言われた","options":["心配しなければならない","心配しないでもない","心配するわけではない","心配することはない"],"answer":4,"word_explain":"Vる + ことはない: không cần phải, không việc gì phải... (dùng để trấn an/khuyên nhủ).","translation_vi":"Chú chó tôi nuôi dạo này hay bị nấc. Thấy lo nên tôi hỏi ở bệnh viện thú y thì được bảo rằng nếu kéo dài hơn 1 tiếng thì nên kiểm tra, nhưng nếu ngừng ngay thì không cần phải lo lắng đâu."},{"mondai":7,"q":11,"prompt":"私が教えている経営学の講義では、去年から、毎回学生に講義の感想や質問を書いて（　　）。そこから気づかされることも多いからだ。","options":["出してもらうことにしている","出してもらうことがある","出してあげることにしている","出してあげることがある"],"answer":1,"word_explain":"Vて + もらう (giảng viên nhận bài nộp từ sinh viên) + ことにしている (duy trì thói quen/quy định do bản thân đặt ra từ năm ngoái đến nay).","translation_vi":"Trong giờ giảng môn Quản trị kinh doanh mà tôi phụ trách, từ năm ngoái tôi quy định mỗi buổi đều cho sinh viên viết cảm nhận hoặc câu hỏi rồi nộp lại. Bởi vì từ đó tôi cũng nhận ra được nhiều điều."},{"mondai":7,"q":12,"prompt":"A「ねえ、大変。これから行くお寺、見学するには（　　）だよ、ガイドブックのここに書いてある」 B「本当だ。今から予約できるか電話して聞いてみようか」","options":["予約しないといけないみたい","予約しないといけないはず","予約したくなるみたい","予約したくなるはず"],"answer":1,"word_explain":"～みたいだ: hình như, có vẻ như (suy đoán dựa trên thông tin vừa đọc thấy trong sách hướng dẫn). はず mang tính chắc chắn theo logic/kinh nghiệm cá nhân nên không hợp khi mới đọc thấy thông tin gây bất ngờ.","translation_vi":"A: \"Này, nguy rồi. Ngôi chùa sắp đi ấy, hình như phải đặt trước mới vào tham quan được đấy, ở chỗ này trong sách hướng dẫn có ghi nè.\" B: \"Thật vậy luôn. Hay giờ mình gọi điện hỏi thử xem có đặt được không nhé.\""},{"mondai":8,"q":13,"prompt":"この歌を聞く＿＿＿　＿＿＿　★　＿＿＿ことだ。彼はカラオケに行くと必ずこの歌を歌っていた。","options":["のは","思い出す","たびに","高校時代の友人の"],"answer":1,"word_explain":"Thứ tự đúng: 3 → 2 → ★1 → 4. Câu hoàn chỉnh: この歌を聞くたびに思い出すのは高校時代の友人のことだ。(Vるたびに: mỗi lần làm gì; 思い出すのは〜ことだ: điều nhớ đến là về...).","translation_vi":"Điều tôi nhớ đến mỗi khi nghe bài hát này là về người bạn thời cấp 3 của mình. Cậu ấy cứ đi karaoke là nhất định sẽ hát bài này."},{"mondai":8,"q":14,"prompt":"昨日、アルバイトに遅刻しそうだったので＿＿＿　＿＿＿　★　＿＿＿、結局遅刻してしまった。","options":["タクシーに乗ったら","かえって時間がかかり","急ごうと思って","道が渋滞していたせいで"],"answer":4,"word_explain":"Thứ tự đúng: 3 → 1 → ★4 → 2. Câu hoàn chỉnh: 急ごうと思ってタクシーに乗ったら道が渋滞していたせいでかえって時間がかかり、結局遅刻してしまった。(～せいで: tại vì...; かえって: trái lại, ngược lại).","translation_vi":"Hôm qua vì sắp trễ giờ làm thêm nên tôi định đi nhanh bằng cách bắt taxi, nhưng do đường tắc nên lại mất nhiều thời gian hơn, cuối cùng vẫn bị trễ."},{"mondai":8,"q":15,"prompt":"来月結婚する友人に結婚式のスピーチを頼まれた。大勢の前で話すのは＿＿＿　＿＿＿　★　＿＿＿引き受けることにした。","options":["悩んだのだが","と言われて","どうしても","苦手なので"],"answer":3,"word_explain":"Thứ tự đúng: 4 → 1 → ★3 → 2. Câu hoàn chỉnh: 大勢の前で話すのは苦手なので悩んだのだがどうしてもと言われて引き受けることにした。(「どうしても」と言われて: được nói/nài nỉ rằng \"nhất định nhờ cậu\").","translation_vi":"Tôi được người bạn sắp kết hôn vào tháng sau nhờ phát biểu trong lễ cưới. Vì kém khoản nói trước đám đông nên tôi đã băn khoăn, nhưng vì bạn ấy nài nỉ nhất định nhờ tôi nên tôi quyết định nhận lời."},{"mondai":8,"q":16,"prompt":"先日の政治家Ａ氏の発言はあまりに無責任だ。＿＿＿　＿＿＿　★　＿＿＿、と思う。","options":["政治家としての","うえで","発言しなければならなかった","自分の立場をよく考えた"],"answer":2,"word_explain":"Thứ tự đúng: 1 → 4 → ★2 → 3. Câu hoàn chỉnh: 政治家としての自分の立場をよく考えたうえで発言しなければならなかった、と思う。(Nとしての: với tư cách là N; Vたうえで: sau khi đã làm V rồi mới...).","translation_vi":"Phát ngôn hôm trước của chính trị gia A quá vô trách nhiệm. Tôi nghĩ lẽ ra ông ấy phải suy nghĩ kỹ về lập trường của mình với tư cách một chính trị gia rồi mới phát biểu."},{"mondai":8,"q":17,"prompt":"食事や睡眠などの生活習慣は一度乱れてしまうと＿＿＿　＿＿＿　★　＿＿＿が大切だ。","options":["規則正しい生活を","戻そうとしても","普段から意識することが","なかなか戻せいないので"],"answer":1,"word_explain":"Thứ tự đúng: 2 → 4 → ★1 → 3. Câu hoàn chỉnh: 戻そうとしてもなかなか戻せいないので規則正しい生活を普段から意識することが(が)大切だ。(Lưu ý lỗi đánh máy trong PDF gốc: 戻せいないので = 戻せないので, và 意識することが lặp trợ từ が với が大切だ bên ngoài).","translation_vi":"Những thói quen sinh hoạt như ăn uống hay ngủ nghỉ một khi đã bị rối loạn thì dù có cố đưa về như cũ cũng rất khó, vì vậy việc ý thức duy trì lối sống điều độ ngay từ bình thường là rất quan trọng."},{"mondai":9,"q":18,"prompt":"Chỗ trống [48] trong đoạn văn trên","options":["問題だろう","問題である","問題とのことだ","問題ではないか"],"answer":2,"word_explain":"Câu giới thiệu chủ đề bài viết mang tính khẳng định khách quan dùng văn viết ～である: 今回取り上げるのは、自転車の問題である。(Lưu ý trong PDF gốc có ký tự thừa 「出し」 sau chỗ trống [48]).","translation_vi":"Điều được đề cập lần này là vấn đề về xe đạp."},{"mondai":9,"q":19,"prompt":"Chỗ trống [49] trong đoạn văn trên","options":["つくられているにすぎない","つくられているに違いない","つくられているといってもよい","つくられているというだけではない"],"answer":4,"word_explain":"Cấu trúc ～というだけではない。～なのだ。 (không chỉ đơn thuần là được xây dưới lòng đất, mà còn là bãi gửi xe hoàn toàn tự động). Phù hợp mạch chuyển ý từ bãi gửi xe ngầm thông thường sang loại tự động mới.","translation_vi":"Đó không chỉ đơn thuần là loại được xây dựng dưới lòng đất, mà là bãi gửi xe đạp ngầm hoàn toàn tự động."},{"mondai":9,"q":20,"prompt":"Chỗ trống [50] trong đoạn văn trên","options":["駐輪場","ある駐輪場","このような駐輪場","そこの駐輪場"],"answer":3,"word_explain":"このような駐輪場 (bãi gửi xe như thế này) dùng để chỉ lại 「全自動式の地下駐輪場」 vừa được giải thích cơ chế hoạt động ở đoạn văn ngay trước đó.","translation_vi":"Loại bãi gửi xe như thế này có rất nhiều ưu điểm."},{"mondai":9,"q":21,"prompt":"Chỗ trống [51] trong đoạn văn trên","options":["しても","するために","なったように","なってはじめて"],"answer":2,"word_explain":"N + にする + ために (để làm cho thành phố trở nên thoải mái và an toàn hơn), chỉ mục đích và tương ứng tha động từ với vế trước 「駐輪場不足を解決し」.","translation_vi":"Để giải quyết tình trạng thiếu bãi gửi xe và xây dựng một thành phố thoải mái, an toàn hơn, việc lắp đặt bãi gửi xe đạp ngầm hoàn toàn tự động có thể nói là một trong những biện pháp hiệu quả."}]},{"id":"g_2021_12","displayName":"12/2021","subtitle":"21 câu • Mondai 7–9 (Ngữ pháp)","m9_passage":"「落語」体験\nバラージベーテル\n\n今回、留学生センターで行われた文化体験のテーマは「落語」だった。落語は日本の伝統的な芸能の一つだ。着物を着た落語家が舞台に正座したまま、一人で何役も演じ、語って聞かせる。たいていは、面白く、おかしい話だ。私の国には演劇はあるが、落語のようなものはない。\n\n私は、文化体験が落語だと知って、実はがっかりした。以前、ある落語を授業で読んだが、あまり面白いと[48]話をただ聞いているのは退屈だろうと思ったし、聞き取れるかどうかも不安だった。\n\n[49]落語を聞いている間、私はよく笑った。落語家の動作や声の出し方は本当に面白くて、場面の様子もよくわかった。しぐさや話し方を変えて、親と子供など二役以上を一人で演じ、会話を進める。座ったまま体を揺らして歩いている様子を見せ、家から店に移動したことを表す。食事の動作は、本当に何かを食べているようだった。\n\n文化体験が終わったとき、落語の印象がすっかり変わっていた。落語とは、落語家の動作と語りを同時に[50]。私は、話の細部は理解できていなかったかもしれない。しかし、落語家の動作と語りを通して、登場人物の性格や暮らしが感じられた。それに、映像や音楽や踊りがなくても、生き生きと話を伝え、人を笑わせられる落語家の表現力にも感動した。\n\n落語には、怖い話や感動的な話もあるそうだ。落語家は[51]をするのだろうか。ぜひいろいろな落語を聞いてみたい。","questions":[{"mondai":7,"q":1,"prompt":"A「田中さんに話があるんだけど、今、会議中?」 B「うん。」 A「じゃあ、会議が終わるのを待つ(　　)ないわ。」","options":["しか","だけ","まで","さえ"],"answer":1,"word_explain":"Vる + しかない: đành phải, chỉ còn cách làm gì đó (không có lựa chọn nào khác).","translation_vi":"A: \"Tôi có chuyện muốn nói với anh Tanaka, bây giờ đang họp à?\" B: \"Ừ.\" A: \"Vậy thì đành phải đợi cuộc họp kết thúc thôi.\""},{"mondai":7,"q":2,"prompt":"この道路拡張計画を(　　)にあたっては、市民の皆様のご理解が必要です。","options":["進めた","進める","進めたい","進めよう"],"answer":2,"word_explain":"Vる + にあたっては: khi tiến hành / nhân dịp làm một việc quan trọng, trang trọng. Động từ chia ở thể từ điển (進める).","translation_vi":"Khi tiến hành kế hoạch mở rộng con đường này, chúng tôi rất cần sự thông cảm và thấu hiểu của toàn thể người dân thành phố."},{"mondai":7,"q":3,"prompt":"今日の試合は大雪で延期になった。(　　)この時期に大雪になるとは思わなかった。","options":["一体","二度と","まさか","かえって"],"answer":3,"word_explain":"まさか〜とは思わなかった: không ngờ lại..., chẳng thể nào ngờ rằng... (diễn tả sự ngạc nhiên trước điều không lường trước).","translation_vi":"Trận đấu hôm nay đã bị hoãn do tuyết rơi dày. Thật không ngờ vào thời điểm này mà lại có tuyết lớn như vậy."},{"mondai":7,"q":4,"prompt":"水泳クラブの山田コーチは、私たちにとってコーチ(　　)兄のような存在です。","options":["に限らず","なしには","のおかげで","というより"],"answer":4,"word_explain":"AというよりB: nói là A thì đúng hơn là B / giống như B hơn là A (đưa ra cách miêu tả chính xác hơn).","translation_vi":"Huấn luyện viên Yamada của câu lạc bộ bơi lội, đối với chúng tôi, giống như một người anh trai hơn là một huấn luyện viên."},{"mondai":7,"q":5,"prompt":"X社の健康食品はテレビ番組で紹介(　　)以来、とても売れている。","options":["されて","される","されている","された"],"answer":1,"word_explain":"Vて + 以来: kể từ sau khi... (trạng thái kéo dài liên tục từ thời điểm đó đến nay). Lưu ý `以来` đi với thể て (`紹介されて以来`), không đi với thể た.","translation_vi":"Thực phẩm chức năng của công ty X kể từ sau khi được giới thiệu trên chương trình truyền hình thì bán rất chạy."},{"mondai":7,"q":6,"prompt":"(店で) A「このシャツ、かわいい。でも、会社に着ていくには派手かな。」 B「うん。デートで着る(　　)、仕事には派手すぎるよ。」","options":["にしては","としたら","たらともかく","からとはいえ"],"answer":3,"word_explain":"ならともかく (trong đề gốc in nhầm thành `たらともかく`): nếu là A thì còn tạm được / khác, chứ B thì không. Dùng để tách biệt trường hợp có thể chấp nhận với trường hợp không phù hợp.","translation_vi":"(Ở cửa hàng) A: \"Chiếc áo sơ mi này dễ thương quá. Nhưng mặc đi làm ở công ty thì có hơi lòe loẹt không nhỉ?\" B: \"Ừ. Nếu mặc đi hẹn hò thì còn tạm được chứ để đi làm thì lòe loẹt quá đấy.\""},{"mondai":7,"q":7,"prompt":"娘は、社会人(　　)朝一人で起きられない。私が起こさないといつまでも寝ている。","options":["にもなって","にもなれば","にでもなって","にでもなれば"],"answer":1,"word_explain":"N + にもなって: đã trở thành / đã ở cương vị, độ tuổi... vậy rồi mà (mang sắc thái ngạc nhiên, chê trách trước hành vi không tương xứng).","translation_vi":"Con gái tôi đã đi làm rồi mà buổi sáng vẫn không thể tự mình thức dậy được. Nếu tôi không gọi dậy thì cứ ngủ mãi."},{"mondai":7,"q":8,"prompt":"友達は、お茶でうがいを(　　)、風邪をひかなくなったらしい。私も始めてみようと思う。","options":["しようとすれば","しようとしたことで","するようにすれば","するようにしたことで"],"answer":4,"word_explain":"Vる + ようにする (cố gắng tạo thói quen) + たことで (nhờ việc đã làm như vậy mà dẫn đến kết quả tích cực).","translation_vi":"Nghe nói bạn tôi nhờ tạo thói quen súc miệng bằng trà mà không còn bị cảm nữa. Tôi cũng định thử làm theo xem sao."},{"mondai":7,"q":9,"prompt":"彼女があのとき何を考えていたのか知りたいけれど、今はもう会うこともないので、(　　)。","options":["確かめかねない","確かめるほかない","確かめようがない","確かめるわけではない"],"answer":3,"word_explain":"Vます + ようがない: không có cách nào để làm gì (bất khả kháng vì thiếu phương tiện/điều kiện).","translation_vi":"Tôi muốn biết lúc đó cô ấy đã nghĩ gì, nhưng bây giờ không còn gặp nhau nữa nên cũng không có cách nào để kiểm chứng cả."},{"mondai":7,"q":10,"prompt":"(不動産屋で) 店員「お客様、本日いくつかのお部屋を(　　)が、ご希望に合うお部屋はございましたか。」 客「最初の部屋がいいなと思ったんですが、ちょっと検討させてください。」","options":["参りました","拝見しました","お越しいただきました","ご覧いただきました"],"answer":4,"word_explain":"Tôn kính ngữ của `見る` là `ご覧になる`; dạng `ご覧いただきました` thể hiện việc \"quý khách đã vui lòng xem qua\" (dành cho hành động của khách hàng). `参りました` và `拝見しました` là khiêm nhường ngữ.","translation_vi":"(Tại văn phòng bất động sản) Nhân viên: \"Thưa quý khách, hôm nay quý khách đã xem qua một vài căn phòng rồi, không biết có căn nào phù hợp với mong muốn của quý khách không ạ?\" Khách: \"Tôi thấy căn đầu tiên cũng ổn đấy, nhưng hãy cho tôi suy nghĩ thêm một chút.\""},{"mondai":7,"q":11,"prompt":"カレーを大量に作りすぎて、一人では食べ(　　)と思ったので、友人をよんで食べた。","options":["切れるかもしれない","切れそうにない","かねないだろう","かねないようだ"],"answer":2,"word_explain":"Vます + きれる (làm hết được) → `食べきれそうにない`: có vẻ không thể ăn hết nổi (`Vます + そうもない / そうにない` = có vẻ không thể). `〜かねない` mang nghĩa \"có nguy cơ xảy ra điều xấu\".","translation_vi":"Vì nấu quá nhiều cà ri, tôi nghĩ một mình có vẻ không ăn hết nổi nên đã gọi bạn đến ăn cùng."},{"mondai":7,"q":12,"prompt":"最近は毎月決まった金額でかけ放題の国際電話サービスがある。私が留学していたときにもそんなサービスがあったら(　　)。","options":["どれだけよかった","どれだけよかったか","どうしてもよかった","どうしてもよかったか"],"answer":2,"word_explain":"〜たらどれだけ〜か: nếu mà... thì biết bao nhiêu (câu cảm thán tiếc nuối: `どれだけよかったか` = tốt biết nhường nào).","translation_vi":"Gần đây có dịch vụ gọi điện quốc tế không giới hạn với mức phí cố định hàng tháng. Giá mà hồi tôi đi du học cũng có dịch vụ như thế thì tốt biết bao."},{"mondai":8,"q":13,"prompt":"もう酒は飲まないと ＿＿＿　＿＿＿　★　＿＿＿ 絶対に守りたい。","options":["決めた","どんなに","以上は","誘われても"],"answer":2,"word_explain":"Thứ tự đúng: 1 → 3 → ★2 → 4. Cấu trúc `Vた + 以上は` (một khi đã... thì) kết hợp với `どんなに〜ても` (dù có... thế nào đi nữa). Câu hoàn chỉnh: もう酒は飲まないと決めた以上は、どんなに誘われても絶対に守りたい。","translation_vi":"Một khi đã quyết tâm sẽ không uống rượu nữa thì dù có bị rủ rê thế nào đi nữa tôi cũng muốn giữ vững lời hứa đó."},{"mondai":8,"q":14,"prompt":"必要のない物でも、欲しくなると ＿＿＿　＿＿＿　★　＿＿＿ しまう。","options":["買わずには","すぐ買って","いられなく","なって"],"answer":4,"word_explain":"Thứ tự đúng: 1 → 3 → ★4 → 2. Cấu trúc `Vない + ずにはいられなくなる` (trở nên không thể nhịn được mà không làm gì), nối với `すぐ買ってしまう`. Câu hoàn chỉnh: 必要のない物でも、欲しくなると買わずにはいられなくなってすぐ買ってしまう。","translation_vi":"Ngay cả những thứ không cần thiết, hễ cứ muốn có là tôi lại không kiềm chế được mà mua ngay mất."},{"mondai":8,"q":15,"prompt":"パソコンの電源を入れたのだが、画面に「お待ちください」という ＿＿＿　★　＿＿＿　＿＿＿ 電源を入れ直した。","options":["待っても","何分","メッセージが出たまま","先に進まないので"],"answer":2,"word_explain":"Thứ tự đúng: 3 → ★2 → 1 → 4. `〜というメッセージが出たまま` (giữ nguyên trạng thái hiện thông báo...) + `何分待っても` (dù đợi mấy phút đi nữa) + `先に進まないので` (vì không tiến triển nên). Câu hoàn chỉnh: 画面に「お待ちください」というメッセージが出たまま何分待っても先に進まないので電源を入れ直した。","translation_vi":"Tôi đã bật nguồn máy tính nhưng màn hình cứ hiện dòng thông báo \"Xin vui lòng đợi\", dù đợi bao nhiêu phút cũng không chạy tiếp nên tôi đã tắt bật lại nguồn."},{"mondai":8,"q":16,"prompt":"(電話で) A「すみません、来週の2時からの会議ですが、その時間、別の用件が入ってしまいまして、もしそちらのご都合が ＿＿＿　＿＿＿　★　＿＿＿ 、いかがでしょうか。」 B「こちらは大丈夫ですよ。」","options":["ありがたいんですが","変更していただけると","4時以降に","よろしければ"],"answer":2,"word_explain":"Thứ tự đúng: 4 → 3 → ★2 → 1. Mẫu câu nhờ vả lịch sự: `ご都合がよろしければ` (nếu thuận tiện) + `4時以降に変更していただけるとありがたいんですが` (nếu có thể đổi sang sau 4 giờ thì tôi rất cảm kích). Câu hoàn chỉnh: もしそちらのご都合がよろしければ4時以降に変更していただけるとありがたいんですが、いかがでしょうか。","translation_vi":"(Qua điện thoại) A: \"Xin lỗi, về cuộc họp lúc 2 giờ tuần tới, vào giờ đó tôi lại có việc khác xen vào mất, nếu bên anh/chị thuận tiện thì có thể dời sang sau 4 giờ giúp tôi được không ạ, không biết ý anh/chị thế nào?\" B: \"Bên tôi thì ổn thôi ạ.\""},{"mondai":8,"q":17,"prompt":"20年前に初めてこの歌手の歌を聴いたとき、＿＿＿　＿＿＿　★　＿＿＿","options":["と思った","よく覚えている","のを","なんと美しい声なんだろう"],"answer":3,"word_explain":"Thứ tự đúng: 4 → 1 → ★3 → 2. Mệnh đề trích dẫn cảm thán `なんと〜なんだろう` + `と思った` được danh từ hóa bằng `のを` làm tân ngữ cho `よく覚えている`. Câu hoàn chỉnh: 20年前に初めてこの歌手の歌を聴いたとき、なんと美しい声なんだろうと思ったのをよく覚えている。","translation_vi":"Tôi vẫn nhớ rất rõ lần đầu tiên nghe ca sĩ này hát cách đây 20 năm, tôi đã thầm nghĩ \"Giọng hát mới đẹp làm sao!\"."},{"mondai":9,"q":18,"prompt":"Chỗ trống [48] trong đoạn văn trên","options":["思えなかったまでだ","思えなかったほどだ","思えなかっただけだ","思えなかったからだ"],"answer":4,"word_explain":"`〜からだ` dùng để nêu lý do cho việc tác giả thất vọng và nghĩ rằng nghe Rakugo sẽ nhàm chán (vì trước đó đọc trong lớp không thấy hay). Các lựa chọn khác (`までだ`, `ほどだ`, `だけだ`) không thể hiện quan hệ nguyên nhân phù hợp với vế sau.","translation_vi":"Trước đây tôi từng đọc một vở Rakugo trong giờ học, nhưng vì không thấy nó thú vị lắm nên tôi nghĩ việc chỉ ngồi nghe kể chuyện chắc sẽ chán lắm, lại còn lo không biết mình có nghe hiểu được hay không."},{"mondai":9,"q":19,"prompt":"Chỗ trống [49] trong đoạn văn trên","options":["しかも","すなわち","ところが","したがって"],"answer":3,"word_explain":"`ところが` (thế nhưng, trái lại) diễn tả kết quả thực tế trái ngược hoàn toàn với dự đoán lo lắng, chán nản ở đoạn trước. `しかも` (hơn nữa), `すなわち` (tức là), `したがって` (do đó) không phù hợp ngữ cảnh tương phản.","translation_vi":"Thế nhưng, suốt thời gian nghe Rakugo, tôi đã cười rất nhiều."},{"mondai":9,"q":20,"prompt":"Chỗ trống [50] trong đoạn văn trên","options":["楽しむものなのだ","楽しむはずなのだ","楽しむようにするのだ","楽しむことになったのだ"],"answer":1,"word_explain":"Cấu trúc `Aとは〜もの（な）だ` dùng để định nghĩa hoặc nêu bản chất, đặc trưng của sự vật A (`落語とは...楽しむものなのだ`).","translation_vi":"Rakugo là loại hình nghệ thuật để thưởng thức đồng thời cả động tác lẫn lời kể của nghệ sĩ Rakugo."},{"mondai":9,"q":21,"prompt":"Chỗ trống [51] trong đoạn văn trên","options":["どんな表現","その表現","表現","こういう表現"],"answer":1,"word_explain":"Do tác giả chưa từng xem Rakugo thể loại kinh dị hay cảm động (chỉ mới nghe nói `〜そうだ`), câu tiếp theo là sự tò mò đặt câu hỏi với nghi vấn từ `どんな表現` (\"cách biểu đạt như thế nào\") đi với `〜のだろうか`. `その表現` và `こういう表現` chỉ những thứ đã biết/vừa minh họa nên không hợp.","translation_vi":"Nghe nói Rakugo còn có cả những câu chuyện kinh dị hay những câu chuyện cảm động nữa. Không biết nghệ sĩ Rakugo sẽ thể hiện những cách biểu đạt như thế nào nhỉ?"}]},{"id":"g_2021_07","displayName":"07/2021","subtitle":"21 câu • Mondai 7–9 (Ngữ pháp)","m9_passage":"以下は、新聞コラムである。\n\n毎日の生活の中で、天気予報は欠かせない情報の一つだ。着る服を選ぶときも、休日の予定を立てるときも、天気は [48] 。毎朝天気予報をチェックしている人も多いだろう。\n\nそんな天気予報を活用した新たな取り組みが始まっている。気象情報から食品の高度な需要予測を行い、「食品ロス」、つまり、まだ食べられるのに捨てられてしまう食品を減らすというものだ。\n\n食品の中には、天候や気温に需要が大きく左右されるものも多い。需要予測を誤り、過剰に生産してしまうと、それだけ多くの食品ロスが生じてしまう。\n\n[49] 政府は、気象データとPOSデータ(何が、いつ、いくつ、いくらで売れたのかを示す販売情報)から高度な需要予測を行い、製造や販売の各社に提供する取り組みを始めた。その効果は、食品ロスを減らせるばかりではない。食品が無駄に捨てられることが少なくなるため、その処理の過程で発生する二酸化炭素を減らすこともできる。\n\n[50] 、まず、長期保存ができず気象状況が売り上げに大きく影響する「豆腐」と、特定の季節に需要が集中する「麺つゆ」に絞って実験が行われた。その結果、食品ロスを20〜30%減らせることがわかった。現在は、対象商品を拡大しながら、人工知能も取り入れ、さらに高度な需要予測が可能になってきているという。このように、私たちの生活に欠かせない気象情報は、食品ロス問題の解決にも役立っているのである。\n\n今後、より大きな成果が [51] 。","questions":[{"mondai":7,"q":1,"prompt":"野党の追及に対し、大臣は満足な回答ができなかったどころか、質問の内容（　　）理解できていなかった。","options":["すら","こそ","のみ","ほど"],"answer":1,"word_explain":"「～どころか、～すら～ない」: chẳng những không..., mà thậm chí đến cả... cũng không. Danh từ + すら nhấn mạnh mức độ tối thiểu (\"đến cả...\"). こそ (chính là), のみ (chỉ), ほど (đến mức) đều không phù hợp.","translation_vi":"Trước sự chất vấn của phe đối lập, Bộ trưởng chẳng những không thể đưa ra câu trả lời thỏa đáng mà thậm chí đến cả nội dung câu hỏi cũng không hiểu được."},{"mondai":7,"q":2,"prompt":"最近（　　）パソコンの調子がおかしい。この状態が続くようだったら一度修理に出したほうがよさそうだ。","options":["ちっとも","いったい","どうも","まさか"],"answer":3,"word_explain":"「どうも～おかしい」: không hiểu sao / dường như có gì đó bất thường. ちっとも đi với phủ định, いったい dùng trong câu hỏi, まさか dùng khi phủ định mạnh (\"chẳng lẽ nào\").","translation_vi":"Gần đây không hiểu sao tình trạng máy tính cứ bất ổn. Nếu tình trạng này còn tiếp diễn thì có lẽ nên mang đi sửa một lần thì hơn."},{"mondai":7,"q":3,"prompt":"（広告で） 川西ピアノ教室では、初心者、経験者（　　）、どなたにでも丁寧に指導します。","options":["を通して","を問わず","にかけて","にもかかわらず"],"answer":2,"word_explain":"「N＋を問わず」: bất kể, không phân biệt (thường đi với các cặp đối lập như 初心者・経験者, 年齢, 男女). を通して (xuyên suốt/thông qua), にかけて (từ... đến...), にもかかわらず (mặc dù) không hợp.","translation_vi":"(Trong quảng cáo) Tại lớp học piano Kawanishi, bất kể là người mới bắt đầu hay người đã có kinh nghiệm, chúng tôi đều hướng dẫn tận tình cho mọi học viên."},{"mondai":7,"q":4,"prompt":"めったに出かけないのに、外出するとき（　　）大雨になる。","options":["にあたって","にかぎって","において","に際して"],"answer":2,"word_explain":"「～にかぎって」: đúng lúc..., chỉ riêng lúc... (lại xảy ra chuyện xui xẻo/tréo ngoe). にあたって và に際して dùng khi bắt đầu sự kiện trọng đại; において chỉ địa điểm/phạm vi.","translation_vi":"Bình thường hiếm khi ra ngoài, thế mà hễ cứ đúng lúc ra ngoài là trời lại mưa to."},{"mondai":7,"q":5,"prompt":"昨夜よく眠れなかった（　　）、体がだるい。","options":["からには","わけか","あまりに","せいか"],"answer":4,"word_explain":"「～せいか」: có lẽ tại vì... (nguyên nhân phỏng đoán dẫn đến kết quả không mong muốn). からには (một khi đã), わけか (không hợp ngữ pháp), あまりに (quá mức - không nối sau thể phủ định 眠れなかった như vậy).","translation_vi":"Có lẽ vì tối qua không ngủ ngon giấc nên người cứ uể oải."},{"mondai":7,"q":6,"prompt":"初めてこの町を訪れたが、不思議な（　　）、ずっと前からここに住んでいるような気がする。","options":["ことに","うえに","くせに","ものに"],"answer":1,"word_explain":"「不思議なことに」 (Aな＋ことに): kỳ lạ thay, điều kỳ lạ là... (cấu trúc đánh giá cảm xúc của người nói đối với sự việc phía sau). うえに (hơn nữa), くせに (dù... thế mà, mang sắc thái chê trách), ものに (không hợp).","translation_vi":"Đây là lần đầu tiên tôi đến thăm thị trấn này, nhưng kỳ lạ thay, tôi có cảm giác như mình đã sống ở đây từ rất lâu rồi."},{"mondai":7,"q":7,"prompt":"（会社で） A「じゃ、来週の打ち合わせも水曜日でいいですか。」 B「あ、スケジュールを（　　）ちょっとわからないので、あとで連絡します。」","options":["確認していないと","確認してみないと","確認しているか","確認してみるか"],"answer":2,"word_explain":"「Vてみないと（わからない）」: nếu không thử làm... thì không biết được. 確認していないと (nếu chưa đang kiểm tra) sai nghĩa; các dạng đuôi か không nối tự nhiên với ちょっとわからないので.","translation_vi":"(Ở công ty) A: \"Vậy cuộc họp tuần sau cũng vào thứ Tư được chứ ạ?\" B: \"À, nếu không kiểm tra thử lịch trình thì tôi cũng chưa rõ nữa, nên lát nữa tôi sẽ liên lạc lại nhé.\""},{"mondai":7,"q":8,"prompt":"「一つの仕事を少なくとも三年は（　　）どこに行っても何もできない」と言われた。","options":["やり続けられなかったら","やり続けられなくなっても","やり始められなかったら","やり始められなくなっても"],"answer":1,"word_explain":"「やり続ける」 (tiếp tục làm) ở thể khả năng phủ định điều kiện 「やり続けられなかったら」 (nếu không thể tiếp tục làm thì...). ても (cho dù) sai quan hệ điều kiện; やり始める (bắt đầu làm) không hợp với 少なくとも三年は.","translation_vi":"Tôi đã bị nói rằng: \"Nếu một công việc mà còn không thể kiên trì làm tiếp ít nhất ba năm thì đi đâu cũng chẳng làm nên trò trống gì đâu.\""},{"mondai":7,"q":9,"prompt":"仕事でも勉強でも、一度やると決めたら最後まで（　　）ことが大事だと思う。","options":["やり直す","やりだす","やり抜く","やりかける"],"answer":3,"word_explain":"「Vます＋抜く」 (やり抜く): làm đến cùng, hoàn thành trọn vẹn. やり直す (làm lại), やりだす (bắt đầu làm), やりかける (làm dở dang).","translation_vi":"Dù là công việc hay học tập, một khi đã quyết định làm thì tôi nghĩ điều quan trọng là phải làm đến cùng."},{"mondai":7,"q":10,"prompt":"（受付で） 山川「すみません。ABC社の山川と申しますが、営業部の中西さんをお願いします。」 受付「申し訳ございません。中西はただいま外出しておりますが。」 山川「え、中西さんご本人から、この時間だったらいらっしゃると（　　）が。」","options":["お聞きになったんです","申し上げたんです","ご存じなんです","伺ったんです"],"answer":4,"word_explain":"「伺う」 là khiêm nhường ngữ của 聞く (\"nghe / hỏi\" từ bề trên hoặc đối tác: 中西さんご本人から...と伺ったんです). お聞きになる là tôn kính ngữ (sai chủ thể), 申し上げる là khiêm nhường ngữ của 言う (nói), ご存じ là tôn kính ngữ của 知っている (biết).","translation_vi":"(Tại quầy lễ tân) Yamakawa: \"Xin lỗi. Tôi là Yamakawa của công ty ABC, xin cho gặp anh Nakanishi ở phòng Kinh doanh ạ.\" Lễ tân: \"Thành thật xin lỗi. Anh Nakanishi hiện đang ra ngoài rồi ạ.\" Yamakawa: \"Ơ, tôi có nghe chính anh Nakanishi nói là giờ này anh ấy có mặt ở đây mà.\""},{"mondai":7,"q":11,"prompt":"就職が決まった会社に「早く働きたい」と話したら、その後連絡が来て、就職するまでの間、アルバイトを（　　）。","options":["してあげることになった","してもらうことにした","させてあげることにした","させてもらうことになった"],"answer":4,"word_explain":"「V(sa)せてもらうことになった」: được (công ty) cho phép làm... / quyết định khách quan là mình được phép làm thêm. ～てあげる là mình làm/cho phép người khác (sai chiều); ことにした là tự mình quyết định.","translation_vi":"Khi tôi nói với công ty mà mình đã được nhận vào làm rằng \"Tôi muốn đi làm sớm\", sau đó họ đã liên lạc lại, và trong thời gian chờ đến lúc vào làm chính thức, tôi đã được công ty cho phép làm thêm."},{"mondai":7,"q":12,"prompt":"A「先輩に食事に誘われちゃって。どうしよう。行きたくないなあ。」 B「どうして悩むの？嫌なら（　　）。」 A「そうなんだけど、先輩だし断りにくくない？」","options":["断ればいいだけなの","断りたいだけなの","断ればいいだけでしょう","断りたいだけでしょう"],"answer":3,"word_explain":"「～ばいいだけでしょう」: chỉ cần làm... là được thôi mà (đưa ra lời khuyên/nhận xét hiển nhiên với người nghe). 断りたいだけ (chỉ muốn từ chối) sai nghĩa; ～なの không hợp với giọng điệu khuyên/chất vấn nhẹ ở đây bằng ～でしょう.","translation_vi":"A: \"Tôi bị đàn anh rủ đi ăn mất rồi. Làm sao đây, chẳng muốn đi chút nào.\" B: \"Sao phải bận tâm thế? Nếu không thích thì chỉ cần từ chối là được thôi mà?\" A: \"Đúng là vậy, nhưng vì là đàn anh nên khó từ chối quá phải không?\""},{"mondai":8,"q":13,"prompt":"もうすぐ高校卒業だ。この学校で先生や友達と過ごす ＿＿＿　＿＿＿　★　＿＿＿ 。","options":["あと数週間","と思うと","のも","寂しさが増してくる"],"answer":2,"word_explain":"Thứ tự đúng: 3 → 1 → ★2 → 4. Câu hoàn chỉnh: 「この学校で先生や友達と過ごすのもあと数週間と思うと寂しさが増してくる。」 (過ごすのもあと数週間: việc ở bên nhau cũng chỉ còn vài tuần; ～と思うと: hễ nghĩ đến việc...).","translation_vi":"Sắp tốt nghiệp cấp ba rồi. Nghĩ đến việc khoảng thời gian được ở bên thầy cô và bạn bè tại ngôi trường này cũng chỉ còn vài tuần nữa thôi, nỗi buồn lại càng tăng lên."},{"mondai":8,"q":14,"prompt":"A「サラリーマンから農家 ＿＿＿　＿＿＿　★　＿＿＿ があるんだね。」 B「自分の夢をどうしてもあきらめきれなくてね。」","options":["勇気","とは","ずいぶん","になる"],"answer":3,"word_explain":"Thứ tự đúng: 4 → 2 → ★3 → 1. Câu hoàn chỉnh: 「サラリーマンから農家になるとは、ずいぶん勇気があるんだね。」 (～になるとは: việc trở thành... thì thật bất ngờ/đúng là...; ずいぶん勇気がある: có rất nhiều dũng khí).","translation_vi":"A: \"Chuyển từ nhân viên văn phòng sang làm nông dân thì đúng là bạn có rất nhiều dũng khí đấy nhỉ.\" B: \"Vì tôi nhất quyết không thể từ bỏ ước mơ của mình được mà.\""},{"mondai":8,"q":15,"prompt":"遠足の日の朝、娘は、「いってきます」と ＿＿＿　＿＿＿　★　＿＿＿ 飛び出していった。","options":["終わらないか","言い終わるか","玄関を","のうちに"],"answer":4,"word_explain":"Thứ tự đúng: 2 → 1 → ★4 → 3. Câu hoàn chỉnh: 「『いってきます』と言い終わるか終わらないかのうちに玄関を飛び出していった。」 (VるかVないかのうちに: vừa mới... xong / còn chưa kịp... xong thì đã...).","translation_vi":"Vào buổi sáng ngày đi dã ngoại, con gái tôi còn chưa kịp nói dứt câu \"Con đi đây\" thì đã lao vụt ra khỏi cửa trước."},{"mondai":8,"q":16,"prompt":"参考書を読んで完璧に ＿＿＿　＿＿＿　★　＿＿＿ ということがよくある。","options":["理解した","問題を解いてみると","できない","つもりでも"],"answer":2,"word_explain":"Thứ tự đúng: 1 → 4 → ★2 → 3. Câu hoàn chỉnh: 「参考書を読んで完璧に理解したつもりでも、問題を解いてみるとできないということがよくある。」 (Vた＋つもりでも: dù cứ nghĩ là đã...; Vてみると: khi thử làm... thì).","translation_vi":"Dù có đọc sách tham khảo và cứ ngỡ mình đã hiểu hoàn hảo rồi, nhưng khi thử giải bài tập thì thường xuyên không làm được."},{"mondai":8,"q":17,"prompt":"この池に ＿＿＿　＿＿＿　★　＿＿＿ そうだ。","options":["ものもいる","すむ","魚のなかには","100年以上生きる"],"answer":4,"word_explain":"Thứ tự đúng: 2 → 3 → ★4 → 1. Câu hoàn chỉnh: 「この池にすむ魚のなかには100年以上生きるものもいるそうだ。」 (この池にすむ魚: cá sống ở ao này; ～のなかには...ものもいる: trong số... cũng có con...).","translation_vi":"Nghe nói trong số các loài cá sống ở cái ao này có cả những con sống trên 100 năm."},{"mondai":9,"q":18,"prompt":"Chỗ trống [48] trong đoạn văn trên","options":["気になるもの","気になるだけ","気になるかどうか","気になるかのよう"],"answer":1,"word_explain":"「～もの(だ)」 diễn tả chân lý, lẽ tự nhiên thông thường (ai cũng thường để tâm đến thời tiết). Các phương án còn lại (だけ, かどうか, かのよう) không thể kết thúc câu tự nhiên về mặt ngữ pháp và ý nghĩa.","translation_vi":"Dù là khi chọn quần áo để mặc hay khi lên kế hoạch cho ngày nghỉ, thời tiết luôn là điều khiến người ta phải bận tâm."},{"mondai":9,"q":19,"prompt":"Chỗ trống [49] trong đoạn văn trên","options":["なお","たとえば","そこで","ところが"],"answer":3,"word_explain":"Đoạn trước nêu vấn đề (dự đoán nhu cầu sai dẫn đến lãng phí thực phẩm). Đoạn này nêu hành động/giải pháp của chính phủ để khắc phục vấn đề đó, nên dùng liên từ 「そこで」 (\"vì vậy / do đó\"). なお (ngoài ra), たとえば (ví dụ), ところが (tuy nhiên) đều không khớp mạch văn.","translation_vi":"Vì vậy, chính phủ đã bắt đầu triển khai sáng kiến thực hiện dự đoán nhu cầu ở trình độ cao dựa trên dữ liệu thời tiết và dữ liệu POS (thông tin bán hàng cho biết mặt hàng nào, vào lúc nào, số lượng bao nhiêu và được bán với giá nào), rồi cung cấp cho các công ty sản xuất và bán lẻ."},{"mondai":9,"q":20,"prompt":"Chỗ trống [50] trong đoạn văn trên","options":["この取り組みは","そういった取り組みも","あのような取り組みは","どちらの取り組みも"],"answer":1,"word_explain":"Đoạn trước vừa giới thiệu trực tiếp 「取り組み」 của chính phủ, nên câu tiếp theo dùng chỉ thị từ 「この」 (この取り組みは) để chỉ chính sáng kiến vừa nhắc ngay phía trước. あの dùng cho đối tượng xa về tâm lý/không gian, そういった/どちら không hợp ngữ cảnh chỉ có một sáng kiến duy nhất.","translation_vi":"Trong sáng kiến này, trước tiên một cuộc thử nghiệm đã được tiến hành tập trung vào \"đậu phụ\" — mặt hàng không thể bảo quản lâu dài và doanh số chịu ảnh hưởng lớn bởi tình hình thời tiết — cùng với \"nước dùng mì (mentsuyu)\" vốn có nhu cầu tập trung vào một mùa nhất định."},{"mondai":9,"q":21,"prompt":"Chỗ trống [51] trong đoạn văn trên","options":["期待できるからだ","期待できそうだ","期待できるはずだった","期待できればよかった"],"answer":2,"word_explain":"Câu kết hướng tới tương lai (「今後」), dùng 「Vます＋そうだ」 (期待できそうだ: có vẻ có thể kỳ vọng được) để diễn tả triển vọng tích cực sắp tới. からだ (giải thích nguyên nhân), はずだった (quá khứ trái thực tế), ばよかった (ước muốn trái thực tế) đều không phù hợp.","translation_vi":"Trong thời gian tới, có vẻ chúng ta có thể kỳ vọng vào những thành quả to lớn hơn nữa."}]},{"id":"g_2020_12","displayName":"12/2020","subtitle":"21 câu • Mondai 7–9 (Ngữ pháp)","m9_passage":"以下は留学生がスピーチのために書いた文章である。\n\nロボット・セラビー\nプリュースター ジョン\n\n私はロボット工学を専攻しています。将来は医療分野でのロボット活用に関わる仕事をするのが夢です。今は「ロボット・セラビー」というものに興味があります。最近、介護の現場で注目されているものですが、みなさん、[48]。\n\n「ロボット・セラビー」なら聞いたことのある人も多いかもしれません。動物と触れ合うことで穏やかな気持ちになり、ストレスが減るなどの医療効果で知られています。しかし、実際に介護施設などで動物を飼おうとすると、アレルギーや世話の問題など、難しい面もあります[49]、マニアル・セラビーに替わるものとして、最近、ロボット・セラビーが注目されるようになりました。\n\nロボット・セラビーのロボットには動物型、赤ちゃん型などがあり、それらに共通するのはコミュニケーションが可能だということです。どの型のロボットも、感覚機能を持っており、触れ合う人の様子や周囲の状況を判断して、様々な感情を表現することができます。例えば、だっこされたり、なでられたりすると、可愛い声を出して喜んだり、気持ち良さそうな表情をしたりします。こういったロボットとの触れ合いによって、精神的安定やコミュニケーション能力の改善などの効果が[50]。\n\n私が今学んでいるのはロボット工学の基礎です。将来こういったロボットの研究、開発に参加するために、これからも勉強を続けます。そして、医療分野に[51]。","questions":[{"mondai":7,"q":1,"prompt":"明日、海外に留学中の友人が1年(　　)帰国する。会って話を聞くのが楽しみだ。","options":["おきに","たびに","ぶりに","うちに"],"answer":3,"word_explain":"「〜ぶりに」 biểu thị sau một khoảng thời gian dài thì mới làm lại việc gì đó (\"sau 1 năm mới...\"). 「おきに」 là cách đều (mỗi 1 năm một lần), 「たびに」 là mỗi lần, 「うちに」 là nhân lúc.","translation_vi":"Ngày mai, người bạn đang du học ở nước ngoài của tôi sẽ về nước sau 1 năm. Tôi rất mong được gặp và nghe bạn ấy kể chuyện."},{"mondai":7,"q":2,"prompt":"2年間付き合っている彼女に、今年(　　)結婚を申し込もうと思っている。","options":["こそ","さえ","すら","のみ"],"answer":1,"word_explain":"「〜こそ」 dùng để nhấn mạnh (chính năm nay / nhất định năm nay). 「さえ」「すら」 mang nghĩa \"ngay cả\", 「のみ」 nghĩa là \"chỉ\".","translation_vi":"Tôi đang định chính năm nay sẽ cầu hôn bạn gái đã hẹn hò suốt 2 năm qua."},{"mondai":7,"q":3,"prompt":"腰の曲がった老人に似ている(　　)エビは「海老」とも書かれると聞いた。","options":["ものを","とともに","うえで","ところから"],"answer":4,"word_explain":"「〜ところから」 dùng để nêu căn cứ, lý do cho một tên gọi hoặc nhận định (\"từ việc giống... nên...\"). 「ものを」 (dùng để trách móc/ngược lại), 「とともに」 (cùng với), 「うえで」 (sau khi / trên phương diện).","translation_vi":"Tôi nghe nói vì trông giống ông lão lưng còng nên con tôm cũng được viết bằng chữ Hán là 「海老」 (Hải Lão)."},{"mondai":7,"q":4,"prompt":"上司：「セミナー会場の準備はどう？順調？」 部下：「ええ、いすも並べ終わりましたし、(　　)資料を受付に運ぶだけです。」","options":["特に","あとは","少しも","あまりに"],"answer":2,"word_explain":"「あとは〜だけだ」 mang nghĩa \"phần còn lại chỉ cần...\". Phù hợp với ngữ cảnh các việc chính đã xong, chỉ còn mỗi việc cuối cùng.","translation_vi":"Cấp trên: \"Việc chuẩn bị hội trường hội thảo thế nào rồi? Suôn sẻ chứ?\" Cấp dưới: \"Vâng, ghế cũng đã xếp xong hết rồi, phần còn lại chỉ việc mang tài liệu ra quầy lễ tân thôi ạ.\""},{"mondai":7,"q":5,"prompt":"このテニスコートの利用料金は2時間1000円で、1時間しかつかわない(　　)、1000円支払わなければならない。","options":["場合でも","点でも","場合には","場合では"],"answer":1,"word_explain":"「〜場合でも」 mang nghĩa \"ngay cả trong trường hợp...\". Diễn tả vế sau vẫn không thay đổi dù ở trường hợp ngoại lệ.","translation_vi":"Phí sử dụng sân tennis này là 1000 yên cho 2 tiếng, ngay cả trong trường hợp chỉ dùng 1 tiếng thì vẫn phải trả 1000 yên."},{"mondai":7,"q":6,"prompt":"毎日日記を書きつづけることは、(　　)、けっこう難しいことだ。","options":["簡単らしいし","簡単なようであれば","簡単らしくて","簡単なようでいて"],"answer":4,"word_explain":"「〜ようでいて」 diễn tả sự tương phản: \"tưởng như là A nhưng thực chất lại B\" (tưởng chừng đơn giản nhưng lại khá khó).","translation_vi":"Việc viết nhật ký đều đặn mỗi ngày tưởng chừng đơn giản vậy mà thực ra lại khá khó."},{"mondai":7,"q":7,"prompt":"梅雨に入ってもほとんど雨が降らないで、庭の花が(　　)心配だ。","options":["枯れていないことで","枯れてしまわないか","枯れていないからと","枯れてしようもうのだ"],"answer":2,"word_explain":"「〜ないか心配だ」 dùng để diễn tả nỗi lo lắng rằng một điều xấu có thể xảy ra (\"lo lắng không biết có bị héo mất không\"). (Lưu ý: đáp án 4 trong bản in PDF gốc bị lỗi đánh máy).","translation_vi":"Dù đã vào mùa mưa nhưng hầu như không có mưa, tôi lo lắng không biết hoa trong vườn có bị héo mất không."},{"mondai":7,"q":8,"prompt":"今日は、本当は映画を(　　)が、雪が降ってきたので、やめた。","options":["見に行ってばかりだ","見に行ったばかりだ","見に行くつもりだった","見に行ったつもりだった"],"answer":3,"word_explain":"「Vるつもりだった」 diễn tả ý định trước đó trong quá khứ nhưng thực tế đã không làm (\"đã định đi xem nhưng...\").","translation_vi":"Hôm nay thật ra tôi đã định đi xem phim, nhưng vì trời bắt đầu đổ tuyết nên tôi đã thôi."},{"mondai":7,"q":9,"prompt":"今回戦略が有効であったかどうかは、まだ結果が出ていない現時点では(　　)。","options":["判断すべきだ","判断しかねる","判断したにすぎない","判断ざるを得ない"],"answer":2,"word_explain":"「Vます + かねる」 mang nghĩa \"khó lòng mà / không thể làm gì đó\" (do điều kiện khách quan chưa đủ cơ sở để phán đoán).","translation_vi":"Chiến lược lần này có hiệu quả hay không thì ở thời điểm hiện tại khi chưa có kết quả vẫn khó mà phán đoán được."},{"mondai":7,"q":10,"prompt":"この馬の絵は本物そっくりに描かれていて(　　)。","options":["走っていたい","走っているようだ","走り出しそうだ","走り出したがる"],"answer":3,"word_explain":"「Vます + そうだ」 diễn tả trạng thái nhìn bề ngoài có vẻ sắp xảy ra (\"trông như sắp chạy vọt ra\"). 「走り出す」 là bắt đầu chạy.","translation_vi":"Bức tranh con ngựa này được vẽ giống như thật, trông như sắp chạy ra đến nơi vậy."},{"mondai":7,"q":11,"prompt":"私たちが旅館に着くと、従業員たちが笑顔で「ようこそ(　　)」とあいさつしてくれた。","options":["お越しくださいました","お伺いしました","お呼びいただきました","お迎えしました"],"answer":1,"word_explain":"「お越しくださいました」 là tôn kính ngữ của 「来てくれました」 (\"quý khách đã cất công đến\"), dùng để cảm ơn khách đến thăm. 「お伺いしました」 là khiêm nhường ngữ.","translation_vi":"Khi chúng tôi đến lữ quán, các nhân viên đã mỉm cười chào đón: \"Chào mừng quý khách đã đến ạ\"."},{"mondai":7,"q":12,"prompt":"木村：「田中くん、アルバイトを探してるんだって？」 田中：「うん、そうなんだ」 木村：「私が働いている店がアルバイトを募集しているから応募してみない？もちろん田中さんが(　　)」","options":["いいなんて","よかったっけ","いいからだよね","よければだけど"],"answer":4,"word_explain":"「〜ばだけど」 dùng ở cuối câu hội thoại để đưa ra điều kiện bổ sung một cách nhẹ nhàng (\"tất nhiên là nếu cậu thấy được thì...\").","translation_vi":"Kimura: \"Tanaka này, nghe nói cậu đang tìm việc làm thêm à?\" Tanaka: \"Ừ, đúng rồi.\" Kimura: \"Quán mình đang làm có tuyển nhân viên làm thêm đấy, cậu thử ứng tuyển xem sao? Tất nhiên là nếu cậu thấy ổn nhé.\""},{"mondai":8,"q":13,"prompt":"昨日、初めてパンを作ってみた。料理雑誌の＿＿＿　＿＿＿　★　＿＿＿　うまく膨らまなかった。","options":["のに","レシピに書いてある","とおりに","作った"],"answer":4,"word_explain":"Thứ tự đúng: 2 → 3 → ★4 → 1. Cấu trúc 「〜とおりに」(theo đúng như...) và 「〜のに」(mặc dù... nhưng...): レシピに書いてあるとおりに作ったのに。","translation_vi":"Hôm qua tôi đã thử làm bánh mì lần đầu tiên. Mặc dù đã làm đúng theo công thức ghi trên tạp chí nấu ăn, nhưng bánh lại không nở được."},{"mondai":8,"q":14,"prompt":"「10倍がゆ」とは＿＿＿　＿＿＿　★　＿＿＿　おかゆのことです。","options":["作った","水で","10倍の","米1に対して"],"answer":2,"word_explain":"Thứ tự đúng: 4 → 3 → ★2 → 1. Cụm 「米1に対して10倍の水で作ったおかゆ」: đối với 1 phần gạo thì dùng lượng nước gấp 10 lần để nấu.","translation_vi":"\"Cháo tỷ lệ 10\" là loại cháo được nấu bằng lượng nước gấp 10 lần so với 1 phần gạo."},{"mondai":8,"q":15,"prompt":"私が就職した商社は大手の＿＿＿　＿＿＿　★　＿＿＿　新人でも大きな仕事を任せてもらえるので、やりがいがある。","options":["決して","商社に比べると","やる気があれば","規模は大きくないか"],"answer":4,"word_explain":"Thứ tự đúng: 2 → 1 → ★4 → 3. 「大手の商社に比べると決して規模は大きくないが、やる気があれば...」. (Lưu ý: trong bản in PDF gốc ở lựa chọn 4 bị thiếu dấu ten-ten ở chữ 「か」, đúng phải là 「規模は大きくないが」).","translation_vi":"Công ty thương mại nơi tôi vào làm nếu so với các công ty thương mại lớn thì quy mô hoàn toàn không lớn, nhưng chỉ cần có nhiệt huyết thì ngay cả nhân viên mới cũng được giao việc lớn nên rất đáng làm."},{"mondai":8,"q":16,"prompt":"彼女は1970年代に活躍したジャンズピアニストで、この人＿＿＿　＿＿＿　★　＿＿＿　大きな存在だった。","options":["語れない","日本のジャンズは","抜きには","というほど"],"answer":1,"word_explain":"Thứ tự đúng: 3 → 2 → ★1 → 4. Cấu trúc 「〜抜きには〜ない」(nếu không có... thì không thể...) kết hợp 「〜というほど」(đến mức mà...): この人抜きには日本のジャズは語れないというほど. (Lưu ý: bản in PDF gốc đánh máy nhầm 「ジャズ」 thành 「ジャンズ」).","translation_vi":"Bà là nghệ sĩ piano nhạc jazz hoạt động nổi bật vào thập niên 1970, là một nhân vật lớn đến mức nếu thiếu bà thì không thể nói về nền nhạc jazz Nhật Bản được."},{"mondai":8,"q":17,"prompt":"贈り物するときは、自分の勝手な＿＿＿　＿＿＿　★　＿＿＿　相手の趣味や都合をよく考えて決めましょう。","options":["思い込みだけで","喜ばれるどころか","迷惑をかけることもあるので","品物を選ぶと"],"answer":2,"word_explain":"Thứ tự đúng: 1 → 4 → ★2 → 3. Cấu trúc 「〜どころか」(đừng nói là... mà ngược lại còn...): 自分の勝手な思い込みだけで品物を選ぶと喜ばれるどころか迷惑をかけることもあるので.","translation_vi":"Khi tặng quà, nếu chọn đồ chỉ dựa theo suy nghĩ chủ quan của bản thân thì đừng nói là được vui mừng, đôi khi còn gây phiền phức cho đối phương nữa, nên hãy cân nhắc kỹ sở thích và hoàn cảnh của họ rồi hãy quyết định."},{"mondai":9,"q":18,"prompt":"Chỗ trống [48] trong đoạn văn trên","options":["ご存知でしょう","ご存知だと思います","ご存知でしょうか","ご存知だと思いますか"],"answer":3,"word_explain":"Đây là bài viết cho bài phát biểu (スピーチ), tác giả hỏi khán giả một cách lịch sự xem mọi người có biết về \"Robot Therapy\" không nên dùng 「ご存知でしょうか」. (Lưu ý: trong bản in PDF gốc đánh máy nhầm 「セラピー」 thành 「セラビー」).","translation_vi":"Gần đây điều này đang được chú ý tại các cơ sở chăm sóc điều dưỡng, các bạn có biết đến nó không ạ?"},{"mondai":9,"q":19,"prompt":"Chỗ trống [49] trong đoạn văn trên","options":["そこで","そのうえ","それなのに","そういえば"],"answer":1,"word_explain":"「そこで」 (Vì vậy / Do đó) dùng để nối từ vấn đề/khó khăn vừa nêu ở câu trước (nuôi động vật thật gặp khó khăn về dị ứng, chăm sóc) sang giải pháp ở vế sau (chú ý đến robot therapy thay thế cho animal therapy). (Lưu ý: trong bản in PDF gốc có lỗi đánh máy 「マニアル・セラビー」 thay cho 「アニマル・セラピー」).","translation_vi":"Tuy nhiên, khi thực sự định nuôi động vật ở các cơ sở điều dưỡng thì có những mặt khó khăn như vấn đề dị ứng hay chăm sóc. Vì vậy, gần đây liệu pháp robot đã bắt đầu được chú ý như một giải pháp thay thế cho liệu pháp động vật."},{"mondai":9,"q":20,"prompt":"Chỗ trống [50] trong đoạn văn trên","options":["得られる点です","得られてもかまいません","得られるのだそうです","得られなければなりません"],"answer":3,"word_explain":"「〜のだそうです」 dùng để truyền đạt lại thông tin mà người viết tìm hiểu/nghe được từ tài liệu hoặc chuyên môn (tác giả là sinh viên đang tìm hiểu về lĩnh vực này).","translation_vi":"Người ta nói rằng nhờ sự tiếp xúc với những chú robot như vậy, có thể đạt được những hiệu quả như ổn định tinh thần hay cải thiện khả năng giao tiếp."},{"mondai":9,"q":21,"prompt":"Chỗ trống [51] trong đoạn văn trên","options":["貢献するつもりでした","貢献すべきだからです","貢献できるようにしています","貢献できるようになりたいです"],"answer":4,"word_explain":"Câu trước tác giả nói ước mơ tương lai và việc sẽ tiếp tục học tập để tham gia nghiên cứu phát triển robot, nên câu kết hợp lý nhất là bày tỏ mong muốn trong tương lai: 「〜できるようになりたいです」 (muốn trở nên có thể cống hiến).","translation_vi":"Và tôi muốn trở nên có thể đóng góp cho lĩnh vực y tế."}]},{"id":"g_2019_12","displayName":"12/2019","subtitle":"22 câu • Mondai 7–9 (Ngữ pháp)","m9_passage":"初めて正確な日本地図を作成した人物として知られる伊能忠敬は、1745年、上総国(今の千葉県)に生まれた。優れた経営者だった忠敬だが、50歳を前に仕事をやめ、興味があった星や暦について高橋至時のもとで[48]。19歳も年下の至時を忠敬は敬い、熱心に勉強した。\n\n当時の学者たちの関心は、地球の直径を知ることにあった。江戸(今の東京)から蝦夷地(今の北海道)までの距離は当時はまだわからなかったが、それが[49]正確に直径が計算できると知った忠敬は、蝦夷地へ行くことを願う。しかし、蝦夷地に行くには国の許可が必要だった。至時は、蝦夷地の地図作成を理由に国の許可をとり、忠敬を担当にする。[50]、忠敬55歳のとき、地図作りの旅が始まった。\n\n昼間は測って歩き、夜は星を観察して昼間測った数値を修正する日々が続いた。完成した蝦夷地の地図は国から高く評価され、忠敬は東日本の地図作成も[51]。地図作成の旅は順調に終わったが、完成前、忠敬を支え続けた至時が病気で亡くなってしまう。一番の理解者である至時を失い、忠敬はひどく落ち込んだ。だが、悲しみに耐え、さらに命じられた西日本の地図作成にも取り組む。旅を終え、完成に向けて作業の最終段階に入っていた1818年、忠敬は73歳で人生の幕を閉じた。作業は弟子らが続け、1821年、日本全国の地図が完成した。\n\n忠敬は自分に大きな仕事ができたのはすべて至時先生のおかげだと書き残している。歴史に残る[52]は、二人の信頼関係によって、誕生したのである。","questions":[{"mondai":7,"q":1,"prompt":"X市とY市を結ぶ橋が、約10年の工事(　　)、昨年ようやく完成した。","options":["の際","の末","のたび","のもと"],"answer":2,"word_explain":"Cấu trúc 「Danh từ + の末（に）」: sau một quá trình lâu dài, vất vả thì cuối cùng đạt được kết quả gì đó. Ở đây mang nghĩa \"sau khoảng 10 năm thi công, cuối cùng cũng hoàn thành\".","translation_vi":"Cây cầu nối thành phố X và thành phố Y, sau khoảng 10 năm thi công, cuối cùng cũng đã hoàn thành vào năm ngoái."},{"mondai":7,"q":2,"prompt":"「田中さんがこの会社をやめるって話、まだ秘密みたいだから、悪いけど、聞かなかった(　　)にしてくれない？」","options":["こと","だけ","もの","の"],"answer":1,"word_explain":"Cấu trúc 「Vた + ことにする」: coi như là đã (hoặc chưa) làm gì. 「聞かなかったことにする」 nghĩa là \"coi như chưa từng nghe thấy\".","translation_vi":"\"Chuyện anh Tanaka nghỉ việc ở công ty này hình như vẫn còn là bí mật đấy, nên ngại quá nhưng cậu coi như chưa nghe thấy được không?\""},{"mondai":7,"q":3,"prompt":"最近、よくお腹が痛くなるので、病院で診てもらったら、(　　)ストレスが原因だろうと言われた。","options":["どうか","まさか","おそらく","いったい"],"answer":3,"word_explain":"Phó từ 「おそらく」 thường đi kèm với 「〜だろう / 〜と思われる」 để diễn tả sự phỏng đoán có xác suất cao (\"có lẽ là...\").","translation_vi":"Gần đây tôi hay bị đau bụng nên đã đi bệnh viện khám, và được bác sĩ nói rằng có lẽ nguyên nhân là do stress."},{"mondai":7,"q":4,"prompt":"私は、急な雨(　　)、いつも折り畳み傘を持ち歩いている。","options":["に反して","に加えて","に備えて","に応じて"],"answer":3,"word_explain":"Cấu trúc 「Danh từ + に備えて」: để đề phòng, chuẩn bị sẵn sàng cho tình huống bất ngờ hoặc sự việc sắp tới (ở đây là mưa bất chợt).","translation_vi":"Để đề phòng những cơn mưa bất chợt, tôi luôn mang theo ô gấp bên mình."},{"mondai":7,"q":5,"prompt":"(自転車屋で) 客「すみません、自転車のブレーキ。壊れちゃったんですけど、すぐ直りますか。」 店員「そうですね、これだったら30分(　　)直りますよ。」","options":["もあるのに","もあれば","はないのに","はなければ"],"answer":2,"word_explain":"Cấu trúc 「Thời gian/Số lượng + もあれば〜」: chỉ cần có từng đó thời gian/số lượng là đủ để thực hiện hành động (\"chỉ cần 30 phút là sửa xong\").","translation_vi":"(Tại cửa hàng xe đạp) Khách: \"Xin lỗi, phanh xe đạp của tôi bị hỏng mất rồi, có sửa ngay được không ạ?\" Nhân viên: \"Để xem nào, với tình trạng này thì chỉ cần 30 phút là sửa xong đấy ạ.\""},{"mondai":7,"q":6,"prompt":"(講演会で) 司会「ご来場の皆様、本日は第3回さくら市教育講演会に(　　)、ありがとうございます。」","options":["まいり","ご覧になり","お目にかかり","おいでくださり"],"answer":4,"word_explain":"「おいでになる」 là tôn kính ngữ của 「来る」 (đến). Kết hợp 「おいでくださり」 thể hiện sự biết ơn trang trọng đối với việc khách mời đã đến tham dự.","translation_vi":"(Tại buổi diễn thuyết) Người dẫn chương trình: \"Kính thưa quý vị có mặt hôm nay, xin chân thành cảm ơn quý vị đã đến tham dự Buổi diễn thuyết Giáo dục Thành phố Sakura lần thứ 3.\""},{"mondai":7,"q":7,"prompt":"夫は動物が好きじゃないから、もし私がペットを飼いたいと言っても、(　　)。","options":["反対しかねる","反対しようがない","反対するならいい","反対するに決まっている"],"answer":4,"word_explain":"Cấu trúc 「Thể thông thường + に決まっている」: chắc chắn là, nhất định là (phỏng đoán khẳng định cao dựa trên suy luận thực tế).","translation_vi":"Chồng tôi không thích động vật nên dù tôi có nói là muốn nuôi thú cưng thì anh ấy chắc chắn cũng sẽ phản đối thôi."},{"mondai":7,"q":8,"prompt":"今はスポーツも演劇もテレビで見られる時代だが、直接見ることに(　　)得られない感動というものがある。","options":["とってしか","よってしか","ついてのみ","対してのみ"],"answer":2,"word_explain":"Cấu trúc 「〜によってしか〜ない」: chỉ thông qua phương thức/cách làm đó mới có thể đạt được việc gì (\"chỉ có thể có được bằng việc xem trực tiếp\").","translation_vi":"Bây giờ là thời đại mà cả thể thao lẫn kịch nghệ đều có thể xem trên TV, nhưng vẫn có những sự xúc động chỉ có thể có được khi xem trực tiếp."},{"mondai":7,"q":9,"prompt":"子供のおもちゃは、種類ごとに透明なケースにしまって中身がわかる(　　)、子供がおもちゃを探しやすくなるので、おすすめです。","options":["ようになるには","ようにしておくと","ようになっても","ようにしておいて"],"answer":2,"word_explain":"Kết hợp 「ようにする」 (làm sao cho) + 「ておく」 (làm sẵn, giữ trạng thái) + 「と」 (nếu làm vậy thì sẽ dẫn tới kết quả tự nhiên).","translation_vi":"Đồ chơi của trẻ nhỏ, nếu cất vào hộp trong suốt theo từng loại để có thể nhìn thấy bên trong thì trẻ sẽ dễ tìm đồ chơi hơn, nên rất đáng áp dụng."},{"mondai":7,"q":10,"prompt":"昨日購入した中古の大型バイクは、かなり古いものなのだが、とてもきれいな状態だった。前の持ち主によほど大切に(　　)。","options":["されてもおかしくない","し続けてもおかしくない","されていたに違いない","し続けていたに違いない"],"answer":3,"word_explain":"Vì có 「前の持ち主に」 (bởi người chủ trước) nên động từ dùng thể bị động 「大切にされていた」, kết hợp với 「に違いない」 (chắc hẳn là).","translation_vi":"Chiếc xe mô tô phân khối lớn cũ mà tôi mua hôm qua tuy đã khá cổ rồi nhưng vẫn ở trong tình trạng rất đẹp. Chắc hẳn nó đã được người chủ trước giữ gìn vô cùng cẩn thận."},{"mondai":7,"q":11,"prompt":"(電話で) 上田「課長、すみません、今日はお休みをいただけないでしょうか。娘と夫が風邪で熱を出してしまったんです。」 課長「それは大変だね。わかりました。看病でお疲れて、上田さんが(　　)。」","options":["倒れなくなるよ","倒れてしまいたくないのに","倒れないことになるの","倒れてしまわないようにね"],"answer":4,"word_explain":"Cấu trúc 「Vないように（ね）」 ở cuối câu dùng để nhắc nhở, dặn dò đối phương cẩn thận đừng để xảy ra sự việc không mong muốn.","translation_vi":"(Qua điện thoại) Ueda: \"Trưởng phòng ơi, xin lỗi, hôm nay tôi có thể xin nghỉ phép được không ạ? Con gái và chồng tôi bị cảm sốt mất rồi.\" Trưởng phòng: \"Thế thì vất vả rồi. Tôi hiểu rồi. Đừng để vì mệt mỏi chăm sóc người bệnh mà cô Ueda cũng ngã bệnh theo nhé.\""},{"mondai":7,"q":12,"prompt":"山田「林さんの手作りクッキー、本当においしかったです。どうもありがとうございました。」 林「どういたしまして。山田さんにおいしいって(　　)です。」","options":["言ってもらえてよかった","言ってもらってもよかった","言ってあげられてよかった","言ってあげてもよかった"],"answer":1,"word_explain":"「言ってもらえる」 là thể khả năng của 「言ってもらう」 (được người khác nói cho). 「言ってもらえてよかった」 diễn tả niềm vui khi nhận được lời khen.","translation_vi":"Yamada: \"Bánh quy tự làm của chị Hayashi thực sự rất ngon ạ. Cảm ơn chị nhiều.\" Hayashi: \"Không có gì đâu. Được anh Yamada khen ngon là tôi vui rồi.\""},{"mondai":8,"q":13,"prompt":"他社からの質問や問い合わせには、一度社内で　＿＿＿　＿＿＿　★　＿＿＿　できないことになっています。","options":["検討","回答","でないと","してから"],"answer":3,"word_explain":"Thứ tự đúng: 1 → 4 → ★3 → 2. Cấu trúc 「Vてからでないと〜ない」: nếu không làm V trước thì không thể làm hành động sau (「検討してからでないと回答できない」).","translation_vi":"Đối với các câu hỏi hay liên hệ từ công ty khác, quy định là nếu chưa xem xét qua một lượt trong nội bộ công ty thì không thể trả lời được."},{"mondai":8,"q":14,"prompt":"昨日の夜は、11時までには　＿＿＿　＿＿＿　★　＿＿＿　、結局寝たのは1時だった。","options":["つい","寝ようと","思いつつ","テレビを見続けてしまい"],"answer":1,"word_explain":"Thứ tự đúng: 2 → 3 → ★1 → 4. Cấu trúc 「〜ようと思いつつ」 (tuy nghĩ là sẽ... nhưng) kết hợp với phó từ 「つい〜てしまう」 (lỡ, vô tình làm gì ngoài ý muốn).","translation_vi":"Tối hôm qua, dù trong lòng nghĩ là sẽ đi ngủ trước 11 giờ nhưng tôi lại lỡ xem TV tiếp mất, kết cục là 1 giờ mới ngủ."},{"mondai":8,"q":15,"prompt":"私は、新しいことにチャレンジするときでも悩まない。　＿＿＿　＿＿＿　★　＿＿＿　と思っているからだ。","options":["まずやってみて","もう一度考えればいい","うまくいかなかったら","そのときにどうしたらいいか"],"answer":4,"word_explain":"Thứ tự đúng: 1 → 3 → ★4 → 2. Mạch câu: trước tiên cứ thử làm (1), nếu không ổn (3) thì lúc đó nên làm thế nào (4) hãy suy nghĩ lại một lần nữa (2).","translation_vi":"Tôi không hề băn khoăn ngay cả khi thử thách bản thân với những điều mới mẻ. Bởi vì tôi nghĩ rằng trước tiên cứ thử làm xem, nếu không suôn sẻ thì lúc đó suy nghĩ lại xem nên làm thế nào là được."},{"mondai":8,"q":16,"prompt":"家の近くの本屋では　＿＿＿　＿＿＿　★　＿＿＿　少し遠いけど行ってみようと思う。","options":["買えなかった漫画の最新号が","まだ買えるらしいので","もう売り切れていて","隣町のABC書店に行けば"],"answer":4,"word_explain":"Thứ tự đúng: 3 → 1 → ★4 → 2. Mệnh đề 「家の近くの本屋ではもう売り切れていて買えなかった」 bổ nghĩa cho 「漫画の最新号が」, sau đó 「隣町のABC書店に行けばまだ買えるらしいので」 nêu lý do.","translation_vi":"Tập mới nhất của bộ truyện tranh mà ở hiệu sách gần nhà đã bán hết nên không mua được, nghe nói nếu đến hiệu sách ABC ở thị trấn bên cạnh thì vẫn mua được, nên dù hơi xa một chút nhưng tôi định sẽ đi thử."},{"mondai":8,"q":17,"prompt":"話題のカレー屋さんを初訪問。野菜の　＿＿＿　＿＿＿　★　＿＿＿　「夏限定ベジタブルカレー」。評判どおりのおいしさだった。","options":["中で","私が選んだのは","夏の野菜がたっぷり入った","カレーがいくつかある"],"answer":2,"word_explain":"Thứ tự đúng: 4 → 1 → ★2 → 3. Cụm 「野菜のカレーがいくつかある中で」 (trong số vài món cà ri rau củ), tiếp theo là 「私が選んだのは」(món tôi chọn là) + 「夏の野菜がたっぷり入った」(bổ nghĩa cho 「夏限定ベジタブルカレー」).","translation_vi":"Lần đầu ghé thăm quán cà ri đang nổi tiếng. Trong số vài món cà ri rau củ ở đây, món tôi chọn là \"Cà ri rau củ giới hạn mùa hè\" có thật nhiều rau củ mùa hè. Ngon đúng như lời đồn."},{"mondai":9,"q":18,"prompt":"Chỗ trống [48] trong đoạn văn trên","options":["学んだばかりだ","学ぼうと思っている","学び始めた","学ぶところだった"],"answer":3,"word_explain":"Câu chuyện được kể ở thì quá khứ (câu sau có 「熱心に勉強した」), nên cần 「学び始めた」 (bắt đầu theo học dưới sự chỉ dạy của Takahashi Yoshitoki).","translation_vi":"Tadataka vốn là một nhà kinh doanh xuất sắc, nhưng trước năm 50 tuổi ông đã nghỉ việc và bắt đầu theo học về các vì sao và lịch pháp mà mình hứng thú dưới sự hướng dẫn của Takahashi Yoshitoki."},{"mondai":9,"q":19,"prompt":"Chỗ trống [49] trong đoạn văn trên","options":["わかって","わかれば","わかるため","わかったことで"],"answer":2,"word_explain":"Vì ở thời điểm đó khoảng cách vẫn chưa được biết rõ (「まだわからなかったが」), nên phải dùng thể điều kiện giả định 「わかれば」 (\"nếu biết được khoảng cách đó thì có thể tính chính xác đường kính\").","translation_vi":"Khoảng cách từ Edo (Tokyo ngày nay) đến vùng đất Ezo (Hokkaido ngày nay) khi đó vẫn chưa được biết rõ, nhưng khi biết rằng nếu nắm được khoảng cách đó thì có thể tính chính xác đường kính Trái Đất, Tadataka đã mong muốn được đến Ezo."},{"mondai":9,"q":20,"prompt":"Chỗ trống [50] trong đoạn văn trên","options":["また","しかも","ところが","こうして"],"answer":4,"word_explain":"Liên từ 「こうして」 (như vậy, thế là) nối kết quả tự nhiên ngay sau quá trình chuẩn bị ở câu trước (xin được phép của triều đình và giao cho Tadataka phụ trách).","translation_vi":"Thế là, vào năm Tadataka 55 tuổi, chuyến hành trình vẽ bản đồ đã bắt đầu."},{"mondai":9,"q":21,"prompt":"Chỗ trống [51] trong đoạn văn trên","options":["命じられることとなる","命じられたことになる","命じられることもある","命じられたことである"],"answer":1,"word_explain":"Cấu trúc 「V（bị động）+ こととなる」 (tương đương 「ことになる」 trong văn viết trang trọng): dẫn đến việc được giao lệnh lập bản đồ khu vực Đông Nhật Bản.","translation_vi":"Bản đồ vùng Ezo hoàn thành đã được chính quyền đánh giá cao, và Tadataka cũng được giao nhiệm vụ lập bản đồ khu vực Đông Nhật Bản."},{"mondai":9,"q":22,"prompt":"Chỗ trống [52] trong đoạn văn trên","options":["これ","あるもの","日本地図","そういう地図"],"answer":3,"word_explain":"Danh từ 「日本地図」 kết hợp với cụm bổ nghĩa 「歴史に残る」 (\"tấm bản đồ Nhật Bản lưu danh sử sách\") phù hợp hoàn toàn với nội dung tổng kết bài văn.","translation_vi":"Tấm bản đồ Nhật Bản lưu danh sử sách đã được ra đời chính nhờ vào mối quan hệ tin cậy giữa hai người."}]},{"id":"g_2019_07","displayName":"07/2019","subtitle":"22 câu • Mondai 7–9 (Ngữ pháp)","m9_passage":"以下は、留学生の作文である。\n\n打ち水\nロバーツ　アレン\n\n夏休みに、友達に誘われて打ち水のイベントに参加しました。私はそのとき初めて打ち水というものを知りました。打ち水は、暑さ対策として道路や庭、玄関先などに水をまくという、日本に昔から伝わる生活の知恵です。もともとは各家庭で行うものでしたが、節電や地球温暖化対策として打ち水のイベントを企画する自治体なども[48]。\n\n打ち水をすると、確かに涼しく感じました。[49]、気分の問題ではないかとも思いました。打ち水によって実際に気温は下がるのでしょうか。\n\n調べてみたら、打ち水の効果を調べた実際結果を紹介している記事がありました。その記事によると、水をまいたところの気温が2度下がったということでした。これは水の性質によるものです。水は気体になるときに、周囲の熱を吸収します。水をまいたところの地面の熱は気体と一緒に逃げていき、気温が[50]。しかも、地面の温度は、水が蒸発しきった後も1時間は下がったままだったとも書かれていました。\n\n打ち水の効果を十分に得るには、朝か夕方に日陰にまくこともポイントのようです。そうすることで水がすぐに蒸発せず、温度の下がった状態が持続します。私が参加したイベントも夕方からだったので、なぜだろうと思っていましたが、[51]あったのだと知って、なるほどと思いました。\n\n打ち水の効果は、科学的に説明できるものでした。だから昔から今まで打ち水の文化が続いているのだと[52]。","questions":[{"mondai":7,"q":1,"prompt":"レビの後ろ側は、すぐほこり(　　)になってしまう。","options":["きり","じゅう","ぐらい","だらけ"],"answer":4,"word_explain":"「N + だらけ」diễn tả trạng thái bị phủ đầy hoặc toàn là thứ không mong muốn như bụi bẩn, rác, lỗi sai (ほこりだらけ = đầy bụi). Lưu ý bản đề in thiếu chữ テ trong テレビ (レビ).","translation_vi":"Phía sau tivi rất nhanh bị bám đầy bụi."},{"mondai":7,"q":2,"prompt":"A「ねえ、明日、有事があるって言ってたけど、パーティーには来られそう？」 B「有事が何時に終わるかわからないんだよ。行ける(　　)、多分、途中からになると思う。」","options":["からって","ものなら","どころか","としても"],"answer":4,"word_explain":"「V + としても」mang nghĩa \"dù giả sử có... đi nữa thì...\" (nhượng bộ giả định). Các lựa chọn khác không hợp ngữ cảnh: からって (vì... mà), ものなら (nếu có thể...), どころか (huống hồ là...). Lưu ý bản đề gõ nhầm 用事 thành 有事.","translation_vi":"A: \"Này, ngày mai cậu bảo có việc bận, liệu có đến dự tiệc được không?\" B: \"Tớ không biết việc bận mấy giờ mới xong nữa. Dù có đi được chăng nữa, chắc cũng phải tham gia từ giữa chừng.\""},{"mondai":7,"q":3,"prompt":"X社は、新しい事業を始める(　　)、現在、社員を募集している。","options":["とすると","にあたって","からには","のだったら"],"answer":2,"word_explain":"「V(る) / N + にあたって」diễn tả ý nghĩa \"nhân dịp / khi bước vào thực hiện\" một sự việc quan trọng, mang tính bước ngoặt hoặc trang trọng.","translation_vi":"Nhân dịp khởi đầu mảng kinh doanh mới, công ty X hiện đang tuyển dụng nhân viên."},{"mondai":7,"q":4,"prompt":"私はピアノを弾くことが、好き(　　)好き(　　)たまらない。","options":["が/が","に/に","で/で","は/は"],"answer":3,"word_explain":"Mẫu nhấn mạnh cảm xúc「〜て〜てたまらない」hoặc với tính từ đuôi な là「Aな + で + Aな + でたまらない」(好きで好きでたまらない = thích ơi là thích).","translation_vi":"Tôi thích chơi đàn piano đến mức không thể chịu nổi (cực kỳ thích)."},{"mondai":7,"q":5,"prompt":"（電話で） 田中「ねえ、明日のイベントの準備、終わった？」 小川「まだ終わってないけど、まあ、大丈夫だよ。」 田中「(　　)小川さんの楽観的な性格がうらやましいよ。」","options":["そんなに","あんなに","そういう","ああいう"],"answer":3,"word_explain":"「そういう + danh từ」dùng để chỉ tính chất vừa được thể hiện trong lời nói ngay trước đó của người nghe (\"tính cách lạc quan như thế\"). 「そんなに・あんなに」không đứng trực tiếp trước「小川さんの…」để bổ nghĩa cho cụm danh từ này, còn「ああいう」chỉ sự việc xa lạ hoặc trong ký ức chung.","translation_vi":"(Qua điện thoại) Tanaka: \"Này, chuẩn bị cho sự kiện ngày mai xong chưa?\" Ogawa: \"Vẫn chưa xong đâu, nhưng mà chắc ổn thôi.\" Tanaka: \"Tớ ghen tị với tính cách lạc quan như thế của cậu đấy, Ogawa ạ.\""},{"mondai":7,"q":6,"prompt":"日曜日に行われたマラソン大会に弟が参加して、10キロのコースを45分で(　　)","options":["走りきった","走り始めた","走ってばかりだ","走るようにする"],"answer":1,"word_explain":"「V(ます) + きる」nghĩa là làm hết hoàn toàn đến cuối cùng (走りきる = chạy hết toàn bộ chặng đường).","translation_vi":"Em trai tôi đã tham gia giải marathon tổ chức vào Chủ nhật và chạy hết chặng đường 10 km trong 45 phút."},{"mondai":7,"q":7,"prompt":"子供のころ、海水浴に行く前の日はいつも「どうか明日は雨が(　　)」と祈りながら寝ていた。","options":["降ることはありません","降りませんように","降らなくてもいいです","降らないでしょうか"],"answer":2,"word_explain":"「どうか〜ますように / 〜ませんように」là mẫu câu cầu nguyện, mong ước (đi cùng động từ 祈る).","translation_vi":"Hồi nhỏ, trước ngày đi tắm biển hôm nào tôi cũng đi ngủ vừa cầu nguyện: \"Xin cho ngày mai trời đừng mưa\"."},{"mondai":7,"q":8,"prompt":"鈴木選手は、アマチュア時代に何度かこの大会に出場しているが、プロの選手(　　)今回が初めての出場だ。","options":["としては","としても","にとっては","にとっても"],"answer":1,"word_explain":"「N + としては」diễn tả lập trường, tư cách (\"với tư cách là...\", có hàm ý đối chiếu với tư cách khác như アマチュア時代). 「にとっては」mang nghĩa \"đối với (ai đó trong việc đánh giá)\".","translation_vi":"Tuyển thủ Suzuki từng tham gia giải đấu này vài lần thời còn nghiệp dư, nhưng với tư cách tuyển thủ chuyên nghiệp thì đây là lần đầu tiên anh tham dự."},{"mondai":7,"q":9,"prompt":"泣くのを我慢(　　)、逆に涙はあふれ出した。","options":["しようとすることから","しそうになることから","しようとすればするほど","しそうになればなるほど"],"answer":3,"word_explain":"「V(よう)とすればするほど」diễn tả ý \"càng cố gắng làm gì thì kết quả lại càng...\". Ở đây chủ thể chủ động cố nhịn (我慢しようとする) chứ không phải trạng thái tự nhiên sắp nhịn (しそうになる).","translation_vi":"Càng cố nhịn khóc thì nước mắt ngược lại càng trào ra."},{"mondai":7,"q":10,"prompt":"押し入れを片付けていたら、子供のころに大切にしていたぬいぐるみが出てきた。(　　)と思ったが、どうしても捨てられなかった。","options":["捨ててくるだろう","捨てているのだ","捨ててあるのか","捨ててしまおうか"],"answer":4,"word_explain":"「V(よう)かと思う」diễn tả ý định thoáng qua trong suy nghĩ (\"tính làm... xem sao\"), kết hợp với「〜てしまう」mang sắc thái làm dứt khoát/vứt bỏ hoàn toàn.","translation_vi":"Khi dọn tủ âm tường thì thấy con thú nhồi bông từng trân trọng hồi nhỏ. Tôi đã định vứt quách đi, nhưng dù thế nào cũng không nỡ vứt."},{"mondai":7,"q":11,"prompt":"田中「昨日、息子がひろしくんに(　　)、ありがとうございます。」 ひろしの母「いえいえ。」","options":["遊んでもらえそうで","遊んでくれそうで","遊んでもらったそうで","遊んでくれたそうで"],"answer":3,"word_explain":"Chủ ngữ là「息子が」và đối tác thực hiện hành động cho mình là「ひろしくんに」, nên bắt buộc dùng「〜に〜てもらう」(息子がひろしくんに遊んでもらった). Kết hợp「〜そうだ」nghe kể lại ở dạng nối「〜そうで」để cảm ơn.","translation_vi":"Tanaka: \"Nghe nói hôm qua con trai tôi được bé Hiroshi chơi cùng, cảm ơn chị nhiều ạ.\" Mẹ của Hiroshi: \"Không có gì đâu ạ.\""},{"mondai":7,"q":12,"prompt":"この映画を見て、私は今までこれほど何かに夢中に(　　)と考えさせられた。","options":["なることがあるだろうか","なったことがあっただろうか","することがあるだろうか","したことがあっただろうか"],"answer":2,"word_explain":"Cụm cố định là「夢中になる」(say mê vào cái gì), loại「する」. Vì có trạng từ「今まで」(cho đến bây giờ) hỏi về trải nghiệm trong quá khứ nên dùng「なったことがあっただろうか」.","translation_vi":"Xem bộ phim này xong, tôi chợt phải suy nghĩ rằng từ trước đến nay liệu mình đã từng say mê điều gì đến mức như thế này chưa."},{"mondai":8,"q":13,"prompt":"料理の面白いところは、安い材料でも　＿＿＿　＿＿＿　★　＿＿＿　ができるところです。","options":["ごちそう","工夫","豪華な","次第で"],"answer":3,"word_explain":"Thứ tự đúng: 2 → 4 → ★3 → 1 (工夫 / 次第で / 豪華な / ごちそう). Mẫu「N + 次第で」(tùy thuộc vào sự khéo léo) và cụm danh từ「豪華なごちそう」(món ăn thịnh soạn).","translation_vi":"Điểm thú vị của nấu ăn là ngay cả với nguyên liệu rẻ tiền, tùy vào sự khéo léo sáng tạo cũng có thể làm ra món ăn thịnh soạn."},{"mondai":8,"q":14,"prompt":"田中「昨日は、息子の高校の入学式だったんですよ。」 山田「田中さんの　＿＿＿　＿＿＿　★　＿＿＿　ですか。早いですね。」","options":["もう","息子さん","高校生","も"],"answer":1,"word_explain":"Thứ tự đúng: 2 → 4 → ★1 → 3 (息子さん / も / もう / 高校生). Sau「田中さんの」là danh từ「息子さん」, đi với trợ từ「も」và phó từ「もう」(cũng đã là học sinh cấp 3 rồi sao).","translation_vi":"Tanaka: \"Hôm qua là lễ nhập học cấp 3 của con trai tôi đấy.\" Yamada: \"Con trai của anh Tanaka cũng đã lên cấp 3 rồi sao? Nhanh thật đấy.\""},{"mondai":8,"q":15,"prompt":"世界各国の国会議員選挙における投票率を世代ごとに見ると、若い世代の　＿＿＿　＿＿＿　★　＿＿＿　ことがわかる。","options":["我が国に限らず","傾向がある","投票率は","相対的に低い"],"answer":4,"word_explain":"Thứ tự đúng: 3 → 1 → ★4 → 2 (投票率は / 我が国に限らず / 相対的に低い / 傾向がある). Sau「若い世代の」là danh từ「投票率は」, tiếp theo là trạng ngữ「我が国に限らず」(không chỉ ở nước ta) và vị ngữ「相対的に低い傾向がある」.","translation_vi":"Khi xem tỷ lệ bỏ phiếu trong bầu cử quốc hội ở các nước trên thế giới theo từng thế hệ, có thể thấy tỷ lệ bỏ phiếu của thế hệ trẻ, không chỉ riêng ở nước ta, có xu hướng thấp một cách tương đối."},{"mondai":8,"q":16,"prompt":"5歳の娘は、私と同じ警察官になりたいと言っている。本当に将来　＿＿＿　＿＿＿　★　＿＿＿　感激した。","options":["別として","そんなことを","言ってくれたことに","なるかどうかは"],"answer":2,"word_explain":"Thứ tự đúng: 4 → 1 → ★2 → 3 (なるかどうかは / 別として / そんなことを / 言ってくれたことに). Mẫu「〜は別として」(tạm gác chuyện... sang một bên / khoan nói chuyện...) nối với「そんなことを言ってくれたことに感激した」.","translation_vi":"Cô con gái 5 tuổi của tôi nói muốn trở thành cảnh sát giống tôi. Thực sự tương lai có trở thành hay không thì khoan hãy nói, tôi rất cảm động vì con bé đã nói ra điều đó."},{"mondai":8,"q":17,"prompt":"試合に負けて本当は　★　＿＿＿　＿＿＿　＿＿＿　表情だったのは、「つらいときこそ明るく」というのが監督の方針だからだそうだ。","options":["悔しいはずの","明るい","なぜか","選手たちが"],"answer":1,"word_explain":"Thứ tự đúng: ★1 → 4 → 3 → 2 (悔しいはずの / 選手たちが / なぜか / 明るい). 「本当は悔しいはずの」bổ nghĩa cho「選手たちが」, sau đó「なぜか明るい表情だったのは」tạo thành mệnh đề chủ ngữ giải thích lý do.","translation_vi":"Việc các tuyển thủ vốn dĩ thua trận hẳn phải rất tiếc nuối nhưng không hiểu sao lại có vẻ mặt tươi sáng, nghe nói là vì phương châm của huấn luyện viên là \"Chính lúc gian khổ mới phải vui vẻ\"."},{"mondai":9,"q":18,"prompt":"Chỗ trống [48] trong đoạn văn trên","options":["増えたとします","増えたためです","増えてしまいます","増えているそうです"],"answer":4,"word_explain":"「〜ているそうです」dùng để truyền đạt thông tin nghe được/tìm hiểu được phù hợp với giọng văn bài viết của du học sinh kể về kiến thức mới biết. 「〜てしまいます」mang sắc thái tiêu cực/nuối tiếc nên không hợp.","translation_vi":"Vốn dĩ đây là việc làm ở từng gia đình, nhưng nghe nói gần đây các chính quyền địa phương đứng ra tổ chức sự kiện té nước như một biện pháp tiết kiệm điện và chống nóng lên toàn cầu cũng đang tăng lên."},{"mondai":9,"q":19,"prompt":"Chỗ trống [49] trong đoạn văn trên","options":["ただ","それに","つまり","それどころか"],"answer":1,"word_explain":"「ただ」(tuy nhiên / chỉ có điều) dùng để bổ sung ý trái ngược hoặc băn khoăn so với câu trước (\"đúng là thấy mát, nhưng chỉ có điều lại nghĩ hay là do tâm lý\").","translation_vi":"Khi té nước thì đúng là tôi cảm thấy mát mẻ. Tuy nhiên, tôi cũng tự hỏi liệu có phải chỉ là vấn đề cảm giác tâm lý hay không."},{"mondai":9,"q":20,"prompt":"Chỗ trống [50] trong đoạn văn trên","options":["下がるところです","下がる一方でした","下がるというわけです","下がることがありました"],"answer":3,"word_explain":"「〜というわけです」(nghĩa là / sở dĩ như vậy là...) dùng để đúc kết lời giải thích về cơ chế khoa học đã trình bày ở các câu trước.","translation_vi":"Nhiệt của mặt đất nơi vừa té nước sẽ thoát ra cùng với hơi nước, điều đó có nghĩa là nhiệt độ không khí giảm xuống."},{"mondai":9,"q":21,"prompt":"Chỗ trống [51] trong đoạn văn trên","options":["ある理由が","そのような理由が","どの理由も","あんな理由も"],"answer":2,"word_explain":"「そのような理由が」dùng từ chỉ thị「そのよう」để quy chiếu lại lý do vừa được nêu ngay ở câu trước (nên tưới vào sáng sớm hoặc chiều tối ở chỗ râm để nước không bay hơi ngay).","translation_vi":"Sự kiện tôi tham gia cũng diễn ra từ chiều tối nên tôi từng thắc mắc tại sao lại thế, và khi biết có lý do như vậy thì tôi thấy quả đúng là như thế thật."},{"mondai":9,"q":22,"prompt":"Chỗ trống [52] trong đoạn văn trên","options":["納得させられました","納得したのでしょう","納得させてほしかったです","納得してもらえました"],"answer":1,"word_explain":"「納得させられました」(thể sai khiến bị động của 納得する) diễn tả người viết cảm thấy hoàn toàn bị thuyết phục một cách tự nhiên bởi chứng cứ khoa học vừa tìm hiểu được.","translation_vi":"Tôi đã thực sự bị thuyết phục rằng chính vì thế mà văn hóa té nước mới được duy trì từ xưa đến nay."}]},{"id":"g_2018_12","displayName":"12/2018","subtitle":"22 câu • Mondai 7–9 (Ngữ pháp)","m9_passage":"伝統から最新技術へ\n\n今も昔も、子供たちに親しまれている折り紙。そんな身近な折り紙が今、「折り紙工学」という学問となっている。一例を[48]。\n\n折り紙の「折って畳むこと」と「畳んだものを広げること」を利用した研究がある。大きなものを小さくし、それを簡単に元の大きさに戻す方法として、折るだけで形や大きさが変えられる折り紙が注目されたのだ。ただ折って小さくするのなら、新聞を折り畳むように何回も折ればいい。しかしそれでは、広げるときに、畳んだ分の回数だけ開くことになる。[49]、一気に元の大きさに戻せる折り方を開発するために研究が重ねられた。\n\nその結果、何回折った後でも、折り畳んだ状態から両端を引っ張るだけで、元の平面に戻すことができる方法にたどり着いたのである。\n\nこの折り方を[50]、人工衛星に用いる「太陽電池パネル」などの装置が作られている。\n\n装置を宇宙へ運ぶロケットの容量には限界があり、装置は小さくしなければならない。だからといって分割して部品にすると、宇宙空間で組み立てる技術が必要となる。ここに研究の成果が生かされる。開発された折り方を使えば、装置を折り畳んで小さくすることができ、宇宙空間に出たときには簡単に[51]。\n\n伝統的な遊びが宇宙で使われる最新技術につながっている。子供と折り紙で遊びながら、このような科学の話を[52]。折り紙を通して、宇宙工学や技術開発の分野にも興味を持つかもしれない。","questions":[{"mondai":7,"q":1,"prompt":"あの人は、人の意見を聞き(　　)しないで、自分の主張ばかりする。","options":["まで","も","と","を"],"answer":2,"word_explain":"Cấu trúc「Vます + もしない」mang nghĩa \"thậm chí không làm ~ / chẳng thèm làm ~\", nhấn mạnh sự phủ định hoàn toàn hành động.","translation_vi":"Người đó thậm chí còn chẳng thèm nghe ý kiến của người khác mà chỉ toàn khẳng định ý kiến của bản thân."},{"mondai":7,"q":2,"prompt":"さっき、買い物(　　)、コンビニに寄ってATMでお金を下ろしてきた。","options":["の場合","にしては","のついでに","というのは"],"answer":3,"word_explain":"「Nのついでに / Vるついでに」có nghĩa là \"nhân tiện làm A thì kết hợp làm luôn B\".","translation_vi":"Lúc nãy, nhân tiện đi mua sắm, tôi đã ghé vào cửa hàng tiện lợi và rút tiền ở cây ATM."},{"mondai":7,"q":3,"prompt":"（テレビ番組で） 「私たちが住んでいる地球は、(　　)どうやってできたのでしょうか。地球誕生の秘密を見てみましょう。」","options":["とうとう","おそらく","まもなく","いったい"],"answer":4,"word_explain":"Phó từ「いったい」thường đi kèm với từ nghi vấn (như どうやって) để nhấn mạnh sự thắc mắc: \"rốt cuộc thì / thế nào mà...\".","translation_vi":"(Trong chương trình truyền hình) \"Trái đất nơi chúng ta đang sinh sống rốt cuộc đã được hình thành như thế nào nhỉ? Hãy cùng xem bí mật về sự ra đời của Trái đất.\""},{"mondai":7,"q":4,"prompt":"X社の調査によると、共働き夫婦における夫の家事負担の割合は、夫の年齢が(　　)にしたがって増加しているという。","options":["下がる","下がっている","下がった","下がっていた"],"answer":1,"word_explain":"Mẫu「Vる（thể từ điển）＋にしたがって」diễn tả sự biến đổi tỷ lệ thuận: \"càng ~ thì càng ~ / theo sự biến đổi của ~\".","translation_vi":"Theo khảo sát của công ty X, tỷ lệ gánh vác việc nhà của người chồng trong các cặp vợ chồng cùng đi làm đang tăng lên khi độ tuổi của người chồng giảm xuống (tức là chồng càng trẻ)."},{"mondai":7,"q":5,"prompt":"12月に入り、インフルエンザの患者数は増える(　　)。","options":["ほどだ","までだ","一方だ","次第だ"],"answer":3,"word_explain":"Mẫu「Vる + 一方だ」diễn tả một xu hướng thay đổi liên tục theo một chiều hướng (thường là tăng hoặc giảm không ngừng): \"ngày càng ~ / chỉ toàn ~\".","translation_vi":"Bước sang tháng 12, số lượng bệnh nhân mắc cúm chỉ có tăng chứ không giảm."},{"mondai":7,"q":6,"prompt":"わが国は、石油や石炭などのエネルギー資源がほとんどないため、多くを海外からの輸入に(　　)。","options":["頼らざるを得ない","頼るわけにはいかない","頼らないに違いない","頼ることにほかならない"],"answer":1,"word_explain":"Mẫu「Vない + ざるを得ない」mang nghĩa \"không còn cách nào khác ngoài việc phải ~ / đành phải ~\".「頼る」chia sang「頼らざるを得ない」.","translation_vi":"Vì nước ta hầu như không có tài nguyên năng lượng như dầu mỏ hay than đá, nên đành phải phụ thuộc phần lớn vào việc nhập khẩu từ nước ngoài."},{"mondai":7,"q":7,"prompt":"（会社で） 受付「A社の山下様が受付で(　　)。」 田中「あ、わかりました。すぐ行きます。」","options":["お待ちです","待っております","お待ちください","待っていただけますか"],"answer":1,"word_explain":"Cấu trúc tôn kính ngữ「お + Vます + です」dùng để nâng cao hành động của đối tác (ông Yamashita của công ty A đang đợi).「待っております」là khiêm nhường ngữ không phù hợp cho chủ thể là khách.","translation_vi":"(Ở công ty) Lễ tân: \"Ông Yamashita của công ty A đang đợi ở quầy lễ tân ạ.\" Tanaka: \"À, tôi hiểu rồi. Tôi ra ngay đây.\""},{"mondai":7,"q":8,"prompt":"レストランハヤマのランチは、AランチかBランチの2種類(　　)選べないが、安くてとてもおいしい。","options":["にしか","にだけ","からしか","からだけ"],"answer":3,"word_explain":"Động từ「選ぶ」(chọn) đi với trợ từ「から」(chọn từ trong các lựa chọn), kết hợp với「しか～ない」(chỉ) tạo thành「2種類からしか選べない」.","translation_vi":"Bữa trưa của nhà hàng Hayama chỉ có thể chọn từ 2 loại là suất A hoặc suất B, nhưng rẻ và rất ngon."},{"mondai":7,"q":9,"prompt":"昨日私が乗った飛行機は、今まで乗ったどの(　　)小さかった。","options":["飛行機のわりに","飛行機よりも","飛行機がいちばん","飛行機のほうが"],"answer":2,"word_explain":"Cấu trúc so sánh「どのNよりも～」(hơn bất kỳ N nào) dùng để diễn tả tính chất vượt trội nhất so với tất cả các đối tượng cùng loại.","translation_vi":"Chiếc máy bay tôi đi hôm qua nhỏ hơn bất kỳ chiếc máy bay nào tôi từng đi trước đây."},{"mondai":7,"q":10,"prompt":"髪が傷んでしまうので、髪を洗った後は、ぬれた(　　)、しっかり乾かしましょう。","options":["ままにせず","ようになっても","だけにすれば","ことにならなくて"],"answer":1,"word_explain":"Mẫu「Vた + ままにする」(để nguyên trạng thái đó), ở đây dùng dạng phủ định nối câu「ぬれたままにせず」nghĩa là \"không để nguyên tình trạng ướt mà...\".","translation_vi":"Vì tóc sẽ bị hư tổn nên sau khi gội đầu, đừng để nguyên trạng thái ướt mà hãy sấy khô thật kỹ nhé."},{"mondai":7,"q":11,"prompt":"A「最近元気ないみたいだけど、どうしたの？」 B「別れた彼のことがなかなか忘れられなくて……。」 A「忘れられないなら、そんなに無理に(　　)と思うよ。」","options":["忘れてしまいたくない","忘れようとしているんだ","忘れてしまうんだろう","忘れようとしなくてもいい"],"answer":4,"word_explain":"「Vようとする」(cố gắng làm gì) kết hợp với「なくてもいい」(không cần phải) thành「無理に忘れようとしなくてもいい」(không cần phải gượng ép cố quên).","translation_vi":"A: \"Gần đây trông cậu có vẻ không vui, có chuyện gì thế?\" B: \"Tớ mãi mà không thể quên được anh người yêu cũ...\" A: \"Nếu không quên được thì tớ nghĩ cậu không cần phải cố gắng ép mình quên đi như vậy đâu.\""},{"mondai":7,"q":12,"prompt":"私は両親に子供のころから自分がやりたいことを自由に(　　)。","options":["やらせてもらってくる","やらせてくれている","やらせてもらってきた","やらせてくれていた"],"answer":3,"word_explain":"Chủ ngữ là「私は」và đối tượng cho phép là「両親に」nên dùng thể sai khiến nhận ơn「Vさせてもらう」. Kết hợp với「子供のころから」và「てきた」diễn tả sự việc kéo dài từ quá khứ đến hiện tại.","translation_vi":"Từ hồi nhỏ tôi đã được bố mẹ cho phép tự do làm những điều mình muốn."},{"mondai":8,"q":13,"prompt":"山や植物の写真家　＿＿＿　＿＿＿　＿＿＿　★　写真展が15日からABCデパートで開催される。","options":["として","の","岩本まさき氏","有名な"],"answer":2,"word_explain":"Thứ tự đúng: 1 → 4 → 3 → ★2.「山や植物の写真家として有名な岩本まさき氏の写真展」:「として」(với tư cách là) bổ nghĩa cho「有名な」, rồi cụm định ngữ bổ nghĩa cho「岩本まさき氏」, cuối cùng nối với「写真展」bằng trợ từ「の」.","translation_vi":"Triển lãm ảnh của ông Masaki Iwamoto, người nổi tiếng với tư cách là nhiếp ảnh gia chụp núi và thực vật, sẽ được tổ chức tại trung tâm thương mại ABC từ ngày 15."},{"mondai":8,"q":14,"prompt":"子供のころは、1年が長く感じられたのに、年をとる　＿＿＿　＿＿＿　★　＿＿＿　だろうか。","options":["のは","につれて","なぜ","短く感じるようになる"],"answer":1,"word_explain":"Thứ tự đúng: 2 → 4 → ★1 → 3. Mẫu「Vる + につれて」(càng ~ thì càng ~), sau đó dùng cấu trúc nhấn mạnh câu hỏi「～のはなぜだろうか」(tại sao lại ~ nhỉ?).","translation_vi":"Hồi nhỏ một năm trôi qua thấy thật dài, vậy mà tại sao càng lớn tuổi người ta lại càng cảm thấy thời gian ngắn đi nhỉ?"},{"mondai":8,"q":15,"prompt":"情報をどのような　＿＿＿　＿＿＿　★　＿＿＿　が変わってくるので、順番を意識して話す必要がある。","options":["相手の受け止め方","提示するか","によって","順番で"],"answer":3,"word_explain":"Thứ tự đúng: 4 → 2 → ★3 → 1.「どのような順番で提示するか」(trình bày theo trình tự nào) +「によって」(tùy thuộc vào) +「相手の受け止め方が変わってくる」(cách tiếp nhận của đối phương sẽ thay đổi).","translation_vi":"Tùy thuộc vào việc trình bày thông tin theo trình tự như thế nào mà cách tiếp nhận của đối phương sẽ thay đổi, nên cần chú ý đến thứ tự khi nói."},{"mondai":8,"q":16,"prompt":"日本では、99歳のお祝いを「白寿」と言います。「百」の字から「一」をとる　＿＿＿　＿＿＿　★　＿＿＿　そう呼ばれています。","options":["と","字になる","ことから","「白」という"],"answer":2,"word_explain":"Thứ tự đúng: 1 → 4 → ★2 → 3.「～をとると」(nếu bỏ ~ thì) +「『白』という字になる」(sẽ thành chữ \"Bạch\") +「ことから」(từ lý do đó mà...).","translation_vi":"Ở Nhật Bản, lễ mừng thọ 99 tuổi được gọi là \"Hakuju\" (Bạch thọ). Từ việc bỏ nét \"Nhất\" (一) khỏi chữ \"Bách\" (百) thì sẽ thành chữ \"Bạch\" (白), nên người ta gọi như vậy."},{"mondai":8,"q":17,"prompt":"講師「最初は　＿＿＿　＿＿＿　★　＿＿＿　気になってくるということはありませんか。このような心理現象を『ザイオンス効果』と言います。」","options":["うちに","全く興味がなかった","商品なのに","CMなどで何度か見ている"],"answer":4,"word_explain":"Thứ tự đúng: 2 → 3 → ★4 → 1.「最初は全く興味がなかった商品なのに」(dù là sản phẩm ban đầu hoàn toàn không hứng thú nhưng) +「CMなどで何度か見ているうちに」(trong lúc xem vài lần qua quảng cáo thì...).","translation_vi":"Giảng viên: \"Chẳng phải đôi khi có trường hợp ban đầu vốn là một sản phẩm mình hoàn toàn không có hứng thú, nhưng trong lúc xem đi xem lại vài lần qua quảng cáo... thì lại đâm ra để ý tới nó hay sao? Hiện tượng tâm lý như thế này được gọi là 'Hiệu ứng Zajonc'.\""},{"mondai":9,"q":18,"prompt":"Chọn đáp án phù hợp cho chỗ trống [48] trong đoạn văn trên.","options":["挙げている","挙げようとする","挙げよう","挙げるだろう"],"answer":3,"word_explain":"Dạng ý hướng「挙げよう」(hãy cùng nêu ra / tôi xin nêu ra) thường được dùng trong văn viết học thuật, bài luận để dẫn dắt vào phần ví dụ cụ thể ở đoạn tiếp theo.","translation_vi":"Hãy cùng đưa ra một ví dụ."},{"mondai":9,"q":19,"prompt":"Chọn đáp án phù hợp cho chỗ trống [49] trong đoạn văn trên.","options":["ただし","しかも","そこで","かえって"],"answer":3,"word_explain":"「そこで」(do đó / vì vậy) dùng để nối giữa vấn đề vừa nêu ở câu trước (mở ra mất nhiều lần) với giải pháp/hành động được thực hiện ở câu sau (nghiên cứu cách gấp mở ra một lần).","translation_vi":"Do đó, người ta đã liên tục nghiên cứu để phát triển một cách gấp có thể đưa về kích thước ban đầu chỉ trong một lần."},{"mondai":9,"q":20,"prompt":"Chọn đáp án phù hợp cho chỗ trống [50] trong đoạn văn trên.","options":["活用して","活用するほかに","活用するまで","活用したにもかかわらず"],"answer":1,"word_explain":"「この折り方を活用して」(tận dụng cách gấp này để...) diễn đạt mục đích, phương thức thực hiện hành động ở vế sau một cách tự nhiên nhất.","translation_vi":"Tận dụng phương pháp gấp này, các thiết bị như \"tấm pin mặt trời\" dùng trên vệ tinh nhân tạo đang được chế tạo."},{"mondai":9,"q":21,"prompt":"Chọn đáp án phù hợp cho chỗ trống [51] trong đoạn văn trên.","options":["広げられるというのか","広げられるかのようだ","広げられるのだろうか","広げられるというわけだ"],"answer":4,"word_explain":"Mẫu「～というわけだ」(như vậy có nghĩa là / chính vì thế mà) dùng để tóm tắt, kết luận lại cơ chế hoặc ý nghĩa đã giải thích ở các câu trước.","translation_vi":"Nếu sử dụng cách gấp đã được phát triển, người ta có thể gấp nhỏ thiết bị lại, và khi ra ngoài không gian vũ trụ thì có thể mở rộng ra một cách dễ dàng — đó chính là nguyên lý/kết quả đạt được."},{"mondai":9,"q":22,"prompt":"Chọn đáp án phù hợp cho chỗ trống [52] trong đoạn văn trên.","options":["してみたがらない","してみるのも悪くない","してみそうない","してみても始まらない"],"answer":2,"word_explain":"「～てみるのも悪くない」(thử làm gì đó cũng không tệ / cũng đáng để thử) là cách đề xuất nhẹ nhàng ở cuối bài, phù hợp với câu tiếp theo nói về việc trẻ em có thể nảy sinh hứng thú với kỹ thuật vũ trụ.","translation_vi":"Vừa chơi gấp giấy origami cùng trẻ em vừa thử kể những câu chuyện khoa học như thế này cũng không tệ chút nào."}]},{"id":"g_2018_07","displayName":"07/2018","subtitle":"17 câu • Mondai 7–9 (Ngữ pháp)","m9_passage":"道路のひみつ\n\n仕事、買い物、遊びに行くとき、誰でも必ずお世話になるものがある。[50]だ。当たり前のように存在し、多くの人に利用されているが、様々な工夫がされていることはあまり知られていない。\n\n例えば、高速道路や大きな道路の多くで雨水が道路上にたまりにくい設計になっていることは[51]。道路表面に小さな無数の穴があり、水が舗装の下に抜けるという仕組みだ。高速道路で雨の日に事故が多かった地点も、この舗装にした後、雨の日の事故が約80%減少したという。\n\n[52]、寒い地域では雪や氷が原因でスリップ事故が多発する。そのため、雪や氷を砕く機能をもった道路が開発されている。粒状のゴムなど、柔軟性のある小さな素材を道路に埋め込み、車の重みで道路をわずかに変形させて雪や氷を砕く。カーブや坂道などをそういう舗装にすれば、道路に雪や氷が密着するのを防ぐことができ、スリップの危険性が減る。\n\n道路表面の温度を下げる[53]。道路は太陽に熱せられ、夏は特に熱くなりやすい。そこで、太陽光線の吸収を防ぐ物質を表面に塗ることで温度上昇を抑えている。この舗装により、道路の温度は最大10度以上も下がる。人やペットが歩く公園や歩道にぴったりだ。\n\nこれら以外にも、様々な機能の道路が日々開発され、利用されている。道路の違いは見た目にはよくわからないかもしれない。しかし、人々がより安全で快適に暮らせるよう、足元で[54]。","questions":[{"mondai":7,"q":1,"prompt":"昨日泊まったホテルの部屋は、シングルルーム(　　)広かった。","options":["ばかりか","をとわず","にしては","かというと"],"answer":3,"word_explain":"N + にしては: so với tiêu chuẩn/mức thông thường của N thì (khá bất ngờ, trái với suy nghĩ thông thường).","translation_vi":"Phòng khách sạn tôi ở hôm qua, so với phòng đơn thì rộng hơn hẳn."},{"mondai":7,"q":2,"prompt":"（店の前で） 客「すみません、開店はまだですか。」 店員「(　　)開店いたしますので、もう少々お待ちください。」","options":["いまにも","まもなく","ほとんど","いつのまに"],"answer":2,"word_explain":"まもなく: sắp sửa, chẳng mấy chốc nữa (dùng cho sự việc sắp diễn ra trong tương lai gần, văn phong lịch sự). いまにも thường đi với ～そうだ để tả trạng thái sắp xảy ra ngay trước mắt.","translation_vi":"(Trước cửa hàng) Khách: \"Xin lỗi, cửa hàng vẫn chưa mở cửa ạ?\" Nhân viên: \"Chẳng mấy chốc nữa sẽ mở cửa ạ, xin quý khách vui lòng đợi thêm một chút nữa.\""},{"mondai":7,"q":3,"prompt":"北山には、初心者でも楽しめるハイキングコースや上級者(　　)コースなど、いくつかの登山コースがあります。","options":["ほどの","向けの","きりの","どおりの"],"answer":2,"word_explain":"N + 向けの + N: dành cho đối tượng N (上級者向けのコース: lộ trình dành cho người trình độ cao).","translation_vi":"Ở núi Kitayama có một số lộ trình leo núi, như lộ trình đi bộ đường dài mà ngay cả người mới cũng có thể tận hưởng hay lộ trình dành cho người có trình độ cao."},{"mondai":7,"q":4,"prompt":"昨日、高熱が出たので病院に行った(　　)、インフルエンザと診断された。","options":["場合","以上","ことに","ところ"],"answer":4,"word_explain":"Vた + ところ: sau khi làm V thì (nhận được kết quả/phát hiện ra sự việc gì đó).","translation_vi":"Hôm qua vì bị sốt cao nên khi tôi đi bệnh viện khám thì được chẩn đoán là bị cúm."},{"mondai":7,"q":5,"prompt":"散歩が大好きなうちの犬が、今日は散歩に(　　)。具合でも悪いのだろうか。","options":["行きたがらなかった","行かなければよかった","行ってほしくなかった","行きたくなかった"],"answer":1,"word_explain":"Vて-stem + たがる: diễn tả mong muốn của ngôi thứ 3 (ở đây là chú chó うちの犬). Phủ định quá khứ là 行きたがらなかった (tỏ ra không muốn đi).","translation_vi":"Chú chó nhà tôi vốn rất thích đi dạo mà hôm nay lại chẳng muốn đi dạo. Không biết có phải nó bị ốm ở đâu không nữa."},{"mondai":7,"q":6,"prompt":"市長は、記者会見で「高速道路建設に反対している市民も少なくないのだから、市長として、そのことを無視して建設計画を(　　)。」と述べた。","options":["進めそうにない","進めてもかまわない","進めずにはいられない","進めるわけにはいかない"],"answer":4,"word_explain":"Vる + わけにはいかない: không thể làm V được (vì lý do đạo đức, trách nhiệm, hoàn cảnh xã hội không cho phép).","translation_vi":"Tại buổi họp báo, thị trưởng đã phát biểu: \"Vì số người dân phản đối việc xây dựng đường cao tốc không hề ít, nên với tư cách là thị trưởng, tôi không thể phớt lờ điều đó mà cứ tiến hành kế hoạch xây dựng được.\""},{"mondai":7,"q":7,"prompt":"（スピーチで） 「本日は弊社創立50周年記念パーティーにお越しくださりありがとうございます。社長の小林でございます。社を代表して、私から一言ごあいさつ(　　)。」","options":["されます","うかがいます","申し上げます","おっしゃいます"],"answer":3,"word_explain":"ごあいさつ申し上げます: khiêm nhường ngữ của ごあいさつします / 言います (\"tôi xin phép gửi lời chào\"), dùng cho hành động của người nói hướng tới người nghe/khách mời.","translation_vi":"(Trong bài phát biểu) \"Xin chân thành cảm ơn quý vị đã đến tham dự buổi tiệc kỷ niệm 50 năm thành lập công ty chúng tôi ngày hôm nay. Tôi là Kobayashi, giám đốc công ty. Đại diện cho công ty, tôi xin phép được gửi đôi lời chào tới quý vị.\""},{"mondai":7,"q":8,"prompt":"そのバッグは、どこにでもあるような物なのに、人気歌手が愛用している(　　)、1万個も売れたそうだ。","options":["とすること","というだけ","とすることを","というだけで"],"answer":4,"word_explain":"～というだけで: chỉ với lý do là / chỉ vì..., nhấn mạnh một nguyên nhân tưởng nhỏ nhưng lại dẫn đến kết quả lớn/bất ngờ.","translation_vi":"Chiếc túi đó dù chỉ là món đồ bình thường ở đâu cũng có, nhưng nghe nói chỉ vì được một ca sĩ nổi tiếng tin dùng mà đã bán được tới 10 nghìn chiếc."},{"mondai":7,"q":9,"prompt":"ホテルのフロント係として働き始めたころは、「どんなに忙しくてもお客様には疲れた顔を(　　)。」と先輩によく注意された。","options":["見せないために","見えないこと","見せないように","見えないもの"],"answer":3,"word_explain":"Vないように（しなさい／気をつけなさい）: hãy chú ý để đừng làm V (lời khuyên/nhắc nhở lược bỏ vế sau). Dùng tha động từ 見せる (để lộ/cho xem khuôn mặt).","translation_vi":"Hồi mới bắt đầu làm nhân viên lễ tân khách sạn, tôi thường bị tiền bối nhắc nhở rằng: \"Dù bận rộn đến đâu cũng đừng để khách hàng thấy vẻ mặt mệt mỏi.\""},{"mondai":7,"q":10,"prompt":"母「たかし、寝る前に必ず明日の準備を(　　)。朝、慌てて準備すると絶対忘れ物するから。」 たかし「大丈夫、もう終わってるよ。」","options":["してあるんだよ","しておきなさいよ","してあるんじゃないの","しておいたの"],"answer":2,"word_explain":"Vておきなさいよ: sự kết hợp giữa Vておく (chuẩn bị sẵn trước) + ～なさい (mệnh lệnh nhẹ nhàng của cha mẹ với con cái) + よ.","translation_vi":"Mẹ: \"Takashi, trước khi đi ngủ nhớ chuẩn bị sẵn đồ cho ngày mai đấy nhé. Sáng ra cuống quýt chuẩn bị thì thế nào cũng để quên đồ đấy.\" Takashi: \"Không sao đâu mẹ, con làm xong hết rồi.\""},{"mondai":7,"q":11,"prompt":"X社に入社すると、新入社員は、まず電話の応対の練習を2週間(　　)。","options":["させられるそうだ","させるつもりだ","させられたままだ","させているところだ"],"answer":1,"word_explain":"Vさせられる (sai khiến bị động: bị bắt/phải làm) + ～そうだ (nghe nói). Chủ ngữ là 新入社員は nên phải dùng thể sai khiến bị động.","translation_vi":"Nghe nói khi vào làm tại công ty X, nhân viên mới trước tiên sẽ phải luyện tập cách trả lời điện thoại trong 2 tuần."},{"mondai":7,"q":12,"prompt":"田中「次回の勉強会のテーマは何にしましょうか。」 山下「私は消費者心理に興味があります。」 石川「それも面白そうですが、私はアンケートの分析方法を(　　)。」","options":["取り上げようとするでしょうか","取り上げるようになるでしょうか","取り上げたいのだろうと思います","取り上げてみてはどうかと思います"],"answer":4,"word_explain":"Vてみてはどうかと思います: tôi nghĩ hay là thử làm V xem sao (cách đưa ra đề xuất lịch sự, nhẹ nhàng trong thảo luận).","translation_vi":"Tanaka: \"Chủ đề cho buổi học nhóm lần tới chúng ta nên chọn gì nhỉ?\" Yamashita: \"Tôi có hứng thú với tâm lý người tiêu dùng.\" Ishikawa: \"Chủ đề đó cũng có vẻ thú vị đấy, nhưng tôi nghĩ hay là thử chọn phương pháp phân tích bảng khảo sát xem sao.\""},{"mondai":9,"q":13,"prompt":"Chỗ trống [50] trong đoạn văn trên","options":["道路","ある道路","その道路","こんな道路"],"answer":1,"word_explain":"Câu mở đầu giới thiệu đối tượng chung khớp với tiêu đề 「道路のひみつ」 (\"Bí mật của đường sá\"), không dùng các từ chỉ định その・こんな・ある khi nhắc đến khái niệm chung lần đầu.","translation_vi":"Đó chính là đường sá."},{"mondai":9,"q":14,"prompt":"Chỗ trống [51] trong đoạn văn trên","options":["ご存じだ","ご存じのようだ","ご存じだろうか","ご存じなのだろう"],"answer":3,"word_explain":"Sau khi nói rằng ít người biết về các cải tiến trên đường, tác giả dùng 「～ことはご存じだろうか」 (\"Quý vị/bạn có biết rằng ... không?\") để đặt câu hỏi dẫn dắt người đọc vào ví dụ đầu tiên.","translation_vi":"Ví dụ, bạn có biết rằng ở phần lớn các tuyến đường cao tốc và đường lớn, chúng đều được thiết kế để nước mưa khó đọng lại trên mặt đường không?"},{"mondai":9,"q":15,"prompt":"Chỗ trống [52] trong đoạn văn trên","options":["また","すると","こうして","したがって"],"answer":1,"word_explain":"また (ngoài ra, thêm vào đó): dùng để bổ sung thêm một ví dụ mới về cải tiến đường sá (sau ví dụ thoát nước mưa ở đoạn trước, chuyển sang ví dụ chống trượt tuyết băng).","translation_vi":"Ngoài ra, ở những vùng lạnh giá, tai nạn trơn trượt do tuyết và băng xảy ra rất nhiều."},{"mondai":9,"q":16,"prompt":"Chỗ trống [53] trong đoạn văn trên","options":["工夫だと言える","工夫も考えられる","工夫だと思われる","工夫も見られる"],"answer":4,"word_explain":"「工夫も見られる」 (cũng có thể thấy những cải tiến...): giới thiệu thêm một cải tiến khác đang được áp dụng trong thực tế (câu sau mô tả chất liệu đang được sơn lên bề mặt đường để giảm nhiệt).","translation_vi":"Người ta cũng thấy có cả những cải tiến nhằm hạ nhiệt độ bề mặt đường."},{"mondai":9,"q":17,"prompt":"Chỗ trống [54] trong đoạn văn trên","options":["支えてくれているはずだった","支えてくれているわけだ","支えてくれているからだった","支えてくれているおかげだ"],"answer":2,"word_explain":"「～ているわけだ」 diễn tả kết luận tự nhiên rút ra từ những dẫn chứng ở các đoạn trên (\"hóa ra là / như vậy tức là chúng đang nâng đỡ...\"). Các mẫu はずだった, からだった, おかげだ không phù hợp với cấu trúc câu kết luận này.","translation_vi":"Thế nhưng, có thể thấy chúng đang âm thầm nâng đỡ ngay dưới chân để mọi người có thể sinh sống an toàn và thoải mái hơn."}]},{"id":"g_2017_12","displayName":"12/2017","subtitle":"22 câu • Mondai 7–9 (Ngữ pháp)","m9_passage":"以下は、ある子供雑誌に寄せられた質問と、質問に対する回答である\n\n◇質問◇\n鳥はなぜ飛べるのですか。人間も翼つばさをつけたら、飛べますか。（草太（そうた）小3）\n\n◇回答◇\n空を飛ぶためには体が軽いことが大切です。[50]、空を飛ぶ鳥は、体や翼（つばさ）の大きさのわりには、体がとても軽くできているのです。例えば、コンドルという鳥は、翼（つばさ）の長さ（左右の翼（つばさ）を広げたときの翼（つばさ）の先から先までの長さ）が3mほどもありますが、体重は10〜15kgしかありません。鳥が重そうに見えるのは、羽が膨（ふく）らんでいるからで、本当はとても細い体をしています。そして、鳥の骨は細く、骨の中はトンネルのような空洞（くうどう）の状態になっているため、軽いのです。\n\nでも草太（そうた）君は、もしかしたら「それなら人間は、体重に合わせて大きい翼（つばさ）をつければいい。」と思うかもしれませんね。では、翼（つばさ）はどのくらいの[51]。ある説によると、体重60kgの人間が飛ぶのに必要な翼（つばさ）の長さは、約34mだそうです。長さ10mの大型バスを3台並べたときの長さよりも長いわけです。[52]は人間にはとても動かせませんよね。鳥が体のわりに大きな翼（つばさ）を動かせるのは、胸（むね）の筋肉（きんにく）が大変発達しているからです。鳥の胸（むね）の筋肉（きんにく）は、体重の約35％を占めると言われています。そのため、鳥は翼（つばさ）を強く動かすことができるのです。そのほかにも、鳥の体は表面の羽がなめらかで、空気の抵抗を受けにくい形になっています。\n\n[53]、鳥は、単に翼（つばさ）があるから飛べるのではなく、いろいろな点で体全体が飛ぶのに最適な構造になっていることがわかりますね。鳥は飛ぶために進化してきたのです。残念ながら、人間は、翼（つばさ）をつけただけでは飛ぶのは[54]。","questions":[{"mondai":7,"q":1,"prompt":"（大学のホームページで） ABC大学の法学部には、六つのゼミがあります。ゼミでの活動（　　）、物事を論理的に考える力を身につけることができます。","options":["とは","にも","にとって","を通して"],"answer":4,"word_explain":"「Nを通して」: thông qua N (làm phương tiện, môi trường để đạt được kết quả gì đó). 「とは」 dùng để định nghĩa, 「にも」 là cũng/ngay cả, 「にとって」 là đối với (lập trường).","translation_vi":"(Trên trang web của trường đại học) Khoa Luật của Đại học ABC có 6 nhóm seminar. Thông qua hoạt động tại seminar, bạn có thể rèn luyện khả năng tư duy sự việc một cách logic."},{"mondai":7,"q":2,"prompt":"（会社で） A「ねえ、昨日できたパンフレットってどこにある？」 B「えっと、どこだろう。」 C「ああ、（　　）、あの棚の中にあるよ。」","options":["パンフレットなら","パンフレットでも","パンフレットについて","パンフレットのことで"],"answer":1,"word_explain":"「Nなら」: nếu nói về N thì... (dùng để tiếp nối chủ đề mà người đối diện vừa nhắc tới và đưa ra thông tin liên quan).","translation_vi":"(Ở công ty) A: \"Này, cuốn tờ rơi làm xong hôm qua để ở đâu thế?\" B: \"Ừm, ở đâu nhỉ.\" C: \"À, nếu là cuốn tờ rơi thì ở trong cái kệ kia kìa.\""},{"mondai":7,"q":3,"prompt":"（テレビ番組で） 司会「森もりさん、第五回X文学賞受賞おめでとうございます。今のお気持ちはいかがですか。」 森もり「ありがとうございます。（　　）受賞できるとは思わなかったので、すごくうれしいです。」","options":["たとえ","まさか","せめて","かりに"],"answer":2,"word_explain":"「まさか〜とは思わなかった」: không ngờ lại..., không thể tin nổi là... (diễn tả sự ngạc nhiên lớn ngoài sức tưởng tượng).","translation_vi":"(Trong chương trình truyền hình) MC: \"Chúc mừng Morimori đã đoạt giải Văn học X lần thứ 5. Cảm xúc của bạn lúc này thế nào ạ?\" Morimori: \"Xin cảm ơn. Tôi không ngờ mình lại có thể đoạt giải, nên tôi vô cùng vui sướng.\""},{"mondai":7,"q":4,"prompt":"毎朝体操を（　　）、硬かった体が柔らかくなった。","options":["続けるうちに","続けるからには","続けるとすると","続けるかというと"],"answer":1,"word_explain":"「Vるうちに」: trong lúc/trong quá trình làm V thì tự nhiên dẫn đến một sự biến đổi ở vế sau. 「からには」 là một khi đã, 「とすると」 là giả sử nếu, 「かというと」 là nếu hỏi có phải... hay không.","translation_vi":"Trong quá trình kiên trì tập thể dục mỗi sáng, cơ thể vốn cứng của tôi đã trở nên dẻo dai hơn."},{"mondai":7,"q":5,"prompt":"囲碁（いご）・将棋（しょうぎ）クラブに入って半年。初めは（　　）が、最近少しずつ勝てるようになってきた。","options":["負けてばかりだった","負けたばかりだった","負けるところだった","負けているところだった"],"answer":1,"word_explain":"「Vてばかりだ」: toàn là làm V, lặp đi lặp lại mỗi việc V (toàn thua). 「Vたばかり」 là vừa mới, 「Vるところだった」 là suýt nữa thì.","translation_vi":"Đã nửa năm kể từ khi tôi gia nhập câu lạc bộ cờ vây và shogi. Lúc đầu tôi toàn thua, nhưng gần đây đã dần dần thắng được rồi."},{"mondai":7,"q":6,"prompt":"政府の発表によると、景気は回復しつつある（　　）が、そうした実感はない。","options":["つもりだ","おかげだ","ということだ","というものだ"],"answer":3,"word_explain":"「〜によると、〜ということだ」: theo nguồn tin nào đó thì nghe nói là / được biết là (truyền đạt lại thông tin).","translation_vi":"Theo thông báo của chính phủ thì tình hình kinh tế đang dần hồi phục, nhưng tôi chẳng có cảm nhận thực tế như vậy."},{"mondai":7,"q":7,"prompt":"客「すみません、『山の中で』っていう本を探しているんですけど。」 店員「はい、新刊コーナーに（　　）。ご案内します。」","options":["いたします","おります","ございます","なさいます"],"answer":3,"word_explain":"「ございます」 là dạng lịch sự (丁寧語) của 「あります」 (dùng cho đồ vật: cuốn sách). 「おります」 là khiêm nhường ngữ của 「います」, 「いたします」 là khiêm nhường của 「します」, 「なさいます」 là tôn kính của 「します」.","translation_vi":"Khách: \"Xin lỗi, tôi đang tìm cuốn sách tên là 'Trong núi'.\" Nhân viên: \"Vâng, sách có ở quầy sách mới phát hành ạ. Để tôi dẫn quý khách ra đó.\""},{"mondai":7,"q":8,"prompt":"先生「田中（たなか）さん、この問題をどうやって（　　）、みんなの前で説明してください。」 田中（たなか）「はい、わかりました。」","options":["解いたか","解いたのを","解いたとは","解いたことも"],"answer":1,"word_explain":"Cấu trúc câu nghi vấn gián tiếp 「どうやって〜Vたか」 (đã làm bằng cách nào) làm mệnh đề bổ ngữ cho 「説明してください」.","translation_vi":"Giáo viên: \"Em Tanaka, hãy giải thích trước mọi người xem em đã giải bài toán này bằng cách nào.\" Tanaka: \"Vâng, em hiểu rồi ạ.\""},{"mondai":7,"q":9,"prompt":"先生「皆さん、海や川に落ちてしまったときは、無理に（　　）、仰向（あおむけ）になって、浮かんで助けを待つことが大切です。」","options":["泳げなくなると","泳ごうとしないので","泳げなくなって","泳ごうとしないで"],"answer":4,"word_explain":"「Vようとしないで」: đừng cố làm V mà hãy... (khuyên ngăn không cố thực hiện hành động V). 「〜ないので」 diễn tả nguyên nhân (không hợp nghĩa).","translation_vi":"Giáo viên: \"Các em ạ, khi chẳng may bị rơi xuống biển hay sông, điều quan trọng là đừng cố gắng bơi một cách quá sức, mà hãy nằm ngửa người ra, nổi trên mặt nước và chờ người đến cứu.\""},{"mondai":7,"q":10,"prompt":"春子（はるこ）「えりちゃん、みかん、好き？」 えり「うん、好きだけど。なんで？」 春子（はるこ）「親しんせきがたくさん送ってきてくれたんだけど、一人じゃ食べ切れなくて。よかったら、少し（　　）？」 えり「いいの？ありがとう。」","options":["あげない","くれない","もらってくれない","もらってもらわない"],"answer":3,"word_explain":"「もらってくれない？」: cậu nhận giúp mình được không? Người nói dùng 「もらう」 (người nghe nhận) + 「〜てくれない」 (nhờ vả thân mật mang ơn người nghe nhận giùm).","translation_vi":"Haruko: \"Eri ơi, cậu có thích quýt không?\" Eri: \"Ừ, thích chứ. Sao thế?\" Haruko: \"Họ hàng gửi cho tớ nhiều lắm, một mình ăn không hết. Nếu được thì cậu nhận giúp tớ một ít nhé?\" Eri: \"Thật không? Cảm ơn cậu.\""},{"mondai":7,"q":11,"prompt":"（夕食時に） 妻「ねえ、このスープ、レシピ通りに作ったんだけど、どう？味、薄くない？もう少し塩を（　　）。」 夫「ううん、ちょうどいいよ。」","options":["入れたことはよかったね","入れたからよかったなあ","入れたほうがよかったかな","入れたところがよかったよね"],"answer":3,"word_explain":"「Vたほうがよかったかな」: tự hỏi/băn khoăn không biết lúc nãy có nên làm V thì tốt hơn không. Phù hợp với ngữ cảnh người vợ lo món súp bị nhạt.","translation_vi":"(Vào bữa tối) Vợ: \"Này anh, món súp này em nấu đúng theo công thức đấy, sao hả anh? Vị có nhạt không? Hay là lúc nãy em nên cho thêm chút muối thì hơn nhỉ.\" Chồng: \"Không đâu, vừa vặn lắm rồi.\""},{"mondai":7,"q":12,"prompt":"高校野球全国大会を前に、X高校野球部の南（みなみ）豊（ゆたか）選手は「監督（かんとく）やコーチが私たち一人一人に毎日熱心に指導を（　　）。監督（かんとく）やコーチのためにも、優勝したいです。」と決意を述べた。","options":["いらっしゃいました","してくださいました","まいりました","していただきました"],"answer":2,"word_explain":"Chủ ngữ là 「監督やコーチが」 (người bề trên thực hiện hành động cho phía mình), nên dùng tôn kính ngữ 「〜てくださいました」: 「指導をしてくださいました」. Nếu dùng 「していただきました」 thì chủ ngữ phải là phía người nói (chúng tôi) và người dạy đi với 「に」.","translation_vi":"Trước thềm giải bóng chày trung học toàn quốc, tuyển thủ Minami Yutaka của đội bóng chày trường trung học X đã bày tỏ quyết tâm: \"Huấn luyện viên và các thầy phụ trách đã nhiệt tình chỉ bảo cho từng người chúng tôi mỗi ngày. Vì huấn luyện viên và các thầy, chúng tôi muốn giành chức vô địch.\""},{"mondai":8,"q":13,"prompt":"（教室で） 生徒「これからご紹介するのは、私が新しい単語を覚える＿＿＿　★　＿＿＿　＿＿＿思いついた方法です。皆さんも、ぜひ試してみてください。」","options":["のに","とあれこれ考えた","末に","いい方法はないか"],"answer":4,"word_explain":"Thứ tự đúng: 1 → ★4 → 2 → 3. 「覚えるのに」 (để nhớ) + 「いい方法はないか」 (liệu có cách nào hay không) + 「とあれこれ考えた」 (đã suy nghĩ đủ điều rằng...) + 「末に」 (cuối cùng sau một quá trình dài suy nghĩ) + 「思いついた方法です」.","translation_vi":"(Trong lớp học) Học sinh: \"Điều mà em sắp giới thiệu sau đây là phương pháp mà em đã nghĩ ra sau khi suy nghĩ đủ cách xem liệu có cách nào hay để nhớ từ vựng mới hay không. Mọi người cũng hãy thử xem nhé.\""},{"mondai":8,"q":14,"prompt":"講師「片付けが苦手という話をよく聞きますが、それは＿＿＿　★　＿＿＿　＿＿＿だけなので、やり方を身につければ必ず片付けられるようになります。」","options":["決して","やり方を知らない","ではなく","性格や能力の問題"],"answer":4,"word_explain":"Thứ tự đúng: 1 → ★4 → 3 → 2. Cấu trúc 「決して〜ではなく〜だけだ」 (hoàn toàn không phải là A mà chỉ là B thôi). 「決して」 đi cùng dạng phủ định 「ではなく」.","translation_vi":"Giảng viên: \"Tôi thường nghe mọi người nói mình kém việc dọn dẹp, nhưng đó hoàn toàn không phải là vấn đề tính cách hay năng lực mà chỉ là do chưa biết cách làm thôi, nên nếu nắm được phương pháp thì nhất định sẽ dọn dẹp được.\""},{"mondai":8,"q":15,"prompt":"X市には、市民のための文化施設が＿＿＿　★　＿＿＿　＿＿＿行っている。","options":["はじめとした","二つあり","さまざまな催しを","音楽コンサートを"],"answer":4,"word_explain":"Thứ tự đúng: 2 → ★4 → 1 → 3. 「文化施設が二つあり」 (có hai cơ sở văn hóa, và...) + 「音楽コンサートをはじめとしたさまざまな催しを行っている」 (tổ chức nhiều sự kiện đa dạng tiêu biểu như hòa nhạc; mẫu 「NをはじめとしたN2」).","translation_vi":"Ở thành phố X có hai cơ sở văn hóa dành cho người dân, và nơi đây đang tổ chức nhiều sự kiện đa dạng mà tiêu biểu là các buổi hòa nhạc."},{"mondai":8,"q":16,"prompt":"おなかがすいている＿＿＿　＿＿＿　★　＿＿＿だろう。","options":["どうして","おなかが鳴るのは","でもないのに","わけ"],"answer":2,"word_explain":"Thứ tự đúng: 4 → 3 → ★2 → 1. 「おなかがすいているわけでもないのに」 (mặc dù không phải là đang đói) + 「おなかが鳴るのはどうしてだろう」 (tại sao bụng lại kêu nhỉ).","translation_vi":"Dù không phải là đang đói bụng, vậy mà tại sao bụng vẫn kêu nhỉ?"},{"mondai":8,"q":17,"prompt":"＿＿＿　＿＿＿　★　＿＿＿先週から工事で休業中なので、今回は別のホテルに泊まることにした。","options":["泊まっている","たびに","Yホテルが","出張に行く"],"answer":1,"word_explain":"Thứ tự đúng: 4 → 2 → ★1 → 3. Cụm danh từ 「出張に行くたびに泊まっているYホテルが」 (khách sạn Y mà mỗi lần đi công tác tôi đều ở) làm chủ ngữ cho vế 「先週から工事で休業中なので」.","translation_vi":"Vì khách sạn Y mà tôi vẫn thường ở mỗi lần đi công tác đang tạm nghỉ để sửa chữa từ tuần trước, nên lần này tôi quyết định ở một khách sạn khác."},{"mondai":9,"q":18,"prompt":"Chỗ trống [50] trong đoạn văn trên","options":["一方","実は","ところが","なぜなら"],"answer":2,"word_explain":"「実は」 (thực ra là / trên thực tế) dùng để tiếp nối câu trước (\"Để bay được thì cơ thể nhẹ là điều quan trọng\") nhằm đưa ra sự thật cụ thể giải thích về cấu tạo nhẹ của loài chim. 「なぜなら」 không hợp vì câu sau không giải thích lý do tại sao nhẹ lại quan trọng.","translation_vi":"Thực ra là, những loài chim bay trên trời có cấu tạo cơ thể rất nhẹ so với kích thước cơ thể và đôi cánh của chúng."},{"mondai":9,"q":19,"prompt":"Chỗ trống [51] trong đoạn văn trên","options":["長さがあるのでしょう","長さになりましたか","長さだと言いましたか","長さが要るのでしょう"],"answer":4,"word_explain":"「長さが要る（いる）のでしょう」 (cần độ dài bao nhiêu nhỉ). Câu ngay sau đó viết 「必要な翼の長さは約34mだそうです」 (độ dài cánh cần thiết là khoảng 34m), khớp hoàn toàn về nghĩa với 「要る」 (cần).","translation_vi":"Vậy thì, sẽ cần đôi cánh có độ dài khoảng bao nhiêu nhỉ?"},{"mondai":9,"q":20,"prompt":"Chỗ trống [52] trong đoạn văn trên","options":["翼（つばさ）","そんなに大きな翼（つばさ）","こっちの翼（つばさ）","あのような大きな翼（つばさ）"],"answer":2,"word_explain":"Dùng chỉ thị từ hệ 「そ」 (「そんなに大きな翼」 = đôi cánh lớn đến như vậy) để quy chiếu lại kích thước cánh dài tận 34m (hơn cả 3 chiếc xe buýt lớn nối đuôi nhau) vừa được nhắc tới ở câu ngay trước đó.","translation_vi":"Đôi cánh lớn đến như vậy thì con người hoàn toàn không thể cử động nổi đâu nhỉ."},{"mondai":9,"q":21,"prompt":"Chỗ trống [53] trong đoạn văn trên","options":["これに対して","最初に述べたように","こうして見てみると","最後の結論から"],"answer":3,"word_explain":"「こうして見てみると」 (nhìn nhận/xem xét tổng hợp lại như thế này thì thấy...) dùng để tóm tắt, rút ra kết luận từ toàn bộ các đặc điểm đã phân tích ở đoạn trên (xương rỗng nhẹ, cơ ngực phát triển, lông mượt giảm sức cản không khí).","translation_vi":"Xem xét như vậy thì ta có thể thấy rằng loài chim bay được không chỉ đơn thuần vì có cánh, mà toàn bộ cơ thể ở nhiều khía cạnh đều có cấu trúc tối ưu để bay."},{"mondai":9,"q":22,"prompt":"Chỗ trống [54] trong đoạn văn trên","options":["難しそうです","難しいからです","難しくなってきたらしいです","難しくなってしまうためです"],"answer":1,"word_explain":"「難しそうです」 (xem ra khó / có vẻ khó) phù hợp để kết thúc câu trả lời lịch sự cho câu hỏi \"Con người gắn cánh vào có bay được không?\". Các phương án 「〜からです」「〜ためです」 nêu lý do nên không hợp với cấu trúc câu kết luận này.","translation_vi":"Đáng tiếc là, con người nếu chỉ gắn thêm cánh thôi thì xem ra rất khó mà bay được."}]},{"id":"g_2017_07","displayName":"07/2017","subtitle":"22 câu • Mondai 7–9 (Ngữ pháp)","m9_passage":"高齢化社会におけるスポーツ\n\n105歳の日本人男性が、陸上競技の100メートルで世界記録を出した。2015年に行われたある陸上の世界大会でのことだ。\n\n「マスターズ」と呼ばれる[50]。日本ではまだあまり知られていないが、スポーツをいくつになっても楽しむことを目的とした大会で、陸上、水泳、テニスなど様々な競技の大会が世界中で開催されている。陸上の大会では通常5歳ごとに分けられたクラスで同年代と競う。そのため、体力が落ちて若いころのように走れなくても対等に競うことができる。つまり、105歳の男性が出した世界記録は、彼が参加したクラスにおける世界記録[51]。\n\nある調査によると、マスターズに参加している高齢者は心と体の健康を維持しているという。運動は心に活気を生み、記録という目標は生活の中で感じる不安やストレスを少なくするそうだ。\n\n心も体も元気な高齢者の多い社会は、高齢化社会の一つの理想である。マスターズに参加する高齢者が増えれば、この理想に近づくことができる。[52]、マスターズの存在が影響を与えるのは、参加者にとどまらない。参加者以外の高齢者も、同年代が記録を目指す姿を目にすることで、体を動かすきっかけや心の活力が得られるに違いない。[53]、マスターズが広く知られる必要がある。テレビなどで目にする機会が増えるといい。\n\nいつまでも心身ともに元気でいられる[54]。その社会の実現に向けて、マスターズの今後の発展が期待される。","questions":[{"mondai":7,"q":1,"prompt":"私の職場では、節電のため、廊下の蛍光灯を一つ（　　）外している。","options":["に対し","ぶりに","につき","おきに"],"answer":4,"word_explain":"「数詞 + おきに」diễn tả khoảng cách đều đặn: cứ cách một đơn vị lại có một lần (cứ cách một bóng đèn lại tháo một bóng). 「に対し」(đối với), 「ぶりに」(sau một khoảng thời gian), 「につき」(mỗi/vì) không phù hợp.","translation_vi":"Ở nơi làm việc của tôi, để tiết kiệm điện, người ta tháo cách một bóng đèn huỳnh quang ở hành lang."},{"mondai":7,"q":2,"prompt":"時間のある学生時代に、もっと本を読んだり、海外旅行に行ったりしておけばよかった。あのころに戻れる（　　）戻りたい。","options":["かわりに","とすると","ものなら","にしたって"],"answer":3,"word_explain":"「V(thể khả năng) + ものなら + V(nguyện vọng)」diễn tả ước muốn mãnh liệt về một điều khó có thể thực hiện: \"Nếu mà có thể... thì tôi rất muốn...\".","translation_vi":"Giá mà hồi còn là sinh viên có thời gian tôi đọc nhiều sách hơn và đi du lịch nước ngoài nhiều hơn thì tốt biết mấy. Nếu có thể quay lại thời đó, tôi rất muốn quay lại."},{"mondai":7,"q":3,"prompt":"転校する友人からの手紙に、「たとえ遠く（　　）、私たちの友情は変わらない」と書いてあった。","options":["離れても","離れなくて","離れるけれど","離れなければ"],"answer":1,"word_explain":"Cấu trúc tương ứng cố định 「たとえ ～ ても／でも」mang nghĩa \"dù cho... đi nữa thì vẫn...\". 「離れても」là dạng Vて+も phù hợp.","translation_vi":"Trong bức thư từ người bạn sắp chuyển trường có viết: \"Dù cho có cách xa nhau đi chăng nữa, tình bạn của chúng ta cũng sẽ không thay đổi.\""},{"mondai":7,"q":4,"prompt":"祖母は、留学中の私のことが（　　）らしい。","options":["心配どおり","心配でならない","心配すべき","心配してもしかたない"],"answer":2,"word_explain":"「A(tính từ cảm xúc) + てならない／でならない」diễn tả cảm xúc dâng trào không thể kìm nén: \"vô cùng...\", \"hết sức...\". Ở đây là \"vô cùng lo lắng\".","translation_vi":"Hình như bà tôi vô cùng lo lắng cho tôi đang đi du học."},{"mondai":7,"q":5,"prompt":"発達する低気圧の影響で、明日の夕方から夜にかけて、激しい雨が（　　）。","options":["降りがちだ","降りつつある","降ってばかりだ","降るおそれがある"],"answer":4,"word_explain":"「Vる + おそれがある」diễn tả khả năng/nguy cơ xảy ra một sự việc không mong muốn trong tương lai (dùng nhiều trong dự báo thời tiết, tin tức). 「がちだ」(hay có xu hướng), 「つつある」(đang dần), 「てばかりだ」(toàn là) không hợp với ngữ cảnh dự báo ngày mai.","translation_vi":"Do ảnh hưởng của vùng áp thấp đang phát triển, từ chiều tối đến đêm ngày mai có nguy cơ xảy ra mưa lớn."},{"mondai":7,"q":6,"prompt":"（おもちゃ屋で） 店員「お客様、何か（　　）、ご案内いたしますが。」 客「あ、孫に頼まれたゲームソフトを探しているんです。」","options":["お探しでしたら","探してくださいましたら","お探ししましたら","探させていただきましたら"],"answer":1,"word_explain":"Cần dùng tôn kính ngữ (尊敬語) cho hành động của khách hàng: 「お + V(bỏ ます) + です」→「お探しでしたら」(nếu quý khách đang tìm). Các phương án 3, 4 là khiêm nhường ngữ, phương án 2 sai hướng tiếp nhận hành động.","translation_vi":"(Ở cửa hàng đồ chơi) Nhân viên: \"Thưa quý khách, nếu quý khách đang tìm thứ gì đó thì tôi xin phép hướng dẫn ạ.\" Khách: \"À, tôi đang tìm đĩa game mà cháu nhờ mua.\""},{"mondai":7,"q":7,"prompt":"A「ねえねえ、夏休みのキャンプ、楽しみだね。」 B「うん。早く夏休みに（　　）。」","options":["なるかな","ならないかな","なるんだね","ならないんだね"],"answer":2,"word_explain":"「～ないかな」diễn tả mong ước, hy vọng điều gì đó sớm xảy ra (\"Ước gì... nhỉ\"). 「早く夏休みにならないかな」= Mong sao mau chóng tới kỳ nghỉ hè.","translation_vi":"A: \"Này này, chuyến cắm trại kỳ nghỉ hè đáng mong chờ quá nhỉ.\" B: \"Ừ. Ước gì mau đến kỳ nghỉ hè nhỉ.\""},{"mondai":7,"q":8,"prompt":"課長「田中さん、さっき頼んだ書類の整理ですけど、今週は出張もあって忙しいでしょうし、特に急ぎじゃないので、来週（　　）お願いします。」 田中「はい、わかりました。」","options":["になら","にでも","でなら","ででも"],"answer":2,"word_explain":"「N(thời gian) + にでも」dùng để đưa ra một đề xuất/gợi ý nhẹ nhàng, linh hoạt về thời điểm (ví dụ như: 明日にでも, 今度にでも, 来週にでも = tầm tuần sau cũng được).","translation_vi":"Trưởng phòng: \"Anh/chị Tanaka này, việc sắp xếp tài liệu tôi nhờ lúc nãy ấy, tuần này chắc anh/chị cũng có chuyến công tác nên bận rộn, mà cũng không gấp lắm nên tầm tuần sau làm giúp tôi cũng được.\" Tanaka: \"Vâng, tôi hiểu rồi ạ.\""},{"mondai":7,"q":9,"prompt":"この辺りは、春はお花見、夏は川遊び、秋は紅葉、冬はスキー（　　）、1年中自然を楽しむことができます。","options":["のことかと","かのように","ということと","というように"],"answer":4,"word_explain":"「～というように」dùng sau khi liệt kê các ví dụ cụ thể để tổng kết mang nghĩa \"như là...\", \"kiểu như...\".","translation_vi":"Khu vực này có thể tận hưởng thiên nhiên suốt cả năm, chẳng hạn như mùa xuân ngắm hoa anh đào, mùa hè chơi ở sông, mùa thu ngắm lá đỏ, mùa đông trượt tuyết."},{"mondai":7,"q":10,"prompt":"きれいな鳥がいたので写真を撮りたかったが、かばんからカメラを（　　）飛んでいってしまった。","options":["取り出そうとしたまま","取り出そうとしているうちに","取り出すようにしたまま","取り出すようにしているうちに"],"answer":2,"word_explain":"「V(ý chí) + ようとしているうちに」diễn tả \"trong lúc đang định làm gì đó (chưa kịp làm xong) thì một sự việc khác bất ngờ xảy ra\".","translation_vi":"Vì thấy con chim đẹp nên tôi muốn chụp ảnh, nhưng trong lúc tôi đang định lấy máy ảnh ra khỏi túi thì nó đã bay mất rồi."},{"mondai":7,"q":11,"prompt":"妹「ねえ、ベランダに干しておいた私のTシャツがないんだけど、知らない？」 姉「そうなの？今日、風強かったから、飛ばされて外に（　　）？」","options":["落ちちゃったんだって","落ちちゃったんじゃない","落としちゃったんだって","落としちゃったんじゃない"],"answer":2,"word_explain":"Chủ thể là chiếc áo bị gió thổi bay nên dùng tự động từ 「落ちる」 (「落ちちゃった」), loại tha động từ 「落とす」. 「～んじゃない？」diễn tả sự suy đoán (\"chẳng phải là... sao?\"), hợp ngữ cảnh hơn 「～んだって」(nghe nói).","translation_vi":"Em gái: \"Chị ơi, cái áo phông em phơi ở ban công không thấy đâu cả, chị có biết không?\" Chị gái: \"Thế à? Hôm nay gió mạnh lắm, chẳng phải nó bị thổi bay rồi rơi ra ngoài rồi sao?\""},{"mondai":7,"q":12,"prompt":"情報化や国際化が進む現代において、学校の教育がこれまでと（　　）。コンピュータなどの新しい教育内容が取り入れられるのも当然の流れだと思う。","options":["同じでいいはずがない","同じというだけではない","同じならいいに違いない","同じにならないことはない"],"answer":1,"word_explain":"「～はずがない」nghĩa là \"không thể nào mà lại...\". Phù hợp với câu sau khẳng định việc đưa nội dung giáo dục mới vào là xu thế tất yếu.","translation_vi":"Trong thời đại thông tin hóa và quốc tế hóa đang tiến triển hiện nay, giáo dục ở trường học không thể nào cứ giống như trước đây mãi được. Tôi nghĩ việc đưa các nội dung giáo dục mới như máy tính vào cũng là xu thế tất yếu."},{"mondai":8,"q":13,"prompt":"良い ＿＿＿　★　＿＿＿　＿＿＿ 増加は期待できない。","options":["その良さが","客に伝わらなければ","売り上げの","商品やサービスであっても"],"answer":1,"word_explain":"Thứ tự đúng: 4 → ★1 → 2 → 3. Ghép hoàn chỉnh: 良い商品やサービスであっても(4)その良さが(1)客に伝わらなければ(2)売り上げの(3)増加は期待できない。「～であっても」(\"dù là...\"), 「売り上げの増加」(sự gia tăng doanh số).","translation_vi":"Dù là sản phẩm hay dịch vụ tốt đi chăng nữa, nếu điểm tốt đó không được truyền đạt tới khách hàng thì không thể kỳ vọng sự gia tăng doanh số."},{"mondai":8,"q":14,"prompt":"先輩の家にはオルガンがある。5年前に ＿＿＿　★　＿＿＿　＿＿＿ だと言っていた。","options":["もらったときに","一度弾いたきり","海外に引っ越した","友達からもらったもので"],"answer":4,"word_explain":"Thứ tự đúng: 3 → ★4 → 1 → 2. Ghép hoàn chỉnh: 5年前に海外に引っ越した(3)友達からもらったもので(4)もらったときに(1)一度弾いたきり(2)だと言っていた。Cấu trúc 「Vた + きりだ」nghĩa là \"từ lúc làm V đó xong thì giữ nguyên trạng thái, không làm lại nữa\".","translation_vi":"Nhà tiền bối có một cây đàn organ. Tiền bối nói rằng đó là món đồ nhận được từ một người bạn đã chuyển ra nước ngoài 5 năm trước, và kể từ khi chơi một lần lúc mới nhận thì không đụng tới nữa."},{"mondai":8,"q":15,"prompt":"雑誌か ＿＿＿　★　＿＿＿　＿＿＿ 人との出会いだとインタビューに答えていたのを見て、本当にそうだなと思った。","options":["自分にとって","何かで","人生で一番大切なのは","誰かが"],"answer":4,"word_explain":"Thứ tự đúng: 2 → ★4 → 1 → 3. Ghép hoàn chỉnh: 雑誌か何かで(2)誰かが(4)自分にとって(1)人生で一番大切なのは(3)人との出会いだと...。「雑誌か何かで」(trên tạp chí hay thứ gì đó), 「Aにとって大切なのはBだ」(đối với A, điều quan trọng là B).","translation_vi":"Khi nhìn thấy ai đó trả lời phỏng vấn trên tạp chí hay gì đó rằng điều quan trọng nhất trong cuộc đời đối với bản thân là cuộc gặp gỡ với mọi người, tôi đã nghĩ quả thật đúng là như vậy."},{"mondai":8,"q":16,"prompt":"なかなか ＿＿＿　＿＿＿　★　＿＿＿ 行けることになった。","options":["ようやく","行けなかった","レストランに","予約がとれなくて"],"answer":3,"word_explain":"Thứ tự đúng: 4 → 2 → ★3 → 1. Ghép hoàn chỉnh: なかなか予約がとれなくて(4)行けなかった(2)レストランに(3)ようやく(1)行けることになった。「なかなか～なくて」(mãi mà không...), 「ようやく」(cuối cùng thì cũng).","translation_vi":"Cuối cùng tôi cũng có thể đi đến nhà hàng mà trước giờ mãi không đặt được chỗ nên không đi được."},{"mondai":8,"q":17,"prompt":"なぜときどき駅ですれ違う ＿＿＿　＿＿＿　★　＿＿＿ 自分でもよくわからない。","options":["だけの","こんなに気になる","のか","彼女のことが"],"answer":2,"word_explain":"Thứ tự đúng: 1 → 4 → ★2 → 3. Ghép hoàn chỉnh: なぜときどき駅ですれ違うだけの(1)彼女のことが(4)こんなに気になる(2)のか(3)自分でもよくわからない。Cấu trúc 「なぜ～のか + わからない」(không hiểu tại sao lại...).","translation_vi":"Tại sao tôi lại để tâm đến cô ấy—người mà chỉ thỉnh thoảng lướt qua nhau ở nhà ga—nhiều như vậy, ngay cả bản thân tôi cũng không hiểu rõ nữa."},{"mondai":9,"q":18,"prompt":"Chỗ trống [50] trong đoạn văn trên","options":["大会はある","大会がある","大会はあるのか","大会があるのか"],"answer":2,"word_explain":"Câu này giới thiệu sự tồn tại của giải đấu lần đầu tiên được nhắc tới nên dùng trợ từ 「が」 (「大会がある」) ở dạng câu trần thuật thông thường, không dùng 「は」 hay dạng nghi vấn 「のか」.","translation_vi":"Có một giải đấu được gọi là \"Masters\"."},{"mondai":9,"q":19,"prompt":"Chỗ trống [51] trong đoạn văn trên","options":["というわけだ","と言えないこともない","というだけではない","と言ってもいいぐらいだ"],"answer":1,"word_explain":"Câu bắt đầu bằng 「つまり」(nói tóm lại / tức là), nên kết câu bằng 「というわけだ」(\"tức là / điều đó có nghĩa là...\") để giải thích kết luận lại ý trước đó.","translation_vi":"Nói cách khác, kỷ lục thế giới mà người đàn ông 105 tuổi lập ra chính là kỷ lục thế giới ở hạng mục mà ông ấy tham gia."},{"mondai":9,"q":20,"prompt":"Chỗ trống [52] trong đoạn văn trên","options":["とすると","とはいえ","さらに","このように"],"answer":3,"word_explain":"Câu trước nêu lợi ích đối với người tham gia; câu sau mở rộng thêm lợi ích đối với cả những người không tham gia. Vì vậy dùng từ nối bổ sung 「さらに」(\"hơn nữa, thêm vào đó\").","translation_vi":"Hơn thế nữa, tầm ảnh hưởng từ sự tồn tại của giải Masters không chỉ dừng lại ở những người tham gia."},{"mondai":9,"q":21,"prompt":"Chỗ trống [53] trong đoạn văn trên","options":["そうやって","そうなったら","それでも","それには"],"answer":4,"word_explain":"Câu trước nói rằng những người cao tuổi khác khi thấy bạn đồng trang lứa thi đấu cũng sẽ có động lực vận động và sinh lực tinh thần. Câu sau nêu điều kiện cần thiết để đạt được điều đó, nên dùng 「それには」(để làm được điều đó thì cần..., thường đi kèm 「〜必要がある」).","translation_vi":"Để làm được điều đó, giải Masters cần được biết đến rộng rãi."},{"mondai":9,"q":22,"prompt":"Chỗ trống [54] trong đoạn văn trên","options":["社会","社会だ","社会とは","社会だから"],"answer":1,"word_explain":"Đây là cách kết câu bằng danh từ (体言止め) để nhấn mạnh khái niệm mục tiêu, liên kết trực tiếp với 「その社会の実現に向けて...」ở câu ngay sau đó. Các dạng 「社会だ」「社会とは」「社会だから」đều không phù hợp về mặt ngữ pháp trong câu không có chủ ngữ này.","translation_vi":"Một xã hội mà mọi người có thể khỏe mạnh cả thể chất lẫn tinh thần mãi mãi."}]},{"id":"g_2016_12","displayName":"12/2016","subtitle":"22 câu • Mondai 7–9 (Ngữ pháp)","m9_passage":"以下は、雑誌のコラムである。\n\n日本発のトイレマーク\n\n公衆トイレの入り口に描かれている男女の絵のマーク。そのマークがあれば、文字で「トイレ」と書かれていなくても、そこがトイレであることがわかる。世界のあちこちで使われているこのトイレマークが実は日本で生まれたものだということを[50]。\n\nトイレマークが生まれたのは、1964年の東京オリンピックがきっかけだ。この東京オリンピックは、アルファベットを使わない国での初めての開催であったため、特に問題になったのが、言葉の壁だった。当時、日本国内の案内板は「お手洗い」などと日本語で書かれているものがほとんどだった。[51]、それでは世界90数か国から来日する選手たちに理解してもらえない。かといって、参加国すべての国の言葉で書くわけにもいかない。そこで、案内板作成者たちは、あらゆる国の選手が理解できるよう、絵で表すことを考えた。[52]、トイレマークなのだ。\n\nそのほかにも、食堂、シャワー、公衆電話等の施設や設備を表すマークや、水泳、バレーボール等の競技を表すマークも作られた。競技を表すマークは、この東京オリンピックで初めて全面的に導入され、高い評価を受けた。そして、その後のオリンピックでもデザインを変えながら毎回[53]。トイレマークに代表されるように、東京オリンピックをきっかけに日本で生まれたマークが、言葉の壁を越え、今や新たなコミュニケーション手段として、世界に広がっている。それは、あらゆる人にわかりやすくという思いが世界に届いた[54]。","questions":[{"mondai":7,"q":1,"prompt":"卒業論文がなかなか書けなくて、一時は(　　)かけたが、何とか今日無事に提出することができた。","options":["あきらめ","あきらめて","あきらめる","あきらめた"],"answer":1,"word_explain":"「Vます + かける」: suýt nữa thì làm gì, đang làm dở (chỉ hành động sắp xảy ra nhưng chưa hoàn thành). 「あきらめる」 chia sang thể ます là 「あきらめ」 + 「かけた」.","translation_vi":"Vì mãi mà không viết được luận văn tốt nghiệp nên đã có lúc tôi suýt bỏ cuộc, nhưng bằng cách nào đó hôm nay cũng đã nộp được bình an vô sự."},{"mondai":7,"q":2,"prompt":"子どものころ、母(　　)作ったハンバーグが大好きで、よく作ってもらった。","options":["の","との","によって","にとって"],"answer":1,"word_explain":"Trong mệnh đề bổ nghĩa cho danh từ, trợ từ chủ ngữ 「が」 có thể chuyển thành 「の」 (「母が作った」 = 「母の作った」).","translation_vi":"Hồi nhỏ, tôi rất thích món hamburger mà mẹ làm và thường xuyên được mẹ làm cho ăn."},{"mondai":7,"q":3,"prompt":"多様な情報があふれる現代社会(　　)、大切なのは、膨大な情報の中から、自分に必要な情報を選ぶ力である。","options":["に加えて","において","を基にして","を込めて"],"answer":2,"word_explain":"「N + において」: tại, ở, trong (bối cảnh, thời đại, lĩnh vực - văn phong trang trọng). 「現代社会において」 = trong xã hội hiện đại.","translation_vi":"Trong xã hội hiện đại tràn ngập thông tin đa dạng, điều quan trọng là năng lực lựa chọn thông tin cần thiết cho bản thân từ trong lượng thông tin khổng lồ đó."},{"mondai":7,"q":4,"prompt":"作文が得意な友達に「どうやったらうまくなれるの？」と聞いたら、「たくさん書けば(　　)うまくなるよ。」と言われた。","options":["必ずしも","たとえ","そのうち","さっき"],"answer":3,"word_explain":"「そのうち」: chẳng bao lâu nữa, dần dần rồi sẽ (diễn tả sự thay đổi tự nhiên sau một khoảng thời gian). 「必ずしも」 đi với phủ định, 「たとえ」 đi với 「ても」, 「さっき」 là vừa nãy.","translation_vi":"Khi tôi hỏi người bạn giỏi viết văn rằng \"Làm thế nào để viết giỏi lên được?\", bạn ấy nói \"Nếu viết nhiều thì rồi dần dần sẽ giỏi lên thôi.\""},{"mondai":7,"q":5,"prompt":"看護師の仕事は夜勤もあって大変だが、自分でこの仕事を選んだ(　　)、がんばって続けたいと思う。","options":["以上","とたん","あげくに","かのように"],"answer":1,"word_explain":"「V(thể thông thường) + 以上(は)」: một khi đã..., vì đã... nên (thể hiện ý chí, quyết tâm hoặc nghĩa vụ đương nhiên).","translation_vi":"Công việc điều dưỡng có cả trực đêm nên rất vất vả, nhưng một khi đã tự mình chọn công việc này thì tôi muốn cố gắng tiếp tục."},{"mondai":7,"q":6,"prompt":"（内線電話で） 山田「はい、山田です。」 木村「受付の木村ですが、X社の中川様が(　　)。」 山田「わかりました。すぐ行きます。」","options":["伺いました","お目にかかりました","ございました","お越しになりました"],"answer":4,"word_explain":"「お越しになりました」 là tôn kính ngữ của 「来る」 (đến), dùng để nói về hành động của khách hàng (中川様). 「伺いました」 và 「お目にかかりました」 là khiêm nhường ngữ.","translation_vi":"(Qua điện thoại nội bộ) Yamada: \"Vâng, tôi là Yamada.\" Kimura: \"Tôi là Kimura ở quầy lễ tân, ông Nakagawa của công ty X đã đến ạ.\" Yamada: \"Tôi hiểu rồi. Tôi ra ngay.\""},{"mondai":7,"q":7,"prompt":"人は一生のうちどのくらい寝ているのでしょうか。仮に一日8時間寝て、80歳まで生きる(　　)。すると、睡眠時間は約233,600時間で、約27年寝ている計算になります。","options":["となりました","とします","とされていました","と見られます"],"answer":2,"word_explain":"「仮に〜とする」: giả sử rằng... (đặt ra giả thiết để tính toán hoặc lập luận).","translation_vi":"Trong suốt cuộc đời, con người ngủ khoảng bao lâu nhỉ? Giả sử một ngày ngủ 8 tiếng và sống đến 80 tuổi. Khi đó, thời gian ngủ tính ra sẽ là khoảng 233.600 giờ, tức là ngủ khoảng 27 năm."},{"mondai":7,"q":8,"prompt":"夢を語る(　　)誰でもできるが、実現させるのは簡単なことではない。","options":["だけでは","だけなら","ためしか","ためには"],"answer":2,"word_explain":"「Vる + だけなら」: nếu chỉ... thôi thì... (giả định ở mức độ tối thiểu, thường đối lập với vế sau khó hơn). 「だけでは」 không hợp nghĩa với 「誰でもできる」.","translation_vi":"Nếu chỉ nói về ước mơ thôi thì ai cũng làm được, nhưng biến nó thành hiện thực lại không phải chuyện đơn giản."},{"mondai":7,"q":9,"prompt":"（説明書で） エアコンを掃除するときは、安全上、必ずコンセントを(　　)してください。","options":["抜いたことを","抜いたことが","抜いてからに","抜いてからは"],"answer":3,"word_explain":"「Vてからにする」: hãy làm việc gì đó sau khi đã V (nhấn mạnh trình tự bắt buộc phải rút phích cắm trước rồi mới lau chùi).","translation_vi":"(Trong sách hướng dẫn) Khi vệ sinh máy điều hòa, để đảm bảo an toàn, nhất định hãy thực hiện sau khi đã rút phích cắm điện ra."},{"mondai":7,"q":10,"prompt":"私はスピーチが苦手なのに、今度友達の結婚パーティーでスピーチを(　　)、困っている。","options":["しにくくて","してほしくて","させてみたくて","することになってしまって"],"answer":4,"word_explain":"「〜ことになってしまって」 = 「〜ことになる」 (được quyết định, rơi vào tình huống phải làm gì) + 「〜てしまう」 (diễn tả sự việc ngoài ý muốn, đáng tiếc), phù hợp với 「困っている」.","translation_vi":"Tôi vốn dĩ kém khoản phát biểu trước đám đông, thế mà lần này lại bị phân công phát biểu ở tiệc cưới của bạn nên đang rất bối rối."},{"mondai":7,"q":11,"prompt":"せっかく、夕日がきれいなことで有名なA海岸に来たのに、急に雨が降り出した。どうも夕日は(　　)。","options":["見えてもしかたない","見られないことだった","見られそうにない","見えないことがあった"],"answer":3,"word_explain":"「どうも〜Vそうにない」: xem chừng / có vẻ như không thể... (phán đoán tiêu cực dựa trên tình huống thực tế trước mắt). 「見られる」 (thể khả năng) -> 「見られそうにない」.","translation_vi":"Đã mất công đến tận bờ biển A nổi tiếng với cảnh hoàng hôn đẹp, vậy mà trời bỗng đổ mưa. Có vẻ như không thể ngắm được hoàng hôn rồi."},{"mondai":7,"q":12,"prompt":"山川「中村くん、毎日ジョギング(　　)？」 中村「うん、そうなんだよ。」 山川「実は、ぼくもなんだよ。走るっていいよね。」","options":["しない","しててもいい","しちゃえば","してるんだって"],"answer":4,"word_explain":"「〜んだって？」: nghe nói là... à / đúng không? (hỏi xác nhận thông tin nghe được từ người khác, khớp với câu trả lời 「うん、そうなんだよ」).","translation_vi":"Yamakawa: \"Nakamura này, nghe nói cậu chạy bộ mỗi ngày hả?\" Nakamura: \"Ừ, đúng rồi đấy.\" Yamakawa: \"Thực ra tớ cũng thế đấy. Chạy bộ thích thật nhỉ.\""},{"mondai":8,"q":13,"prompt":"結婚生活を送る＿＿＿　＿＿＿　★　＿＿＿、相手への思いやりの気持ちを持つことだと思う。","options":["うえで","といえば","大切か","何が"],"answer":3,"word_explain":"Thứ tự đúng: 1 → 4 → ★3 → 2 (結婚生活を送るうえで 何が ★大切か といえば、…). Cấu trúc 「〜うえで」 (khi làm gì đó) và 「何が〜かといえば」 (nếu nói cái gì... thì).","translation_vi":"Nếu nói điều gì quan trọng khi chung sống hôn nhân, tôi nghĩ đó là việc có tấm lòng quan tâm, thấu hiểu đối phương."},{"mondai":8,"q":14,"prompt":"就職したときに＿＿＿　＿＿＿　★　＿＿＿とうとう壊れたので、買い換えることにした。","options":["ずっと","買って以来","かばんが","使っていた"],"answer":4,"word_explain":"Thứ tự đúng: 2 → 1 → ★4 → 3 (就職したときに 買って以来 ずっと ★使っていた かばんが とうとう…). 「Vて以来」 (kể từ sau khi làm V) bổ nghĩa cho cụm danh từ 「ずっと使っていたかばん」.","translation_vi":"Chiếc cặp mà tôi đã dùng suốt từ khi mua lúc đi làm cuối cùng cũng bị hỏng nên tôi quyết định mua cái mới thay thế."},{"mondai":8,"q":15,"prompt":"登山には不思議な魅力がある。登っているときはこんなに＿＿＿　＿＿＿　★　＿＿＿なぜかまた登りたくなる。","options":["思うのに","二度としたくないと","苦しいことは","山を下りて何日かすると"],"answer":1,"word_explain":"Thứ tự đúng: 3 → 2 → ★1 → 4 (こんなに 苦しいことは 二度としたくないと ★思うのに 山を下りて何日かすると なぜか…). 「〜と思うのに」 (dù nghĩ là... vậy mà...) nối sự đối lập giữa lúc leo và vài ngày sau khi xuống núi.","translation_vi":"Leo núi có một sức hút kỳ lạ. Lúc đang leo thì nghĩ chuyện khổ sở thế này sẽ không bao giờ làm lần hai nữa, vậy mà xuống núi được vài ngày thì chẳng hiểu sao lại muốn leo tiếp."},{"mondai":8,"q":16,"prompt":"彫刻家川村たけるが作る動物の彫刻作品は、形はシンプル＿＿＿　＿＿＿　＿＿＿　★生命力にあふれている。","options":["動き出し","そうな","ながら","今にも"],"answer":2,"word_explain":"Thứ tự đúng: 3 → 4 → 1 → ★2 (形はシンプル ながら 今にも 動き出し ★そうな 生命力にあふれている). 「Aな + ながら」 (tuy... nhưng), kết hợp 「今にも + Vます + そうな + N」 (trông như sắp sửa... bất cứ lúc nào).","translation_vi":"Các tác phẩm điêu khắc động vật do nhà điêu khắc Kawamura Takeru tạo ra tuy hình dáng đơn giản nhưng lại tràn đầy sức sống như thể sắp cử động bất cứ lúc nào."},{"mondai":8,"q":17,"prompt":"ビジネスで成功できる人とできない人の違いは、どんなに大変な状況でもあきらめずに＿＿＿　＿＿＿　＿＿＿　★と思う。","options":["かどうか","取り組める","にある","最後まで"],"answer":3,"word_explain":"Thứ tự đúng: 4 → 2 → 1 → ★3 (あきらめずに 最後まで 取り組める かどうか ★にある と思う). Cấu trúc 「違いは〜かどうかにある」 (sự khác biệt nằm ở việc liệu có... hay không).","translation_vi":"Tôi nghĩ sự khác biệt giữa người có thể thành công và người không thể thành công trong kinh doanh nằm ở việc liệu có thể không bỏ cuộc mà dốc sức đến cuối cùng hay không."},{"mondai":9,"q":18,"prompt":"Chỗ trống [50] trong đoạn văn trên","options":["ご存じなわけだ","ご存じだろうか","ご存じのようだ","ご存じだからだろう"],"answer":2,"word_explain":"「ご存じだろうか」: bạn có biết không? (câu hỏi tu từ lịch sự mở đầu bài viết/chuyên mục để thu hút sự chú ý của người đọc về một sự thật ít người biết).","translation_vi":"Bạn có biết rằng biểu tượng nhà vệ sinh được sử dụng khắp nơi trên thế giới này thực ra được sinh ra ở Nhật Bản không?"},{"mondai":9,"q":19,"prompt":"Chỗ trống [51] trong đoạn văn trên","options":["それに","しかし","または","それどころか"],"answer":2,"word_explain":"「しかし」 (tuy nhiên): nối ý tương phản giữa câu trước (bảng chỉ dẫn hầu hết viết bằng tiếng Nhật) và câu sau (như thế thì vận động viên nước ngoài không hiểu được).","translation_vi":"Tuy nhiên, nếu như vậy thì các vận động viên đến Nhật từ hơn 90 quốc gia trên thế giới sẽ không thể hiểu được."},{"mondai":9,"q":20,"prompt":"Chỗ trống [52] trong đoạn văn trên","options":["作成者が理解したのは","日本で考えられたのが","ここに生み出したのは","こうして生まれたのが"],"answer":4,"word_explain":"「こうして生まれたのが」 (và cái được sinh ra theo cách như vậy chính là...): tổng kết quá trình ở câu trước (những người tạo bảng chỉ dẫn đã nghĩ cách biểu thị bằng hình vẽ) để dẫn sang kết quả 「トイレマークなのだ」.","translation_vi":"Và thứ được sinh ra theo cách như vậy chính là biểu tượng nhà vệ sinh."},{"mondai":9,"q":21,"prompt":"Chỗ trống [53] trong đoạn văn trên","options":["使用されている","使用した点だ","使用していける","使用したいものだ"],"answer":1,"word_explain":"Chủ ngữ là 「競技を表すマークは」 (các biểu tượng môn thi đấu), nên cần thể bị động tiếp diễn 「使用されている」 (được sử dụng đều đặn qua mỗi kỳ cho đến nay).","translation_vi":"Và ở các kỳ Olympic sau đó, chúng cũng đều đang được sử dụng qua từng kỳ trong khi thay đổi thiết kế."},{"mondai":9,"q":22,"prompt":"Chỗ trống [54] trong đoạn văn trên","options":["結果として表れるかもしれない","結果のはずだった","結果に違いない","結果でなければならなかった"],"answer":3,"word_explain":"「〜に違いない」 (chắc chắn là...): câu kết bài khẳng định chắc chắn nhận định/suy đoán của tác giả về lý do biểu tượng Nhật Bản lan rộng ra thế giới.","translation_vi":"Điều đó chắc chắn là kết quả của việc tâm ý \"làm sao để dễ hiểu cho tất cả mọi người\" đã chạm tới thế giới."}]},{"id":"g_2016_07","displayName":"07/2016","subtitle":"22 câu • Mondai 7–9 (Ngữ pháp)","m9_passage":"２５時\nロベズエドガー\n\n先日、サッカーの日本代表が海外で試合を行い、その試合が深夜にテレビで生中継された。生中継が始まる前に、放送は何時からか確認しようとインターネットで調べて驚いた。あるサイトに「金曜２５時放送」と書いてあったのだ。一日は[50]。知人に聞いて、「金曜２５時」というのは土曜の午前１時のことだと知った。「２５時」のような表現は、店の営業時間の掲示などでも見るという。なぜ、午前１時を「２５時」と表現するのだろうか。\n\n[51]表現を使い始めたのはテレビ局だとする説が有力だ。日本の多くのテレビ局では、朝４時前後に一日の放送が始まり、そこからの２４時間を一日と考える。つまり、テレビ局にとっては、夜の０時が一日の終わりではない。２２時、２３時ときたら、その次は０時ではなく２４時で、午前１時は２５時なのである。このようにして「２５時」という表現が[52]。\n\n現代の日本社会は夜型化が進み、午前０時を過ぎても活動している人が多い。だから、午前０時を過ぎても「今日」は続く。[53]、「起きてから寝るまでが今日」だと考えれば、翌日の午前１時ではなく、その日の２５時と表現したほうが的確かもしれない。私も、土曜の午前１時に見た番組は金曜の夜に見たという感じがするので、金曜２５時と考えたほうが実際の感覚に近い気もする。生活の夜型化と「寝るまでが今日」という考え方が、２４時間しかない一日に「２５時」を[54]。","questions":[{"mondai":7,"q":1,"prompt":"この国で、卵、牛乳（　　）３番目に多い食物アレルギーは、小麦アレルギーだ。","options":["ついで","に沿って","に代わって","にしたがって"],"answer":1,"word_explain":"「〜についで」: tiếp theo sau, đứng sau ~ (dùng để xếp thứ tự). Lưu ý trong bản đề in thiếu trợ từ に trước ついで.","translation_vi":"Ở đất nước này, loại dị ứng thực phẩm nhiều thứ 3 sau trứng và sữa bò là dị ứng lúa mì."},{"mondai":7,"q":2,"prompt":"弟がスケートをするのが初めてだったので何度か転んでいたが、初めてにしては（　　）上手だった。","options":["ついに","まさか","なかなか","まもなく"],"answer":3,"word_explain":"「初めてにしては」 (so với lần đầu thì) kết hợp với phó từ 「なかなか」 (khá là) để đánh giá tích cực năng lực vượt kỳ vọng.","translation_vi":"Vì là lần đầu em trai tôi trượt băng nên có ngã mấy lần, nhưng so với lần đầu thì em ấy trượt khá giỏi."},{"mondai":7,"q":3,"prompt":"私は漫画ばかり読んでいると思われているようだが、そんなことはない。たまには小説を読むこと（　　）ある。","options":["なんて","だって","のほかにも","のほうが"],"answer":2,"word_explain":"「〜ことだってある」 (cũng có lúc ~, tương đương こともある nhưng nhấn mạnh sự ngoại lệ so với suy nghĩ thông thường).","translation_vi":"Hình như mọi người nghĩ tôi toàn đọc truyện tranh, nhưng không phải vậy đâu. Thỉnh thoảng tôi cũng có lúc đọc tiểu thuyết chứ."},{"mondai":7,"q":4,"prompt":"私は、進学するか就職するか迷ったが、家族や先生と何日も（　　）、進学を選んだ。","options":["話し合った末に","話し合って以来","話し合ったきり","話し合って初めて"],"answer":1,"word_explain":"「Vた＋末に」: sau một quá trình dài suy nghĩ/thảo luận vất vả thì cuối cùng đi đến kết quả/quyết định ~.","translation_vi":"Tôi đã phân vân giữa việc học lên hay đi làm, nhưng sau nhiều ngày bàn bạc với gia đình và thầy cô, cuối cùng tôi đã chọn học lên."},{"mondai":7,"q":5,"prompt":"（会社で） 課長「山下さん、Ａ社の木村様が（　　）、応接室に案内してください。」 山下「はい、わかりました。」","options":["参ったら","伺ったら","おありだったら","おいでになったら"],"answer":4,"word_explain":"「おいでになる」 là tôn kính ngữ của 「来る」 (đến), dùng cho khách hàng là ông Kimura. 「参る」「伺う」 là khiêm nhường ngữ; 「おありだ」 là tôn kính ngữ của 「ある」.","translation_vi":"(Ở công ty) Trưởng phòng: \"Anh/chị Yamashita này, khi nào ông Kimura của công ty A đến thì hãy hướng dẫn ông ấy vào phòng tiếp khách nhé.\" Yamashita: \"Vâng, tôi hiểu rồi ạ.\""},{"mondai":7,"q":6,"prompt":"実家の押し入れを片付けていたら、祖父母の結婚式の写真が出てきた。よくこんな昔の写真が今まで残っていた（　　）。","options":["わけだ","ものだ","だろうか","のではないか"],"answer":2,"word_explain":"「よく〜たものだ」: diễn tả sự cảm thán sâu sắc, ngạc nhiên (\"thật đáng ngạc nhiên khi mà...\").","translation_vi":"Khi dọn tủ âm tường ở nhà bố mẹ, tôi thấy tấm ảnh đám cưới của ông bà. Thật không ngờ một bức ảnh cũ như thế này mà vẫn còn giữ được đến tận bây giờ."},{"mondai":7,"q":7,"prompt":"今回の戦略が有効であったかどうかは、まだ結果が出ていない現時点では（　　）。","options":["判断すべきだ","判断しかねる","判断したにすぎない","判断せざるを得ない"],"answer":2,"word_explain":"「Vます＋かねる」: khó lòng mà ~, không thể ~ (vì chưa có kết quả nên chưa thể đưa ra phán đoán).","translation_vi":"Chiến lược lần này có hiệu quả hay không thì ở thời điểm hiện tại khi chưa có kết quả vẫn chưa thể phán đoán được."},{"mondai":7,"q":8,"prompt":"妻「ねえ、この雑誌のアンケートに答えると、抽選で一人にテレビが当たるんだって。応募してみようよ。」 夫「抽選で一人じゃ、（　　）。」","options":["当たりますように","当たらないくせに","当たるといいなあ","当たりっこないよ"],"answer":4,"word_explain":"「Vます＋っこない」: tuyệt đối không thể nào ~, làm gì có chuyện ~ (bốc thăm chỉ có 1 người trúng thì chắc chắn không trúng nổi).","translation_vi":"Vợ: \"Này, nghe nói trả lời khảo sát của tạp chí này thì bốc thăm trúng thưởng sẽ có 1 người trúng tivi đấy. Mình đăng ký thử đi.\" Chồng: \"Bốc thăm có 1 người thì đời nào mà trúng được.\""},{"mondai":7,"q":9,"prompt":"どんな人が相手でも厳しく接する森先輩だが、なぜか私（　　）そうではない。","options":["のためにしか","のことだけで","についてしか","に対してだけは"],"answer":4,"word_explain":"「N＋に対してだけは」: chỉ riêng đối với ~ là (khác biệt với mọi người khác).","translation_vi":"Tiền bối Mori là người đối xử nghiêm khắc với bất kỳ ai, nhưng không hiểu sao chỉ riêng với tôi lại không như vậy."},{"mondai":7,"q":10,"prompt":"自分のアドバイスが相手の人生を大きく変える（　　）、誰でも慎重になるだろう。","options":["かもしれない一方で","しかない一方で","かもしれないとしたら","しかないとしたら"],"answer":3,"word_explain":"「〜かもしれないとしたら」: nếu giả sử có khả năng ~ (giả định một tình huống có thể xảy ra).","translation_vi":"Nếu lời khuyên của bản thân có thể làm thay đổi lớn cuộc đời của người khác, thì hẳn ai cũng sẽ trở nên thận trọng."},{"mondai":7,"q":11,"prompt":"近所の図書館によく行くが、人気の本が貸し出し中で読めないことが多いので、もっと数を増やして、たくさんの人が読める（　　）。","options":["ようにしてほしい","ようになりたい","ようにすることができる","ようになろうとしている"],"answer":1,"word_explain":"「V(thể khả năng)＋ようにしてほしい」: mong muốn ai đó/phía thư viện làm cho việc ~ trở nên có thể.","translation_vi":"Tôi thường đến thư viện gần nhà, nhưng những cuốn sách nổi tiếng hay bị mượn hết nên nhiều khi không đọc được; vì vậy tôi mong thư viện tăng thêm số lượng sách để nhiều người có thể đọc được."},{"mondai":7,"q":12,"prompt":"（店で） 客「すみません、この携帯電話を解約したいんですが。」 店員「かしこまりました。差し支えなければ、解約の理由を（　　）。」","options":["お聞きしませんか","お聞きになりますか","お聞きしてもよろしいでしょうか","お聞きになったらいかがですか"],"answer":3,"word_explain":"「お＋Vます＋してもよろしいでしょうか」: dùng khiêm nhường ngữ để xin phép khách hàng một cách lịch sự (\"tôi xin phép được hỏi... có được không ạ?\").","translation_vi":"(Tại cửa hàng) Khách: \"Xin lỗi, tôi muốn hủy hợp đồng chiếc điện thoại di động này.\" Nhân viên: \"Vâng, tôi hiểu rồi ạ. Nếu không phiền, tôi xin phép được hỏi lý do hủy hợp đồng có được không ạ?\""},{"mondai":8,"q":13,"prompt":"一人暮らしを始めたころは、料理も洗濯もすべて自分でするのが大変で、これまでずっと＿＿＿　＿＿＿　★　＿＿＿。","options":["環境にいたか","毎日だった","どんなに恵まれた","と感じさせられる"],"answer":4,"word_explain":"Thứ tự đúng: 3 → 1 → ★4 → 2. Cấu trúc câu nghi vấn lồng 「どんなに〜か」 kết hợp 「〜と感じさせられる」 (bị khiến cho cảm thấy là...) bổ nghĩa cho 「毎日だった」.","translation_vi":"Khoảng thời gian mới bắt đầu sống một mình, việc tự làm hết mọi thứ từ nấu ăn đến giặt giũ thật vất vả, ngày nào cũng khiến tôi phải cảm nhận rằng trước đây mình đã sống trong một môi trường được ưu ái biết nhường nào."},{"mondai":8,"q":14,"prompt":"このお菓子はとても簡単に作れるから初心者でも失敗する＿＿＿　★　＿＿＿　＿＿＿友人の話を聞いて、作ってみようと思った。","options":["ことは","という","ない","まず"],"answer":4,"word_explain":"Thứ tự đúng: 1 → ★4 → 3 → 2. Mẫu câu 「失敗することはまずない」 (hầu như không bao giờ thất bại, phó từ まず đi với phủ định ない) + 「という」 bổ nghĩa cho 「友人の話」.","translation_vi":"Nghe người bạn kể rằng món bánh này làm rất đơn giản nên ngay cả người mới bắt đầu cũng hầu như không thể thất bại, tôi liền nghĩ hay là làm thử xem sao."},{"mondai":8,"q":15,"prompt":"近所のスーパーの隣にはクリーニング屋がある。スーパーもクリーニング屋も私が＿＿＿　＿＿＿　★　＿＿＿助かる。","options":["開いていて","買い物するついでに","預けた服を取りに行けるのが","仕事から帰る時間でも"],"answer":2,"word_explain":"Thứ tự đúng: 4 → 1 → ★2 → 3. 「仕事から帰る時間でも開いていて」 (mở cửa ngay cả giờ tôi tan làm về) nối với 「買い物するついでに預けた服を取りに行けるのが助かる」 (tiện đường mua sắm lấy đồ đã gửi về nên rất tiện).","translation_vi":"Cạnh siêu thị gần nhà tôi có một tiệm giặt ủi. Cả siêu thị lẫn tiệm giặt ủi đều mở cửa ngay cả vào giờ tôi tan làm về, và nhân tiện đi mua sắm tôi có thể ghé lấy quần áo đã gửi nên rất tiện."},{"mondai":8,"q":16,"prompt":"薬は正しく＿＿＿　★　＿＿＿　＿＿＿状態を悪化させてしまう危険もある。","options":["効果が","飲まないと","得られるはずの","得られないだけでなく"],"answer":3,"word_explain":"Thứ tự đúng: 2 → ★3 → 1 → 4. 「正しく飲まないと」 (nếu không uống đúng cách) + 「得られるはずの効果が」 (hiệu quả đáng lẽ có thể đạt được) + 「得られないだけでなく」 (không những không đạt được mà còn...).","translation_vi":"Thuốc mà không uống đúng cách thì không những không đạt được hiệu quả đáng lẽ phải có, mà còn có nguy cơ làm tình trạng bệnh trở nên tồi tệ hơn."},{"mondai":8,"q":17,"prompt":"いつ行っても長い行列ができているラーメン屋なのに＿＿＿　＿＿＿　★　＿＿＿だ。","options":["行ったから","何時ごろがすいているか","事前に確認してから","今回あまり並ばないで済んだのは"],"answer":3,"word_explain":"Thứ tự đúng: 4 → 2 → ★3 → 1. Cấu trúc giải thích lý do 「〜のは〜からだ」 (việc lần này không phải xếp hàng lâu là vì đã xác nhận trước xem tầm mấy giờ vắng rồi mới đi).","translation_vi":"Tuy là quán mì ramen lúc nào đến cũng có hàng dài người xếp hàng, nhưng lý do lần này tôi không phải xếp hàng lâu là vì tôi đã kiểm tra trước xem khoảng mấy giờ thì vắng rồi mới đi."},{"mondai":9,"q":18,"prompt":"Chọn đáp án phù hợp cho chỗ trống [50] trong đoạn văn trên.","options":["２４時間なのか","２４時間ではないのか","２４時間といえるか","２４時間だっただろうか"],"answer":2,"word_explain":"Trước đó tác giả ngạc nhiên khi thấy \"Thứ Sáu 25 giờ phát sóng\", nên đặt câu hỏi tu từ 「一日は２４時間ではないのか」 (\"Một ngày chẳng phải có 24 giờ hay sao?\").","translation_vi":"Chẳng phải một ngày chỉ có 24 tiếng hay sao?"},{"mondai":9,"q":19,"prompt":"Chọn đáp án phù hợp cho chỗ trống [51] trong đoạn văn trên.","options":["こういう","それ以外の","同じ","次のような"],"answer":1,"word_explain":"「こういう」 (như thế này) thay thế cho cách diễn đạt 「『２５時』のような表現」 đã nhắc đến ở đoạn 1. 「次のような」 dùng để chỉ nội dung phía sau nên không hợp.","translation_vi":"Có một giả thuyết rất thuyết phục cho rằng chính các đài truyền hình là nơi đầu tiên sử dụng kiểu cách diễn đạt như thế này."},{"mondai":9,"q":20,"prompt":"Chọn đáp án phù hợp cho chỗ trống [52] trong đoạn văn trên.","options":["生まれることになっている","生まれたとしよう","生まれるといわれていた","生まれたらしい"],"answer":4,"word_explain":"Đầu đoạn 2 mở bằng 「〜とする説が有力だ」 (có giả thuyết mạnh cho rằng...), nên câu kết đoạn giải thích nguồn gốc dùng 「生まれたらしい」 (dường như đã ra đời như thế) là phù hợp nhất về mặt suy đoán dựa trên thông tin nghe/đọc được.","translation_vi":"Theo cách như vậy, cách diễn đạt \"25 giờ\" dường như đã ra đời."},{"mondai":9,"q":21,"prompt":"Chọn đáp án phù hợp cho chỗ trống [53] trong đoạn văn trên.","options":["ただ","一方","確かに","それでも"],"answer":3,"word_explain":"「確かに、〜と考えれば、〜かもしれない」: \"Quả thực, nếu nghĩ như vậy thì có lẽ...\" — dùng để đồng tình/xác nhận nhận định vừa nêu ở câu trước (\"qua 0 giờ sáng thì 'hôm nay' vẫn tiếp tục\").","translation_vi":"Quả thực, nếu nghĩ rằng \"từ lúc thức dậy đến lúc đi ngủ là ngày hôm nay\", thì thay vì nói 1 giờ sáng hôm sau, diễn đạt là 25 giờ của ngày hôm đó có lẽ sẽ chính xác hơn."},{"mondai":9,"q":22,"prompt":"Chọn đáp án phù hợp cho chỗ trống [54] trong đoạn văn trên.","options":["作ったからだ","作ったのだろう","作ったこともある","作ったほどだ"],"answer":2,"word_explain":"Đây là câu kết bài đưa ra suy luận/kết luận của tác giả giải thích cho câu hỏi ở đầu bài, nên dùng 「〜のだろう」 (chắc hẳn là đã tạo nên...). 「〜からだ」 không hợp vì đầu câu không có 「〜のは」.","translation_vi":"Lối sống thức khuya và quan niệm \"đến khi đi ngủ vẫn là hôm nay\" hẳn đã tạo ra \"25 giờ\" trong một ngày vốn chỉ có 24 tiếng đồng hồ."}]},{"id":"g_2015_12","displayName":"12/2015","subtitle":"22 câu • Mondai 7–9 (Ngữ pháp)","m9_passage":"以下の文章は、雑誌のコラムである。\n\nすしを載せた皿が、客席沿いに設置された台の上を通って次々に流れていく。回転ずしの店で、目の前を通り過ぎるおいしそうなすしを見ていると、どれも食べたくなる。つい食べ過ぎてしまうという人も[50]。回転ずしで1回に食べる量の平均は一人約10皿だという。すし1つのご飯の量が約20グラムで、普通、回転ずしでは1皿にすしが2つ載っているから、約400グラムもご飯を食べていることになる。茶わん1杯分のご飯の量が約150グラムだとすると、[51]。回転ずしでたくさん食べてしまうのはなぜなのか。\n\nこんな[52]。すしが好きな人たちにすしを食べてもらう。まずは、すしの皿を台に載せて流さず、1皿ずつ注文してすしを食べる。別の日に今度は、流れているすしの皿を取ってすしを食べる。[53]、流れているときに食べた量は、そうでないときの約1.5倍になったという。\n\n心理学の専門家によると、これは「目の前に流れてくる」ことの効果らしい。すしが目の前に流れてくると、意識しなくても目に入り、あれもこれも食べたいと思ってしまう。また、人間は、目の前で動いている食べ物を見ると目で追って手に入れようとする性質を持っており、それも思わず皿を取ってしまう原因の一つだということだ。\n\n回転ずしでたくさん食べてしまうのには、納得の理由があったのだ。回転ずしの店に行ったとき、食べ過ぎてしまうのは[54]。","questions":[{"mondai":7,"q":1,"prompt":"この花は、毎日水をやる必要はありません。大体２日（　　）やってください。","options":["おきに","ぶりに","うちに","たびに"],"answer":1,"word_explain":"「〜おきに」diễn tả khoảng cách lặp lại đều đặn về thời gian hoặc không gian (\"cứ cách ... lại ...\"). 「２日おきに」là \"cứ cách 2 ngày (lại tưới một lần)\".","translation_vi":"Loài hoa này không cần tưới nước mỗi ngày. Hãy tưới khoảng hai ngày một lần."},{"mondai":7,"q":2,"prompt":"ジョギングは健康にいいが、正しく行わないと、（　　）ひざや腰を痛めてしまう場合もある。","options":["かりに","せっかく","いまにも","かえって"],"answer":4,"word_explain":"「かえって」có nghĩa là \"ngược lại, trái lại\", dùng khi kết quả đi ngược với mong đợi ban đầu (tốt cho sức khỏe >< lại gây đau).","translation_vi":"Chạy bộ tuy tốt cho sức khỏe nhưng nếu không thực hiện đúng cách, ngược lại có khi còn làm đau đầu gối hoặc lưng."},{"mondai":7,"q":3,"prompt":"駅前のパン屋の主人は、商売はあまり上手ではないが、おいしいパンを作ること（　　）一流の技術を持っている。","options":["によっては","を前にして","にかけては","を基にして"],"answer":3,"word_explain":"「〜にかけては」dùng để nêu lĩnh vực mà ai đó có năng lực, kỹ thuật vượt trội (\"nói về mặt ~ thì...\").","translation_vi":"Ông chủ tiệm bánh trước nhà ga tuy buôn bán không giỏi lắm, nhưng nói về việc làm bánh mì ngon thì ông có kỹ thuật bậc nhất."},{"mondai":7,"q":4,"prompt":"ＡＢＣ美術館はとても広くて、たった３時間では全部の作品を（　　）。","options":["見たきりだった","見きれなかった","見ないで済んだ","見ないでもなかった"],"answer":2,"word_explain":"「Vます + きれない」diễn tả không thể làm hết hoàn toàn một việc gì đó do số lượng quá nhiều hoặc không đủ thời gian/sức lực. 「見きれなかった」= \"đã không thể xem hết\".","translation_vi":"Bảo tàng mỹ thuật ABC rất rộng nên chỉ trong 3 tiếng thì không thể xem hết toàn bộ tác phẩm được."},{"mondai":7,"q":5,"prompt":"夫は何でも捨てないで取っておくので、家の中は物が増える（　　）。","options":["ためだ","ほどだ","一方だ","最中だ"],"answer":3,"word_explain":"「Vる + 一方だ」diễn tả một xu hướng biến đổi tiếp diễn liên tục theo một chiều (\"ngày càng..., cứ mãi...\").","translation_vi":"Chồng tôi cái gì cũng giữ lại chứ không vứt đi, nên đồ đạc trong nhà cứ ngày càng tăng lên mãi."},{"mondai":7,"q":6,"prompt":"パソコンの画面が映らなくなってしまった。いろいろ試してみたがうまくいかず、もう自分ではどうしようもないので、修理に（　　）。","options":["出しがちだ","出すほかない","出したおかげだ","出すことがある"],"answer":2,"word_explain":"「Vる + ほかない」mang nghĩa \"không còn cách nào khác ngoài việc...\", phù hợp với ngữ cảnh 「もう自分ではどうしようもない」.","translation_vi":"Màn hình máy tính không hiển thị nữa rồi. Tôi đã thử nhiều cách nhưng không được, tự mình không thể xoay xở được nữa nên đành phải mang đi sửa thôi."},{"mondai":7,"q":7,"prompt":"テニスコートの入り口の看板に「コート内では必ずテニスシューズを履く（　　）。」と書いてあるのに、守らない人がいるので困る。","options":["こと","はず","など","のみ"],"answer":1,"word_explain":"「Vる + こと」ở cuối câu dùng trong quy định, nội quy, chỉ thị (\"Phải.../Không được...\").","translation_vi":"Trên biển báo ở lối vào sân tennis có viết rằng \"Trong sân nhất định phải đi giày tennis\", vậy mà vẫn có người không tuân thủ nên thật phiền."},{"mondai":7,"q":8,"prompt":"A「最近、いつも眠そうだね。毎晩、寝るの遅いの？」 B「うん。早く（　　）思ってるんだけど。」","options":["寝なきゃって","寝ちゃったと","寝たいのは","寝られないとか"],"answer":1,"word_explain":"「寝なきゃって思ってる」là dạng nói rút gọn của「寝なければ（いけない）と思っている」(\"đang nghĩ là phải ngủ sớm\").","translation_vi":"A: \"Dạo này trông cậu lúc nào cũng buồn ngủ nhỉ. Tối nào cũng ngủ muộn à?\" B: \"Ừ. Tớ cũng nghĩ là phải đi ngủ sớm đấy chứ.\""},{"mondai":7,"q":9,"prompt":"私は歯医者が苦手だ。歯の痛みがひどいときには行くが、少し（　　）我慢してしまう。","options":["痛くなる前に","痛そうなときは","痛いぐらいなら","痛くないのだから"],"answer":3,"word_explain":"「〜ぐらいなら」diễn tả mức độ nhẹ/có thể chấp nhận được (\"nếu chỉ ở mức ~ thì...\"). 「少し痛いぐらいなら」= \"nếu chỉ hơi đau một chút thì\".","translation_vi":"Tôi rất ngại đi nha sĩ. Lúc đau răng dữ dội thì có đi, chứ nếu chỉ hơi đau một chút thì tôi toàn cố chịu đựng."},{"mondai":7,"q":10,"prompt":"私が風邪で学校を休んだ日、心配して電話をかけて（　　）友達がたくさんいて、うれしかった。","options":["きてくれた","きてあげた","みることができた","みることにした"],"answer":1,"word_explain":"「〜てきてくれる」kết hợp 「てくる」(hành động hướng về phía người nói) và 「てくれる」(người khác làm cho mình với lòng tốt).","translation_vi":"Ngày tôi bị cảm phải nghỉ học, có rất nhiều bạn đã lo lắng và gọi điện hỏi thăm cho tôi, làm tôi rất vui."},{"mondai":7,"q":11,"prompt":"A「最近、天気悪いよね。明日は晴れるかなあ。」 B「いや、予報だと、今週は晴れる日が（　　）。」 A「じゃあ、明日も天気悪いのかあ。」","options":["一日もないからだよ","一日もないみたいだよ","一日じゃないからだよ","一日じゃないみたいだよ"],"answer":2,"word_explain":"「（数字）＋も〜ない」diễn tả phủ định hoàn toàn (\"không lấy một ngày nào\"), kết hợp với 「〜みたいだ」dùng để truyền đạt thông tin từ dự báo thời tiết (\"có vẻ là...\").","translation_vi":"A: \"Dạo này thời tiết xấu nhỉ. Không biết ngày mai có nắng không.\" B: \"Không đâu, theo dự báo thì tuần này có vẻ không có lấy một ngày nắng nào đâu.\" A: \"Vậy thì ngày mai thời tiết cũng xấu à.\""},{"mondai":7,"q":12,"prompt":"彼からよく相談を受けるが、何に困っているのかわからないことが多い。私にどういうアドバイスを（　　）。","options":["してもいいようだ","したがるのだろうか","したほうがいいようだ","してほしいのだろうか"],"answer":4,"word_explain":"「私に〜てほしいのだろうか」diễn tả sự băn khoăn của người nói xem đối phương muốn mình làm gì cho họ (\"không biết anh ấy muốn tôi khuyên thế nào\"). 「〜がる」chỉ mong muốn của ngôi thứ ba nhưng không đi với cấu trúc nhờ/muốn người khác làm cho mình như 「私に〜てほしい」.","translation_vi":"Tôi thường xuyên nhận được lời tâm sự từ anh ấy, nhưng nhiều khi không hiểu anh ấy đang gặp khó khăn gì. Không biết anh ấy muốn tôi cho lời khuyên như thế nào nữa."},{"mondai":8,"q":13,"prompt":"狭い部屋でもテーブルの上に物を置かない　＿＿＿　＿＿＿　★　＿＿＿　に本に書いてあった。","options":["だけで","ようになると","ようにする","広く感じられる"],"answer":4,"word_explain":"Thứ tự đúng: 3 → 1 → ★4 → 2. 「物を置かないようにする」(cố gắng không để đồ) + 「だけで」(chỉ bằng việc) + 「広く感じられる」(có thể cảm thấy rộng) + 「ようになると」(trở nên... rằng [lưu ý: đề gốc in nhầm 「に」 thay cho 「と」 trước 「本に書いてあった」]).","translation_vi":"Trong sách có viết rằng ngay cả ở phòng nhỏ, chỉ cần tập thói quen không để đồ lên bàn thôi là sẽ trở nên cảm thấy rộng rãi hơn."},{"mondai":8,"q":14,"prompt":"レストランでアルバイトを始めてから　＿＿＿　＿＿＿　★　＿＿＿　ミスまでしてしまった。","options":["今日で１年たつのに","皿を割るという","うえに","客の注文を間違えた"],"answer":3,"word_explain":"Thứ tự đúng: 1 → 4 → ★3 → 2. 「今日で１年たつのに」(dù hôm nay đã được 1 năm rồi mà) + 「客の注文を間違えた」(đã nhầm đơn của khách) + 「うえに」(hơn nữa/chồng chất thêm) + 「皿を割るという」(lỗi là làm vỡ đĩa).","translation_vi":"Kể từ khi bắt đầu làm thêm ở nhà hàng đến hôm nay đã tròn 1 năm rồi vậy mà tôi đã nhầm đơn gọi món của khách, hơn nữa lại còn mắc cả lỗi làm vỡ đĩa."},{"mondai":8,"q":15,"prompt":"大雨の中を傘を差さずに　＿＿＿　＿＿＿　★　＿＿＿　今朝からずっと鼻水が止まらない。","options":["風邪が","治りかけていた","またひどくなって","帰ったせいか"],"answer":1,"word_explain":"Thứ tự đúng: 4 → 2 → ★1 → 3. 「傘を差さずに帰ったせいか」(có lẽ vì đã đi về mà không che ô) + 「治りかけていた風邪が」(cơn cảm đang sắp khỏi) + 「またひどくなって」(lại trở nặng thêm).","translation_vi":"Có lẽ tại không che ô đi về dưới cơn mưa lớn nên cơn cảm cúm vốn đang sắp khỏi của tôi lại trở nặng hơn, từ sáng nay cứ chảy nước mũi mãi không dứt."},{"mondai":8,"q":16,"prompt":"＿＿＿　＿＿＿　★　＿＿＿　ものが思い浮かぶと思いますが、大豆にもたくさん含まれています。","options":["肉や魚や卵といった","たんぱく質が","食べ物というと","多く含まれる"],"answer":3,"word_explain":"Thứ tự đúng: 2 → 4 → ★3 → 1. 「たんぱく質が多く含まれる」(chứa nhiều protein) + 「食べ物というと」(nói đến thực phẩm thì) + 「肉や魚や卵といった」(những thứ như thịt, cá, trứng) bổ nghĩa cho 「もの」.","translation_vi":"Khi nhắc đến thực phẩm chứa nhiều chất đạm thì chắc hẳn mọi người sẽ liên tưởng đến những thứ như thịt, cá hay trứng, nhưng trong đậu nành cũng chứa rất nhiều đấy."},{"mondai":8,"q":17,"prompt":"イベントの準備には　＿＿＿　＿＿＿　★　＿＿＿　スケジュールに余裕ができた。","options":["二日はかかるだろうと思われたが","多くのボランティアの方の協力で","最低でも","一日で終わったので"],"answer":2,"word_explain":"Thứ tự đúng: 3 → 1 → ★2 → 4. 「最低でも二日はかかるだろうと思われたが」(tưởng rằng ít nhất cũng mất 2 ngày nhưng) + 「多くのボランティアの方の協力で」(nhờ sự hợp tác của nhiều tình nguyện viên) + 「一日で終わったので」(vì đã xong trong 1 ngày nên).","translation_vi":"Công tác chuẩn bị cho sự kiện vốn được cho là sẽ mất ít nhất 2 ngày, nhưng nhờ sự hợp tác của nhiều tình nguyện viên mà đã hoàn thành trong 1 ngày nên lịch trình trở nên dư dả hơn."},{"mondai":9,"q":18,"prompt":"Chỗ trống [50] trong đoạn văn trên","options":["多かったのか","多いのではないか","多ければいい","多くてよかった"],"answer":2,"word_explain":"「〜のではないか」diễn tả sự phỏng đoán nhẹ nhàng, nêu nhận định của tác giả (\"chắc hẳn là nhiều người như vậy nhỉ\"). Các lựa chọn khác không hợp ngữ cảnh mở đầu vấn đề.","translation_vi":"Chắc hẳn cũng có nhiều người lỡ ăn quá nhiều mất."},{"mondai":9,"q":19,"prompt":"Chỗ trống [51] trong đoạn văn trên","options":["２杯分以上だ","２杯分以上でもおかしくない","２杯分以上だからだ","２杯分以上でなければいけない"],"answer":1,"word_explain":"Câu trước tính ra tổng lượng cơm ăn là khoảng 400 gam. Với giả định 「150グラムだとすると」(nếu tính 1 bát là 150g), kết luận trực tiếp về mặt số lượng là 「２杯分以上だ」(hơn 2 bát).","translation_vi":"Nếu lượng cơm trong một bát là khoảng 150 gam thì lượng cơm đó tương đương hơn 2 bát."},{"mondai":9,"q":20,"prompt":"Chỗ trống [52] trong đoạn văn trên","options":["実験だといえる","実験だとしている","実験がある","実験になる"],"answer":3,"word_explain":"Sau câu hỏi \"Tại sao người ta lại ăn nhiều ở quán sushi băng chuyền?\", đoạn mới giới thiệu một thí nghiệm để giải thích lý do bằng cụm 「こんな実験がある。」(\"Có một thí nghiệm như sau.\").","translation_vi":"Có một thí nghiệm như thế này."},{"mondai":9,"q":21,"prompt":"Chỗ trống [53] trong đoạn văn trên","options":["つまり","すると","ところが","一方で"],"answer":2,"word_explain":"「すると」dùng để nối kết quả xảy ra ngay sau khi thực hiện hành động thử nghiệm ở câu trước (\"Thế là / Kết quả là...\").","translation_vi":"Thế rồi, lượng ăn được khi đĩa đang chạy trên băng chuyền đã nhiều gấp khoảng 1,5 lần so với khi không chạy."},{"mondai":9,"q":22,"prompt":"Chỗ trống [54] trong đoạn văn trên","options":["避けたいに決まっている","避けるべきだった","避けられたかもしれない","避けられないのだろう"],"answer":4,"word_explain":"Đoạn kết khẳng định rằng việc ăn nhiều có lý do thuyết phục về mặt tâm lý và bản năng con người (mắt dõi theo thức ăn đang chuyển động), nên 「避けられないのだろう」(\"có lẽ là không thể tránh khỏi\") là hợp lý nhất.","translation_vi":"Khi đến quán sushi băng chuyền, việc lỡ ăn quá nhiều có lẽ là điều khó tránh khỏi."}]},{"id":"g_2015_07","displayName":"07/2015","subtitle":"22 câu • Mondai 7–9 (Ngữ pháp)","m9_passage":"「のぼり」\nシルバ　ジョゼ\n\nそれを見たのは、日本に着いた日、空港からホテルへバスで向かっているときだった。高さは[50]。青い布に白い字で「夏祭り」と書かれた大きな長方形の旗が道路沿いに一定間隔で何本も立っていたのだ。初めて見る、面白い光景だった。\n\nこのとき、「この旗は何だ？」と思った。しかし、街を歩くと、あちこちに似たような旗があり、それらを見ているうちに、「これは広告だ。」と気づいた。旗にはそれぞれ、「お弁当」、「食べ放題」、「本日特売日」といった短い言葉が書かれている。[51]旗も色が派手で高さがあり、１本でもよく目立つ。そのため自然と目が行く。また、何本か同じ旗が並んで立っていると、まるで一つの大きな看板のように見える。さらに、旗はどこにでも簡単に立てられるから、街のあちこちで[52]。私はこの旗に強い関心を持った。\n\n[53]、この旗は「のぼり」というそうだ。サイズは縦１８０センチ、横６０センチのものが多い。布の上部と片方の端に棒が通してあり、風が吹かなくても見えるようになっている。今の形ののぼりは、６００年ぐらい前にはすでにあり、当時は戦いで自分の軍と敵の軍とを見分けるために使われていたらしい。時代は変わり、今はそのような目的で使われることはない。だが、今も、情報を一瞬ではっきりと伝えたいときにのぼりを使うのは[54]。のぼりの特徴をとらえ、広告に応用した発想に感心した。","questions":[{"mondai":7,"q":1,"prompt":"南極の氷を調べること(　　)数十万年前の地球の気候を知ることができるそうだ。","options":["によって","にとって","に関して","に対して"],"answer":1,"word_explain":"「〜によって」: bằng cách, thông qua, nhờ vào (chỉ phương thức, nguyên nhân). Các đáp án khác: にとって (đối với), に関して (liên quan đến), に対して (đối với/trái với).","translation_vi":"Nghe nói rằng bằng việc nghiên cứu băng ở Nam Cực, có thể biết được khí hậu Trái Đất từ hàng trăm nghìn năm trước."},{"mondai":7,"q":2,"prompt":"この曲は、私には難しすぎて(　　)弾けそうにない。","options":["だんだん","今にも","必ず","とても"],"answer":4,"word_explain":"「とても〜ない」: hoàn toàn không thể ~, khó mà ~ nổi (đi với thể phủ định hoặc biểu thị sự bất khả thi).","translation_vi":"Bản nhạc này đối với tôi quá khó nên tôi hoàn toàn không thể nào chơi nổi."},{"mondai":7,"q":3,"prompt":"入社試験の面接で、緊張の(　　)、声が震えてしまった。","options":["わけで","あまり","ことに","中を"],"answer":2,"word_explain":"「Nのあまり / Vるあまり」: vì quá ~ đến mức dẫn đến kết quả không mong muốn (thường mang sắc thái tiêu cực hoặc ngoài ý muốn).","translation_vi":"Trong buổi phỏng vấn thi tuyển vào công ty, vì quá căng thẳng nên giọng tôi đã bị run."},{"mondai":7,"q":4,"prompt":"森川動物園は、森川駅からバスで３０分(　　)行ったところにある。","options":["など","などに","ほど","ほどに"],"answer":3,"word_explain":"「Số lượng/thời gian + ほど」: khoảng, chừng (ước lượng mức độ thời gian/khoảng cách).","translation_vi":"Vườn thú Morikawa nằm ở nơi đi xe buýt khoảng 30 phút từ ga Morikawa."},{"mondai":7,"q":5,"prompt":"(メールで) ４月２０日に新入生歓迎会を開きますので、ぜひご参加ください。なお、場所は(　　)、お知らせします。","options":["決まったおかげで","決まり次第","決まって以来","決まる一方で"],"answer":2,"word_explain":"「Vます形 + 次第」: ngay sau khi ~ (thường dùng trong thông báo trang trọng, vế sau là hành động sẽ thực hiện ngay).","translation_vi":"(Trong email) Vào ngày 20 tháng 4 chúng tôi sẽ tổ chức tiệc chào đón tân sinh viên, rất mong các bạn tham gia. Ngoài ra, ngay sau khi địa điểm được quyết định, chúng tôi sẽ thông báo."},{"mondai":7,"q":6,"prompt":"この地域のみかんの生産量は、２０００年から２００３年にかけて一時減少した(　　)、再び増加し、２０１０年には過去最高となった。","options":["として","のかどうか","からには","ものの"],"answer":4,"word_explain":"「〜ものの」: tuy ~ nhưng ~ (liên từ nhượng bộ, nối hai vế tương phản). Các đáp án khác: として (với tư cách), からには (một khi đã ~).","translation_vi":"Sản lượng quýt của khu vực này tuy đã giảm tạm thời từ năm 2000 đến năm 2003, nhưng sau đó lại tăng lên và đạt mức cao nhất từ trước đến nay vào năm 2010."},{"mondai":7,"q":7,"prompt":"(育児書で) 赤ちゃんの熱が少しあると心配になるかもしれませんが、熱が多少あっても、元気に遊んでいるなら、(　　)。","options":["慌てることはありません","慌てざるを得ません","慌てずにはいられません","慌てるに違いありません"],"answer":1,"word_explain":"「Vることはない」: không cần thiết phải ~. Các đáp án khác: ざるを得ない (đành phải), ずにはいられない (không thể nhịn được), に違いない (chắc chắn).","translation_vi":"(Trong sách nuôi dạy con) Nếu bé hơi sốt một chút thì có lẽ bạn sẽ lo lắng, nhưng dù có sốt nhẹ mà bé vẫn chơi đùa khỏe mạnh thì bạn không cần phải hoảng hốt đâu."},{"mondai":7,"q":8,"prompt":"(就職説明会で) 「就職活動とは、企業に応募することです。この企業で働きたいと思っていても、応募(　　)、何も進みません。まずは応募しましょう。」","options":["してみるより","できるといいし","しないことには","するのではなく"],"answer":3,"word_explain":"「〜ないことには〜ない」: nếu không ~ thì không thể ~ (điều kiện tiên quyết).","translation_vi":"(Tại buổi hướng dẫn tìm việc) \"Hoạt động tìm việc chính là ứng tuyển vào doanh nghiệp. Dù bạn có muốn làm việc ở doanh nghiệp này đi nữa, nếu không ứng tuyển thì sẽ chẳng có gì tiến triển cả. Trước hết hãy ứng tuyển đi.\""},{"mondai":7,"q":9,"prompt":"先月、エアコンを(　　)使っていたら、電気代が２万円を超えてしまった。","options":["使いすぎて","使ったまま","使いたいだけ","使いつづけたり"],"answer":3,"word_explain":"「Vたいだけ + V」: làm gì đó thỏa thích, bao nhiêu tùy thích. Các phương án khác lặp động từ 「使う」 một cách sai ngữ pháp hoặc thiếu vế song song.","translation_vi":"Tháng trước, vì dùng điều hòa thỏa thích bao nhiêu tùy thích nên tiền điện đã vượt quá 2 vạn yên."},{"mondai":7,"q":10,"prompt":"山川「ごめんね。田村さんに借りたCD、今日返そうと思っていたのに、持ってくるの忘れちゃった。」 田村「ああ、別に急がないから、次に会うときに(　　)よ。」","options":["持ってきてくれるはずだ","持ってきてあげるつもりだ","持ってきてくれればいい","持ってきてあげたほうがいい"],"answer":3,"word_explain":"「Vてくれればいい」: (bạn) làm ~ cho tôi là được rồi (diễn đạt sự chấp nhận nhẹ nhàng, không đòi hỏi). 「あげる」 sai hướng cho nhận.","translation_vi":"Yamakawa: \"Xin lỗi nhé. Cái CD mượn của cậu, mình định hôm nay trả mà lại quên mang theo mất rồi.\" Tamura: \"À, không vội đâu, lần sau gặp nhau cậu mang đến cho mình là được rồi.\""},{"mondai":7,"q":11,"prompt":"まだ読んでいない本が１０冊もあるから、しばらく本は(　　)と決めていたのに、面白そうな本を見つけて、つい買ってしまった。","options":["買うべきじゃなかった","買わないでいたんだ","買っていないだろう","買わずにおこう"],"answer":4,"word_explain":"「Vずにおく」: cứ để nguyên không làm V (có chủ đích). Kết hợp với 「〜と決めていた」 (đã quyết định rằng sẽ không mua) nên dùng thể ý chí 「買わずにおこう」.","translation_vi":"Vì vẫn còn tận 10 cuốn sách chưa đọc nên đã tự nhủ tạm thời sẽ không mua sách nữa, thế mà thấy cuốn có vẻ hay nên lỡ mua mất."},{"mondai":7,"q":12,"prompt":"昨日、天気がよかったので公園に出かけた。春の日ざしが暖かく、風が気持ちよくて、ベンチに座っていると、つい(　　)。","options":["眠そうだった","眠ってしまいそうになった","眠そうにしていた","眠っていそうだった"],"answer":2,"word_explain":"「Vてしまいそうになる」: suýt chút nữa thì lỡ làm ~ (thường đi với phó từ 「つい」). Các đáp án với 「〜そうだ」 (trông có vẻ) chỉ dùng để suy đoán trạng thái của người khác, không hợp chủ thể 「私」.","translation_vi":"Hôm qua thời tiết đẹp nên tôi ra công viên. Nắng xuân ấm áp, gió thổi dễ chịu, ngồi trên ghế dài thì suýt chút nữa tôi đã lỡ ngủ thiếp đi."},{"mondai":8,"q":13,"prompt":"優しい子になってほしい。娘の　＿＿＿　＿＿＿　★　＿＿＿　込めたからだ。","options":["優子に","そういった願いを","名前を","したのは"],"answer":4,"word_explain":"Thứ tự đúng: 3 → 1 → ★4 → 2. Câu hoàn chỉnh: 娘の名前を優子にしたのはそういった願いを込めたからだ。「〜を〜にする」 (đặt/chọn làm) + 「〜のは〜からだ」 (lý do là vì).","translation_vi":"Mong con trở thành một đứa trẻ dịu dàng. Lý do đặt tên con gái là Yuko là vì đã gửi gắm ước nguyện như vậy."},{"mondai":8,"q":14,"prompt":"日本で携帯電話が発売されて約２０年。いまや携帯電話は　＿＿＿　＿＿＿　★　＿＿＿　定着したといえるのではないか。","options":["に欠かせない","道具","として","生活"],"answer":2,"word_explain":"Thứ tự đúng: 4 → 1 → ★2 → 3. Câu hoàn chỉnh: いまや携帯電話は生活に欠かせない道具として定着したといえるのではないか。「生活に欠かせない道具として」 (như một công cụ không thể thiếu đối với cuộc sống).","translation_vi":"Khoảng 20 năm kể từ khi điện thoại di động được bán ra tại Nhật. Giờ đây chẳng phải có thể nói điện thoại di động đã ăn sâu như một công cụ không thể thiếu trong cuộc sống hay sao?"},{"mondai":8,"q":15,"prompt":"私は、スケジュール　＿＿＿　＿＿＿　★　＿＿＿　常に考えながら作業をしている。","options":["どうすればいいか","どおりに","には","仕事を進める"],"answer":3,"word_explain":"Thứ tự đúng: 2 → 4 → ★3 → 1. Câu hoàn chỉnh: 私は、スケジュールどおりに仕事を進めるにはどうすればいいか常に考えながら作業をしている。「Nどおりに」 (đúng theo) + 「Vるにはどうすればいいか」 (để làm V thì phải làm thế nào).","translation_vi":"Tôi vừa làm việc vừa luôn suy nghĩ xem phải làm thế nào để tiến hành công việc đúng theo lịch trình."},{"mondai":8,"q":16,"prompt":"筋肉トレーニングを　＿＿＿　＿＿＿　★　＿＿＿　効果は全く違います。","options":["今自分がどこを鍛えているのか","しているとき","しないのでは","意識するのと"],"answer":4,"word_explain":"Thứ tự đúng: 2 → 1 → ★4 → 3. Câu hoàn chỉnh: 筋肉トレーニングをしているとき、今自分がどこを鍛えているのか意識するのとしないのでは効果は全く違います。「Vるの＋と＋Vないのとでは」 (so sánh giữa việc làm và không làm).","translation_vi":"Khi đang tập cơ bắp, việc có ý thức xem hiện mình đang rèn luyện phần nào với việc không ý thức thì hiệu quả hoàn toàn khác nhau."},{"mondai":8,"q":17,"prompt":"「みるく屋」は、Ａ市に　＿＿＿　＿＿＿　★　＿＿＿　です。","options":["有名な","住んでいる人なら","知らない人はいないくらい","お菓子屋さん"],"answer":1,"word_explain":"Thứ tự đúng: 2 → 3 → ★1 → 4. Câu hoàn chỉnh: 「みるく屋」は、Ａ市に住んでいる人なら知らない人はいないくらい有名なお菓子屋さんです。「Nなら〜ない人はいないくらい」 (nếu là N thì đến mức không ai là không ~).","translation_vi":"\"Mirukuya\" là một tiệm bánh kẹo nổi tiếng đến mức hễ là người sống ở thành phố A thì không ai là không biết."},{"mondai":9,"q":18,"prompt":"Chỗ trống [50] trong đoạn văn trên","options":["２メートルくらいだっただろうか","２メートルくらいだったものなのか","２メートルくらいだと言われたそうだ","２メートルくらいだと思われていたことだ"],"answer":1,"word_explain":"「〜だっただろうか」 dùng khi người viết hồi tưởng lại và ước lượng một cách không chắc chắn tuyệt đối về cảnh tượng đã nhìn thấy lần đầu tiên. Các lựa chọn khác không hợp ngữ cảnh hồi tưởng cá nhân.","translation_vi":"Chiều cao của nó chắc là khoảng 2 mét chăng."},{"mondai":9,"q":19,"prompt":"Chỗ trống [51] trong đoạn văn trên","options":["このように","あのように","どの","そちらの"],"answer":3,"word_explain":"Trước danh từ 「旗」 cần một từ bổ nghĩa trực tiếp (liên thể từ), và đi cùng trợ từ 「も」 tạo thành cấu trúc 「どのNも〜」 (cây cờ nào cũng ~). 「このように」「あのように」 là phó từ không đứng trực tiếp trước danh từ.","translation_vi":"Cây cờ nào cũng có màu sắc sặc sỡ và chiều cao, nên dù chỉ một cây cũng rất nổi bật."},{"mondai":9,"q":20,"prompt":"Chỗ trống [52] trong đoạn văn trên","options":["使われている","使っていく","使おう","使わせる"],"answer":1,"word_explain":"Chủ ngữ ngầm định là 「旗」 (lá cờ), miêu tả trạng thái thực tế đang diễn ra ở đường phố nên dùng thể bị động tiếp diễn 「使われている」 (được sử dụng).","translation_vi":"Hơn nữa, vì cờ có thể dễ dàng dựng ở bất cứ đâu nên nó đang được sử dụng ở khắp mọi nơi trong thành phố."},{"mondai":9,"q":21,"prompt":"Chỗ trống [53] trong đoạn văn trên","options":["以上から","旗といえば","しかしながら","調べてみたところ"],"answer":4,"word_explain":"Cuối đoạn trước tác giả viết 「私はこの旗に強い関心を持った」 (Tôi có hứng thú mạnh mẽ với lá cờ này), mở đầu đoạn sau là kết quả tìm hiểu kèm truyền đạt thông tin 「〜というそうだ」 nên 「調べてみたところ」 (khi thử tìm hiểu thì) liên kết mạch lạc nhất.","translation_vi":"Khi tôi thử tìm hiểu thì nghe nói loại cờ này được gọi là \"nobori\"."},{"mondai":9,"q":22,"prompt":"Chỗ trống [54] trong đoạn văn trên","options":["変わらないこともない","変わらないようだ","変えないでおきたい","変えなければならない"],"answer":2,"word_explain":"Câu trước nói thời đại thay đổi nên mục đích chiến trận không còn nữa, nối với 「だが、今も〜」 (nhưng ngay cả bây giờ...) để chỉ ra điểm vẫn giống xưa dựa trên quan sát/tìm hiểu của tác giả nên dùng 「変わらないようだ」 (dường như vẫn không thay đổi).","translation_vi":"Tuy nhiên, ngay cả bây giờ, việc sử dụng nobori khi muốn truyền đạt thông tin một cách rõ ràng trong tích tắc dường như vẫn không thay đổi."}]},{"id":"g_2014_12","displayName":"12/2014","subtitle":"22 câu • Mondai 7–9 (Ngữ pháp)","m9_passage":"日本の「大人」\n\nチャンエディー\n\n商品名や商品の説明などで「大人の旅」「大人のパスタ」「大人のピアノ教室」といった表現をよく目にする。「大人」とあるが、成人用ではなく年齢制限はない。とすると、こうした表現で使われている「大人」とは[50]を指しているのだろうか。気になって調べてみた。\n\nある旅行会社は、「大人の旅」を企画している。これは、高級な旅館に泊まったり、時間をかけて旅行したり[51]。私はずっと、旅行会社が企画するのは低価格で短時間に多くの観光地に行く忙しい旅行というイメージを持っていたが、「大人の旅」は違っていた。\n\nまた、先日読んだ記事によると、「大人のパスタ」というのは、素材にこだわった商品らしい。価値があれば価格はあまり気にしないという人を対象として開発された。だから、良い素材を使うことによって多少価格が高くなっても[52]。\n\n駅にはられていた「大人のピアノ教室」のポスターで募集していた生徒は、昔習っていたピアノをまた習いたいという人や、仕事や家事以外に何か趣味を見つけたいという人だった。\n\n[53]、経済的、時間的、精神的に余裕がある人が「大人」なのだろう。私は、旅行はお金をかけないで行きたいし、食事は質より量だ。勉強とアルバイトで精いっぱいだから、何かを習う余裕もない。「大人」の価値観がわからない私は、まだ「大人」ではなさそうだ。「大人」の商品の価値がわかるようになったら、「大人」に[54]。","questions":[{"mondai":7,"q":1,"prompt":"竹石海水浴場は、約７００メートル（　　）、美しい砂浜が続いています。","options":["を通じて","に次いで","をめぐって","にわたって"],"answer":4,"word_explain":"「～にわたって」 diễn tả phạm vi kéo dài về không gian, thời gian hoặc số lượng (\"trải dài suốt...\"). 「約７００メートルにわたって」 = trải dài khoảng 700 mét.","translation_vi":"Bãi tắm biển Takeishi có bãi cát trắng đẹp trải dài khoảng 700 mét."},{"mondai":7,"q":2,"prompt":"奨学金の申請希望者は、締め切り日までに必要な書類を学生課奨学金係に直接持参するか、（　　）郵送してください。","options":["あるいは","および","なお","すなわち"],"answer":1,"word_explain":"「～か、あるいは～」 mang nghĩa \"hoặc là ~, hoặc là ~\", dùng để nối hai lựa chọn tương đương nhau.","translation_vi":"Những người có nguyện vọng đăng ký học bổng hãy mang trực tiếp hồ sơ cần thiết đến Bộ phận Học bổng thuộc Phòng Công tác Sinh viên trước hạn chót, hoặc gửi qua đường bưu điện."},{"mondai":7,"q":3,"prompt":"妻「ねえ、最近、天気予報、当たらないよね。今日（　　）一日晴れるって言ってたのに、午後は雨が降ったし。」 夫「そうだね。」","options":["くらいでも","だったり","だって","とかで"],"answer":3,"word_explain":"「～だって」 là dạng khẩu ngữ của 「～でも」 (\"ngay cả... / cũng thế\"), dùng để đưa ra ví dụ điển hình củng cố cho nhận xét trước đó.","translation_vi":"Vợ: \"Này anh, dạo này dự báo thời tiết không đúng nhỉ. Ngay cả hôm nay cũng nói là nắng cả ngày thế mà chiều lại mưa.\" Chồng: \"Ừ đúng thật.\""},{"mondai":7,"q":4,"prompt":"私がテニスを教えている中学生が、県大会で初めて優勝した。彼の努力をずっと見てきた（　　）、本当にうれしい。","options":["あげく","際に","あまり","だけに"],"answer":4,"word_explain":"「～だけに」 mang nghĩa \"chính vì ~ (nên lại càng...)\". Vì đã luôn dõi theo nỗ lực của cậu ấy nên lại càng cảm thấy vui sướng thực sự.","translation_vi":"Học sinh cấp hai mà tôi đang dạy tennis lần đầu tiên đã giành chức vô địch giải cấp tỉnh. Chính vì đã luôn chứng kiến sự nỗ lực của cậu ấy nên tôi thực sự rất vui."},{"mondai":7,"q":5,"prompt":"（会社で） 山下「田中さん、先ほどＡＢＣ建設の木村様からお電話がありました。至急連絡がほしい（　　）。」 田中「はい、わかりました。」","options":["までです","とします","とのことです","ことになります"],"answer":3,"word_explain":"「～とのことです」 dùng để truyền đạt lại lời nhắn hoặc thông tin nghe được từ người khác một cách lịch sự (\"nghe nói rằng / nhắn lại rằng...\").","translation_vi":"(Tại công ty) Yamashita: \"Anh Tanaka, lúc nãy anh Kimura bên công ty Xây dựng ABC có gọi điện đến. Anh ấy nhắn là muốn anh liên lạc lại gấp.\" Tanaka: \"Vâng, tôi hiểu rồi.\""},{"mondai":7,"q":6,"prompt":"夫にもらった指輪をなくしてしまった。一週間以上あちこち探しているが見つからない。もう（　　）のか。","options":["あきらめるしかない","あきらめたこともある","あきらめるはずがない","あきらめがたい"],"answer":1,"word_explain":"「～しかない」 mang nghĩa \"chỉ còn cách ~ / đành phải ~\". 「もうあきらめるしかないのか」 = lẽ nào chỉ còn cách từ bỏ thôi sao.","translation_vi":"Tôi đã làm mất chiếc nhẫn chồng tặng. Đã tìm khắp nơi hơn một tuần rồi mà vẫn không thấy. Lẽ nào đành phải từ bỏ thôi sao."},{"mondai":7,"q":7,"prompt":"先日の勉強会には、社会福祉を専門に研究されている、ＡＢＣ大学の石川春子先生に（　　）。","options":["参りました","お越しいただきました","おいでくださいました","いらっしゃいました"],"answer":2,"word_explain":"Trợ từ 「に」 trước chỗ trống chỉ đối tượng mà người nói nhận được hành động kính trọng từ họ, khớp với mẫu khiêm nhường 「（Người trên）に お～いただく」. 「お越しいただきました」 = đã mời được cô đến dự. (Nếu dùng 「おいでくださいました」 hay 「いらっしゃいました」 thì trợ từ phải là 「が」).","translation_vi":"Tại buổi học tập chuyên đề hôm trước, chúng tôi đã vinh dự mời được cô Haruko Ishikawa của trường Đại học ABC, người chuyên nghiên cứu về phúc lợi xã hội, đến tham dự."},{"mondai":7,"q":8,"prompt":"「村山屋」はコロッケが人気のお店で、いつも行列ができている。多いときは一日に千個も売れる（　　）驚きだ。","options":["となってでも","とするには","とあったほど","というから"],"answer":4,"word_explain":"「～というから驚きだ」 là cụm diễn đạt thông dụng mang nghĩa \"nghe nói rằng ~ nên thật đáng ngạc nhiên\".","translation_vi":"\"Murayamaya\" là quán nổi tiếng về món bánh khoai tây chiên korokke, lúc nào cũng có người xếp hàng. Nghe nói vào những lúc đông khách, một ngày bán được tận một nghìn cái nên thật đáng kinh ngạc."},{"mondai":7,"q":9,"prompt":"私は、いつ雨が（　　）、常に折り畳み傘を持ち歩いている。","options":["降ってもいいように","降っているとすると","降らないせいで","降ることがないのに"],"answer":1,"word_explain":"「～てもいいように」 diễn tả sự chuẩn bị sẵn sàng cho tình huống có thể xảy ra (\"để dù có ~ thì cũng không sao / để phòng khi...\"). 「いつ雨が降ってもいいように」 = để lỡ lúc nào trời có mưa cũng vẫn xoay xở được.","translation_vi":"Để phòng khi trời có thể mưa bất cứ lúc nào, tôi luôn mang theo ô gấp bên mình."},{"mondai":7,"q":10,"prompt":"（育児の本で） ３歳ぐらいになると、「なぜ？」「どうして？」という質問が多くなりますが、（　　）きちんと答えてあげましょう。","options":["めんどうくさくなくて","めんどうくさくなるのが","めんどうくさがらずに","めんどうくさがっていては"],"answer":3,"word_explain":"Tính từ 「めんどうくさい」 + 「がる」 thành động từ 「めんどうくさがる」 (tỏ ra phiền phức, ngại làm), kết hợp với 「～ずに」 (không làm V) thành 「めんどうくさがらずに」 = đừng tỏ ra phiền hà mà hãy trả lời tử tế.","translation_vi":"(Trong sách nuôi dạy con) Khi trẻ lên khoảng 3 tuổi, các câu hỏi \"Tại sao?\", \"Vì sao?\" sẽ nhiều lên, nhưng bạn đừng ngại phiền mà hãy trả lời con một cách đàng hoàng nhé."},{"mondai":7,"q":11,"prompt":"Ａ「ねえ、夏休みの宿題、進んでる？」 Ｂ「私はもう全部終わったよ。どうせ（　　）、早めにやっちゃおうと思って、夏休みに入ってすぐ始めたんだ。」","options":["やろうとしないわりには","やらなきゃいけないんなら","やろうとしないばかりか","やらなきゃいけないといっても"],"answer":2,"word_explain":"「どうせ～なら」 mang nghĩa \"đằng nào cũng ~ thì...\". 「やらなきゃいけないんなら」 là dạng rút gọn khẩu ngữ của 「やらなければいけないのなら」 (\"nếu đằng nào cũng phải làm thì...\").","translation_vi":"A: \"Này, bài tập nghỉ hè làm đến đâu rồi?\" B: \"Tớ làm xong hết cả rồi. Nghĩ rằng đằng nào cũng phải làm thì làm sớm cho xong, nên vừa vào kỳ nghỉ hè là tớ bắt tay vào làm ngay.\""},{"mondai":7,"q":12,"prompt":"現在、Ａ港周辺では再開発が進んでおり、道路や公園などの公共施設が整備（　　）。","options":["させられそうになる","し始めていく","させ続ける一方だ","されつつある"],"answer":4,"word_explain":"「V(ます)つつある」 diễn tả sự thay đổi hoặc quá trình đang diễn ra dần dần (\"đang dần được...\"). 「整備されつつある」 = đang dần được hoàn thiện/xây dựng.","translation_vi":"Hiện nay, việc tái quy hoạch xung quanh cảng A đang được xúc tiến, các công trình công cộng như đường sá và công viên cũng đang dần được hoàn thiện."},{"mondai":8,"q":13,"prompt":"X社から新しく発売される腕時計は、これまでのどの時計にも　＿＿＿　＿＿＿　★　＿＿＿　そうで、非常に楽しみだ。","options":["なっている","デザインに","なかった","全く新しい"],"answer":2,"word_explain":"Thứ tự đúng: 3 → 4 → ★2 → 1. 「これまでのどの時計にもなかった」 bổ nghĩa cho 「全く新しいデザイン」, kết hợp với 「～になっているそうだ」 (nghe nói là có thiết kế...).","translation_vi":"Nghe nói chiếc đồng hồ đeo tay sắp được công ty X ra mắt có thiết kế hoàn toàn mới chưa từng có ở bất kỳ chiếc đồng hồ nào trước đây, nên tôi rất mong chờ."},{"mondai":8,"q":14,"prompt":"姉の　＿＿＿　★　＿＿＿　＿＿＿　、私にはとてもできない。","options":["欠かさず","ように","１０年以上一日も","日記を書くなんて"],"answer":3,"word_explain":"Thứ tự đúng: 2 → ★3 → 1 → 4. 「姉のように」 (giống như chị gái) + cụm cố định 「一日も欠かさず」 (không bỏ sót một ngày nào) + 「日記を書くなんて」 (việc viết nhật ký như thế thì...).","translation_vi":"Việc viết nhật ký suốt hơn 10 năm mà không bỏ sót một ngày nào như chị gái tôi thì tôi hoàn toàn không thể làm nổi."},{"mondai":8,"q":15,"prompt":"朝、開花したときには　＿＿＿　＿＿＿　★　＿＿＿　珍しい花があります。","options":["花が","真っ白だった","次第にピンクへと変化していく","夕方が近づくにつれて"],"answer":4,"word_explain":"Thứ tự đúng: 2 → 1 → ★4 → 3. 「朝、開花したときには真っ白だった花」 (bông hoa vốn trắng tinh khi nở vào buổi sáng) + 「夕方が近づくにつれて」 (càng về gần chiều tối) + 「次第にピンクへと変化していく」 bổ nghĩa cho 「珍しい花」.","translation_vi":"Có một loài hoa hiếm mà khi nở vào buổi sáng thì trắng tinh, rồi càng về gần chiều tối lại dần dần chuyển sang màu hồng."},{"mondai":8,"q":16,"prompt":"部下の作った書類にミスがあるとき、部下にもう一度　＿＿＿　＿＿＿　★　＿＿＿　多い。","options":["書き直させるより","つい自分で直してしまうことも","早いと思って","自分でやってしまったほうが"],"answer":3,"word_explain":"Thứ tự đúng: 1 → 4 → ★3 → 2. Mẫu so sánh 「～より～ほうが早い」 (tự mình làm còn nhanh hơn là bắt nhân viên viết lại) + 「～と思って」 + 「つい自分で直してしまうことも多い」 (cũng thường hay lỡ tự sửa luôn).","translation_vi":"Khi tài liệu do cấp dưới làm có sai sót, nhiều người nghĩ rằng tự mình làm còn nhanh hơn là bắt cấp dưới viết lại lần nữa nên thường hay tiện tay tự sửa luôn."},{"mondai":8,"q":17,"prompt":"友人に　＿＿＿　＿＿＿　★　＿＿＿　が、やってみたら意外に面白くて、自分に向いていると感じた。","options":["塾講師の仕事だった","どうしても","引き受けた","と頼まれて"],"answer":3,"word_explain":"Thứ tự đúng: 2 → 4 → ★3 → 1. 「友人に『どうしても』と頼まれて」 (được bạn năn nỉ hết mực) + 「引き受けた塾講師の仕事だった」 (là công việc gia sư tại trung tâm luyện thi mà tôi đã nhận lời).","translation_vi":"Đó là công việc giáo viên trung tâm luyện thi mà tôi đã nhận lời vì được bạn nhờ vả khẩn thiết, nhưng khi làm thử thì lại thấy thú vị bất ngờ và cảm thấy rất hợp với bản thân."},{"mondai":9,"q":18,"prompt":"Chỗ trống [50] trong đoạn văn trên","options":["ここまで","そういう大人","どのような人","それ以下"],"answer":3,"word_explain":"Câu kết thúc bằng nghi vấn 「～のだろうか」 và nối tiếp bằng 「気になって調べてみた」 (tò mò nên đã tìm hiểu thử), nên cần cụm nghi vấn 「どのような人」 (\"kiểu người như thế nào\").","translation_vi":"Vậy thì, từ \"người lớn\" được dùng trong những cách diễn đạt như thế này là đang chỉ kiểu người như thế nào nhỉ?"},{"mondai":9,"q":19,"prompt":"Chỗ trống [51] trong đoạn văn trên","options":["するものだ","するつもりだ","するほうだ","するべきだ"],"answer":1,"word_explain":"「これは、～たり、～たりするものだ」 dùng 「ものだ」 để giải thích bản chất, đặc trưng của loại hình du lịch này (\"đây là loại hình mà người ta sẽ...\"). Các lựa chọn khác (つもりだ, ほうだ, べきだ) không hợp với ngữ cảnh mô tả sản phẩm.","translation_vi":"Đây là kiểu du lịch mà người ta nghỉ ở những lữ quán cao cấp và dành nhiều thời gian thong thả đi đây đó."},{"mondai":9,"q":20,"prompt":"Chỗ trống [52] trong đoạn văn trên","options":["問題ないかどうかだ","問題ないということだ","問題ないとするだろうか","問題ないのだと思っていた"],"answer":2,"word_explain":"「だから、～ということだ」 dùng để rút ra kết luận, giải thích ý nghĩa từ câu trước (\"vì vậy, điều đó có nghĩa là dù giá có cao hơn chút ít do dùng nguyên liệu tốt thì cũng không sao\").","translation_vi":"Vì thế, điều đó có nghĩa là dù giá thành có cao hơn một chút do sử dụng nguyên liệu tốt thì cũng không thành vấn đề."},{"mondai":9,"q":21,"prompt":"Chỗ trống [53] trong đoạn văn trên","options":["しかも","ただし","要するに","それどころか"],"answer":3,"word_explain":"「要するに」 (\"tóm lại là / nói ngắn gọn là\") dùng để tổng kết lại cả 3 ví dụ ở các đoạn trước (du lịch cao cấp, mì Ý chú trọng nguyên liệu, lớp học piano cho người muốn tìm sở thích).","translation_vi":"Tóm lại, những người có sự dư dả về kinh tế, thời gian và tinh thần chính là \"người lớn\" chăng."},{"mondai":9,"q":22,"prompt":"Chỗ trống [54] trong đoạn văn trên","options":["なれるはずだった","なりたくなってきた","なるわけではない","なれるのかもしれない"],"answer":4,"word_explain":"「～ようになったら、～なれるのかもしれない」 diễn tả suy đoán về tương lai (\"khi nào hiểu được giá trị của các sản phẩm dành cho 'người lớn', có lẽ tôi cũng sẽ trở thành 'người lớn' được chăng\").","translation_vi":"Khi nào hiểu được giá trị của những sản phẩm dành cho \"người lớn\", có lẽ tôi cũng sẽ có thể trở thành \"người lớn\" chăng."}]},{"id":"g_2014_07","displayName":"07/2014","subtitle":"22 câu • Mondai 7–9 (Ngữ pháp)","m9_passage":"以下は、ある雑誌に寄せられた質問と、質問に対する回答である。\n\n質問\n田舎にキャンプに行ったとき、夜空には無数の星があり、本当にきれいでした。毎晩あんな空が見たいと思っても、私の街では月しか見えません。都会で星は見られないのでしょうか。（東京・１４歳女子）\n\n回答\n都会で星が見えないのは、夜の街の照明が空気中のちりなどに当たって起こる「光害」という公害によるものです。「『光害』と言われても、夜は照明なしで生活できないから、都会で星を見るのはあきらめよう」とあなたは[50]。\n\nしかし、あきらめる前に少し考えてみてください。照明の登場で夜も明るくなり、人々の生活は安全で便利になりましたが、都会の夜の明るさは必要以上だと思いませんか。また、[51]を受けているのは人間だけです。昼は明るく、夜は暗いという自然のリズムがくずれ、植物や動物に大きな影響を与えています。\n\n夜、照明を使わなければ、光害はなくなります。[52]、東京のような大都会で夜にまったく照明を使わずに生活するのは現実的に不可能です。そこで、照明を目的に合わせて適切に使うことが、光害対策として重要になります。すでに現在、環境省が定めた光害対策の方針の下、道を照らすなら上方向に光がもれないようにするなどの取り組みが[53]。\n\n私たちも不要な照明はすぐに消すなど、常に適切な量の光を使おうと意識して行動していく必要があります。時間はかかるかもしれませんが、あなたの街でもキャンプの夜に見たような星が見られるように[54]。","questions":[{"mondai":7,"q":1,"prompt":"料理の本に書いてある（　　）作ってみたのだが、なぜかうまくいかなかった。","options":["ようで","もとで","ほどに","とおりに"],"answer":4,"word_explain":"Cấu trúc 「V辞書形／Vた形 ＋ とおりに」 mang nghĩa \"theo đúng như ~\". Ở đây là làm theo đúng như sách hướng dẫn nấu ăn viết. 「もとで」 là \"dưới sự (chỉ dẫn/ảnh hưởng của ai đó)\".","translation_vi":"Tôi đã thử làm theo đúng như những gì viết trong sách dạy nấu ăn, nhưng không hiểu sao lại không thành công."},{"mondai":7,"q":2,"prompt":"村田「青木くんって、本当に面白い人だよね。」 西野「うん。彼、人を笑わせることに（　　）天才だからね。」","options":["向けては","かけては","沿っては","わたっては"],"answer":2,"word_explain":"Cấu trúc 「N にかけては」 dùng để nhấn mạnh rằng xét riêng về mặt/lĩnh vực nào đó thì vượt trội, không ai sánh bằng (thường đi với đánh giá tích cực như 天才).","translation_vi":"Murata: \"Aoki đúng là người thú vị thật đấy.\" Nishino: \"Ừ. Về khoản làm cho người khác cười thì cậu ấy đúng là thiên tài mà.\""},{"mondai":7,"q":3,"prompt":"山田「私、青木先輩のようにカメラマンの仕事をしたいと思っているんです。ぜひ青木先輩のお話を（　　）いただけないでしょうか。」 青木「ああ、かまわないよ。」","options":["聞いて","聞けて","聞かせて","聞かれて"],"answer":3,"word_explain":"Cấu trúc 「V（さ）せていただけないでしょうか」 là cách nói lịch sự khi xin phép đối phương cho mình làm gì. 「お話を聞かせていただけないでしょうか」 nghĩa là \"Anh/chị có thể kể cho em nghe (cho phép em được nghe) câu chuyện của anh/chị được không ạ?\".","translation_vi":"Yamada: \"Em rất muốn làm công việc nhiếp ảnh gia giống như tiền bối Aoki. Anh có thể cho em nghe câu chuyện của anh được không ạ?\" Aoki: \"À, được thôi.\""},{"mondai":7,"q":4,"prompt":"今回の京都旅行は、天気が悪い日が多かったが、行きたかったお寺には行けたし、（　　）楽しめた。","options":["そのうえ","それなりに","そのころに","それどころか"],"answer":2,"word_explain":"「それなりに」 mang nghĩa \"tương ứng với hoàn cảnh đó / theo cách riêng của nó / tuy chưa hoàn hảo nhưng cũng khá ổn\". Phù hợp với vế trước có thời tiết xấu nhưng vẫn đi được chùa mình thích.","translation_vi":"Chuyến du lịch Kyoto lần này có nhiều ngày thời tiết xấu, nhưng tôi đã đi được đến ngôi chùa mình muốn đi, và cũng tận hưởng được theo cách riêng (khá vui)."},{"mondai":7,"q":5,"prompt":"バス停に着いたとき、出発時刻の１時間前に空港に着くバスがちょうど来たので（　　）が、満員で乗れず、結局、飛行機に間に合わなかった。","options":["乗っている途中だった","乗ったところだ","乗っているつもりだった","乗ろうとした"],"answer":4,"word_explain":"Cấu trúc 「V(よう)としたが、〜」 diễn tả ý định làm gì hoặc bắt đầu làm gì nhưng kết quả không thực hiện được. Ở đây định lên xe buýt (乗ろうとした) nhưng vì đầy người nên không lên được.","translation_vi":"Khi tôi đến trạm xe buýt thì đúng lúc có chuyến xe buýt đến sân bay trước giờ khởi hành 1 tiếng tới nên tôi định lên xe, nhưng vì chật kín khách không lên được, kết cục là đã bị lỡ máy bay."},{"mondai":7,"q":6,"prompt":"友達の中には、仕事が休みの日はすることがなくて、暇（　　）と言う人もいる。","options":["でしょうがない","そうにない","にすぎない","すらない"],"answer":1,"word_explain":"Cấu trúc 「Aい／Aな ＋ て・で ＋ しょうがない」 (ở đây 「暇でしょうがない」) diễn tả trạng thái/cảm xúc ở mức độ quá lớn, \"vô cùng ~ / ~ không chịu nổi\".","translation_vi":"Trong số bạn bè tôi, cũng có người nói rằng ngày nghỉ làm chẳng có việc gì để làm nên rảnh rỗi đến phát chán."},{"mondai":7,"q":7,"prompt":"森田「村山さん、Ｙ社の川西部長が（　　）。会議室でお待ちです。」 村山「わかりました。」","options":["参りました","承りました","見えました","伺いました"],"answer":3,"word_explain":"「見える」（見えました） là tôn kính ngữ (尊敬語) của 「来る」 (đến), dùng để nói về khách hàng hoặc cấp trên (Trưởng phòng Kawanishi của công ty Y). Các lựa chọn khác (参る, 承る, 伺う) đều là khiêm nhường ngữ.","translation_vi":"Morita: \"Anh Murayama, trưởng phòng Kawanishi bên công ty Y đã đến rồi ạ. Ông ấy đang đợi ở phòng họp.\" Murayama: \"Tôi hiểu rồi.\""},{"mondai":7,"q":8,"prompt":"医者「明日になっても熱が下がらない（　　）、この薬を飲んでください。」","options":["ようであれば","からであれば","というようには","というからには"],"answer":1,"word_explain":"Cấu trúc 「〜ようであれば」 (biến thể trang trọng hơn của 〜ようなら) mang nghĩa \"nếu tình hình có vẻ như ~ / nếu có dấu hiệu ~ thì...\".","translation_vi":"Bác sĩ: \"Nếu đến ngày mai mà tình hình vẫn có vẻ không hạ sốt thì hãy uống thuốc này nhé.\""},{"mondai":7,"q":9,"prompt":"(歌の練習で) 先生「最初は、緊張して大きな声で歌えないと思います。でも、（　　）だんだん大きな声で歌えるようになりますよ。」","options":["練習していくうちに","練習してでも","練習するのに対して","練習するのに比べて"],"answer":1,"word_explain":"Cấu trúc 「〜うちに」 diễn tả sự thay đổi diễn ra dần dần trong khi một quá trình đang tiếp diễn (thường đi với 「だんだん」「〜ようになる」). 「練習していくうちに」 = trong quá trình tiếp tục luyện tập.","translation_vi":"(Trong buổi tập hát) Thầy giáo: \"Ban đầu thầy nghĩ các em sẽ căng thẳng nên không hát to được. Nhưng trong quá trình luyện tập dần dần các em sẽ hát được bằng giọng to thôi.\""},{"mondai":7,"q":10,"prompt":"監督「みんな、今日は本当によくやった。この調子であしたの決勝戦もがんばろう。おれたちが勝って世間を（　　）じゃないか。」","options":["驚いてやろう","驚いてもらおう","驚かせてやろう","驚かせてもらおう"],"answer":3,"word_explain":"Động từ sai khiến 「驚かせる」 (\"làm cho ~ kinh ngạc\", đi với trợ từ を: 世間を驚かせる) kết hợp với 「〜てやろうじゃないか」 thể hiện quyết tâm/khí thế cùng làm cho đối tượng khác phải bất ngờ.","translation_vi":"Huấn luyện viên: \"Mọi người hôm nay làm tốt lắm. Cứ đà này ngày mai trận chung kết cũng cố gắng nhé. Chúng ta hãy thắng và làm cho cả thiên hạ phải kinh ngạc đi nào!\""},{"mondai":7,"q":11,"prompt":"会議は９時開始の予定だったが、開始時刻までに来たのは３人だけだった。遅れてきた人に理由を聞いたら、開始時刻が正しく（　　）。","options":["伝わらないはずだった","伝えなかったらしい","伝えていないはずだった","伝わっていなかったらしい"],"answer":4,"word_explain":"Chủ ngữ đi với trợ từ 「が」 là 「開始時刻が」, nên cần tự động từ 「伝わる」 ở dạng trạng thái 「伝わっていなかったらしい」 (\"có vẻ như đã không được truyền đạt tới\"). 「伝える」 là tha động từ nên không hợp với chủ ngữ 「開始時刻が」.","translation_vi":"Cuộc họp dự định bắt đầu lúc 9 giờ, nhưng đến giờ bắt đầu chỉ có 3 người có mặt. Khi hỏi lý do những người đến muộn thì có vẻ như thời gian bắt đầu đã không được truyền đạt chính xác."},{"mondai":7,"q":12,"prompt":"妹「お姉ちゃん、パソコン貸して。」 姉「いいよ。あ、あとで私も使うから、電源は（　　）。」 妹「わかった。」","options":["入れてからにして","入れたままにしておいて","入れたつもりでいて","入れなきゃならなくて"],"answer":2,"word_explain":"Cấu trúc 「Vた + ままにしておく」 mang nghĩa \"cứ để nguyên trạng thái đã làm V như vậy\". 「電源は入れたままにしておいて」 = cứ để nguyên nguồn máy tính bật sẵn như vậy nhé.","translation_vi":"Em gái: \"Chị ơi, cho em mượn máy tính với.\" Chị gái: \"Ừ được. À, lát nữa chị cũng dùng nên em cứ để nguyên nguồn bật như vậy nhé.\" Em gái: \"Vâng ạ.\""},{"mondai":8,"q":13,"prompt":"A「じゃあ、そろそろ帰るね。お茶、ごちそうさまでした。」 B「え、もう帰るの？せっかく ＿＿＿　＿＿＿　★　＿＿＿ いいのに。」","options":["もう少し","いけば","来たんだから","ゆっくりして"],"answer":4,"word_explain":"Thứ tự đúng: 3 → 1 → ★4 → 2 (来たんだから → もう少し → ★ゆっくりして → いけば). Cấu trúc 「せっかく〜んだから、〜ばいいのに」 (cất công ~ rồi mà, giá mà ~ thì tốt biết mấy) và 「ゆっくりしていく」 (ở lại thư giãn thêm rồi mới về).","translation_vi":"A: \"Vậy thôi tớ về đây nhé. Cảm ơn cậu vì tách trà ngon.\" B: \"Ủa, về rồi à? Cất công đến đây rồi mà ở lại thư giãn thêm chút nữa rồi hãy về có phải hơn không.\""},{"mondai":8,"q":14,"prompt":"レポートを作成 ＿＿＿　＿＿＿　★　＿＿＿ ことは、事実なのか意見なのかを明確にすることだ。","options":["注意","上で","する","すべき"],"answer":1,"word_explain":"Thứ tự đúng: 3 → 2 → ★1 → 4 (する → 上で → ★注意 → すべき). Cấu trúc 「V辞書形 + 上で」 (khi làm ~ / trong quá trình làm ~) và 「注意すべきこと」 (điều cần chú ý).","translation_vi":"Điều cần chú ý khi viết báo cáo là làm rõ đâu là sự thật và đâu là ý kiến cá nhân."},{"mondai":8,"q":15,"prompt":"私は、どんなに ＿＿＿　＿＿＿　★　＿＿＿ 。","options":["つらいことがあっても","いつもにこにこしている","石川さんを尊敬している","そんな様子を全く見せず"],"answer":2,"word_explain":"Thứ tự đúng: 1 → 4 → ★2 → 3 (つらいことがあっても → そんな様子を全く見せず → ★いつもにこにこしている → 石川さんを尊敬している). Mệnh đề 「どんなに〜ても」 (dù đến mức nào đi nữa) nối với 「そんな様子を全く見せず」 (không hề để lộ bộ dạng đó) và 「いつもにこにこしている」 cùng bổ nghĩa cho danh từ 「石川さん」.","translation_vi":"Tôi rất kính trọng anh/chị Ishikawa, người mà dù có chuyện vất vả đến mấy cũng hoàn toàn không để lộ vẻ như vậy và lúc nào cũng tươi cười."},{"mondai":8,"q":16,"prompt":"A「サラリーマンから農家 ＿＿＿　＿＿＿　★　＿＿＿ あるんだね。」 B「自分の夢をどうしてもあきらめきれなくてね。」","options":["勇気","とは","ずいぶん","になる"],"answer":3,"word_explain":"Thứ tự đúng: 4 → 2 → ★3 → 1 (になる → とは → ★ずいぶん → 勇気). Cấu trúc 「〜とは」 thể hiện sự ngạc nhiên/cảm thán trước việc gì đó, theo sau là 「ずいぶん勇気(が)あるんだね」 (có rất nhiều dũng khí đấy nhỉ).","translation_vi":"A: \"Từ nhân viên văn phòng mà chuyển sang làm nông dân thì đúng là bạn có dũng khí thật đấy nhỉ.\" B: \"Vì mình không tài nào từ bỏ được ước mơ của bản thân mà.\""},{"mondai":8,"q":17,"prompt":"A「昨日、また仕事で失敗しちゃったんだよね。この仕事、私には向いていないんだろうね。やっぱり転職しようかな。」 B「私は反対しないよ。本当に向いていないと ＿＿＿　＿＿＿　★　＿＿＿ 思うからね。」","options":["こともないと","思う","んだったら","続ける"],"answer":4,"word_explain":"Thứ tự đúng: 2 → 3 → ★4 → 1 (思う → んだったら → ★続ける → こともないと). Cấu trúc 「V普通形 + んだったら」 (nếu mà ~) và 「V辞書形 + こともない」 (không cần thiết phải làm ~).","translation_vi":"A: \"Hôm qua tớ lại làm hỏng việc nữa rồi. Công việc này chắc không hợp với tớ đâu nhỉ. Hay là chuyển việc nhỉ.\" B: \"Tớ không phản đối đâu. Vì tớ nghĩ nếu cậu thực sự thấy không hợp thì cũng không nhất thiết phải tiếp tục đâu mà.\""},{"mondai":9,"q":18,"prompt":"Chỗ trống [50] trong đoạn văn trên","options":["思うかもしれません","思ってはいけません","思わねばなりません","思わなくてもいいです"],"answer":1,"word_explain":"Câu ngay sau bắt đầu bằng 「しかし、あきらめる前に少し考えてみてください」 (\"Tuy nhiên, trước khi từ bỏ hãy thử suy nghĩ một chút\"). Điều này cho thấy tác giả đang dự đoán suy nghĩ có thể có của người hỏi, nên dùng 「〜と思うかもしれません」 (\"có lẽ bạn sẽ nghĩ rằng...\").","translation_vi":"Có lẽ bạn sẽ nghĩ rằng: \"Dù nói là 'ô nhiễm ánh sáng', nhưng ban đêm không thể sống thiếu đèn được nên đành từ bỏ việc ngắm sao ở thành phố thôi.\""},{"mondai":9,"q":19,"prompt":"Chỗ trống [51] trong đoạn văn trên","options":["どちらも影響","そのような害","こちらの照明","その恩恵"],"answer":4,"word_explain":"Câu trước nêu lợi ích của đèn điện (cuộc sống an toàn và tiện lợi hơn), câu sau nêu tác hại đối với động thực vật (nhịp sinh học tự nhiên bị phá vỡ). Do đó chỗ trống [51] là 「その恩恵」 (\"lợi ích/ân huệ đó\" — cụm 「恩恵を受ける」), tạo sự đối lập: chỉ có con người được hưởng lợi ích, còn động thực vật thì chịu ảnh hưởng xấu.","translation_vi":"Hơn nữa, chỉ có con người là đang được hưởng lợi ích đó."},{"mondai":9,"q":20,"prompt":"Chỗ trống [52] trong đoạn văn trên","options":["つまり","とはいえ","ところで","しかも"],"answer":2,"word_explain":"Câu trước nói \"Nếu ban đêm không dùng đèn thì ô nhiễm ánh sáng sẽ biến mất\", còn câu sau nêu thực tế ngược lại \"sống ở Tokyo mà không dùng đèn vào ban đêm là bất khả thi\". Liên từ 「とはいえ」 (\"tuy nói là vậy nhưng / mặc dù vậy\") phù hợp nhất để nối hai vế đối lập này.","translation_vi":"Tuy nói vậy, việc sống ở một đô thị lớn như Tokyo mà hoàn toàn không dùng đèn vào ban đêm là điều bất khả thi trên thực tế."},{"mondai":9,"q":21,"prompt":"Chỗ trống [53] trong đoạn văn trên","options":["行われるためです","行われています","行われるという点です","行われているとします"],"answer":2,"word_explain":"Trạng ngữ chỉ thời gian 「すでに現在」 (\"đã và đang hiện nay\") kết hợp với chủ ngữ 「〜などの取り組みが」 cần vị ngữ bị động chỉ hành động đang diễn ra ở hiện tại là 「行われています」 (\"đang được tiến hành/thực hiện\").","translation_vi":"Hiện nay, dưới phương châm đối sách chống ô nhiễm ánh sáng do Bộ Môi trường đề ra, những nỗ lực như không để ánh sáng lọt lên phía trên khi chiếu sáng đường phố đang được thực hiện."},{"mondai":9,"q":22,"prompt":"Chỗ trống [54] trong đoạn văn trên","options":["なると言えるでしょうか","なっているとよかったのです","なるといいですね","なってほしかったのでしょう"],"answer":3,"word_explain":"Đây là lời kết ấm áp dành cho cô bé 14 tuổi đã gửi câu hỏi đến tạp chí. Cấu trúc 「〜ようになるといいですね」 diễn tả lời chúc, hy vọng nhẹ nhàng (\"mong rằng sẽ trở nên có thể ~ nhé\").","translation_vi":"Có thể sẽ mất thời gian, nhưng mong rằng ở thành phố của bạn cũng sẽ có thể ngắm được những vì sao giống như bạn đã thấy vào đêm đi cắm trại nhé."}]},{"id":"g_2013_12","displayName":"12/2013","subtitle":"22 câu • Mondai 7–9 (Ngữ pháp)","m9_passage":"ポケットティッシュ\n\n　今日も新宿駅前でティッシュをもらった。小さな袋の中に１０枚ほどのティッシュが入っていて、ポケットなどに入れて持ち歩けるポケットティッシュだ。\n\n　新宿や渋谷などの大きな駅を出して少し歩くと、ポケットティッシュを配っている人にあちこちで[50]。彼らが配るのは、ティッシュでもあり広告でもある。受け取るティッシュの袋には、旅行会社の名前が印刷されていたり、美容院や居酒屋の広告の紙が入っていたりする。最初は無料で配っているとは知らなかったので、渡されたときは驚いた。\n\n　ティッシュペーパーが日本で使われるようになったのは、１９５０年代。その十数年後、[51]が広告宣伝用に配るためのポケットティッシュを開発した。そして、１９７０年ごろにそれを道で配り始めた会社があり、それ以来、ポケットティッシュを道で配ることが定着していったらしい。\n\n　確かに、ポケットティッシュは優れた宣伝グッズだ。まず、道で直接配るから、歩いている人の性別・年齢を見て、渡すことができる。個人情報を集めなくても、宣伝したい相手に宣伝できる効果的な[52]。また、ティッシュなら実用的で、ちらしだけよりも受け取ってもらいやすいし、使うたびに広告を見てもらえるという利点もある。\n\n　[53]、私はポケットティッシュの広告を見て行動を起こしたことはない。もらう広告には全く興味がないが、無料だからついもらってしまい、たまっていく一方だ。だから、帰国したら友達に配りたい。日本文化の一つとして[54]。","questions":[{"mondai":7,"q":1,"prompt":"この料理はとても簡単で、鶏肉と卵（　　）あればすぐに作れます。","options":["にも","こそ","とも","さえ"],"answer":4,"word_explain":"Cấu trúc「N + さえ + ば」(chỉ cần N thì...), nhấn mạnh điều kiện tối thiểu cần thiết để sự việc xảy ra.","translation_vi":"Món ăn này rất đơn giản, chỉ cần có thịt gà và trứng là có thể làm được ngay."},{"mondai":7,"q":2,"prompt":"このメーカーのヘルメットは安全性（　　）、他のどのメーカーの製品よりも優れている。","options":["に沿って","に向けて","にわたって","において"],"answer":4,"word_explain":"「～において」(về mặt..., trong lĩnh vực...), dùng để chỉ phạm vi hoặc phương diện đang được đánh giá/so sánh.","translation_vi":"Mũ bảo hiểm của hãng này vượt trội hơn sản phẩm của bất kỳ hãng nào khác về mặt độ an toàn."},{"mondai":7,"q":3,"prompt":"山田「今度の連休、木村さんは温泉にいくみたいだよ。森さんはどこかいかないの？」 森「（　　）ものなら行きたいけど、今度の連休は仕事が入っちゃったんだよね。」","options":["行き","行こう","行ける","行きたい"],"answer":3,"word_explain":"Cấu trúc「V(khả năng) + ものなら」(nếu có thể làm V thì...), diễn tả mong muốn làm điều gì đó nhưng thực tế khó hoặc không thể thực hiện được.","translation_vi":"Yamada: \"Kỳ nghỉ liên tiếp sắp tới hình như Kimura đi suối nước nóng đấy. Mori có đi đâu không?\" Mori: \"Nếu đi được thì tôi cũng muốn đi lắm, nhưng kỳ nghỉ lần này lại vướng công việc mất rồi.\""},{"mondai":7,"q":4,"prompt":"（セミナーの案内で） 受講料は、無料です。（　　）、資料代５００円をいただきます。","options":["ただし","および","すなわち","あるいは"],"answer":1,"word_explain":"「ただし」(tuy nhiên / ngoại trừ việc...), dùng để bổ sung điều kiện kèm theo hoặc ngoại lệ cho thông tin đã nêu trước đó.","translation_vi":"(Trong thông báo hội thảo) Học phí là miễn phí. Tuy nhiên, chúng tôi xin thu 500 yên tiền tài liệu."},{"mondai":7,"q":5,"prompt":"今年の映画祭の来場者は、開幕から３日で１０万人に達した。八日間の開催期間で最終的には昨年の２０万人を大幅に上回る（　　）。","options":["までだ","次第だ","勢いだ","最中だ"],"answer":3,"word_explain":"「Vる + 勢いだ」(có đà/có xu thế...), diễn tả tình hình đang phát triển mạnh mẽ hướng tới một kết quả nào đó.","translation_vi":"Lượng khách đến liên hoan phim năm nay đã đạt 100.000 người chỉ sau 3 ngày khai mạc. Với thời gian tổ chức 8 ngày, cuối cùng với đà này sẽ vượt xa con số 200.000 người của năm ngoái."},{"mondai":7,"q":6,"prompt":"大西病院では、現在事務職員を募集しています。詳細は、ホームページを（　　）か、直接お電話でお問い合わせください。","options":["拝見する","ご覧いただく","ご覧に入れる","見せてくださる"],"answer":2,"word_explain":"「ご覧いただく」là cách nói lịch sự khi phía người viết nhờ/mời đối phương (người đọc) xem trang web của mình (nhận được hành động「ご覧になる」từ phía khách/ứng viên).「拝見する」và「ご覧に入れる」là khiêm nhường ngữ của người nói, không phù hợp ở đây.","translation_vi":"Bệnh viện Onishi hiện đang tuyển dụng nhân viên văn phòng. Để biết thêm chi tiết, xin vui lòng xem trang chủ hoặc liên hệ trực tiếp qua điện thoại."},{"mondai":7,"q":7,"prompt":"北川市は、かつては人口５千人の小さな村（　　）が、今では人口５０万人の大都市だ。","options":["でもなかった","よりほかなかった","にすぎなかった","ばかりではなかった"],"answer":3,"word_explain":"「～にすぎない」(chỉ là..., không hơn không kém), dùng để đánh giá quy mô hoặc mức độ nhỏ bé so với hiện tại.","translation_vi":"Thành phố Kitagawa trước đây chỉ là một ngôi làng nhỏ với dân số 5.000 người, nhưng ngày nay đã trở thành một thành phố lớn với 500.000 dân."},{"mondai":7,"q":8,"prompt":"（店で） A「このシャツ、かわいい。でも、会社に着ていくには派手かな。」 B「うん。デートで着る（　　）、仕事には派手すぎるよ。」","options":["にしては","としたら","ならともかく","からとはいえ"],"answer":3,"word_explain":"「～ならともかく」(nếu là... thì còn tạm bỏ qua/không nói làm gì, đằng này...), dùng để đối chiếu một trường hợp chấp nhận được với trường hợp đang bàn đến.","translation_vi":"(Tại cửa hàng) A: \"Chiếc áo sơ mi này dễ thương nhỉ. Nhưng mặc đi làm ở công ty thì có lòe loẹt quá không?\" B: \"Ừm. Nếu mặc đi hẹn hò thì còn được, chứ mặc đi làm thì lòe loẹt quá đấy.\""},{"mondai":7,"q":9,"prompt":"悩んでいる時は、誰かに話を（　　）気持ちが楽になる場合もある。","options":["聞いてあげることは","聞いてもらうことで","聞いてくれることに","聞いてやることが"],"answer":2,"word_explain":"「誰かに話を聞いてもらう」(nhờ/được ai đó lắng nghe câu chuyện của mình) kết hợp với「ことで」(bằng việc..., nhờ việc...).","translation_vi":"Khi đang phiền muộn, cũng có trường hợp nhờ ai đó lắng nghe tâm sự mà tâm trạng trở nên nhẹ nhõm hơn."},{"mondai":7,"q":10,"prompt":"（駅で） A「まだ切符買ってないの？もう電車来ちゃうよ。はやくはやく」 B「まだ５分もあるでしょう。そんなに（　　）。」","options":["急がせないでよ","急がせられないのかな","急がなくちゃね","急がされるんだから"],"answer":1,"word_explain":"Thể sai khiến phủ định「急がせないでよ」(đừng bắt tôi phải vội/đừng giục tôi như vậy chứ), từ động từ「急ぐ」→「急がせる」(làm cho ai vội, thúc giục).","translation_vi":"(Ở nhà ga) A: \"Vẫn chưa mua vé à? Tàu sắp đến rồi đấy. Nhanh lên nhanh lên.\" B: \"Vẫn còn tận 5 phút nữa cơ mà. Đừng có giục vội như thế chứ.\""},{"mondai":7,"q":11,"prompt":"（電話で） A「営業部の山下さんをお願いしたいのですが。」 B「申し訳ありません、山下はただいま会議で席を外しております。戻りましたらこちらからお電話（　　）。」 A「はい、お願いします。」","options":["いたしましょうか","申しましょうか","くださいませんか","いただきませんか"],"answer":1,"word_explain":"Mẫu khiêm nhường ngữ đề nghị giúp đỡ「お/ご + N + いたしましょうか」(chúng tôi xin phép làm... cho quý khách nhé?).「お電話いたしましょうか」là khiêm nhường ngữ của「電話しましょうか」.","translation_vi":"(Qua điện thoại) A: \"Xin cho tôi gặp anh Yamashita ở phòng kinh doanh ạ.\" B: \"Thành thật xin lỗi, anh Yamashita hiện đang họp nên không có mặt tại chỗ. Khi anh ấy quay lại, chúng tôi gọi lại cho quý khách từ bên này nhé?\" A: \"Vâng, nhờ anh/chị ạ.\""},{"mondai":7,"q":12,"prompt":"「自分がされてうれしいことは相手もうれしい」とつい（　　）だが、相手が嫌がる場合もあるので、気をつけようと思う。","options":["思っているところ","思ってしまいがち","思いたがるおそれ","思うしかないため"],"answer":2,"word_explain":"Cấu trúc「つい + Vてしまいがちだ」(thường hay lỡ làm gì đó theo thói quen hoặc vô thức).","translation_vi":"Người ta thường hay lỡ nghĩ rằng \"điều mình thấy vui khi được làm cho thì đối phương cũng vui\", nhưng cũng có trường hợp đối phương không thích nên tôi nghĩ cần phải chú ý."},{"mondai":8,"q":13,"prompt":"A「夏休み、あしたで終わりだね」 B「そうだね。でもまだ　＿＿＿　＿＿＿　★　＿＿＿　休みたいよね。」","options":["ぐらい","１週間","あと","は"],"answer":1,"word_explain":"Thứ tự đúng: 3 → 2 → ★1 → 4. Câu hoàn chỉnh:「でもまだ あと １週間 ぐらい は 休みたいよね。」(あと + khoảng thời gian + ぐらい + は: nhấn mạnh mức độ tối thiểu muốn thêm khoảng 1 tuần nữa).","translation_vi":"A: \"Kỳ nghỉ hè ngày mai là kết thúc rồi nhỉ.\" B: \"Ừ nhỉ. Nhưng vẫn muốn nghỉ thêm khoảng 1 tuần nữa cơ.\""},{"mondai":8,"q":14,"prompt":"（北川先生へのメールで） 昨日無事に帰国しました。 日本滞在中は　＿＿＿　＿＿＿　★　＿＿＿　お世話になり、本当にありがとうございました。","options":["をはじめ","北川先生","に","多くの方々"],"answer":4,"word_explain":"Thứ tự đúng: 2 → 1 → ★4 → 3. Câu hoàn chỉnh:「日本滞在中は 北川先生 をはじめ 多くの方々 に お世話になり、本当にありがとうございました。」(N1 をはじめ N2 に: trước hết là N1, cùng với nhiều N2).","translation_vi":"(Trong email gửi thầy Kitagawa) Hôm qua em đã về nước an toàn. Trong thời gian ở Nhật, em đã nhận được sự giúp đỡ của nhiều người, trước hết là thầy Kitagawa, em xin chân thành cảm ơn."},{"mondai":8,"q":15,"prompt":"私の祖父は、風をひいても、「風のときはあたたかく　＿＿＿　＿＿＿　★　＿＿＿　。」と言って病院に行かない。","options":["に限る","早く","寝る","して"],"answer":3,"word_explain":"Thứ tự đúng: 4 → 2 → ★3 → 1. Câu hoàn chỉnh:「あたたかく して 早く 寝る に限る。」(あたたかくして: giữ ấm; Vる + に限る: làm V là tốt nhất/nhất định phải làm V).","translation_vi":"Ông tôi dù có bị cảm cũng nói rằng \"Khi bị cảm thì giữ ấm rồi đi ngủ sớm là tốt nhất.\" chứ không chịu đi bệnh viện."},{"mondai":8,"q":16,"prompt":"留学中、自分の国のことを聞かれて初めて、今まで　＿＿＿　＿＿＿　★　＿＿＿　ことが多いのに気づいた。","options":["思って","疑問にすら","思っていなかった","当たり前だと"],"answer":2,"word_explain":"Thứ tự đúng: 4 → 1 → ★2 → 3. Câu hoàn chỉnh:「今まで 当たり前だと 思って 疑問にすら 思っていなかった ことが多いのに気づいた。」(Nにすら～ない: thậm chí đến N cũng không...).","translation_vi":"Trong thời gian du học, khi được hỏi về đất nước mình tôi mới lần đầu nhận ra rằng có rất nhiều điều mà trước đây tôi cứ nghĩ là hiển nhiên nên thậm chí không hề đặt câu hỏi nghi vấn."},{"mondai":8,"q":17,"prompt":"彼が描いたライオンの絵は、　＿＿＿　＿＿＿　★　＿＿＿　いる。","options":["今にも動き出して","近づいてきそうなほど","描かれて","本物そっくりに"],"answer":4,"word_explain":"Thứ tự đúng: 1 → 2 → ★4 → 3. Câu hoàn chỉnh:「彼が描いたライオンの絵は、今にも動き出して 近づいてきそうなほど 本物そっくりに 描かれて いる。」(～ほど本物そっくりに描かれている: được vẽ giống thật đến mức...).","translation_vi":"Bức tranh sư tử do anh ấy vẽ được vẽ giống hệt như thật đến mức tưởng chừng như sắp sửa cử động và tiến lại gần ngay lập tức."},{"mondai":9,"q":18,"prompt":"Chỗ trống [50] trong đoạn văn trên","options":["出会う","出合ったのか","出会うこともあった","出会うはずだった"],"answer":1,"word_explain":"Cấu trúc「Vると、～出会う」diễn tả một sự việc thường xuyên xảy ra như một lẽ tự nhiên ở hiện tại (phù hợp với thì hiện tại của câu tiếp theo). Các lựa chọn còn lại mang thì quá khứ hoặc suy đoán quá khứ không phù hợp mạch văn.","translation_vi":"Khi ra khỏi các ga lớn như Shinjuku hay Shibuya và đi bộ một chút, bạn sẽ bắt gặp ở khắp mọi nơi những người đang phát khăn giấy bỏ túi."},{"mondai":9,"q":19,"prompt":"Chỗ trống [51] trong đoạn văn trên","options":["その会社","ある会社","彼らの会社","こういう会社"],"answer":2,"word_explain":"「ある会社」(một công ty nọ) dùng để giới thiệu lần đầu tiên một đối tượng chưa được nhắc đến trước đó trong đoạn văn.「その会社」hoặc「彼らの会社」dùng khi đối tượng đã xuất hiện trước đó.","translation_vi":"Mười mấy năm sau đó, một công ty nọ đã phát triển ra loại khăn giấy bỏ túi để phát cho mục đích quảng cáo tuyên truyền."},{"mondai":9,"q":20,"prompt":"Chỗ trống [52] trong đoạn văn trên","options":["方法にするべきだ","方法だと言える","方法になりかねない","方法があるに違いない"],"answer":2,"word_explain":"「効果的な方法だと言える」(có thể nói đó là một phương pháp hiệu quả) phù hợp với câu mở đầu đoạn「確かに、ポケットティッシュは優れた宣伝グッズだ。」khi đang phân tích và khẳng định ưu điểm của việc phát khăn giấy bỏ túi.","translation_vi":"Có thể nói đây là một phương pháp hiệu quả giúp quảng bá tới đúng đối tượng muốn quảng cáo mà không cần thu thập thông tin cá nhân."},{"mondai":9,"q":21,"prompt":"Chỗ trống [53] trong đoạn văn trên","options":["むしろ","要するに","したがって","とはいえ"],"answer":4,"word_explain":"Đoạn trước khen ngợi hiệu quả quảng cáo của khăn giấy bỏ túi, còn đoạn này tác giả nói ngược lại rằng bản thân mình chưa bao giờ quan tâm hay hành động theo quảng cáo đó, nên dùng liên từ mang nghĩa nhượng bộ/tương phản「とはいえ」(tuy nói vậy nhưng / thế nhưng).","translation_vi":"Tuy nói vậy, tôi chưa từng xem quảng cáo trên khăn giấy bỏ túi rồi thực hiện hành động nào cả."},{"mondai":9,"q":22,"prompt":"Chỗ trống [54] trong đoạn văn trên","options":["紹介されたわけだ","紹介したからだ","紹介しようと思う","紹介されのだと思う"],"answer":3,"word_explain":"Nối tiếp câu「だから、帰国したら友達に配りたい。」(Vì vậy, khi về nước tôi muốn phát cho bạn bè), người viết nêu ý định cá nhân「紹介しようと思う」(Tôi định sẽ giới thiệu).","translation_vi":"Tôi định sẽ giới thiệu nó như một nét văn hóa của Nhật Bản."}]},{"id":"g_2013_07","displayName":"07/2013","subtitle":"22 câu • Mondai 7–9 (Ngữ pháp)","m9_passage":"日本における米食の変化\nヨハンソン　ダグ\n\n日本食というと米の印象が強く、私は、日本人は米を一日三食食べていると思っていた。ところが日本に来てみると、[50]ので驚いた。\n\nある調査によると、１９６０年の日本の米の消費量は一人当たり年間約１２０キロだったが、２０１０年は約６０キロだったという。この５０年で米の消費量が半減したわけだ。けれども、５０年で一日の食事の回数や総量が半減する[51]。では、どのような事情で米の消費量が半減したのか。\n\nそれにはいくつか[52]があるようだ。その中で私が取り上げたいのは、食の多様化だ。１９６５年ごろから日本では様々な食物を輸入するようになり、米以外にパンなどを主食としてよく食べるようになった。また、１９６０年から２０１０年の５０年で、肉の消費量は約５倍に、乳製品は約４倍に増えた。こうした変化の中で、相対的に米の消費量が減少したのだろう。\n\n食の多様化自体は、食卓が豊かになるのだし悪いことではない。[53]、食の多様化に伴う問題も起きているようだ。日本では昔から米や野菜がよく食べられてきたため、日本人の体はそれらの消化に適しており、肉や乳製品の消化が苦手だという。食の変化によって病気になる人も増えているそうだ。日本人が守ってきた伝統的な食文化は、日本人の健康を支えていたのだ。\n\n私の国の食文化も私たちの健康を支えてくれていたのだろうか。日本に来て、その土地に生きる人と食文化とのつながりについて[54]。","questions":[{"mondai":7,"q":1,"prompt":"Ｙ遊園地の昨年の入場者数は、１０００万人（　　）上った。","options":["に","で","が","と"],"answer":1,"word_explain":"Cấu trúc「～に上る（にのぼる）」: đạt tới, lên tới (một con số lớn về số lượng, tiền bạc...). Trợ từ đi kèm luôn là「に」.","translation_vi":"Lượng khách vào cửa năm ngoái của công viên giải trí Y đã lên tới 10 triệu người."},{"mondai":7,"q":2,"prompt":"鉄道会社と自治体による長期間の議論（　　）、新駅の建設が決定された。","options":["をめぐり","を込めて","の末に","のことで"],"answer":3,"word_explain":"「Nの末（に）」: sau quá trình dài làm gì đó (thường mang tính vất vả, suy nghĩ/thảo luận lâu) thì cuối cùng đạt được kết quả.「をめぐり」là \"xoay quanh\", không hợp kết cấu trước dấu phẩy để dẫn tới kết quả quyết định.","translation_vi":"Sau một thời gian dài thảo luận giữa công ty đường sắt và chính quyền địa phương, việc xây dựng nhà ga mới đã được quyết định."},{"mondai":7,"q":3,"prompt":"今日は午後から晴れるという予報だったが、午後になっても雨はやまず、むしろ（　　）ばかりだった。","options":["強い","強く","強かった","強くなる"],"answer":4,"word_explain":"「V（thể từ điển）＋ばかりだ」: ngày càng, chỉ toàn trở nên... (diễn tả sự biến đổi theo chiều hướng ngày càng tăng, thường theo hướng xấu).「強くなるばかりだった」= ngày càng mạnh lên.","translation_vi":"Dự báo nói hôm nay từ chiều trời sẽ nắng, nhưng sang chiều rồi mưa vẫn không tạnh, ngược lại chỉ càng lúc càng nặng hạt hơn."},{"mondai":7,"q":4,"prompt":"哲学Ⅱの授業は、哲学Ⅰの単位を取得（　　）、受けることができません。","options":["してからか","してからでないと","してからで","してからでなくて"],"answer":2,"word_explain":"「Vてからでないと（～ない）」: nếu không làm V trước thì không thể ~ (điều kiện tiên quyết).","translation_vi":"Môn Triết học II nếu chưa lấy được tín chỉ môn Triết học I trước thì không thể đăng ký học được."},{"mondai":7,"q":5,"prompt":"（広告で） 現在、数量限定半額セールを実施中。商品が（　　）終了しますので、お早めに。","options":["なくなり次第","なくなった以上","なくなるうちに","なくなっては"],"answer":1,"word_explain":"「Vます＋次第（しだい）」: ngay sau khi ~ thì lập tức... (dùng nhiều trong thông báo, quảng cáo).「なくなり次第」= ngay khi hết hàng.","translation_vi":"(Trong quảng cáo) Hiện đang thực hiện chương trình giảm giá một nửa số lượng có hạn. Chương trình sẽ kết thúc ngay khi hết hàng, xin hãy nhanh tay."},{"mondai":7,"q":6,"prompt":"（花屋のホームページで） ご予算に合わせて、花束をお作りします。送料無料で日にち指定の全国発送も（　　）。","options":["申し上げます","差し上げます","いただきます","うけたまわります"],"answer":4,"word_explain":"「うけたまわります（承ります）」là khiêm nhường ngữ của「引き受ける・聞く」, dùng khi cửa hàng/công ty tiếp nhận yêu cầu, đơn đặt hàng từ khách hàng.","translation_vi":"(Trên trang web cửa hàng hoa) Chúng tôi sẽ làm bó hoa theo ngân sách của quý khách. Chúng tôi cũng nhận giao hàng toàn quốc miễn phí vận chuyển và chọn ngày giao."},{"mondai":7,"q":7,"prompt":"夫「行ってきます。」 妻「え？会社、行くの？まだ熱があるんでしょう？」 夫「大事な会議があるから、（　　）んだ。」","options":["休んでもおかしくない","休みっこない","休むわけにはいかない","休むほかない"],"answer":3,"word_explain":"「Vる＋わけにはいかない」: không thể làm V được (vì lý do trách nhiệm, hoàn cảnh, đạo lý xã hội).「休むわけにはいかない」= không thể nghỉ làm được.","translation_vi":"Chồng: \"Anh đi đây.\" Vợ: \"Ơ? Anh đi làm à? Vẫn còn sốt mà đúng không?\" Chồng: \"Vì có cuộc họp quan trọng nên anh không thể nghỉ được.\""},{"mondai":7,"q":8,"prompt":"A「ねえ見て、このゲーム。面白そうだから、買っちゃった。」 B「あ、それって、最近雑誌（　　）よく取り上げられてるゲームでしょう？」","options":["か何かを","や何かで","か何かか","や何かは"],"answer":2,"word_explain":"「Nや何か」: N hay đại loại như thế. Kết hợp với trợ từ「で」để chỉ phương tiện/nơi xuất hiện của động từ「取り上げられる」(được đề cập/giới thiệu trên tạp chí...).","translation_vi":"A: \"Này nhìn nè, trò chơi này. Thấy có vẻ hay nên tớ mua mất rồi.\" B: \"À, đó chẳng phải là trò chơi dạo gần đây hay được giới thiệu trên tạp chí hay gì đó sao?\""},{"mondai":7,"q":9,"prompt":"砂糖、塩、酢、しょうゆ、みそ、これらは日本食を作る（　　）調味料です。","options":["のに欠かせない","ことは欠かさない","のを欠かさない","ことも欠かせない"],"answer":1,"word_explain":"「Vる＋のに欠かせない」: không thể thiếu để làm V.「日本食を作るのに欠かせない」= không thể thiếu trong việc chế biến món Nhật.","translation_vi":"Đường, muối, giấm, nước tương, tương miso — đây là những loại gia vị không thể thiếu để nấu món ăn Nhật Bản."},{"mondai":7,"q":10,"prompt":"うちの犬は、私が（　　）、寂しそうな目で私を見る。","options":["出かけるところに","出かけようとしたまま","出かけるところみたいで","出かけようとするたびに"],"answer":4,"word_explain":"「Vる＋たびに」: mỗi lần, hễ cứ ~ là lại...「出かけようとするたびに」= cứ mỗi lần tôi sắp/định ra ngoài.","translation_vi":"Con chó nhà tôi cứ mỗi lần tôi định ra ngoài là lại nhìn tôi bằng ánh mắt buồn bã."},{"mondai":7,"q":11,"prompt":"私は、ストレスは悪い（　　）思っていたので、良いストレスもあると知って驚いた。","options":["ものだとなんて","ものだとばかり","などのことだと","のみでのことだと"],"answer":2,"word_explain":"「～とばかり思っていた」: cứ nhất mực/đinh ninh nghĩ rằng ~ (nhưng thực tế lại khác).","translation_vi":"Tôi cứ đinh ninh căng thẳng là thứ xấu, nên khi biết cũng có loại căng thẳng tốt thì tôi đã rất ngạc nhiên."},{"mondai":7,"q":12,"prompt":"司会者「お二人は、子供が外で遊ばなくなったのはなぜだと思いますか。」 山田「子供が安心して遊べる場所がなくなったからだと思います。」 西川「確かに（　　）が、遊びの種類が変わったことも理由の一つだと思います。」","options":["そうします","そのつもりです","それもあるかもしれません","それではありません"],"answer":3,"word_explain":"「確かにそれもあるかもしれませんが、…」: Đúng là cũng có thể có nguyên nhân đó, nhưng... (cách nói đồng tình một phần ý kiến người trước bằng「それ」= lý do Yamada vừa nêu, rồi bổ sung ý kiến khác).","translation_vi":"Người dẫn chương trình: \"Hai vị nghĩ tại sao trẻ em không còn chơi ở ngoài nữa?\" Yamada: \"Tôi nghĩ là vì không còn nơi nào trẻ em có thể yên tâm vui chơi nữa.\" Nishikawa: \"Đúng là cũng có thể có lý do đó, nhưng việc loại hình trò chơi thay đổi cũng là một trong những nguyên nhân.\""},{"mondai":8,"q":13,"prompt":"この国でサッカー　＿＿＿　＿＿＿　★　＿＿＿　野球だ。","options":["スポーツ","に次いで","といえば","人気のある"],"answer":1,"word_explain":"Thứ tự đúng: 2 → 4 → ★1 → 3.「～に次いで」: đứng sau / chỉ sau ~;「人気のあるスポーツといえば」: nhắc đến môn thể thao được ưa chuộng thì... Câu hoàn chỉnh:「この国でサッカーに次いで人気のあるスポーツといえば野球だ。」","translation_vi":"Ở đất nước này, nhắc đến môn thể thao được yêu thích thứ hai sau bóng đá thì đó là bóng chày."},{"mondai":8,"q":14,"prompt":"田中「あれ？木村さん、だいぶ髪が伸びましたね。」 木村「ええ、半年前に　＿＿＿　＿＿＿　★　＿＿＿　ないんですよ。」","options":["きり","一度も","切って","切った"],"answer":2,"word_explain":"Thứ tự đúng: 4 → 1 → ★2 → 3.「Vた＋きり」: kể từ khi làm V thì cứ thế luôn / không làm lại nữa;「一度も切っていない」rút gọn thành「一度も切ってない」. Câu hoàn chỉnh:「半年前に切ったきり一度も切ってないんですよ。」","translation_vi":"Tanaka: \"Ơ? Anh Kimura, tóc anh dài ra nhiều rồi nhỉ.\" Kimura: \"Vâng, kể từ lần cắt cách đây nửa năm thì tôi chưa cắt lại lần nào cả.\""},{"mondai":8,"q":15,"prompt":"私たちの学校には指導熱心な先生方が多いが、中でも、経験豊富な　＿＿＿　＿＿＿　★　＿＿＿　信頼も厚い。","options":["生徒は","山田先生は","もとより","保護者からの"],"answer":3,"word_explain":"Thứ tự đúng: 2 → 1 → ★3 → 4.「AはもとよりBも」: không chỉ A (là đương nhiên) mà cả B cũng...「経験豊富な山田先生は」làm chủ ngữ, theo sau bởi「生徒はもとより保護者からの信頼も厚い」.","translation_vi":"Trường chúng tôi có nhiều thầy cô nhiệt huyết trong giảng dạy, trong đó thầy Yamada giàu kinh nghiệm thì đương nhiên nhận được sự tin tưởng của học sinh và cả từ phía phụ huynh cũng rất sâu sắc."},{"mondai":8,"q":16,"prompt":"宇宙にはこれだけ　＿＿＿　＿＿＿　★　＿＿＿　としても不思議ではないと思う。","options":["多くの星がある","生物がいた","のだから","どこかの星に"],"answer":4,"word_explain":"Thứ tự đúng: 1 → 3 → ★4 → 2.「これだけ多くの星があるのだから」: vì có nhiều sao đến thế này nên...;「どこかの星に生物がいたとしても」: cho dù có sinh vật ở ngôi sao nào đó đi nữa... Câu hoàn chỉnh:「宇宙にはこれだけ多くの星があるのだからどこかの星に生物がいたとしても不思議ではないと思う。」","translation_vi":"Trong vũ trụ có nhiều ngôi sao đến thế này, nên tôi nghĩ giả sử có sinh vật tồn tại ở một ngôi sao nào đó thì cũng chẳng có gì lạ."},{"mondai":8,"q":17,"prompt":"仕事の　＿＿＿　＿＿＿　★　＿＿＿　山田さんと林さんだが、プライベートではとても仲がいい。","options":["対立する","ことの","上では","多い"],"answer":2,"word_explain":"Thứ tự đúng: 3 → 1 → ★2 → 4.「仕事の上では」: về mặt công việc; trong mệnh đề định ngữ,「の」thay thế cho「が」:「対立することの多い山田さんと林さん」. Câu hoàn chỉnh:「仕事の上では対立することの多い山田さんと林さんだが、プライベートではとても仲がいい。」","translation_vi":"Anh Yamada và anh Hayashi tuy trên phương diện công việc thường hay đối lập nhau, nhưng trong đời tư lại rất thân thiết."},{"mondai":9,"q":18,"prompt":"Chỗ trống [50] trong đoạn văn trên","options":["これではなかった","それではなかった","そうではなかった","こうでもなかった"],"answer":3,"word_explain":"「そうではなかった」dùng「そう」để chỉ lại nội dung/trạng thái đã nêu ở câu trước (\"người Nhật ăn cơm ngày 3 bữa\"), mang nghĩa \"không phải như thế\".","translation_vi":"Thế nhưng khi đến Nhật xem thử, thực tế lại không phải như vậy nên tôi đã rất ngạc nhiên."},{"mondai":9,"q":19,"prompt":"Chỗ trống [51] trong đoạn văn trên","options":["とは思えない","としか思えない","とも思われる","とさえ思う"],"answer":1,"word_explain":"「～とは思えない」: không thể nghĩ rằng / khó mà cho rằng ~. Phù hợp với lập luận phản biện sau từ「けれども」(tuy lượng gạo giảm một nửa nhưng không thể nào tổng lượng ăn hay số bữa ăn cũng giảm một nửa được).","translation_vi":"Thế nhưng, khó có thể nghĩ rằng trong vòng 50 năm qua số bữa ăn một ngày hay tổng lượng thức ăn đã giảm đi một nửa."},{"mondai":9,"q":20,"prompt":"Chỗ trống [52] trong đoạn văn trên","options":["条件","証拠","基礎","理由"],"answer":4,"word_explain":"Câu trước đặt câu hỏi「どのような事情で米の消費量が半減したのか」(do hoàn cảnh/lý do nào mà lượng tiêu thụ gạo giảm một nửa), nên câu sau dùng「理由」(lý do) để trả lời:「それにはいくつか理由があるようだ」.","translation_vi":"Dường như có một vài lý do cho việc đó."},{"mondai":9,"q":21,"prompt":"Chỗ trống [53] trong đoạn văn trên","options":["例えば","そのうえ","だが","そこで"],"answer":3,"word_explain":"Câu trước nêu mặt tích cực (\"bản thân sự đa dạng hóa ẩm thực làm bàn ăn phong phú và không phải chuyện xấu\"), câu sau nêu mặt tiêu cực (\"nảy sinh vấn đề đi kèm\"), nên cần liên từ đối lập「だが」(tuy nhiên / nhưng).","translation_vi":"Tuy nhiên, dường như cũng đang nảy sinh những vấn đề đi kèm với sự đa dạng hóa ẩm thực."},{"mondai":9,"q":22,"prompt":"Chỗ trống [54] trong đoạn văn trên","options":["考えたのだろう","考えさせられた","考えさせていたのだろう","考えられていた"],"answer":2,"word_explain":"「考えさせられた」(thể sai khiến - bị động của「考える」): bị/được khiến cho phải suy ngẫm (một cách tự nhiên do hoàn cảnh/trải nghiệm tác động). Rất phù hợp với cảm nhận của nhân vật「私」khi sang Nhật.","translation_vi":"Đến Nhật Bản, tôi đã được thôi thúc suy nghĩ về mối liên kết giữa con người sống trên mảnh đất đó và văn hóa ẩm thực."}]},{"id":"g_2012_12","displayName":"12/2012","subtitle":"22 câu • Mondai 7–9 (Ngữ pháp)","m9_passage":"サクラが春に咲く不思議\n\n冬の寒さも緩み、春の陽気が感じられるようになってきました。春は花の季節。サクラをはじめ、ウメやモモなど多くの木々が花を咲かせます。\n\nところで、これらの花は、なぜ春に一斉に咲くのでしょう。花なんて暖かくなれば咲くものだと[50]。確かに、気温の上昇も重要です。ただ、皆さんは、春に花を咲かせる木がいつその準備をしているかご存じですか。[51]、開花する前の年の夏には、すでに花となる芽（花芽）が作られ、花を咲かせる準備ができているのです。そう考えると、春まで待って一斉に咲くというのは不思議ではありませんか。一体どういう仕組みなのでしょう。\n\nサクラやウメなどの木は夏に、成長を抑える休眠物質を葉で作ります。それが花芽にたまると、葉が落ち、花芽は「休眠」という期間に入ります。[52]花芽は成長しません。休眠から目覚めるには、一定の低温期間を経験することが必要です。「一定の低温期間」とはどれくらいかというと、それは花によって違うことがわかっています。例えば、サクラのソメイヨシノでは、５度前後の気温が約９００時間[53]。そして休眠から目覚めると、成長を抑えていた休眠物質が減り始めます。それがなくなると成長が再開し、春になって、１日の平均気温が１２～１３度になると開花するのです。\n\n春に一斉に咲く花の仕組み、[54]。冬の間、私たちは寒さが去るのを待つばかりですが、春に咲く花のためには、その寒さは必要なものなのです。","questions":[{"mondai":7,"q":1,"prompt":"電子メールが普及している今の時代であるから(　　)、手書きの手紙に温かい気持ちを感じる。","options":["こそ","さえ","すら","だけ"],"answer":1,"word_explain":"Cấu trúc「～からこそ」(chính vì... nên mới...): nhấn mạnh nguyên nhân trực tiếp dẫn đến kết quả ở vế sau.","translation_vi":"Chính vì đang ở thời đại mà email trở nên phổ biến như bây giờ, nên người ta mới cảm nhận được tình cảm ấm áp từ những bức thư viết tay."},{"mondai":7,"q":2,"prompt":"母「また寝てるの？せっかくの休みなんだから、寝て(　　)いないで、外に出かけたら？」 息子「わかったよ。」","options":["しか","でも","ぐらい","ばかり"],"answer":4,"word_explain":"Cấu trúc「～てばかりいる」(chỉ toàn làm gì đó, thường mang sắc thái phàn nàn). Ở dạng phủ định khuyên nhủ「～てばかりいないで」(đừng có suốt ngày chỉ...).","translation_vi":"Mẹ: \"Lại đang ngủ à? Đã mất công là ngày nghỉ rồi, đừng có chỉ toàn ngủ mãi thế, ra ngoài đi chơi xem nào?\" Con trai: \"Con biết rồi.\""},{"mondai":7,"q":3,"prompt":"人は通勤に多くの時間を使っている。(　　)通勤に往復２時間かけるとすると、１年間で４８０時間も通勤に使っている計算になる。","options":["たとえ","かりに","ようやく","かえって"],"answer":2,"word_explain":"Phó từ「かりに（仮に）～とすると」(giả sử nếu... thì...): dùng để đưa ra một giả định tính toán hoặc ví dụ minh họa.「たとえ」thường đi với「～ても」.","translation_vi":"Con người dành rất nhiều thời gian cho việc đi làm. Giả sử nếu mất 2 tiếng cả đi lẫn về để đi làm, thì tính ra trong 1 năm sẽ tiêu tốn tận 480 tiếng cho việc đi làm."},{"mondai":7,"q":4,"prompt":"先月電子レンジを買ったが、いくらも(　　)壊れてしまった。","options":["使っていると","使っているうちに","使わないと","使わないうちに"],"answer":4,"word_explain":"Cấu trúc「いくらも～ないうちに」(chưa... được bao nhiêu/bao lâu thì đã...): diễn tả sự việc xảy ra quá sớm, khi trạng thái hay hành động chưa diễn ra được bao nhiêu.","translation_vi":"Tháng trước tôi đã mua một chiếc lò vi sóng, nhưng mới dùng chưa được bao lâu thì đã hỏng mất rồi."},{"mondai":7,"q":5,"prompt":"彼は小説家になってから、１年に１冊のペースで長編小説を(　　)、来月出る小説で１０冊目となる。","options":["発表しつつ","発表しており","発表するにつれ","発表したところで"],"answer":2,"word_explain":"「発表しており」là dạng liên kết câu của「発表している」(tiếp diễn/tập quán lặp đi lặp lại từ quá khứ đến hiện tại), nối mượt với vế sau nêu cột mốc tiếp theo.","translation_vi":"Từ sau khi trở thành tiểu thuyết gia, anh ấy vẫn đều đặn cho ra mắt tiểu thuyết dài tập với tốc độ mỗi năm 1 cuốn, và cuốn ra mắt vào tháng tới sẽ là cuốn thứ 10."},{"mondai":7,"q":6,"prompt":"駅前に新しくできたラーメン屋はいつも込んでいる。昨日も大雨(　　)行列ができていた。","options":["にしても","にしたって","にかぎらず","にもかかわらず"],"answer":4,"word_explain":"Cấu trúc「N＋にもかかわらず」(mặc dù N nhưng vẫn...): diễn tả sự việc trái với dự đoán thông thường.","translation_vi":"Quán mì ramen mới mở trước nhà ga lúc nào cũng đông đúc. Hôm qua mặc dù trời mưa to nhưng vẫn có hàng người xếp hàng."},{"mondai":7,"q":7,"prompt":"川村「青木くんは、今日お休み？」 山田「うん。アイスの食べ過ぎでおなかが痛くなったって連絡あったよ。」 川村「青木くん(　　)ね。」","options":["らしい","みたいだ","のようだ","のことだ"],"answer":1,"word_explain":"「N＋らしい」mang nghĩa \"đúng là phong cách/tính cách đặc trưng của N\", thể hiện sự đồng tình rằng hành động đó rất hợp với con người của Aoki.","translation_vi":"Kawamura: \"Hôm nay cậu Aoki nghỉ à?\" Yamada: \"Ừ. Có tin nhắn báo là cậu ấy bị đau bụng vì ăn quá nhiều kem đấy.\" Kawamura: \"Đúng là kiểu của Aoki nhỉ.\""},{"mondai":7,"q":8,"prompt":"最近は夜遅くまで開いているスーパーが多くなってきた。スーパーに(　　)、２４時間営業のところもある。","options":["よっては","とっても","ついても","おいては"],"answer":1,"word_explain":"Cấu trúc「N＋によっては」(tùy từng N mà có trường hợp...): nêu lên một số trường hợp cá biệt trong tập hợp N.","translation_vi":"Gần đây ngày càng có nhiều siêu thị mở cửa đến tận đêm khuya. Tùy từng siêu thị mà thậm chí có nơi kinh doanh 24 giờ."},{"mondai":7,"q":9,"prompt":"先輩「受験する大学は決まった？」 後輩「いえ、僕は海外の大学に行きたいんですけど、両親は僕を自宅から通える大学に(　　)」","options":["行かせてほしいんです","行こうとしてほしいんです","行かせたがっているんです","行こうとしたがっているんです"],"answer":3,"word_explain":"Chủ ngữ là ngôi thứ 3 (「両親は」), tân ngữ là「僕を」(tôi), nên bố mẹ muốn cho tôi đi học dùng thể sai khiến +「たい」chuyển sang ngôi thứ 3「～たがっている」→「行かせたがっているんです」.","translation_vi":"Tiền bối: \"Em đã quyết định được trường đại học sẽ thi chưa?\" Hậu bối: \"Chưa ạ, em thì muốn đi học đại học ở nước ngoài, nhưng bố mẹ em lại muốn cho em vào học một trường đại học có thể đi lại từ nhà.\""},{"mondai":7,"q":10,"prompt":"最近は毎月決まった金額でかけ放題の国際電話サービスがある。私が留学していたときにもそんなサービスがあったら(　　)。","options":["どれだけよかった","どれだけよかったか","どうしてもよかった","どうしてもよかったか"],"answer":2,"word_explain":"Cấu trúc cảm thán「どれだけ～か / ～ことか」(biết bao nhiêu!): diễn tả sự nuối tiếc hay cảm xúc mạnh mẽ (nếu hồi đó có thì tốt biết mấy).","translation_vi":"Gần đây có dịch vụ gọi điện quốc tế không giới hạn với mức cước cố định hàng tháng. Giá như hồi tôi đi du học cũng có dịch vụ như thế thì tốt biết bao nhiêu."},{"mondai":7,"q":11,"prompt":"（店で） 店員「こちらの車はいかがですか。中古車ですが、(　　)新車と変わらないくらいきれいですよ。」 客「そうですね。きれいですね。」","options":["ご覧のように","ご覧いただくために","拝見したとおり","拝見したきり"],"answer":1,"word_explain":"「ご覧になる」là tôn kính ngữ của「見る」(nhìn/xem), dùng với khách hàng.「ご覧のように」nghĩa là \"như quý khách đang thấy\".「拝見する」là khiêm nhường ngữ (dùng cho hành động của bản thân người nói) nên không hợp.","translation_vi":"(Tại cửa hàng) Nhân viên: \"Quý khách thấy chiếc xe này thế nào ạ? Tuy là xe đã qua sử dụng nhưng như quý khách thấy đấy, nó đẹp chẳng khác gì xe mới đâu ạ.\" Khách: \"Đúng vậy nhỉ. Đẹp thật đấy.\""},{"mondai":7,"q":12,"prompt":"（ホームページで） Ｑ：ゲームをしていたら、急に画面が暗くなってしまいました。どうしたらいいですか。 Ａ：一度電源を切り、１分くらい経ってからまたつけてみてください。ただし、同じことが何度も(　　)故障です。修理を依頼してください。","options":["繰り返させるようならば","繰り返せるようになれば","繰り返されるようならば","繰り返させられるようになれば"],"answer":3,"word_explain":"Chủ ngữ là「同じことが」(cùng một sự việc đó), nên dùng thể bị động「繰り返される」(bị lặp lại), kết hợp với「～ようならば」(nếu có vẻ như...).","translation_vi":"(Trên trang chủ) Hỏi: Đang chơi game thì tự dưng màn hình tối sầm lại. Tôi phải làm thế nào? Đáp: Xin hãy thử tắt nguồn một lần, đợi khoảng 1 phút rồi bật lại xem sao. Tuy nhiên, nếu tình trạng tương tự có vẻ lặp đi lặp lại nhiều lần thì là hỏng hóc rồi. Xin hãy yêu cầu sửa chữa."},{"mondai":8,"q":13,"prompt":"Ａ「あ、飲み物がなくなってしまいましたね。」 Ｂ「じゃあ、私がちょっとコンビニに　＿＿＿　＿＿＿　★　＿＿＿　いてください。」 Ａ「私もいっしょに買いに行きますよ。」","options":["きますから","行って","待って","買って"],"answer":1,"word_explain":"Thứ tự đúng: 2 → 4 → ★1 → 3. Câu hoàn chỉnh:「コンビニに行って買ってきますから待っていてください。」(đi mua rồi quay lại nên hãy đợi nhé).","translation_vi":"A: \"Ồ, đồ uống hết mất rồi nhỉ.\" B: \"Vậy thì để tôi chạy ra cửa hàng tiện lợi mua về một chút nhé, bạn cứ đợi ở đây đi.\" A: \"Tôi cũng đi mua cùng bạn luôn.\""},{"mondai":8,"q":14,"prompt":"この計画をこのまま　＿＿＿　＿＿＿　★　＿＿＿　だろう。","options":["必要がある","いずれにしても","早急に結論を出す","進めるかやめるか"],"answer":3,"word_explain":"Thứ tự đúng: 4 → 2 → ★3 → 1. Câu hoàn chỉnh:「この計画をこのまま進めるかやめるかいずれにしても早急に結論を出す必要があるだろう。」(「いずれにしても」nhận lại mệnh đề lựa chọn「進めるかやめるか」ở trước).","translation_vi":"Dù là tiếp tục hay dừng kế hoạch này như hiện tại, thì dù thế nào đi nữa chắc cũng cần phải sớm đưa ra kết luận."},{"mondai":8,"q":15,"prompt":"「来週の登山の持ち物について質問があります。配られたプリントに、ビニール袋を持参　＿＿＿　＿＿＿　★　＿＿＿　足りるのでしょうか。」","options":["ありますが","だいたい何枚ぐらい","のことと","用意すれば"],"answer":2,"word_explain":"Thứ tự đúng: 3 → 1 → ★2 → 4. Câu hoàn chỉnh:「ビニール袋を持参のこととありますが、だいたい何枚ぐらい用意すれば足りるのでしょうか。」(「～のこと」là cách viết chỉ thị trên thông báo/tờ rơi;「～とありますが」nghĩa là \"có ghi như vậy nhưng...\").","translation_vi":"\"Em có câu hỏi về đồ mang theo cho buổi leo núi tuần tới ạ. Trên tờ giấy được phát có ghi là mang theo túi nilon, nhưng đại khái chuẩn bị khoảng mấy chiếc thì đủ ạ?\""},{"mondai":8,"q":16,"prompt":"何か目的があって　＿＿＿　＿＿＿　★　＿＿＿　ということがよくある。","options":["何をしに行ったのか","忘れてしまう","はずなのに","その場所に行った"],"answer":1,"word_explain":"Thứ tự đúng: 4 → 3 → ★1 → 2. Câu hoàn chỉnh:「何か目的があってその場所に行ったはずなのに何をしに行ったのか忘れてしまうということがよくある。」(「～はずなのに」diễn tả sự tương phản với điều vốn chắc chắn ở vế trước).","translation_vi":"Chuyện thường hay xảy ra là rõ ràng mình có mục đích gì đó nên mới đến nơi ấy, vậy mà lại quên mất mình đến đó để làm gì."},{"mondai":8,"q":17,"prompt":"日本の食卓に　＿＿＿　＿＿＿　★　＿＿＿　大豆だが、日本国内で作られているものはわずかで、その多くを海外からの輸入に頼っているという。","options":["欠かせない","原料となる","調味料の","みそやしょうゆといった"],"answer":3,"word_explain":"Thứ tự đúng: 1 → 4 → ★3 → 2. Câu hoàn chỉnh:「日本の食卓に欠かせないみそやしょうゆといった調味料の原料となる大豆だが、…」.「欠かせない」bổ nghĩa cho cụm「みそやしょうゆといった調味料」.","translation_vi":"Đậu nành là nguyên liệu của các loại gia vị không thể thiếu trên bàn ăn Nhật Bản như miso hay nước tương, thế nhưng lượng được sản xuất trong nước Nhật lại rất ít, và phần lớn phải dựa vào nhập khẩu từ nước ngoài."},{"mondai":9,"q":18,"prompt":"Chỗ trống [50] trong đoạn văn trên","options":["思うせいです","思うかもしれません","思うほどです","思うことにしました"],"answer":2,"word_explain":"Cấu trúc「～かもしれません」(có lẽ sẽ...): tác giả phỏng đoán suy nghĩ thông thường của người đọc trước khi giải thích cơ chế thực sự ở câu tiếp theo.","translation_vi":"Các bạn có lẽ sẽ nghĩ rằng hoa thì cứ ấm lên là nở thôi."},{"mondai":9,"q":19,"prompt":"Chỗ trống [51] trong đoạn văn trên","options":["また","こうして","実は","一方"],"answer":3,"word_explain":"「実は」(thực ra là): dùng ngay sau câu hỏi gợi mở để đưa ra sự thật bất ngờ mà người đọc có thể chưa biết.","translation_vi":"Thực ra, ngay từ mùa hè năm trước khi nở hoa, mầm hoa (chồi hoa) đã được hình thành và sẵn sàng cho việc nở hoa rồi."},{"mondai":9,"q":20,"prompt":"Chỗ trống [52] trong đoạn văn trên","options":["この期間は","あの期間では","これくらいの期間では","あれくらいの期間は"],"answer":1,"word_explain":"「この期間は」: dùng chỉ thị từ「この」để thay thế cho danh từ「『休眠』という期間」(thời kỳ gọi là \"ngủ đông\") vừa được nhắc tới ngay ở câu liền trước.","translation_vi":"Trong khoảng thời gian này, chồi hoa không phát triển."},{"mondai":9,"q":21,"prompt":"Chỗ trống [53] trong đoạn văn trên","options":["必要かどうか調査されます","必要かどうか明らかになります","必要だとされています","必要だと気づかされます"],"answer":3,"word_explain":"「必要だとされています」: mẫu「～とされている」(được cho là / được xác định là), dùng để trình bày kiến thức khoa học hoặc số liệu được công nhận chung.","translation_vi":"Ví dụ, đối với hoa anh đào Somei-Yoshino, người ta cho rằng cần nhiệt độ khoảng 5 độ trong khoảng 900 giờ."},{"mondai":9,"q":22,"prompt":"Chỗ trống [54] trong đoạn văn trên","options":["ご存じでしょうか","ご存じだったのですね","おわかりいただけるのですね","おわかりいただけましたか"],"answer":4,"word_explain":"「おわかりいただけましたか」(Quý vị đã hiểu được rồi chứ ạ?): cách nói kính trọng, lịch sự kết thúc bài viết sau khi tác giả đã giải thích xong câu hỏi nêu ra ở đoạn 2.","translation_vi":"Cơ chế hoa đồng loạt nở vào mùa xuân, các bạn đã hiểu được rồi chứ ạ?"}]},{"id":"g_2012_07","displayName":"07/2012","subtitle":"22 câu • Mondai 7–9 (Ngữ pháp)","m9_passage":"ランチメニューはなぜ安い？\n\n飲食店には、夜だけでなく昼も営業して、ランチメニューを出しているところも多い。このランチメニュー、たいていは夜に比べると手ごろな価格に設定されている。[50]、夜はパスタだけで１，２００円ぐらいする店でも昼はパスタにスープとサラダがついて９８０円といったものや、夜はコース料理が５，０００円以上する店でも昼は１，０００円前後になるといったものだ。\n\nこの昼と夜の価格差は一体、何によるものなのだろうか。安いからといって、料理人が手を抜いているとか、安い材料を使っているとか、そういったことは[51]ない。味が落ちれば悪い評判が立ち、夜の営業にも悪影響を与えてしまう。\n\nランチメニューを安くできる理由は単純明快だ。\n\n飲食店に限らず、店を経営していくためには、材料費、光熱費、店員の給料などさまざまなコストがかかるが、そのコストをおさえられれば、商品の価格を下げても利益は上げることができる。[52]、メニューをいくつかに絞るという方法で、コストをおさえているケースが多い。メニューが少なければ、準備や調理に手間がかからず、多くの料理人を働かせる必要もない。そのため、安くすることができると[53]。\n\nコストをおさえて、安いランチメニューでも飲食店は利益を上げている。また、安くておいしいランチを食べた客が店を気に入り、夜も店を訪れる可能性もある。飲食店にとって、利益が上げられ、さらに客も獲得できるランチは、「おいしい」[54]","questions":[{"mondai":7,"q":1,"prompt":"小川「ねえ、山田さん。昨日の夜、オリンピック中継見た？」 山田「ううん。昨日は残業で疲れちゃって。だから、夕飯(　　)食べないで寝ちゃったんだ。」","options":["も","が","とは","にまで"],"answer":1,"word_explain":"Trợ từ 「も」 kết hợp với thể phủ định 「～ないで」 nhấn mạnh mức độ tối thiểu: \"ngay cả (bữa tối) cũng không ăn\".","translation_vi":"Ogawa: \"Này anh Yamada, tối qua anh có xem tường thuật Olympic không?\" Yamada: \"Không. Hôm qua làm thêm giờ mệt quá, nên tôi ngủ luôn mà chẳng ăn cả bữa tối nữa.\""},{"mondai":7,"q":2,"prompt":"（広告で） 川西ピアノ教室では、初心者、経験者(　　)、どなたにでも丁寧に指導します。","options":["を通して","を問わず","にかけて","にもかかわらず"],"answer":2,"word_explain":"Cấu trúc 「Nを問わず」 mang nghĩa \"không phân biệt / bất kể N\", thường đi với các danh từ đối lập như 「初心者、経験者」.","translation_vi":"(Trong quảng cáo) Tại lớp học piano Kawanishi, bất kể là người mới bắt đầu hay người đã có kinh nghiệm, chúng tôi đều hướng dẫn tận tình cho tất cả mọi người."},{"mondai":7,"q":3,"prompt":"今日、子どもをきつくしかりすぎたので、気をつけようと思う。(　　)、本人はそれほど気にしていないかもしれないが。","options":["そのかわり","それなら","もっとも","しかも"],"answer":3,"word_explain":"Liên từ 「もっとも」 dùng để bổ sung ý ngoại lệ hoặc hạn chế cho điều vừa nói trước đó (\"tuy nhiên / nói đi cũng phải nói lại là...\"), thường đi với 「～かもしれないが」.","translation_vi":"Hôm nay tôi đã mắng con hơi quá lời nên nghĩ phải chú ý hơn. Tuy nhiên, có lẽ bản thân đứa bé cũng không để tâm đến mức đó đâu."},{"mondai":7,"q":4,"prompt":"娘「なぞなぞです。お父さんが嫌いな果物は何でしょう。」 父「ううん、なんだろう。あ、そうか、(　　)。パパイヤだ。パパが嫌な果物ってことだよね。」 娘「正解です。」","options":["わかった","わかったのに","わかってた","わかってね"],"answer":1,"word_explain":"「わかった」 diễn tả khoảnh khắc người nói vừa mới hiểu ra hoặc nghĩ ra đáp án ngay tại thời điểm nói (\"À, ra thế, hiểu/biết rồi!\").","translation_vi":"Con gái: \"Đố bố nhé. Loại trái cây mà bố ghét là gì?\" Bố: \"Ừm, là gì nhỉ. À, ra thế, bố biết rồi. Là đu đủ (papaya) đúng không. Ý là loại quả mà papa ghét chứ gì.\" Con gái: \"Chính xác ạ.\""},{"mondai":7,"q":5,"prompt":"この小説を読んで、友のためなら、自分はどうなったって(　　)という主人公の熱い思いに感動した。","options":["たまらない","かまわない","わけがない","ならない"],"answer":2,"word_explain":"Cấu trúc 「～たってかまわない」 (= ～てもかまわない) mang nghĩa \"cho dù có... cũng không sao / chẳng màng\".","translation_vi":"Đọc cuốn tiểu thuyết này, tôi đã rất cảm động trước tấm lòng nhiệt thành của nhân vật chính rằng vì bạn bè thì bản thân mình có ra sao cũng chẳng màng."},{"mondai":7,"q":6,"prompt":"わたしたちが旅館に着くと、従業員たちが笑顔で「ようこそ(　　)。」とあいさつしてくれた。","options":["お越しくださいました","お伺いしました","お呼びいただきました","お迎えしました"],"answer":1,"word_explain":"Cụm kính ngữ chào đón cố định: 「ようこそお越しくださいました」 (cảm ơn quý khách đã cất công đến thăm; 「お越しになる」 là tôn kính ngữ của 来る).","translation_vi":"Khi chúng tôi đến lữ quán, các nhân viên đã mỉm cười chào đón: \"Chào mừng quý khách đã đến.\""},{"mondai":7,"q":7,"prompt":"A「次の登山、大山に登るのはどう？」 B「大山は3年前に一度(　　)から、ほかの山がいいなあ。」","options":["登ってみる","登ってくる","登っていく","登っている"],"answer":4,"word_explain":"Thể 「～ている」 đi với mốc thời gian quá khứ và số lần (3年前に一度) diễn tả kinh nghiệm đã từng làm việc gì đó trong quá khứ.","translation_vi":"A: \"Chuyến leo núi tới, leo núi Oyama thì sao?\" B: \"Núi Oyama 3 năm trước tôi đã từng leo một lần rồi nên chọn núi khác thì hay hơn.\""},{"mondai":7,"q":8,"prompt":"日本の人気バンド「Z」は、ヨーロッパでコンサートを行うなど、活動を世界(　　)広げている。","options":["でと","へと","からも","ほども"],"answer":2,"word_explain":"Trợ từ kép 「へと」 nhấn mạnh phương hướng hoặc phạm vi mở rộng tiến tới (「世界へと広げる」: mở rộng vươn ra thế giới).","translation_vi":"Ban nhạc nổi tiếng của Nhật Bản \"Z\" đang mở rộng hoạt động vươn ra thế giới, chẳng hạn như tổ chức hòa nhạc tại châu Âu."},{"mondai":7,"q":9,"prompt":"パソコン教室の講師に(　　)、人に教えるのは難しいけど楽しいということがわかりました。","options":["なったかぎり","したかぎり","したおかげで","なったおかげで"],"answer":4,"word_explain":"Đi với 「講師に」 phải dùng động từ 「なる」 (trở thành giảng viên), kết hợp với 「～おかげで」 diễn tả nguyên nhân dẫn đến kết quả tốt đẹp (\"nhờ... mà...\").","translation_vi":"Nhờ trở thành giảng viên của lớp học máy tính, tôi đã hiểu ra rằng việc dạy cho người khác tuy khó nhưng rất vui."},{"mondai":7,"q":10,"prompt":"だれだって、失敗もするし、(　　)やれないときもある。","options":["やるなと言われたことが","やるなと言われたのは","やらなくてはいけないことが","やらなくてはならないのは"],"answer":3,"word_explain":"Động từ khả năng phủ định 「やれない」 dùng trợ từ 「が」 cho đối tượng, và về mặt ý nghĩa phải là \"những việc phải làm\" (「やらなくてはいけないことが」).","translation_vi":"Ai cũng có lúc thất bại, và cũng có lúc không thể làm được những việc cần phải làm."},{"mondai":7,"q":11,"prompt":"内容がわからない話を長時間(　　)、大人だって耐えられないことでしょう。","options":["聞かなくていいとしたら","聞かなければならないことで","聞かなければならないとしたら","聞かなくていいことで"],"answer":3,"word_explain":"Cấu trúc giả định 「～としたら」 (nếu giả sử là...) kết hợp với 「聞かなければならない」 (phải nghe) tạo nghĩa hợp lý với vế sau \"đến người lớn cũng không chịu nổi\".","translation_vi":"Nếu giả sử phải nghe một câu chuyện không hiểu nội dung trong thời gian dài, thì ngay cả người lớn cũng khó mà chịu đựng nổi."},{"mondai":7,"q":12,"prompt":"（本屋で） A「あ、この本、面白いよ。」 B「どんな話？」 A「主人公と恋人が、親に無理やり(　　)話なんだけど、すごくどきどきするんだ。」","options":["別れそうになる","別れられそうになる","別れさせそうになる","別れさせられそうになる"],"answer":4,"word_explain":"Thể bị động sai khiến 「別れさせられる」 (bị ép chia tay, bởi 「親に」) kết hợp với 「～そうになる」 (suýt nữa thì bị...).","translation_vi":"(Tại hiệu sách) A: \"À, cuốn sách này hay lắm đấy.\" B: \"Câu chuyện thế nào?\" A: \"Là câu chuyện về nhân vật chính và người yêu suýt bị bố mẹ ép chia tay, nhưng đọc hồi hộp lắm.\""},{"mondai":8,"q":13,"prompt":"「わたし、辛いものを食べると、＿＿＿　＿＿＿　★　＿＿＿ せきが出るんです。」","options":["ほど","必ず","いい","といって"],"answer":3,"word_explain":"Thứ tự đúng: 2 → 4 → ★3 → 1. Cụm cố định 「必ずといっていいほど」 mang nghĩa \"hầu như chắc chắn / gần như lúc nào cũng\".","translation_vi":"\"Tôi ấy à, hễ ăn đồ cay là gần như lúc nào cũng bị ho.\""},{"mondai":8,"q":14,"prompt":"（学校の正門で） A「みんないますか。」 B「田中さんがいません。」 A「授業のあと ＿＿＿　★　＿＿＿　＿＿＿ のかな。」","options":["なっていたのに","一人で行っちゃった","ここで待ち合わせて","一緒に行くことに"],"answer":4,"word_explain":"Thứ tự đúng: 3 → ★4 → 1 → 2. Cấu trúc 「～ことになっていたのに」 (theo kế hoạch/hẹn là sẽ... vậy mà...) nối với 「一人で行っちゃったのかな」.","translation_vi":"(Ở cổng chính trường học) A: \"Mọi người có mặt đủ chưa?\" B: \"Thiếu bạn Tanaka.\" A: \"Đã hẹn là sau giờ học tập trung ở đây rồi cùng đi cơ mà, không biết có phải bạn ấy đi một mình trước rồi không nhỉ.\""},{"mondai":8,"q":15,"prompt":"A「あ、今から行く博物館、一週間前に予約してないと入れないってガイドブックに書いてあるよ。」 B「え、そうなの？ 困ったなあ。」 A「行く ＿＿＿　＿＿＿　＿＿＿　★ みようか。」","options":["行って","だけ","交渉して","入れてもらえないか"],"answer":3,"word_explain":"Thứ tự đúng: 2 → 1 → 4 → ★3. Cụm 「行くだけ行って」 (dù sao cũng cứ đến đó xem sao) + 「入れてもらえないか交渉してみようか」 (thử thương lượng xem có được cho vào không).","translation_vi":"A: \"À, sách hướng dẫn viết là bảo tàng mình sắp đi nếu không đặt trước một tuần thì không vào được đâu.\" B: \"Hả, thế à? Gay go nhỉ.\" A: \"Thôi cứ đi thử đến nơi rồi thương lượng xem họ có cho mình vào không nhé.\""},{"mondai":8,"q":16,"prompt":"（電話で） A「すみません、来週の２時からの会議ですが、その時間、別の用件が入ってしまいまして…。もしそちらのご都合が ＿＿＿　★　＿＿＿　＿＿＿ 、いかがでしょうか。」 B「こちらは大丈夫ですよ。」","options":["ありがたいんですが","変更していただけると","４時以降に","よろしければ"],"answer":3,"word_explain":"Thứ tự đúng: 4 → ★3 → 2 → 1. Mẫu câu nhờ vả lịch sự: 「ご都合がよろしければ、4時以降に変更していただけるとありがたいんですが」.","translation_vi":"(Qua điện thoại) A: \"Xin lỗi, về cuộc họp lúc 2 giờ tuần tới ấy ạ, vào giờ đó tôi lại có việc khác xen vào mất... Nếu bên anh/chị thuận tiện thì có thể đổi sang từ sau 4 giờ được không ạ, không biết thế nào?\" B: \"Bên tôi thì ổn thôi.\""},{"mondai":8,"q":17,"prompt":"このコンサートの警備には、警備員 ＿＿＿　＿＿＿　★　＿＿＿ 十分です。","options":["いれば","も","が","２０人"],"answer":2,"word_explain":"Thứ tự đúng: 3 → 4 → ★2 → 1. Cấu trúc 「[Số lượng] + も + ～ば十分です」 nhấn mạnh ước lượng tối đa cần thiết (\"chỉ cần đến 20 người là đủ rồi\").","translation_vi":"Để đảm bảo an ninh cho buổi hòa nhạc này, chỉ cần có đến 20 nhân viên bảo vệ là đủ rồi."},{"mondai":9,"q":18,"prompt":"Chỗ trống [50] trong đoạn văn trên","options":["ただし","それに","あるいは","たとえば"],"answer":4,"word_explain":"Câu trước nêu nhận định chung rằng thực đơn trưa thường có giá phải chăng hơn buổi tối, câu sau liệt kê các ví dụ cụ thể về giá cả nên dùng liên từ 「たとえば」 (ví dụ như).","translation_vi":"Ví dụ như, ngay cả ở những quán buổi tối chỉ riêng món mì Ý đã khoảng 1.200 yên thì buổi trưa mì Ý kèm súp và salad lại chỉ có 980 yên, hay ở những quán buổi tối món ăn theo suất trên 5.000 yên thì buổi trưa chỉ vào khoảng 1.000 yên."},{"mondai":9,"q":19,"prompt":"Chỗ trống [51] trong đoạn văn trên","options":["意外では","間違いでは","だから","もちろん"],"answer":4,"word_explain":"「もちろん～ない」 (đương nhiên là không) phủ định mạnh mẽ suy đoán sai lầm về chất lượng món ăn giá rẻ, phù hợp với câu tiếp theo giải thích nếu mất vị ngon sẽ ảnh hưởng xấu cả buổi tối.","translation_vi":"Dù nói là rẻ nhưng đương nhiên không có chuyện đầu bếp làm qua loa hay sử dụng nguyên liệu rẻ tiền."},{"mondai":9,"q":20,"prompt":"Chỗ trống [52] trong đoạn văn trên","options":["次の場合","その店の場","ランチの場合","夜の営業の場合"],"answer":3,"word_explain":"Câu trước nói nguyên lý chung về giảm chi phí ở cửa hàng, câu này quay lại nói cụ thể về cách làm đối với bữa trưa nên dùng 「ランチの場合」.","translation_vi":"Trong trường hợp bữa trưa, có nhiều trường hợp người ta kiềm chế chi phí bằng cách thu hẹp thực đơn lại chỉ còn vài món."},{"mondai":9,"q":21,"prompt":"Chỗ trống [53] trong đoạn văn trên","options":["いうわけだ","いう点か","いうくらいだ","いうからか"],"answer":1,"word_explain":"Cấu trúc 「～というわけだ」 dùng để kết luận và tổng kết lý do vừa giải thích (\"chính vì vậy mà có thể hạ giá được\").","translation_vi":"Chính vì vậy, điều đó có nghĩa là có thể làm cho giá thành rẻ đi được."},{"mondai":9,"q":22,"prompt":"Chỗ trống [54] trong đoạn văn trên","options":["ランチではあったか","ランチなのである","ランチなのではないだろう","ランチではないのではないか"],"answer":2,"word_explain":"「～なのである」 là thể khẳng định mang tính kết luận bài viết (chơi chữ 「おいしい」 vừa là ngon miệng vừa là \"béo bở/có lợi\"). Đáp án 4 「ではないのではないか」 bị phủ định kép sai nghĩa.","translation_vi":"Đối với các quán ăn, bữa trưa vừa giúp thu lợi nhuận lại vừa có thể thu hút thêm khách hàng chính là một bữa trưa \"béo bở\"."}]},{"id":"g_2011_12","displayName":"12/2011","subtitle":"22 câu • Mondai 7–9 (Ngữ pháp)","m9_passage":"日本の家の寿命\n\nもし家を建てるなら、どんな家がいいですか。もちろん長く住める家がいいですよね。日本で町を見渡してみると、頑丈そうな建物が並んでいます。ところが、ある調査によると日本の家の平均寿命は、英国７７年、米国５５年に比べて短く３０年ほどだそうです。[50]結果になったのでしょうか。\n\n原因の一つに、戦後の日本の特殊な住宅事情があるようです。第二次世界大戦後、日本では、家不足が深刻だったため、質より量を優先させて家が作られました。しかし、経済が成長して生活に余裕が生まれると、人々はより質の高い家を求めるようになります。そこで、それまでの家は次々に[51]そうです。その結果、町には、今のような頑丈そうな質の高い住宅が立ち並ぶことになったのです。\n\nまた、日本人の住宅観も原因として[52]。日本には、家はそこに住む家族に合わせて建てるという考え方があります。たとえば、将来子供が生まれ、家族が増えることを考えて建てた家も、子供が成人して独立してしまうと、夫婦二人だけの生活には合わなくなります。そのため、年をとった夫婦ためには住むのに適した家へと建て替えるのです。そんなふうに家族の形が変わったとき、今まで住んでいた家を建て替えることも少なくないそうです。\n\n[53]、日本では家を建て替えることが多いために、家の平均寿命が短いという調査結果になったのだと思います。平均寿命３０年というのは、３０年で壊れてしまうという意味ではないのです。もし皆さんが、自分のために、家族のために、日本で家を建てるなら…どんな[54]。","questions":[{"mondai":7,"q":1,"prompt":"今まで何人(　　)の人に成功の理由を聞かれましたが、決して特別なことをしてきたのではありません。","options":["と","も","だけ","きり"],"answer":2,"word_explain":"Cấu trúc 「疑問詞＋も＋の＋名詞」 (何人もの人) dùng để nhấn mạnh số lượng lớn (\"biết bao nhiêu người\", \"rất nhiều người\").","translation_vi":"Cho đến nay tôi đã được rất nhiều người hỏi về lý do thành công, nhưng tôi hoàn toàn không làm điều gì đặc biệt cả."},{"mondai":7,"q":2,"prompt":"野党の追及に対し、大臣は満足な回答できなかったどころか、質問の内容(　　)理解できていなかった。","options":["すら","こそ","のみ","ほど"],"answer":1,"word_explain":"「〜すら（〜ない）」 mang nghĩa \"ngay cả... cũng (không)\", thường đi với 「〜どころか」 (huống hồ là / chẳng những không... mà ngay cả...).","translation_vi":"Trước sự chất vấn của đảng đối lập, bộ trưởng chẳng những không thể trả lời thỏa đáng mà ngay cả nội dung câu hỏi cũng không hiểu nổi."},{"mondai":7,"q":3,"prompt":"テレビゲームなんて子供の遊び(　　)に思っていたのだが、やってみたら、面白くて夢中になってしまった。","options":["まで","ぬき","どおり","くらい"],"answer":4,"word_explain":"「N＋くらいに思う」 diễn tả sự đánh giá thấp, xem nhẹ (\"chỉ coi như là... thôi\").","translation_vi":"Tôi đã từng nghĩ trò chơi điện tử chỉ là trò trẻ con thôi, nhưng khi chơi thử thì thấy thú vị đến mức mê mẩn luôn."},{"mondai":7,"q":4,"prompt":"山田「課長、先ほど出した報告書なのですが、表の数字が(　　)間違っていたようなんです、申し訳ありません。」 課長「そうか、じゃ、もう一度計算して出して。」","options":["どうか","どうも","どうにか","どうでも"],"answer":2,"word_explain":"「どうも〜ようだ」 diễn tả sự phỏng đoán có phần mơ hồ nhưng cảm thấy chắc là vậy (\"hình như / có vẻ như là...\").","translation_vi":"Yamada: \"Trưởng phòng ơi, về bản báo cáo tôi nộp lúc nãy, các con số trong bảng hình như bị sai rồi ạ, tôi thành thật xin lỗi.\" Trưởng phòng: \"Vậy à, thế thì tính lại rồi nộp nhé.\""},{"mondai":7,"q":5,"prompt":"この美術館では、利用者の声に(　　)、夏期の開館時間を１時間延長することにします。","options":["いたって","むけて","こたえて","かかわって"],"answer":3,"word_explain":"「N＋にこたえて（に応えて）」 có nghĩa là \"đáp lại, đáp ứng (ý kiến, nguyện vọng, kỳ vọng của ai đó)\".","translation_vi":"Tại bảo tàng mỹ thuật này, để đáp lại ý kiến của khách tham quan, chúng tôi quyết định kéo dài thời gian mở cửa vào mùa hè thêm 1 tiếng."},{"mondai":7,"q":6,"prompt":"この曲は、最初はあまり好きではなかったが、何度も聞いている(　　)だんだん好きになってきた。","options":["なかに","うちに","ついでに","とたんに"],"answer":2,"word_explain":"「Vている＋うちに」 diễn tả trong quá trình liên tục làm một việc gì đó thì có sự thay đổi tự nhiên xảy ra (\"trong khi / dần dần...\").","translation_vi":"Bài hát này lúc đầu tôi không thích lắm, nhưng trong lúc nghe đi nghe lại nhiều lần thì dần dần tôi lại thấy thích."},{"mondai":7,"q":7,"prompt":"このサイトでは、ご自宅からインターネットで本が注文できます、午後４時以前にご注文いただければ数量や合計金額(　　)、翌日中にお届けします。","options":["をのぞき","を含めず","によらず","にかぎり"],"answer":3,"word_explain":"「N＋によらず」 mang nghĩa \"không phụ thuộc vào, bất kể N là gì\". Ở đây là bất kể số lượng hay tổng số tiền.","translation_vi":"Tại trang web này, quý khách có thể đặt mua sách qua mạng ngay tại nhà; nếu đặt hàng trước 4 giờ chiều thì bất kể số lượng hay tổng số tiền là bao nhiêu, chúng tôi sẽ giao hàng trong ngày hôm sau."},{"mondai":7,"q":8,"prompt":"彼の論文は、構成にはまだ少し問題がある気が(　　)、内容自体はだいぶ良くなったと思う。","options":["することはないが","しないでもないが","するよりほかないが","しないのではないが"],"answer":2,"word_explain":"「Vない＋でもない」 là dạng phủ định kép mang nghĩa khẳng định nhẹ: \"không phải là không..., cũng có phần...\" (「気がしないでもない」 = cũng hơi có cảm giác là...).","translation_vi":"Luận văn của anh ấy tuy tôi vẫn hơi có cảm giác bố cục còn chút vấn đề, nhưng bản thân nội dung thì tôi thấy đã khá hơn nhiều rồi."},{"mondai":7,"q":9,"prompt":"Ａ「このレストラン、すごく人気があるから、予約して行ったほうがいいね。」 Ｂ「うん、かなり早めに、予約(　　)だめかもしれないね。」","options":["しとかなくちゃ","しなきゃって","してるんじゃ","しちゃうって"],"answer":1,"word_explain":"「〜とかなくちゃ」 là dạng nói tắt khẩu ngữ của 「〜ておかなくては」, đi với 「だめ」 thành 「〜ておかなくちゃだめ」 mang nghĩa \"phải (làm sẵn) ... thì mới được\".","translation_vi":"A: \"Nhà hàng này rất nổi tiếng nên đặt bàn trước rồi hãy đi nhỉ.\" B: \"Ừ, chắc là phải đặt trước thật sớm mới được đấy nhỉ.\""},{"mondai":7,"q":10,"prompt":"母によく「部屋を片付けなさい」としかられるのだが、片付けたら(　　)今度は、「片付けられるなら、どうして普段から片付けないの」と、またしかられる。","options":["片付けるまで","片付けたが","片付けるのに","片付けたで"],"answer":4,"word_explain":"Mẫu câu 「Vたら＋Vたで」 diễn tả ý \"nếu làm V thì đến lượt V rồi lại nảy sinh chuyện phiền phức khác\".","translation_vi":"Tôi hay bị mẹ mắng là \"Dọn phòng đi\", nhưng hễ dọn xong rồi thì lần này lại bị mắng tiếp là \"Nếu dọn được thì sao bình thường không dọn đi\"."},{"mondai":7,"q":11,"prompt":"台風が近づいているので、明日からの旅行は、残念だが(　　)。","options":["延期しないわけではない","延期せざるを得ない","延期しうるはずもない","延期すべきものではない"],"answer":2,"word_explain":"「Vない形＋ざるを得ない」 (「する」 thành 「せざるを得ない」) mang nghĩa \"buộc phải, đành phải làm gì dù không muốn\".","translation_vi":"Vì bão đang tiến đến gần nên chuyến du lịch từ ngày mai dù rất đáng tiếc nhưng đành phải hoãn lại."},{"mondai":7,"q":12,"prompt":"面接官「恐れ入りますが、この仕事に向ける資格は(　　)。」 応募者「はい、電力エンジエアの資格をお持ちしています。」","options":["お持ちしますか","お持ちですか","お持ちになりますか","お持ちいますか"],"answer":2,"word_explain":"「お＋Vます形＋ですか」 là kính ngữ dùng cho động từ chỉ trạng thái như 「持っている」 (\"Ngài có chứng chỉ ... không ạ?\"). 「お持ちになりますか」 dùng cho hành động cầm/mang, còn 「お持ちしますか」 là khiêm nhường ngữ.","translation_vi":"Người phỏng vấn: \"Xin lỗi, anh/chị có chứng chỉ phù hợp cho công việc này không ạ?\" Ứng viên: \"Vâng, tôi có chứng chỉ kỹ sư điện lực ạ.\""},{"mondai":8,"q":13,"prompt":"もう秋になるのに、今日の暑さは　＿＿＿　＿＿＿　★　＿＿＿　エアコンをつけた家も多かったらしい。","options":["真夏","のようで","まるで","に戻ったか"],"answer":4,"word_explain":"Thứ tự đúng: 3 → 1 → ★4 → 2. Cấu trúc 「まるで〜かのようだ」 diễn tả sự ví von \"cứ như thể là...\".","translation_vi":"Mặc dù sắp sang thu rồi nhưng cái nóng hôm nay cứ như thể đã quay trở lại giữa mùa hè vậy, nghe nói có nhiều nhà đã bật điều hòa."},{"mondai":8,"q":14,"prompt":"（ホテルで） 支配人「お客様を間違った部屋に案内してしまったそうだね」。 従業員「はい。事前にリストをしっかり　＿＿＿　＿＿＿　★　＿＿＿　のに申し訳ありません。」","options":["しておけば","確認さえ","ミスでした","防げる"],"answer":4,"word_explain":"Thứ tự đúng: 2 → 1 → ★4 → 3. Cấu trúc 「〜さえ〜ば」 (\"chỉ cần... thì...\") kết hợp với mệnh đề định ngữ 「防げるミス」 (\"lỗi có thể phòng tránh được\").","translation_vi":"(Tại khách sạn) Quản lý: \"Nghe nói đã dẫn nhầm phòng cho khách rồi phải không.\" Nhân viên: \"Vâng. Đáng lẽ đây là lỗi có thể tránh được nếu chỉ cần kiểm tra kỹ danh sách trước, tôi thật sự xin lỗi ạ.\""},{"mondai":8,"q":15,"prompt":"今回失敗した　＿＿＿　＿＿＿　★　＿＿＿　必ずこの経験を生かしてほしい。","options":["としても","今後","ことは","仕方ない"],"answer":1,"word_explain":"Thứ tự đúng: 3 → 4 → ★1 → 2. Cấu trúc 「〜としても」 (\"cho dù là... đi nữa thì...\") đặt giả thiết nhượng bộ.","translation_vi":"Cho dù việc thất bại lần này là chuyện không thể tránh khỏi đi nữa, thì sau này tôi mong bạn nhất định hãy vận dụng tốt kinh nghiệm này."},{"mondai":8,"q":16,"prompt":"試合に負けて本当に悔しかったので、もっと強くなるため　＿＿＿　＿＿＿　★　＿＿＿　耐えようと思います。","options":["だって","なら","厳しい練習に","どんな"],"answer":3,"word_explain":"Thứ tự đúng: 2 → 4 → ★3 → 1. Cấu trúc 「N＋ためなら」 (\"nếu là vì...\") và 「どんな＋N＋にだって」 (\"bất kể N nào đi nữa cũng...\").","translation_vi":"Vì thua trận đấu nên tôi thật sự rất cay cú, thế nên nếu là để trở nên mạnh mẽ hơn thì bất kể bài tập khắc nghiệt thế nào tôi cũng sẽ cố gắng chịu đựng."},{"mondai":8,"q":17,"prompt":"母は「風邪をひかないのは、　＿＿＿　＿＿＿　★　＿＿＿　」とよく言っている。","options":["ジョギングの","している","おかげだ","毎朝"],"answer":1,"word_explain":"Thứ tự đúng: 4 → 2 → ★1 → 3. Cấu trúc 「〜のは〜のおかげだ」 (\"việc mà... là nhờ vào...\") kết hợp mệnh đề bổ nghĩa 「毎朝しているジョギング」.","translation_vi":"Mẹ tôi thường hay nói rằng: \"Việc mẹ không bị cảm là nhờ vào việc chạy bộ mỗi sáng đấy.\""},{"mondai":9,"q":18,"prompt":"Chỗ trống [50] trong đoạn văn trên","options":["なぜこのような","なぜあのような","果してどのような","はたしてそのような"],"answer":1,"word_explain":"「なぜこのような」 (\"tại sao lại có kết quả như thế này\"): dùng 「この」 để chỉ kết quả vừa nêu ở câu trước (tuổi thọ trung bình nhà ở Nhật khoảng 30 năm) và 「なぜ」 để hỏi nguyên nhân, khớp với đoạn tiếp theo mở đầu bằng 「原因の一つに〜」.","translation_vi":"Tại sao lại dẫn đến kết quả như thế này nhỉ?"},{"mondai":9,"q":19,"prompt":"Chỗ trống [51] trong đoạn văn trên","options":["建て替えていく","建て替えさせていた","建て替えさせられている","建て替えられていった"],"answer":4,"word_explain":"Chủ ngữ là 「それまでの家は」 (những ngôi nhà trước đó) nên động từ phải chia thể bị động 「建て替えられる」 (được xây mới thay thế), kết hợp 「〜ていった」 chỉ diễn biến tiếp diễn trong quá khứ.","translation_vi":"Vì thế, nghe nói những ngôi nhà trước đó đã lần lượt được xây mới thay thế."},{"mondai":9,"q":20,"prompt":"Chỗ trống [52] trong đoạn văn trên","options":["思われます","わかります","考えられます","調べられます"],"answer":3,"word_explain":"Cụm cố định 「原因として考えられる」 mang nghĩa \"có thể được xem là một nguyên nhân\". 「思われる」 không đi tự nhiên với 「〜として」 trong ngữ cảnh này.","translation_vi":"Ngoài ra, quan điểm về nhà ở của người Nhật cũng có thể được xem là một nguyên nhân."},{"mondai":9,"q":21,"prompt":"Chỗ trống [53] trong đoạn văn trên","options":["ところで","つまり","なぜなら","もちろん"],"answer":2,"word_explain":"「つまり」 (\"tóm lại là / nói cách khác\") dùng để tổng kết lại hai nguyên nhân đã trình bày ở các đoạn trước để đưa ra kết luận.","translation_vi":"Tóm lại, tôi nghĩ rằng chính vì ở Nhật thường xuyên xây lại nhà nên mới có kết quả khảo sát là tuổi thọ trung bình của nhà ngắn."},{"mondai":9,"q":22,"prompt":"Chỗ trống [54] trong đoạn văn trên","options":["家を建てたのですか","家に住めたのですか","家を建てますか","家に住めますか"],"answer":3,"word_explain":"Câu kết nối lại với giả định 「もし〜建てるなら」 (\"nếu xây nhà ở Nhật thì...\"), hướng tới lựa chọn ở hiện tại/tương lai nên dùng 「どんな家を建てますか」 (\"bạn sẽ xây ngôi nhà như thế nào?\").","translation_vi":"Nếu các bạn xây nhà ở Nhật vì bản thân, vì gia đình mình... thì bạn sẽ xây một ngôi nhà như thế nào?"}]},{"id":"g_2011_07","displayName":"07/2011","subtitle":"22 câu • Mondai 7–9 (Ngữ pháp)","m9_passage":"日本の鉄道ファン\n\n鉄道ファンとは、鉄道が好きで鉄道に関することを趣味にしている人たちのことだ。鉄道ファンは単に「鉄」と言われたりもする。日本では、これまでは「鉄」といえば男性だと思われていたが、近年は女性のファンが急増しているらしい。\n\nところで、彼ら鉄道ファンたちは[50]趣味を楽しんでいるのだろうか。\n\n一言で鉄道ファンといってもその趣味の内容は多種多様だ。そして、電車に乗るのが好きな「鉄」は「乗り鉄」というように、それぞれその内容に対応した呼び名がある。\n\n「乗り鉄」[51]、写真を撮るのが好きな「撮り鉄」、車両や鉄道がある風景を描く「描き鉄」、鉄道の模型が好きな「模型鉄」などだ。\n\nある４０代の「乗り鉄」の女性は鉄道の魅力を[52]語る。「窓の外の風景をながめていると旅の気分が味わえるし、車と違って座っているだけで目的地に着けるのがいい」。「模型鉄」である３０代の男性は、模型の魅力について「車両の形を見ているだけでうっとり。本物は買えないけど模型なら買えるし」と説明する。\n\nまた、最近急増している女性ファンには「ママ鉄」も多い。電車を見たがる子どもを連れて電車を見に行くうち、自分も鉄道ファンになってしまったという人たちだ。[53]の特徴は、他の「鉄」とは異なり、ホームではなく、電車が見えるところにある公園やレストランなど、子どもと一緒にゆっくり過ごせる場所で電車を見るという点である。\n\n鉄道ファンにはいろいろなタイプがあり、楽しみ方も[54]。","questions":[{"mondai":7,"q":1,"prompt":"A「もう無理だよ、私には５キロなんて走れないよ。」 B「まだ５００メートルだよ。なんでそうやってすぐ、もうだめ（　　）言うの。」","options":["を","は","とか","とは"],"answer":3,"word_explain":"「～とか言う」: nói những điều đại loại như là..., đưa ra ví dụ về lời nói một cách suồng sã.","translation_vi":"A: \"Chịu thôi, tớ không thể chạy nổi 5 ki-lô-mét đâu.\" B: \"Mới được 500 mét thôi mà. Sao cậu cứ vội nói những câu kiểu như 'hết chịu nổi rồi' thế?\""},{"mondai":7,"q":2,"prompt":"あれこれ悩んだ（　　）、ＡＢＣ大学を志望校に決めた。","options":["さきに","すえに","ところに","とおりに"],"answer":2,"word_explain":"「Vた＋すえに」: sau khi... (trải qua một quá trình dài suy nghĩ, vất vả rồi cuối cùng đi đến kết quả).","translation_vi":"Sau khi trăn trở suy nghĩ đủ điều, tôi đã quyết định chọn đại học ABC làm trường nguyện vọng."},{"mondai":7,"q":3,"prompt":"プリンターの調子が悪くなり、製造会社に電話で問い合わせたら、向こうの担当者に、あれこれ質問に答え（　　）あげく、対応できないと言われた。","options":["させた","させられる","させる","させられた"],"answer":4,"word_explain":"「V-causative-passive（させられた）＋あげく」: bị bắt phải làm gì đó rồi cuối cùng nhận kết quả không tốt. Cần dạng quá khứ 「させられた」 để kết hợp với 「あげく」.","translation_vi":"Máy in bị trục trặc nên tôi gọi điện hỏi công ty sản xuất, vậy mà sau khi bị nhân viên bên đó bắt trả lời hết câu hỏi này đến câu hỏi khác, cuối cùng lại bị nói là không hỗ trợ được."},{"mondai":7,"q":4,"prompt":"面倒だが、やはりこの仕事は断れない。引き受ける（　　）。","options":["までもあるまい","こともない","はずもない","しかあるまい"],"answer":4,"word_explain":"「Vる＋しかあるまい」 (= しかないだろう): đành phải..., không còn cách nào khác ngoài việc...","translation_vi":"Tuy phiền phức nhưng quả thực không thể từ chối công việc này. Đành phải nhận thôi."},{"mondai":7,"q":5,"prompt":"山田監督の、「私、山田は、５０年ぶりにふるさとに戻って（　　）」というあいさつに、会場からは大きな拍手が起こった。","options":["まいりました","いらっしゃいました","うかがいました","おいでになりました"],"answer":1,"word_explain":"「～てまいりました」: khiêm nhường ngữ của 「～てきました」, dùng khi người nói tự nói về hành động trở về của chính mình.","translation_vi":"Trước lời chào của đạo diễn Yamada: \"Tôi, Yamada, đã trở về quê hương sau 50 năm\", tiếng vỗ tay vang dội đã nổi lên từ hội trường."},{"mondai":7,"q":6,"prompt":"彼女の絵は、国内より（　　）海外での評価が高い。","options":["まさか","たとえ","むしろ","かりに"],"answer":3,"word_explain":"「AよりむしろB」: đúng hơn là B chứ không phải A / B hơn là A.","translation_vi":"Tranh của cô ấy được đánh giá cao ở nước ngoài hơn là ở trong nước."},{"mondai":7,"q":7,"prompt":"今年も卒業生を送り出した。次に会うときには、彼らも立派な大人に（　　）。","options":["なるだろう","なっただろう","なっているだろう","なっていただろう"],"answer":3,"word_explain":"「次に会うときには～なっているだろう」: diễn tả trạng thái kết quả đã hình thành vào một thời điểm xác định trong tương lai (lúc gặp lại thì đã trở thành...).","translation_vi":"Năm nay tôi lại tiễn thêm một lứa học sinh tốt nghiệp. Đến lúc gặp lại lần sau, chắc hẳn các em cũng đã trở thành những người lớn trưởng thành rồi."},{"mondai":7,"q":8,"prompt":"毎日（　　）どちらでもいいことばかりを日記に書いているのだが、それがストレス解消になっている。","options":["書くとも書かないとも","書いたか書かなかったか","書いても書かなくても","書くとか書かないとか"],"answer":3,"word_explain":"「VてもVなくてもどちらでもいい」: dù làm hay không làm cũng đều được / chẳng sao cả.","translation_vi":"Hàng ngày tôi toàn viết vào nhật ký những chuyện viết hay không viết cũng chẳng sao, nhưng việc đó lại giúp tôi giải tỏa căng thẳng."},{"mondai":7,"q":9,"prompt":"顔を洗うときには、せっけんを（　　）、さっと洗うのが肌にはよい。","options":["使いすぎずに","使うにすぎず","使うにすぎなく","使いすぎもなくて"],"answer":1,"word_explain":"「Vます＋すぎずに」: không làm gì quá mức mà làm...","translation_vi":"Khi rửa mặt, không dùng quá nhiều xà phòng mà rửa nhanh gọn thì sẽ tốt cho da."},{"mondai":7,"q":10,"prompt":"留学するまで、私は自分が見ている世界がすべてだと思っていた。実はそれが世界のほんの小さな一部分（　　）気付いていなかった。","options":["でないことにしか","でしかないことに","にないことでしか","にしかないことで"],"answer":2,"word_explain":"「Nでしかない」: chỉ là N thôi + 「ことに気付く」: nhận ra việc... (dùng phủ định 「気付いていなかった」).","translation_vi":"Cho đến trước khi đi du học, tôi vẫn nghĩ thế giới mà mình nhìn thấy là tất cả. Thực ra tôi đã không nhận ra rằng đó chỉ là một phần rất nhỏ của thế giới."},{"mondai":7,"q":11,"prompt":"（会社で） A「あれ？あそこにいるの、山田さんかな。」 B「山田さんは出張中だよ。今ここに（　　）。」","options":["いないわけじゃないよ","いるわけないじゃない","いたわけじゃないよ","いなかったわけじゃない"],"answer":2,"word_explain":"「Vる＋わけないじゃない」 (= わけがないじゃないか): làm gì có chuyện... được chứ (phủ định mạnh mẽ dựa trên lý lẽ).","translation_vi":"(Ở công ty) A: \"Ủa? Người ở đằng kia phải anh Yamada không nhỉ?\" B: \"Anh Yamada đang đi công tác mà. Làm sao có chuyện đang ở đây được chứ.\""},{"mondai":7,"q":12,"prompt":"A「このタレント、最近よくテレビで見るね。」 B「ほんと。この人を見ない日はない（　　）よね。」","options":["と言ってもいいぐらいだ","と言ったらいいだけだ","と言ってもいいからだ","と言ったらいいことだ"],"answer":1,"word_explain":"「～と言ってもいいぐらいだ」: đến mức có thể nói là... (nhấn mạnh mức độ cao).","translation_vi":"A: \"Nghệ sĩ này dạo gần đây hay thấy trên tivi nhỉ.\" B: \"Đúng thật. Đến mức có thể nói là không có ngày nào không thấy người này luôn ấy chứ.\""},{"mondai":8,"q":13,"prompt":"不調だった山中選手がついにゴールを決めた。彼に　＿＿＿　＿＿＿　★　＿＿＿　相当あったはずだ。","options":["したら","という","プレッシャーは","「もし、またミスをしたら」"],"answer":2,"word_explain":"Thứ tự đúng: 1 → 4 → ★2 → 3. 「Nにしたら」: đối với N mà nói; 「『...』というプレッシャーは」: áp lực rằng \"...\".","translation_vi":"Cầu thủ Yamanaka vốn đang xuống phong độ cuối cùng cũng đã ghi bàn. Đối với anh ấy, áp lực rằng \"lỡ như lại mắc sai lầm nữa thì sao\" hẳn là đã rất lớn."},{"mondai":8,"q":14,"prompt":"「これは地元ではよく知られた料理で、このすっぱさがおいしい。ただ、　＿＿＿　＿＿＿　★　＿＿＿　増えていることだね。」と田中さんは語る。","options":["なんていう","残念なのは","若者が最近","すっぱいのが苦手だ"],"answer":1,"word_explain":"Thứ tự đúng: 2 → 4 → ★1 → 3. Cấu trúc 「残念なのは～ことだ」 (điều đáng tiếc là...); 「～なんていう若者」 (những bạn trẻ nói những lời như...).","translation_vi":"Ông Tanaka chia sẻ: \"Đây là món ăn nổi tiếng ở địa phương, vị chua này rất ngon. Tuy nhiên, điều đáng tiếc là dạo gần đây ngày càng có nhiều bạn trẻ nói kiểu như 'tôi không ăn được đồ chua'.\""},{"mondai":8,"q":15,"prompt":"忘れられないプレゼントは、小学生のときに両親が買ってくれた自転車です。苦しい生活の中、　＿＿＿　＿＿＿　★　＿＿＿　涙が出ます。","options":["それだけで","どんな思いで","買ってくれたのかと","思うと"],"answer":4,"word_explain":"Thứ tự đúng: 2 → 3 → ★4 → 1. 「どんな思いで買ってくれたのかと思うと、それだけで涙が出ます」: hễ nghĩ xem... thì chỉ riêng điều đó thôi cũng rơi nước mắt.","translation_vi":"Món quà không thể nào quên là chiếc xe đạp bố mẹ đã mua cho tôi hồi tiểu học. Nghĩ xem trong cuộc sống khó khăn đó, bố mẹ đã mua cho mình với tâm trạng như thế nào, chỉ riêng điều đó thôi cũng làm tôi rơi nước mắt."},{"mondai":8,"q":16,"prompt":"最近、子どもがピアノを習いたいと言いだした。わたしは、子どもが　＿＿＿　＿＿＿　★　＿＿＿　と思っている。","options":["したい","やりたい","やらせて","と思うことは"],"answer":3,"word_explain":"Thứ tự đúng: 1 → 4 → ★3 → 2. 「子どもがしたいと思うことは」 (những điều con muốn làm) + 「やらせてやりたい」 (muốn cho con làm; 「やらせて＋てやる＋たい」).","translation_vi":"Gần đây con tôi bắt đầu nói muốn học piano. Tôi nghĩ rằng những gì con muốn làm thì tôi muốn cho con được làm."},{"mondai":8,"q":17,"prompt":"国民の、政治　＿＿＿　＿＿＿　★　＿＿＿　政治家は指導力を発揮できるのだ。","options":["初めて","に対する","があって","信頼"],"answer":3,"word_explain":"Thứ tự đúng: 2 → 4 → ★3 → 1. 「Nに対する信頼」 (sự tin tưởng đối với N) + 「～があって初めて」 (chỉ khi có... thì mới...).","translation_vi":"Chỉ khi có được sự tin tưởng của người dân đối với chính trị thì chính trị gia mới có thể phát huy năng lực lãnh đạo."},{"mondai":9,"q":18,"prompt":"Chỗ trống [50] trong đoạn văn trên","options":["それほど","どのように","それでも","どちらの"],"answer":2,"word_explain":"Dùng nghi vấn từ 「どのように」 (như thế nào) đi với 「～のだろうか」 để mở ra phần giải thích chi tiết về các cách thưởng thức đa dạng ở các đoạn sau.","translation_vi":"Nhân tiện, những người hâm mộ đường sắt này đang tận hưởng sở thích của mình như thế nào nhỉ?"},{"mondai":9,"q":19,"prompt":"Chỗ trống [51] trong đoạn văn trên","options":["にかわって","によって","のうえ","のほか"],"answer":4,"word_explain":"「Nのほか」: ngoài N ra (còn có...). Dùng để liệt kê thêm các loại hình khác ngoài 「乗り鉄」.","translation_vi":"Ngoài \"Nori-tetsu\" ra, còn có \"Tori-tetsu\" thích chụp ảnh, \"Kaki-tetsu\" vẽ phong cảnh có toa xe và đường sắt, \"Mokei-tetsu\" thích mô hình đường sắt, v.v."},{"mondai":9,"q":20,"prompt":"Chỗ trống [52] trong đoạn văn trên","options":["こう","そう","同様に","以上のように"],"answer":1,"word_explain":"「こう」: như thế này / như sau, dùng để giới thiệu nội dung trích dẫn ngay phía sau (「こう語る。『...』」).","translation_vi":"Một phụ nữ ngoài 40 tuổi thuộc nhóm \"Nori-tetsu\" kể về sức hấp dẫn của đường sắt như sau: \"Ngắm phong cảnh ngoài cửa sổ có thể cảm nhận được không khí du lịch, và khác với ô tô là chỉ cần ngồi yên thôi cũng đến được đích, điều đó thật tuyệt.\""},{"mondai":9,"q":21,"prompt":"Chỗ trống [53] trong đoạn văn trên","options":["鉄道ファン","女性ファン","彼女たち","大人たち"],"answer":3,"word_explain":"「彼女たち」 thay thế trực tiếp cho nhóm 「ママ鉄」 (\"những người phụ nữ dẫn con đi xem tàu rồi thành fan\") vừa được nhắc ở câu ngay trước đó.","translation_vi":"Đặc điểm của họ (các \"Mama-tetsu\") là khác với các \"Tetsu\" khác, họ ngắm tàu ở những nơi có thể thong thả cùng con như công viên hay nhà hàng có thể nhìn thấy tàu, chứ không phải ở sân ga."},{"mondai":9,"q":22,"prompt":"Chỗ trống [54] trong đoạn văn trên","options":["さまざまだ","さまざまだと言われた","さまざまである点だ","さまざまだと思われている"],"answer":1,"word_explain":"Câu kết bài khái quát trực tiếp nhận định của tác giả bằng thì hiện tại đơn giản 「さまざまだ」, đối ứng với 「多種多様だ」 ở đầu bài.","translation_vi":"Người hâm mộ đường sắt có nhiều kiểu khác nhau, và cách tận hưởng cũng rất đa dạng."}]},{"id":"g_2010_12","displayName":"12/2010","subtitle":"22 câu • Mondai 7–9 (Ngữ pháp)","m9_passage":"花粉症とうまく付き合う\n\n春が訪れ、過ごしやすい季節になりました。しかし最近、[50]花粉症に悩まされる人が増えています。春は花粉症の季節でもあるのです。\n\n花粉症とは何でしょうか。花粉症は花粉に対するアレルギー反応で、アレルギー体質の人は花粉症になりやすいといわれています。花粉は体にとって有害なものではありません。\n\nしかし、花粉症になりやすい人の体に花粉が入ると、体は花粉を侵入者だと思って、花粉に対してガードマンのような働きをする「抗体」を作り出します。この「抗体」が蓄積されて一定の水準になると、花粉を追い出すためにくしゃみや鼻水などのアレルギー症状が現れます。そのくしゃみや鼻水によって花粉を追い出そうとするのです。[51]、花粉に対して体が過剰に反応して症状が出るのが花粉症というわけです。\n\n花粉が多く飛ぶ季節を快適に過ごすために、花粉症の人は規則正しい生活をして、体調管理に努め、とにかく花粉に接しないようにしなければなりません。外出時には、マスクやメガネで花粉が体に入るのを防ぎ、帰宅時には服に付いた花粉を落としてから、家に[52]。\n\n実は、今花粉症ではない人も、今後症状が現れる可能性があります。花粉症にならないようにするためには、花粉症の人と同じようになるべく花粉に接しないことが重要です。生活空間に花粉を持ち込まないようにしてください。いつ誰が花粉症になっても不思議ではありません。誰も自分には関係がないとは言えないもの、それが[53]です。\n\n花粉症の人もそうではない人も、春は過ごし方に少し[54]。","questions":[{"mondai":7,"q":1,"prompt":"休日は混雑が予想されますので、お電話でご予約の（　　）、ご来店ください。","options":["あげく","あまり","うえ","ほう"],"answer":3,"word_explain":"「Danh từ (hành động) + のうえ（で）」 mang nghĩa \"sau khi thực hiện hành động đó thì...\". Ở đây là \"sau khi đặt chỗ qua điện thoại\". 「あげく」 diễn tả kết cục xấu sau thời gian dài, 「あまり」 là quá mức đến nỗi, 「ほう」 là phía/hướng.","translation_vi":"Vì ngày nghỉ dự kiến sẽ đông đúc, xin quý khách vui lòng đặt chỗ trước qua điện thoại rồi hãy đến cửa hàng."},{"mondai":7,"q":2,"prompt":"新作映画について中田一郎監督は、「現実的で（　　）ながらも、詩的な雰囲気を失わないよう意識した。」と語る。","options":["あり","ある","なり","なる"],"answer":1,"word_explain":"Cấu trúc 「Vます (bỏ ます) / Aい / Aな(である→であり) + ながらも」 nghĩa là \"tuy... nhưng vẫn...\". Tính từ đuôi な 「現実的だ」 chuyển sang văn viết trang trọng là 「現実的である」 rồi lấy thể liên dụng 「現実的であり」 để nối với 「ながらも」.","translation_vi":"Về bộ phim mới, đạo diễn Nakada Ichiro chia sẻ: \"Tôi đã chú ý để dù mang tính hiện thực nhưng tác phẩm vẫn không đánh mất bầu không khí đầy chất thơ.\""},{"mondai":7,"q":3,"prompt":"A「これまでありがとう。あなたに会えて本当によかった。元気でね。」 B「そんな、もう一生会えない（　　）言うのはやめてよ。」","options":["らしく","みたいに","らしいって","みたいって"],"answer":2,"word_explain":"「～みたいに + Động từ」 diễn tả sự ví von \"như thể là... (vậy)\". 「らしく」 dùng cho tính chất đúng với bản chất vốn có, còn 「～って」 là dạng trích dẫn khẩu ngữ của 「～と」, không dùng trực tiếp như trạng từ bổ nghĩa cách nói ở đây.","translation_vi":"A: \"Cảm ơn cậu vì tất cả thời gian qua. Thật sự rất vui vì đã gặp được cậu. Bảo trọng nhé.\" B: \"Đừng nói như thể cả đời này không gặp lại nữa vậy chứ.\""},{"mondai":7,"q":4,"prompt":"A「昨日、サッカーの試合見に行ったんでしょ？どうだった？」 B「それが、ミスの連続でね……。（　　）プロの試合とは思えない内容だったよ。」","options":["なんて","仮に","とても","二度と"],"answer":3,"word_explain":"Phó từ 「とても」 khi đi cùng thể phủ định (như 「とても～ない / とは思えない」) mang nghĩa \"hoàn toàn không thể..., chẳng tài nào...\". 「なんて」 dùng để nhấn mạnh/ngạc nhiên sau danh từ, 「仮に」 là \"giả sử\", 「二度と」 là \"không bao giờ nữa\".","translation_vi":"A: \"Hôm qua cậu đi xem trận bóng đá đúng không? Thế nào rồi?\" B: \"À thì, toàn lỗi liên tiếp ấy mà... Nội dung trận đấu chẳng thể nào nghĩ đó là trận đấu chuyên nghiệp được.\""},{"mondai":7,"q":5,"prompt":"現在、建設作業はスムーズに進んでいるが、必ずしも最初から順調だった（　　）。","options":["に限らない","必要はない","にちがいない","わけではない"],"answer":4,"word_explain":"Cấu trúc cố định 「必ずしも～わけではない」 mang nghĩa \"không hẳn là..., không nhất thiết là...\". 「に限らない」 là \"không chỉ giới hạn ở...\", 「必要はない」 là \"không cần thiết phải...\", 「にちがいない」 là \"chắc chắn là...\".","translation_vi":"Hiện tại công việc thi công đang tiến triển suôn sẻ, nhưng không hẳn là ngay từ đầu đã thuận lợi như vậy."},{"mondai":7,"q":6,"prompt":"(カメラ店で) 客「このカメラ直りますか。」 店員「うん、こんなにひどく壊れていると、（　　）ですね。」","options":["直しかねない","直しようがない","直してはならない","直してもかまわない"],"answer":2,"word_explain":"「Vます (bỏ ます) + ようがない」 diễn tả ý \"không có cách nào để làm..., hết cách...\". 「直しかねない」 là \"e rằng có thể sửa\", 「直してはならない」 là \"không được phép sửa\", 「直してもかまわない」 là \"sửa cũng không sao\".","translation_vi":"(Tại cửa hàng máy ảnh) Khách: \"Chiếc máy ảnh này có sửa được không ạ?\" Nhân viên: \"Ừm, hỏng nặng đến thế này thì không có cách nào sửa được đâu.\""},{"mondai":7,"q":7,"prompt":"「このたびは、私どもの商品発送ミスにより、お客様に大変ご迷惑をおかけしましたことを深く（　　）。申し訳ございませんでした。」","options":["おわび申し上げます","おわびいただきます","わびていただきます","わびていらっしゃいます"],"answer":1,"word_explain":"「お + Vます / Danh từ + 申し上げます」 là khiêm nhường ngữ trang trọng dùng cho hành động của bản thân người nói hướng tới đối phương (khách hàng). Các đáp án dùng 「いただく」 (nhận từ người khác) và 「いらっしゃる」 (tôn kính ngữ) đều sai chủ thể.","translation_vi":"\"Lần này, do sai sót trong việc gửi hàng của chúng tôi, chúng tôi xin chân thành gửi lời xin lỗi sâu sắc vì đã gây phiền hà lớn cho quý khách. Thành thật xin lỗi quý khách.\""},{"mondai":7,"q":8,"prompt":"相手のためと思ってしたことが、実はその人にとって迷惑になっては（　　）。","options":["いないでしょうか","おかないでしょう","こないでしょう","みないでしょうか"],"answer":1,"word_explain":"「Vて + はいないか / いないでしょうか」 là dạng nghi vấn tu từ mang nghĩa \"liệu có phải đang (vô tình) rơi vào trạng thái... không?\". Ở đây thể hiện sự tự vấn: việc làm vì đối phương liệu có đang thành phiền toái cho họ không.","translation_vi":"Những việc ta làm vì nghĩ cho đối phương, liệu có khi nào thực chất lại đang trở thành sự phiền phức đối với người đó hay không?"},{"mondai":7,"q":9,"prompt":"これは「あお湖」の写真です。この湖は、季節によってさまざまな景色を水面に映して私たちの目を（　　）。","options":["楽しんでくれます","楽しんでもらいます","楽しませてくれます","楽しませてもらいます"],"answer":3,"word_explain":"Chủ ngữ là 「この湖」 (hồ này), tác động lên 「私たちの目」 (đôi mắt của chúng ta) nên cần dùng thể sai khiến kết hợp 「～てくれる」: 「楽しませてくれます」 (mang lại niềm vui / làm cho mắt chúng ta được thưởng thức).","translation_vi":"Đây là bức ảnh của \"Hồ Ao\". Tùy theo từng mùa, hồ nước này phản chiếu nhiều phong cảnh đa dạng lên mặt nước, làm mãn nhãn chúng ta."},{"mondai":7,"q":10,"prompt":"わたしの気持ちは、きっとあなたにはわからないだろうし、あなたに（　　）。","options":["わかりたくもない","わかってほしくもない","わかりたくはないだろう","わかってほしくはないだろう"],"answer":2,"word_explain":"「Vてほしい」 nghĩa là \"muốn ai đó làm gì\". Dạng phủ định nhấn mạnh thêm 「も」 là 「わかってほしくもない」 = \"và tôi cũng chẳng muốn bạn hiểu\". Vế sau nói về mong muốn của chính người nói chứ không phải suy đoán 「だろう」.","translation_vi":"Cảm xúc của tôi chắc hẳn bạn sẽ không hiểu được đâu, và tôi cũng chẳng mong bạn phải hiểu làm gì."},{"mondai":7,"q":11,"prompt":"さっきご飯を食べた（　　）、もうおなかがすいてきた。","options":["すぐのことだが","ばかりのことだが","すぐだというのに","ばかりだというのに"],"answer":4,"word_explain":"「Vた + ばかりだ」 nghĩa là \"vừa mới làm gì\" (theo cảm nhận của người nói), kết hợp với 「～というのに」 (\"mặc dù thế mà...\") để nhấn mạnh sự ngạc nhiên, trái ngược với thực tế vừa mới ăn xong.","translation_vi":"Mặc dù lúc nãy vừa mới ăn cơm xong, thế mà giờ bụng đã thấy đói rồi."},{"mondai":7,"q":12,"prompt":"大学を決めるときは、自分が本当にその大学に（　　）、じっくり考えることが重要です。","options":["行こうかどうか","行きたいというのは","行こうというのは","行きたいのかどうか"],"answer":4,"word_explain":"「～（の）かどうか」 nghĩa là \"có... hay không\", dùng để đưa ra câu hỏi gián tiếp làm đối tượng cho 「考える」. 「行きたいのかどうか」 = \"liệu có muốn đi hay không\".","translation_vi":"Khi quyết định chọn trường đại học, điều quan trọng là phải suy nghĩ thật kỹ xem bản thân có thực sự muốn vào ngôi trường đó hay không."},{"mondai":8,"q":13,"prompt":"(テレビドラマを見ながら) 弟「このドラマの犯人、誰だと思う？」 兄「＿＿＿　＿＿＿　★　＿＿＿と思うんだけど、ほかの人もみんな怪しいんだよなあ。」","options":["中の","じゃないか","誰か","三姉妹の"],"answer":3,"word_explain":"Thứ tự đúng: 4 → 1 → ★3 → 2 (三姉妹の中の誰かじゃないか). Cụm 「三姉妹の中の誰か」 là \"ai đó trong số ba chị em\", kết hợp với 「～じゃないかと思う」 (tôi nghĩ chẳng phải là... sao).","translation_vi":"(Trong lúc xem phim truyền hình) Em trai: \"Anh nghĩ ai là hung thủ của bộ phim này?\" Anh trai: \"Anh nghĩ chẳng phải là một trong ba chị em sao, nhưng mà những người khác ai trông cũng đáng nghi cả.\""},{"mondai":8,"q":14,"prompt":"新しいパソコンが欲しいが、＿＿＿　＿＿＿　★　＿＿＿、しばらく様子を見ようと思う。","options":["悔しいから","新しいのが出たりしたら","今慌てて買って","何カ月もしないうちに"],"answer":2,"word_explain":"Thứ tự đúng: 3 → 4 → ★2 → 1 (今慌てて買って、何カ月もしないうちに新しいのが出たりしたら悔しいから). 「～たりしたら」 diễn tả giả định nếu việc ra mẫu mới xảy ra trong thời gian ngắn 「何カ月もしないうちに」 thì sẽ thấy tiếc 「悔しいから」.","translation_vi":"Tôi muốn mua một chiếc máy tính mới, nhưng nếu bây giờ vội vàng mua rồi chưa đầy mấy tháng sau lại có mẫu mới ra thì sẽ tiếc lắm, nên tôi định sẽ quan sát tình hình một thời gian đã."},{"mondai":8,"q":15,"prompt":"お互い感情的になっていると、＿＿＿　＿＿＿　★　＿＿＿ものだ。","options":["うまく","冷静に話そう","いかない","としても"],"answer":1,"word_explain":"Thứ tự đúng: 2 → 4 → ★1 → 3 (冷静に話そうとしても、うまくいかない). Cấu trúc 「V(よ)うとしても」 (dù có cố gắng làm gì đi nữa) kết hợp với cụm quán dụng 「うまくいかない」 (không suôn sẻ) và 「ものだ」 (thường là như vậy).","translation_vi":"Khi cả hai bên đều đang mất bình tĩnh, dù có cố gắng nói chuyện một cách bình tĩnh đi nữa thì mọi chuyện cũng thường không suôn sẻ được."},{"mondai":8,"q":16,"prompt":"彼がそんなことをする人間でないことは、あなたが＿＿＿　＿＿＿　★　＿＿＿だ。","options":["はず","ご存じ","いちばん","の"],"answer":4,"word_explain":"Thứ tự đúng: 3 → 2 → ★4 → 1 (いちばんご存じのはず). 「ご存じ」 là tôn kính ngữ của 「知っている」; khi bổ nghĩa cho danh từ 「はず」 thì dùng 「ご存じのはずだ」 (chắc hẳn bạn biết rõ nhất).","translation_vi":"Việc anh ấy không phải là loại người làm chuyện như thế thì chắc chắn bạn là người rõ nhất."},{"mondai":8,"q":17,"prompt":"田中監督が選手たちに厳しくするのは、一度は優勝を＿＿＿　＿＿＿　★　＿＿＿だ。","options":["と","経験させたい","からこそ","願う"],"answer":4,"word_explain":"Thứ tự đúng: 2 → 1 → ★4 → 3 (経験させたいと願うからこそ). Cấu trúc 「～と願う」 (mong muốn rằng...) kết hợp với 「からこそだ」 (chính là vì...).","translation_vi":"Việc huấn luyện viên Tanaka nghiêm khắc với các cầu thủ chính là vì ông mong muốn ít nhất một lần cho họ được trải nghiệm cảm giác vô địch."},{"mondai":9,"q":18,"prompt":"Chỗ trống [50] trong đoạn văn trên","options":["そういう","それの","この季節に","この夏に"],"answer":3,"word_explain":"Câu trước vừa nhắc đến mùa xuân (「春が訪れ、過ごしやすい季節になりました」) và câu sau khẳng định mùa xuân cũng là mùa dị ứng phấn hoa, nên 「この季節に」 (vào mùa này) liên kết mạch văn chính xác nhất.","translation_vi":"Tuy nhiên gần đây, số người bị khổ sở bởi chứng dị ứng phấn hoa vào mùa này đang ngày càng tăng lên."},{"mondai":9,"q":19,"prompt":"Chỗ trống [51] trong đoạn văn trên","options":["このように","いっぽうで","ちなみに","それどころか"],"answer":1,"word_explain":"Đoạn văn vừa giải thích chi tiết cơ chế tạo kháng thể rồi hắt hơi, sổ mũi để đẩy phấn hoa ra ngoài, và câu cuối kết luận tóm lại bằng 「～というわけです」, nên từ nối phù hợp nhất là 「このように」 (Như thế này / Như vậy).","translation_vi":"Như vậy, việc cơ thể phản ứng quá mức với phấn hoa và xuất hiện các triệu chứng đó chính là chứng dị ứng phấn hoa."},{"mondai":9,"q":20,"prompt":"Chỗ trống [52] trong đoạn văn trên","options":["入ってあげるのでしょう","入れてあげましょう","入れるのでしょう","入りましょう"],"answer":4,"word_explain":"Chủ thể hành động là người đọc (người bị dị ứng phấn hoa) khi đi về nhà, nên động từ tự động từ 「家に入る」 ở dạng khuyên bảo 「入りましょう」 (hãy vào nhà) là chính xác. Các đáp án có 「あげる」 hay tha động từ 「入れる」 đều không hợp nghĩa.","translation_vi":"Khi ra ngoài hãy đeo khẩu trang hay kính để ngăn phấn hoa vào cơ thể, còn khi về nhà thì hãy giũ sạch phấn hoa bám trên quần áo rồi mới vào nhà."},{"mondai":9,"q":21,"prompt":"Chỗ trống [53] trong đoạn văn trên","options":["規則","有害","花粉症","抗体"],"answer":3,"word_explain":"Câu ngay trước nói: 「いつ誰が花粉症になっても不思議ではありません」 (Không có gì lạ nếu bất kỳ lúc nào ai đó cũng có thể bị dị ứng phấn hoa), nên danh từ được chỉ đến ở 「それが[53]です」 chính là 「花粉症」.","translation_vi":"Một thứ mà không ai có thể nói là chẳng liên quan gì đến mình, đó chính là chứng dị ứng phấn hoa."},{"mondai":9,"q":22,"prompt":"Chỗ trống [54] trong đoạn văn trên","options":["気をつけてきたらどうでしょうか","気をつけた方がいいのでしょうか","きをつけているそうです","気をつければよかったです"],"answer":1,"word_explain":"Câu kết thúc bài viết đưa ra lời khuyên nhẹ nhàng cho tất cả mọi người đọc, nên mẫu câu đề xuất 「～てみたらどうでしょうか」 là tự nhiên nhất. (Lưu ý: bản PDF gốc gõ nhầm chữ 「きたら」 thay cho 「みたら」 trong đề gốc JLPT 12/2010 là 「気をつけてみたらどうでしょうか」).","translation_vi":"Dù là người bị dị ứng phấn hoa hay không, vào mùa xuân chúng ta hãy thử chú ý một chút đến cách sinh hoạt của mình xem sao."}]},{"id":"g_2010_07","displayName":"07/2010","subtitle":"22 câu • Mondai 7–9 (Ngữ pháp)","m9_passage":"下の文章は雑誌のコラムです。\n\nテレビや雑誌では、よく「血液型性格判断」が取り上げられます。これは、血液型によって性格が決まっている、言い換えれば、血液型がわかれば大体の性格もわかるという [50] です。\n\nその血液型性格判断によると、人の性格は、Ａ型、Ｂ型、Ｏ型、ＡＢ型の血液型ごとに決まっているのだそうです。しかし、この世界には何十億人もの人が [51-a] 、人の性格をたった４種類に分類することが [51-b] 。\n\n血液型は親から子への遺伝によって、４種類のうち、どの型になるかが決まります。つまり、 [52-a] は生まれてから死ぬまで、変わることはほぼありません。一方、 [52-b] はどうでしょうか。 [52-c] に関して言えば、子どものときは我慢が苦手だった子が、成長とともに我慢できるようになるといったことも少なくないでしょう。\n\nまた、ある調査によると、自分の血液型がどんな性格かということを聞いて、知らないうちに自分の性格がその性格に近づいてしまっているということもあるそうです。「私はＡ型だから、こういう性格なんだ」という思い込みで、性格が作られている可能性も否定できないというのです。 [53] 、性格と血液型に関係はあると言えるかもしれませんが、それは血液型で性格が決まるということではありません。\n\nこう考えると、やはり、血液型によって性格がたった４種類に分けられるとは [54] 。","questions":[{"mondai":7,"q":1,"prompt":"このレストランは、客の予算（　　）いくつかのコースを用意してくれる。","options":["に比べて","に先立って","に応じて","に向けて"],"answer":3,"word_explain":"「～に応じて」 mang nghĩa \"tùy theo ~, đáp ứng theo ~\" (tùy theo ngân sách của khách mà chuẩn bị các thực đơn tương ứng). Các đáp án khác: 「に比べて」 (so với), 「に先立って」 (trước khi), 「に向けて」 (hướng tới).","translation_vi":"Nhà hàng này chuẩn bị sẵn một vài thực đơn tùy theo ngân sách của khách hàng."},{"mondai":7,"q":2,"prompt":"学校に来る（　　）財布を忘れたのに気づいた。","options":["とちゅうで","ついでに","なかで","うちに"],"answer":1,"word_explain":"「Vる＋途中で」 diễn tả hành động xảy ra giữa chừng hoặc trên đường đang di chuyển (\"trên đường đến trường thì nhận ra quên ví\"). 「ついでに」 là \"nhân tiện\", 「なかで」 là \"trong số/trong lúc\", 「うちに」 là \"trong khi (trạng thái chưa đổi)\".","translation_vi":"Trên đường đến trường, tôi mới nhận ra là mình đã quên ví."},{"mondai":7,"q":3,"prompt":"踏切事故のために、２時間（　　）、電車がストップしました。","options":["につき","につれ","にわたり","にともない"],"answer":3,"word_explain":"「（時間・範囲）＋にわたり（にわたって）」 diễn tả sự việc kéo dài suốt một khoảng thời gian hoặc phạm vi rộng (suốt 2 tiếng). 「につき」 là \"mỗi/vì\", 「につれ」 và 「にともない」 là \"cùng với sự biến đổi của ~\".","translation_vi":"Vì tai nạn ở đường ngang giao cắt, tàu điện đã bị dừng suốt 2 tiếng đồng hồ."},{"mondai":7,"q":4,"prompt":"一回失敗したくらいで、（　　）そこまで悪く言わなくてもいいだろう。","options":["なにを","なにが","なにも","なにで"],"answer":3,"word_explain":"Cấu trúc 「なにも～（し）なくてもいい」 dùng để nhấn mạnh rằng \"đâu có cần thiết phải làm đến mức như vậy\" (mới thất bại một lần thì đâu cần nói nặng lời đến thế).","translation_vi":"Mới thất bại có một lần thôi mà, đâu cần phải nói nặng lời đến mức như vậy chứ."},{"mondai":7,"q":5,"prompt":"田中選手は前大会に続いて、今大会でも優勝を果たした。彼の今後の活躍に周囲の期待は高まる（　　）。","options":["中心だ","事情だ","原因だ","一方だ"],"answer":4,"word_explain":"「Vる＋一方だ」 diễn tả một xu hướng biến đổi không ngừng theo một chiều (\"ngày càng ~\"). 「期待は高まる一方だ」 nghĩa là kỳ vọng ngày càng dâng cao.","translation_vi":"Tuyển thủ Tanaka tiếp nối giải đấu trước, đã giành chức vô địch ở giải đấu lần này. Kỳ vọng của mọi người xung quanh đối với sự tỏa sáng sắp tới của anh ngày càng tăng cao."},{"mondai":7,"q":6,"prompt":"これだけ景気が悪いのに、税金を上げようとするのは、わたしたち国民には理解（　　）。","options":["しすぎる","しがたい","しかねない","しがちだ"],"answer":2,"word_explain":"「Vます＋がたい」 mang nghĩa \"khó mà ~ được\" (chỉ những việc khó thực hiện về mặt tâm lý/nhận thức như hiểu, tin, tha thứ). 「理解しがたい」 = khó lòng mà hiểu nổi. Các đáp án khác: 「～すぎる」 (quá mức), 「～かねない」 (có nguy cơ), 「～がちだ」 (hay/dễ).","translation_vi":"Tình hình kinh tế đã tệ thế này rồi mà vẫn định tăng thuế thì người dân chúng tôi thật khó lòng mà hiểu nổi."},{"mondai":7,"q":7,"prompt":"（メールで）田中です。先日お話があったスピーチの件なんですが、ぜひわたしに（　　）。","options":["やっていただけないでしょうか","やらせていただけないでしょうか","やってもよろしいでしょうか","やらせてもよろしいでしょうか"],"answer":2,"word_explain":"「V（sai khiến）＋ていただけないでしょうか」 (やらせていただけないでしょうか) là cách nói khiêm nhường, lịch sự để xin phép được làm gì (\"xin hãy cho phép tôi được làm\"). Trợ từ 「わたしに」 kết hợp với thể sai khiến nhận ân huệ để xin được giao việc.","translation_vi":"(Trong email) Tôi là Tanaka. Về việc bài phát biểu mà anh/chị đã trao đổi hôm trước, nhất định xin hãy cho phép tôi được đảm nhận ạ."},{"mondai":7,"q":8,"prompt":"山下「田中君、きみ、また大阪に出張なんだって？」 田中「ええ、そうなんですよ。ついこの前も出張に（　　）なんですけどねえ。」","options":["行かれたまま","行かされたまま","行かれたばかり","行かされたばかり"],"answer":4,"word_explain":"Tanaka nói về bản thân mình nên không dùng tôn kính ngữ 「行かれた」 (loại 1, 3). 「行かされた」 (bị động sai khiến của 「行く」) diễn tả việc phải đi/bị công ty cử đi, kết hợp với 「ついこの前も～たばかり」 (\"mới vừa đi xong cách đây không lâu\").","translation_vi":"Yamashita: \"Này Tanaka, nghe nói cậu lại sắp đi công tác Osaka à?\" Tanaka: \"Vâng, đúng thế đấy ạ. Mới vừa rồi tôi cũng mới bị cử đi công tác xong mà.\""},{"mondai":7,"q":9,"prompt":"仕事の合間にときどき遠くを見る（　　）、目が疲れにくくなった。","options":["ようにしたところに","ようにしたところ","までになったところに","までになったところ"],"answer":2,"word_explain":"「Vるようにする」 diễn tả việc cố gắng tạo thói quen, kết hợp với 「Vたところ」 diễn tả kết quả nhận được sau khi thực hiện (\"sau khi thử cố gắng làm như vậy thì...\"). 「ところに」 nghĩa là \"đúng vào lúc đang ~\" nên không phù hợp.","translation_vi":"Sau khi tôi tập thói quen thỉnh thoảng nhìn ra xa trong lúc giải lao giữa giờ làm việc, mắt tôi đã trở nên khó mỏi hơn."},{"mondai":7,"q":10,"prompt":"人間の脳に関する研究で明らかになったことはまだほんの一部（　　）、その研究は着実に進んできた。","options":["にすぎないとすると","にかかわらないとすると","にすぎないとはいえ","にかかわらないとはいえ"],"answer":3,"word_explain":"「～にすぎない」 (chỉ là ~ mà thôi) kết hợp với 「～とはいえ」 (tuy nói là ~ nhưng...) tạo quan hệ nghịch tiếp: tuy mới chỉ là một phần nhỏ nhưng nghiên cứu vẫn tiến triển vững chắc. 「～とすると」 là \"giả sử rằng\", 「にかかわらない」 là \"không liên quan\".","translation_vi":"Tuy những điều được làm sáng tỏ trong nghiên cứu về não bộ con người mới chỉ là một phần rất nhỏ, nhưng nghiên cứu đó vẫn đang tiến triển một cách vững chắc."},{"mondai":7,"q":11,"prompt":"会議の目的は新商品のアイディアを自由に出し合う（　　）が、結局、上司に意見が優先されて終わった。","options":["ことにあったはずだ","ことにあったためだ","のにあったはずだ","のにあったためだ"],"answer":1,"word_explain":"Cấu trúc 「目的は～ことにある」 (mục đích nằm ở việc ~), dùng danh từ hóa 「こと」 (không dùng 「の」). Kết hợp với 「はずだ」 (đáng lẽ ra là như vậy) đi trước 「が」 để diễn tả thực tế trái ngược với mục đích ban đầu.","translation_vi":"Mục đích của cuộc họp đáng lẽ ra là để mọi người tự do đưa ra ý tưởng về sản phẩm mới, thế nhưng kết cục lại kết thúc bằng việc ý kiến của cấp trên được ưu tiên."},{"mondai":7,"q":12,"prompt":"残業が続いて体を壊したときに、自分の人生は（　　）と思って、転職を決めた。","options":["このままならいいのではないか","このままがいいのではないか","このままよりいいのだろうか","このままでいいのだろうか"],"answer":4,"word_explain":"「このままでいいのだろうか」 là câu tự vấn mang sắc thái lo lắng, băn khoăn: \"Cứ để tình trạng như thế này liệu có ổn không nhỉ?\". Các phương án 1, 2 mang nghĩa khẳng định/đề xuất \"cứ thế này là tốt\", không hợp với quyết định chuyển việc.","translation_vi":"Khi làm thêm giờ liên tục đến mức đổ bệnh, tôi đã tự hỏi rằng cuộc đời mình cứ thế này liệu có ổn không, rồi quyết định chuyển việc."},{"mondai":8,"q":13,"prompt":"A「先週の授業、どこまで進んだ？」 B「３課の文法の練習問題を　＿＿＿　＿＿＿　★　＿＿＿　終わったよ。」","options":["で","解いた","ところ","まで"],"answer":4,"word_explain":"Thứ tự đúng: 2 → 3 → ★4 → 1 (解いた → ところ → ★まで → で). Cụm 「練習問題を解いたところまでで終わったよ」 có nghĩa là kết thúc tại phần đã giải xong bài tập.","translation_vi":"A: \"Buổi học tuần trước đã học đến đâu rồi?\" B: \"Đã kết thúc ở phần giải xong bài tập thực hành ngữ pháp bài 3 rồi đấy.\""},{"mondai":8,"q":14,"prompt":"ひとくちに　＿＿＿　★　＿＿＿　＿＿＿　材料はさまざまだ。","options":["それぞれの店","といっても","によって","カレーライス"],"answer":2,"word_explain":"Thứ tự đúng: 4 → ★2 → 1 → 3 (カレーライス → ★といっても → それぞれの店 → によって). Mẫu 「ひとくちに～といっても」 (tuy gọi chung một tiếng là ~ nhưng thực tế...) đi với 「～によってさまざまだ」 (tùy theo ~ mà khác nhau).","translation_vi":"Tuy nói chung là cơm cà ri, nhưng tùy theo từng cửa hàng mà nguyên liệu lại rất đa dạng."},{"mondai":8,"q":15,"prompt":"田中さんはいつも　＿＿＿　＿＿＿　★　＿＿＿　自分では何もしない。","options":["文句を言う","ばかりで","人の","やることに"],"answer":1,"word_explain":"Thứ tự đúng: 3 → 4 → ★1 → 2 (人の → やることに → ★文句を言う → ばかりで). Cụm 「人のやることに文句を言うばかりで」 dùng 「Vる＋ばかりで」 mang nghĩa \"chỉ toàn làm mỗi việc ~\".","translation_vi":"Anh Tanaka lúc nào cũng chỉ toàn phàn nàn về những việc người khác làm, chứ bản thân thì chẳng làm gì cả."},{"mondai":8,"q":16,"prompt":"A「この『りかい』という言葉はどういう意味ですか。」 B「ああ、確か『わかる』　＿＿＿　★　＿＿＿　＿＿＿　んですけど。」","options":["意味だった","という","ような","と思う"],"answer":3,"word_explain":"Thứ tự đúng: 2 → ★3 → 1 → 4 (という → ★ような → 意味だった → と思う). Cụm 「『わかる』というような意味だったと思うんですけど」 nghĩa là \"tôi nhớ hình như đó là ý nghĩa đại loại như 'hiểu'\".","translation_vi":"A: \"Từ 'rikai' này có nghĩa là gì vậy ạ?\" B: \"À, nếu tôi nhớ không nhầm thì hình như nó có nghĩa đại loại như là 'hiểu' đấy.\""},{"mondai":8,"q":17,"prompt":"毎年、合格者の８０パーセントが　＿＿＿　★　＿＿＿　＿＿＿　この試験に合格するのは簡単ではないだろう。","options":["実務経験者という","私が","ことからすると","未経験者の"],"answer":3,"word_explain":"Thứ tự đúng: 1 → ★3 → 4 → 2 (実務経験者という → ★ことからすると → 未経験者の → 私が). Cấu trúc 「～ということからすると」 (\"xét từ việc là...\") kết hợp với 「未経験者の私が」 (\"người chưa có kinh nghiệm như tôi\").","translation_vi":"Xét từ việc hàng năm có tới 80% người thi đỗ là người có kinh nghiệm thực tế, thì một người chưa có kinh nghiệm như tôi để đỗ được kỳ thi này chắc sẽ không dễ dàng đâu."},{"mondai":9,"q":18,"prompt":"Chỗ trống [50] trong đoạn văn trên","options":["点","もの","場合","結果"],"answer":2,"word_explain":"「これは～というものです」 được dùng để định nghĩa hoặc giải thích khái niệm vừa nêu ở câu trước (「血液型性格判断」). Các từ 「点」 (điểm/khía cạnh), 「場合」 (trường hợp), 「結果」 (kết quả) không hợp để định nghĩa khái niệm này.","translation_vi":"Đây là quan niệm cho rằng tính cách được quyết định bởi nhóm máu, nói cách khác là chỉ cần biết nhóm máu thì cũng có thể biết được đại khái tính cách."},{"mondai":9,"q":19,"prompt":"Chỗ trống [51] trong đoạn văn trên","options":["ａいるわけですから／ｂできたのではないかと考えます","ａいるわけですから／ｂできるのかと疑問に思います","ａいるからこそ／ｂ疑問に思われなかったのです","ａいるからこそ／ｂできなかったのだと考えられます"],"answer":2,"word_explain":"Sau từ nối tương phản 「しかし」, tác giả nêu lý do 「いるわけですから」 (\"bởi vì vốn dĩ trên thế giới có tới hàng tỷ người...\") để bày tỏ sự hoài nghi 「できるのかと疑問に思います」 (\"liệu có thể phân loại chỉ thành 4 kiểu hay không\"). Các phương án 1, 3, 4 sai về logic lập luận hoặc thì quá khứ.","translation_vi":"Tuy nhiên, bởi vì trên thế giới này có tới hàng tỷ con người, nên tôi thấy nghi ngờ rằng liệu có thể phân loại tính cách con người chỉ thành 4 kiểu hay không."},{"mondai":9,"q":20,"prompt":"Chỗ trống [52] trong đoạn văn trên","options":["ａ性格／ｂ血液型／ｃ血液型","ａ性格／ｂ血液型／ｃ性格","ａ血液型／ｂ性格／ｃ性格","ａ血液型／ｂ性格／ｃ血液型"],"answer":3,"word_explain":"Câu đầu đoạn nói nhóm máu được quyết định do di truyền nên [52-a] là 「血液型」 (hầu như không thay đổi suốt đời). Sau 「一方」 (mặt khác), [52-b] chuyển sang đối chiếu với 「性格」 (tính cách), và [52-c] tiếp tục lấy ví dụ về sự thay đổi của 「性格」 khi trưởng thành.","translation_vi":"Nói cách khác, nhóm máu hầu như không thay đổi từ lúc sinh ra cho đến khi chết đi. Mặt khác, còn tính cách thì sao? Nếu nói về tính cách, thì chuyện một đứa trẻ hồi nhỏ kém kiên nhẫn nhưng khi lớn lên lại biết nhẫn nại hơn cũng không phải là hiếm."},{"mondai":9,"q":21,"prompt":"Chỗ trống [53] trong đoạn văn trên","options":["それが本当ならば","それと比べても","そうあるべきなので","それが前提でなかったら"],"answer":1,"word_explain":"「それが本当ならば」 (\"Nếu điều đó là thật thì...\") tiếp nối trực tiếp khả năng được nêu ở câu trước (\"không thể phủ nhận khả năng tính cách bị hình thành do suy nghĩ áp đặt theo nhóm máu\"), dẫn sang mệnh đề nhượng bộ 「～と言えるかもしれませんが」.","translation_vi":"Nếu điều đó là thật thì có lẽ cũng có thể nói rằng tính cách và nhóm máu có mối liên hệ với nhau, nhưng điều đó không có nghĩa là tính cách được quyết định bởi nhóm máu."},{"mondai":9,"q":22,"prompt":"Chỗ trống [54] trong đoạn văn trên","options":["言われてこなかったのです","言われていないのでしょう","言えないことはないのです","言えないのではないでしょうか"],"answer":4,"word_explain":"「～とは言えないのではないでしょうか」 là cách kết luận mềm mỏng mang nghĩa \"chẳng phải là không thể nói rằng ~ hay sao?\", khẳng định lại quan điểm chính của bài viết. Phương án 3 (「言えないことはない」 = có thể nói như vậy) mang nghĩa ngược lại, còn 1 và 2 sai nghĩa/thì so với ngữ cảnh bài.","translation_vi":"Nghĩ như vậy thì suy cho cùng, chẳng phải là không thể nói rằng tính cách được phân chia chỉ thành 4 kiểu dựa theo nhóm máu hay sao."}]}];
